do local function f(R)
R(1,"The \"Chow\" Quest (123)aa",[[description="$Tpunk;!  Kill Kobold Vermin, 2 of em. NEW TEST AGAIN",objectives={"Kill Kobold Vermin, 2 of em."}]])
R(2,"沙普塔隆的爪子",[[description="强大的角鹰兽沙普塔隆已经被你杀死了，它的爪子将成为你胜利的象征。碎木哨岗的塞娜尼·雷心一定会对你的战利品感兴趣的。",objectives={"将沙普塔隆的爪子交给灰谷碎木哨岗的塞娜尼·雷心。"}]])
R(5,"饥肠辘辘的基特斯",[[description="我已经困在这个鬼镇里好几个星期了，除了虫子和野草之外什么吃的都没有！我想吃点正常的食物，即使要多花点钱也无所谓。$B$B给我找点美食来，我就给你大笔的奖赏。$B$B听说夜色镇血鸦旅店的厨师格鲁奥做的黑蟹蛋糕很不错……",objectives={"和厨师格鲁奥谈一谈。"}]])
R(6,"加瑞克·帕德弗特的赏金",[[description="加瑞克·帕德弗特，这个恶棍几周以来一直让我们的农民和商人心惊胆战，前几天有人在农场附近的小屋里看到了他的身影，大概在就是修道院东边过了桥以后的那片地方。提着他的头回来见我，然后领取赏金吧！$B$B不过你要小心一点，$N。加瑞克身边总是有一帮暴徒，他可不是那么容易搞定的家伙。",objectives={"杀死加瑞克·帕德弗特，带着他的头到北郡修道院去找维里副队长。"}]])
R(7,"剿灭狗头人",[[description="你的第一个任务是清剿工作，$N。一个狗头人部族占据了北边的森林。到那儿去，把你能看到的狗头人歹徒都杀掉。尽量减少他们的数量，好让我们有一天能把他们从北郡彻底赶出去。",objectives={"杀死10只狗头人歹徒，然后向治安官玛克布莱德复命。"}]])
R(8,"潜行者的交易",[[description="嘿，伙计！帮我一个忙如何？大堆僵尸和蜘蛛实在让我应接不暇。$B$B现在我手里有一封要送到布瑞尔的信……送给一个名叫瑞尼的还是别的什么的旅店老板，别管她姓什么啦。$B$B总之，那里是一个舒适而温暖的小地方，里面都是些希望重返真实自我的瘟疫受害者，当然那里也是你休息的好去处。你应该自己去看看……如果你愿意跑一趟，我会给你不错的报酬的。",objectives={"把笔迹潦草的信件送给布瑞尔的旅店老板瑞尼。"}]])
R(9,"清理荒野",[[description="看看这片土地上都发生了些什么吧！这片土地曾为一群善良老实的农民们所有。但如今，一群该死的小贼把农民们全部赶走了。当然，除了老子我！但有些看守傀儡一直霸占着我的田地。$b$b如果你觉着自己能够胜任这份工作的话，我希望你能帮忙清除掉20台傀儡。完成了任务之后，记得回来拿酬劳。如果你把我这片田地上的傀儡清光了的话，就去清除旁边田上的傀儡吧。",objectives={"农夫萨丁要求你破坏掉20台看守傀儡。"}]])
R(10,"谢申克的救赎",[[description="啊，这真是太糟糕了！我派我手下最得力的助手，初级勘探员谢申克去沙漠东南面的那个叫做大裂口的地方进行探查。但是现在他失踪了，而他最后一份报告中显示大裂口到处都充斥着那些怪异的虫子。我现在已经派不出足够的人力来同时探查这片沙漠上的两大块重要的地区了。$B$B我想派你去大裂口找谢申克，求求你了！也许他已经……但至少请帮我拿回他的勘探设备来。我恐怕那是可怜的谢申克最后的遗产了。",objectives={"寻找初级勘探员谢申克的下落，把他或者他的勘探设备交给加基森的高级勘探员菲兹杜瑟。"}]])
R(11,"悬赏河爪豺狼人",[[description="有人在艾尔文森林的边界处看见了豺狼人，这些野蛮的动物在这儿肯定不会干什么好事。在了望塔南边的树林里有一大群豺狼人到处游荡，凭我们自己的兵力很难应付他们。$B$B任何帮忙清除这些豺狼人的勇士都会受到暴风城军方的嘉奖。把他们的彩色豺狼人臂章带给我以证明你杀了他们。",objectives={"给兵营的瑞尼尔副队长带去8个彩色豺狼人臂章。"}]])
R(12,"西部荒野人民军",[[description="人民军只一个目标：保护西部荒野的安宁，并将和平带回到这片土地上来。不幸的是，和平总是以鲜血的代价来换取的。$b$b我手下的一个斥候报告说，有一群迪菲亚捕兽者正在附近到处流窜并大肆破坏。最新的报告说他们出现在了西北方的詹戈洛德矿洞中，如果你想加入我们人民军的话，那么就先消灭15名迪菲亚捕兽者和15名迪菲亚走私者，然后回来向我复命。",objectives={"哨兵岭的格里安·斯托曼要求你消灭15名迪菲亚捕兽者和15名迪菲亚走私者，然后回去向他报告。"}]])
R(13,"西部荒野人民军",[[description="有人看见一群凶残的迪菲亚抢劫者洗劫了金海岸矿洞和月溪镇，我们人民军绝不能对这样的事袖手旁观。马上就出发吧，$n，让圣光重新照耀西部荒野。$b$b金海岸矿洞就在哨塔西边的海岸附近，作为训练的第二部分，我希望你能消灭15名迪菲亚抢劫者和15名迪菲亚强夺者。",objectives={"哨兵岭的格里安·斯托曼要求你消灭15名迪菲亚抢劫者和15名迪菲亚强夺者，然后回去向他报告。"}]])
R(14,"西部荒野人民军",[[description="一些迪菲亚路霸最近一直在避开我们，到处作恶。根据我手下最可靠的探子们的线报，这些迪菲亚路霸通常沿着从这里到西部荒野南部的道路打家劫舍。我们觉得他们现在应该就躲在南部的山丘那边，计划着下一步的行动。以人民军的名义，去消灭那些家伙。",objectives={"哨兵岭的格里安·斯托曼要求你消灭15个迪菲亚路霸、5个迪菲亚巡路者和5个迪菲亚拳匪，然后回去向他报告。"}]])
R(15,"回音山调查行动",[[description="$N，我的探子告诉我说，狗头人群落的规模远远大于我们的估计，一群狗头人劳工刚刚入侵了北边的回音山矿洞。$B$B到矿洞里去，把他们都除掉。那里至少有10个狗头人劳工，杀光他们，如果你发现他们的数量远不止这么多的话，就赶快回报给我。",objectives={"杀死10只狗头人劳工，然后向治安官玛克布莱德复命。"}]])
R(16,"葛拉德的饮料")
R(17,"奥达曼的蘑菇",[[description="$N，我听说有一种紫色蘑菇刚刚被发现，它们似乎只在奥达曼挖掘场里生长。我需要十二个这样的蘑菇来进行炼金术的研究。$B$B你要多加小心，这种蘑菇会喷射出有毒的孢子。$B$B帮我这个忙吧，我会给你丰厚的报酬，另外还可以让你尝尝我收藏多年的好酒！",objectives={"收集12颗紫色蘑菇，把它们交给塞尔萨玛的加克。"}]])
R(18,"潜行者兄弟会",[[description="最近, 一伙新来的流寇停留在北郡一带，为祸四方。他们自称为迪菲亚兄弟会，向东过了河之后就能找到他们。$B$B我不知道他们聚在一起到底想要干什么，但我确信他们不是什么好东西。给我带回一些他们的红色粗麻面罩，我就送你一把武器作为奖励。",objectives={"给北郡的维里副队长带回12个红色粗麻面罩。"}]])
R(19,"萨瑞尔祖恩",[[description="黑石前锋和黑石叛节者经常在这里和石堡要塞之间伏击我们，这群前锋的指挥官是个名叫萨瑞尔祖恩的兽人。把他的头给我带来。",objectives={"将萨瑞尔祖恩的头颅带给湖畔镇的治安官马瑞斯。"}]])
R(20,"黑石氏族的威胁",[[description="黑石氏族穿越了燃烧平原并攻下了北方的石堡要塞。他们以那座要塞为据点，劫掠湖畔镇北边的人们，吓得全镇的居民都不敢外出，只能躲在镇子里瑟瑟发抖。$B$B帮湖畔镇解决掉这个威胁吧。杀死黑石氏族的兽人，并带回来十把他们所用的破斧作为证明。$B$B尽管黑石氏族是在北方威胁着我们，但我们也收到了他们在赤脊山脉东南部出现的报告。你可以在那里找到他们，然后猎杀他们。",objectives={"给湖畔镇的治安官马瑞斯带回10把破斧。"}]])
R(21,"回音山清剿行动",[[description="你上次的调查证实，回音山矿洞需要一次清剿行动。回到矿洞那边，帮我们清除那里所有的狗头人吧。$B$B抓紧时间，$N。狗头人无所顾忌地盘踞在矿洞里的时间越长，它们在北郡的据点也就越稳固。",objectives={"杀死12只狗头人苦力，然后向北郡修道院里的治安官玛克布莱德复命。"}]])
R(22,"猪肝馅饼",[[description="削两个洋葱，剥一个大蒜，烤三片面包，剁半两香菜，切几块萝卜，熬一锅肉酱。现在……我还需要10个猪肝来完成我的绝世美味馅饼！",objectives={"萨尔玛·萨丁需要8片血牙野猪的肝来烹制猪肝馅饼。"}]])
R(23,"乌萨苟斯的爪子",[[description="强大的熊怪乌萨苟斯被你杀死了，它的爪子是你灰谷狩猎之行的战利品。爪上有一小块新月形的印记，这个印记的意义对你来说还是一个谜。$B$B你应该把这只爪子交给碎木哨岗的塞娜尼·雷心，以此证明你已经杀死了这只强大的猛兽。",objectives={"将乌萨苟斯的爪子交给灰谷碎木哨岗的的塞娜尼·雷心。"}]])
R(24,"萨杜布拉的头颅",[[description="敏捷而强大的萨杜布拉静静地躺在地上，你取得了最后的胜利。它的头颅是一件非常合适的战利品，碎木哨岗的塞娜尼·雷心肯定会想要看看这件战利品，然后对你在灰谷狩猎中取得的成绩予以嘉奖。",objectives={"将萨杜布拉的头颅交给灰谷碎木哨岗的的塞娜尼·雷心。"}]])
R(25,"石爪山的困境",[[description="如果你想做个有用的$c，那为什么不帮我们解决石爪山那边的困境呢？$B$B灰谷和石爪山脉之间的交通中断了，因为湖水中的生物突然开始攻击任何过路的旅行者……一个都不放过。你要做的并不仅仅是杀死那些水元素，你还要到密斯特拉湖中的眺望台上去一趟——在那里可以看到联盟前哨站的情况。$B$B你准备好了吗？",objectives={"清除位于碎木哨岗西南和石爪小径正东的密斯特拉湖一带的12个污浊的水元素。$B$B在密斯特拉湖上的眺望台中侦查联盟的前哨站。$B$B返回灰谷慰藉之林的碎木哨岗，向马斯托克·维尔西斯报告。"}]])
R(26,"必修的课程",[[description="$N，看到你进展顺利，我非常高兴。你正在不断地努力成为自然界的守护者，这是莫大的荣耀。$B$B现在是你深入学习更高级的变身技能的时候了，塞纳留斯赋予我们特殊的能力，让我们可以变身成为在水中行动自如的动物。所以，你必须到月光林地的永夜港去，跟塞纳里奥议会的德迪利特·星焰谈一谈。他将进一步指引你。",objectives={"与月光林地永夜港的德迪利特·星焰谈一谈。"}]])
R(27,"必修的课程",[[description="$N，看到你进展顺利，我非常高兴。你正在不断地努力成为自然界的守护者，这是莫大的荣耀。$B$B现在是你深入学习更高级的变身技能的时候了，塞纳留斯赋予我们特殊的能力，让我们可以变身成为在水中行动自如的动物。所以，你必须到月光林地的永夜港去，跟塞纳里奥议会的德迪利特·星焰谈一谈。他将进一步指引你。",objectives={"与月光林地永夜港的德迪利特·星焰谈一谈。"}]])
R(28,"湖中试炼",[[description="第一个试炼是要搜寻月神湖底的神殿灵珠。它会很快地腐烂，因此你要在找到它后立即把它拿到雷姆洛斯神殿去。在神殿里使用它，然后跟塔加里谈谈，她是月光林地里最值得信赖的守卫之一。$B$B你的时间非常紧迫，而且还要与其他寻找灵珠的德鲁伊竞争，灵敏和智慧是你取胜的关键。$B$B祝你好运，$N。",objectives={"在月神湖寻找神殿灵珠，把它带到月光林地西北部的雷姆洛斯神殿去。在神殿中使用神殿灵珠，然后与神殿中的塔加里谈话来完成试炼。"}]])
R(29,"湖中试炼",[[description="第一个试炼是要搜寻月神湖底的神殿灵珠。它会很快地腐烂，因此你要在找到它后立即把它拿到雷姆洛斯神殿去。在神殿里使用它，然后跟塔加里谈谈，她是月光林地里最值得信赖的守卫之一。$B$B你的时间非常紧迫，而且还要与其他寻找灵珠的德鲁伊竞争，灵敏和智慧是你取胜的关键。$B$B祝你好运，$N。",objectives={"在月神湖寻找神殿灵珠，把它带到月光林地西北部的雷姆洛斯神殿去。在神殿中使用神殿灵珠，然后与神殿中的塔加里谈话来完成试炼。"}]])
R(30,"海狮试炼",[[description="第二个试炼是要寻找组成海狮坠饰的两个部分。其中的一半蕴含着海狮的敏捷天性，另一半蕴含着海狮那令人难以置信的耐力。德鲁伊汲取这两种特性，将它们运用到自己的水栖形态中。$B$B与月光林地中的居民谈一谈，找到这两个部分，并将它们合并起来。最后把合并好的坠饰交给德迪利特·星焰。",objectives={"寻找水兽耐力坠饰和水兽敏捷坠饰。与月光林地的居民谈一谈，找出这些东西可能被放在哪里。$B$B在雷姆洛斯神殿附近将海狮坠饰的两部分合而为一。$B$B将合并好的坠饰交给月光林地永夜港中的德迪利特·星焰。"}]])
R(31,"水栖形态",[[description="你已经学完了掌握水栖形态所必须具备的所有知识，现在回到雷霆崖的图拉克·符文图腾那儿去吧。把坠饰拿给他看看，以此证明你已准备好接受新的知识。他会让你掌握变化为水栖形态的诀窍，让你在水中灵活自如。$B$B再见，年轻的德鲁伊。我们会再见面的。",objectives={"回到雷霆崖，让图拉克·符文图腾看看你的海狮坠饰。"}]])
R(32,"异种蝎的威胁",[[description="这是我要你去递送的报告，马上把它送到能够对其内容有深入了解的那些人的手中。$B$B我知道一个名叫基尔兹宾·鼓眼的巨魔学者，他致力于研究卡利姆多大陆上的那些与艾泽拉斯生态格格不入的生物形态；他简直是一本活的生物书！如果你想要知道我们面临的是怎样的威胁，以及如何解决这个威胁，那就把这份报告交给他吧，我们现在需要一切可以得到的帮助。$B$B基尔兹宾应该住在奥格瑞玛暗巷区的第二层。",objectives={"把报告带给奥格瑞玛的基尔兹宾·鼓眼。"}]])
R(33,"林中的群狼",[[description="我最讨厌那些肮脏狡猾的森林狼了！但我一直都很爱吃狼肉排……给我带几块硬狼肉来，我会拿一些对你有用的东西来交换。$B$B你可以在北郡的郊外找到森林狼和幼狼，杀掉它们就可以得到硬狼肉了。",objectives={"给北郡修道院外的伊根·派特斯金纳带回8块硬狼肉。"}]])
R(34,"不速之客",[[description="前几天我的花园又被搞得一塌糊涂，不过现在我已经知道是哪个混蛋干的了。就是那只被治安官马瑞斯先生称作“贝利格拉布”的野猪。$b$b你瞧，我在下一季来临之前都没法种我的水仙花了。全毁了！一切都被那只混蛋野猪给毁了！把那祸害给我干掉！把它的獠牙给我带回来，我会付给你酬劳的。它一般就在湖畔镇西南的田边闲逛，但有时候也会跑进我的花园里来。",objectives={"湖畔镇的玛蒂·詹罗斯要求你杀死贝利格拉布，并带回它的獠牙作为证明。"}]])
R(35,"卫兵托马斯",[[description="如果你担心关于鱼人的传言可能属实的话，就去一趟艾尔文森林东部的桥边和卫兵托马斯谈谈吧。他最近一个星期都驻扎在那里，应该很了解那个地区的情况。$B$B搞清楚事态之后，把他的报告带给我。",objectives={"治安官杜汉要你和卫兵托马斯谈一谈。"}]])
R(36,"杂味炖肉",[[description="我从来没有想过有一天会被迫离开我的农庄。但是现在，那些满是小贼和强盗的田地对我们来说已经是太过危险了。等法布隆修好他的车之后，我们就要逃离这里了。$b$b或许你能帮我一个小忙？先让我把我的独家绝活杂味炖肉的食谱给抄下来，然后你帮我把它交给萨尔玛·萨丁。萨丁农场就在路口的另一边。",objectives={"弗娜·法布隆要求你将她的杂味炖肉食谱交给萨尔玛·萨丁。"}]])
R(37,"失踪的卫兵",[[description="几天前，我派了卫兵罗尔夫和马拉凯沿着河岸去侦查这一代的情况，但他们到现在还没回来。我得先搞清楚这两个人发生什么事情才能完成报告。$B$B沿着河岸往北走，找到他们……或是他们的尸体。",objectives={"卫兵托马斯要你沿着河岸向北走，寻找两个失踪的卫兵罗尔夫和马拉凯。"}]])
R(38,"杂味炖肉",[[description="来帮我完成这道最华丽的西部荒野杂味炖肉吧！拜托啦，帮我找到以下这些材料：$b$b3块秃鹫肉条$b3只血牙野猪的头$b3只鱼人的眼睛$b3棵秋葵",objectives={"萨尔玛·萨丁需要3块秃鹫肉条、3只血牙野猪的头、3颗鱼人的眼睛和3棵秋葵。"}]])
R(39,"托马斯的报告",[[description="把罗尔夫和马拉凯的死讯告知治安官杜汉，向他报告说，靠我们现在的部队根本无法遏制住这些在艾尔文森林东部繁衍的鱼人。$B$B我知道我们的兵力很短缺，但是杜汉应该可以为我们提供人手。",objectives={"到闪金镇去向治安官杜汉报告。"}]])
R(40,"鱼人的威胁",[[description="$N，艾尔文森林又遇到新的威胁了！鱼人正陆续从艾尔文森林东部的河流里游过来，把鱼都给吓跑了，而且它们还攻击平民！$B$B我已经向治安官杜汉发出过警告，不过他显然更担心那些豺狼人和强盗，而且他不相信鱼人能对我们构成威胁。$B$B请你和杜汉谈谈吧，最好能说服他向东部派遣更多部队！",objectives={"雷米要你去和闪金镇的治安官杜汉谈一谈。"}]])
R(45,"罗尔夫的下落",[[description="进一步检查这个地区之后，你发现有蹼状的脚印沿着石碑湖岸一直向北延伸。在东边远处，你隐隐约约看见有一个鱼人的村落。$B$B也许罗尔夫就在那儿丧了命……",objectives={"到鱼人村去寻找罗尔夫，或是他死亡的消息。"}]])
R(46,"悬赏鱼人",[[description="暴风城军队悬赏清除那些艾尔文森林内的鱼人潜伏者和鱼人强盗。杀了它们，把它们破损的鱼人鳞片给我带回来，暴风城军队会奖励你的。$B$B鱼人在北面的石碑湖附近建造了一座村庄，另外在南面的溪流分叉处还有一座村庄。",objectives={"给艾尔文森林东部的桥边的卫兵托马斯带去8个破损的鱼人鳞片。"}]])
R(47,"金砂交易",[[description="这一带的狗头人有时会带着金砂出来活动。我真的很需要这些金砂……给我找一些来，我会以镇子里最高的收购价格买下来——最高的价格！",objectives={"为闪金镇的雷米收集10袋金砂，这种东西可以从艾尔文森林的狗头人身上找到。"}]])
R(48,"琥珀酒",[[description="高高的葡萄树生长在南方$b蜿蜒的清泉流过树根旁$b纯净宛如女神的眼泪$b你快点去给我弄来圣泉水！",objectives={"把圣泉之水带给葛瑞姆·雷酒。"}]])
R(49,"琥珀酒",[[description="琥珀的颜色是我毕生之爱$b就像西山夕阳下的云彩$b为了它的诞生呀，勇敢的少年我召唤你$b我要黑麦、大麦和玉米！",objectives={"葛瑞姆·雷酒需要大麦、黑麦和玉米各一袋。"}]])
R(50,"琥珀酒",[[description="我捣！我搅！我捣！我搅！$b少了玩意就没法搞好$b我要一种够硬的金属来当罐儿$b给我弄些真银来，我就唱完歌儿！",objectives={"葛瑞姆·雷酒需要一些真银。"}]])
R(51,"琥珀酒",[[description="还没过滤但是刚刚蒸馏$b就像是新皮甲还没上油$b然后得烧它七八斤炭呀$b我说你赶紧动身去办呀！",objectives={"带给葛瑞姆·雷酒一枝枫树枝。"}]])
R(52,"保卫边境",[[description="你好，$N。我们离开闪金镇越远，在森林里遇到的野生动物就越凶猛。东谷伐木场几乎每天都要受到狼和熊的攻击！$B$B我们需要你的帮助。",objectives={"杀掉8只觅食的灰狼和5只森林熊幼崽，然后回到艾尔文森林东部的桥边去见卫兵托马斯。"}]])
R(53,"琥珀酒",[[description="甜美的液体清澈如婴儿泪$b百年的陈酿色深如琥珀$b但在把它放进地窖存着前$b造个橡木大桶来盛着先！",objectives={"给葛瑞姆·雷酒带去一捆烧焦的橡木。"}]])
R(54,"去闪金镇报到",[[description="$N，如今你已经被证实是一位非常关心北郡的安全的$c了。现在我要派遣你去保卫艾尔文森林的周边地区。$B$B如果你接下了这个任务，就把这些文件送到闪金镇的治安官杜汉手里。沿着向南的大道走，穿过北郡的关卡就能看到闪金镇了。",objectives={"将治安官玛克布莱德的文件带给闪金镇的治安官杜汉。"}]])
R(55,"摩本特·费尔",[[description="摩本特·费尔的老巢就在一个可以俯视乌鸦岭墓地的山顶上。他的日子就快要到头了……$B$B杀掉他，让我们不被他的邪恶所侵害。为我复仇吧，也为了夜色镇的人民！",objectives={"对摩本特·费尔使用摩本特的克星，杀掉他，然后把摩本特的克星交给斯温。"}]])
R(56,"守夜人",[[description="作为守夜人的指挥官，我发过誓要保卫夜色镇人民的安全。暴风城已经把他们驻守在这里的部队撤了回去，现在我们只能依靠自己了。$b$b如果你觉得可以胜任，就请帮助我们吧！到夜色镇南部的静谧花园去，杀掉8个骷髅战士和6个骷髅法师。我们必须尽量减轻亡灵所能够带来的压力！",objectives={"夜色镇的指挥官指挥官阿尔泰娅·埃伯洛克要你去杀掉8个骷髅战士和6个骷髅法师。"}]])
R(57,"守夜人",[[description="$N，我收到报告说有亡灵在森林里出没！如果你能应付的话，就到乌鸦岭的大墓地去杀15个骸骨魔和15个恐怖骸骨。另外，在夜色镇南部的静谧花园一带也都发现有骷髅在出没。我们一定要把这些亡灵驱逐出暮色森林！",objectives={"指挥官阿尔泰娅·埃伯洛克要你去杀掉15个骸骨魔和15个恐怖骸骨。"}]])
R(58,"守夜人",[[description="乌鸦岭的形势仍然十分严峻，$N。但是我们没有足够的人手来保卫夜色镇的安全，对于乌鸦岭更是一筹莫展。你必须迅速赶到乌鸦岭去，在东部的陵墓里除掉20个瘟疫食尸鬼。",objectives={"夜色镇的指挥官阿尔泰娅·埃伯洛克要你到乌鸦岭的东部陵墓去杀20个瘟疫食尸鬼。"}]])
R(59,"布甲和皮甲",[[description="为了表彰你的智慧和勇敢，我把这个标记给你，用在护甲上应该很不错。你把它交给东谷伐木场的萨拉·迪博雷恩，她会为你做件合适的护甲。这件护甲在你为保卫艾尔文森林作战时应该用得到。$B$B东谷伐木场就在卫兵托马斯所在的哨所的东面。",objectives={"把暴风城护甲标记交给萨拉·迪博雷恩。"}]])
R(60,"狗头人的蜡烛",[[description="你好，$g亲爱的先生:尊贵的女士;！你有时间吗？$B$B我和我兄弟在暴风城开了个药店，而我现在正要在这一带找些大蜡烛，以便提取其中的蜡。你能帮助我吗？$B$B你可以在狗头人身上找到大蜡烛，我听说在艾尔文森林的矿洞一带有很多狗头人……在南边的法戈第矿洞和东边的玉石矿洞里都有不少。我建议你去这两个矿洞里看看。",objectives={"为闪金镇的威廉·匹斯特收集8支大蜡烛。"}]])
R(61,"送往暴风城的货物",[[description="我兄弟莫根正在暴风城等我送蜡烛过去，但我自己实在忙得抽不开身。如果你愿意把这批货物送过去的话，他会重金酬谢你的。$B$B我已经把蜡烛装好了，莫根在我们的店里——匹斯特的药剂店，就在暴风城的贸易区。",objectives={"把威廉的货物交给暴风城贸易区的摩根·匹斯特。"}]])
R(62,"法戈第矿洞",[[description="出问题的还不止北郡的矿洞！我接到报告说艾尔文森林的法戈第矿洞已经成了狗头人的天堂。$B$B去那里查看一下这些报告是否属实，然后回来告诉我。法戈第矿洞就在闪金镇的正南方，斯通菲尔德农场和马科伦农场之间。",objectives={"调查法戈第矿洞，然后回到闪金镇去见治安官杜汉。"}]])
R(63,"水之召唤",[[description="沿着银松森林海岸前行，在瑟伯切尔的西边有一处被瘟疫玷污过的神殿。那里的水灵不再和我们交谈，你的任务就是消灭那个污染源并净化那个水池。$B$B将元素护腕和剩余的泉水放置在火盆上，就可以进行召唤水灵的仪式了。$B$B把能够证明你完成了任务的证据带回来给我，然后我就会给你图腾。",objectives={"击败堕落的水之魂，把堕落水之魂的护腕和剩余的最纯净的水放在银松森林的圣泉火盆上。"}]])
R(64,"遗失的怀表",[[description="太可怕了呀！弗娜一听到田里的骚动就把我叫醒了。你猜怎么着，田里全是小流氓。我们只能连夜逃出来，结果我就把我的怀表给忘在家里了。那块怀表是弗娜的爸爸在我们结婚的那天送给我的，我可不想让它落在那些潜行者手里。我应该是把那块表放在小农舍的衣柜里了，就在西边的那片南瓜田边上——你应该不会错过的。如果你能把它拿回来给我的话，我肯定会对你感激不尽的！",objectives={"农夫法布隆希望你能帮他找回他的怀表。怀表在西边南瓜田旁边的农舍的衣柜里。"}]])
R(65,"迪菲亚兄弟会",[[description="那群自称为迪菲亚兄弟会的流寇贼子将我们这些善良的平民赶离西部荒野，他们一定要为自己的罪行负责！我要求你去打探一下，我们必须知道到底谁是他们的头儿，还有他们都藏在哪儿。在湖畔镇的旅馆里有个叫威利的小贼以前欠了我一个人情，你可以找他帮忙。$b$b到艾尔文森林东边的赤脊山去吧，湖畔镇就那座山的脚下，到那里去碰碰运气。",objectives={"格里安·斯托曼要求你去和湖畔镇的威利谈一谈。"}]])
R(66,"斯塔文的传说",[[description="昨夜，一阵突如其来的不安掠过我的全身，令我感到我的孙女奥利萨正处在巨大的危机中。我用纸牌进行了占卜，“死神”在桌上凝视着我。$b$b在长时间的沉思之后，我找到了这个可怕而神秘的事情的一点线索，有一个名字进入了我的脑中，那就是“斯塔文”。$b$b到城镇大厅里去找书记员达尔塔吧，看看你能否得到更多关于这个斯塔文的信息……我担心包括你我在内的所有人都有危险。",objectives={"去夜色镇大厅找到书记员达尔塔。"}]])
R(67,"斯塔文的传说",[[description="斯塔文？让我查查镇里的档案。$b$b斯塔文…斯塔文…让我找找……啊，找到了！这里有斯塔文·密斯特曼托的档案。最后一次记录的地址是在月溪镇的学校里。哎呀，都是过时的东西了！$b$b朋友，你能帮我个忙吗？如果你碰巧路过月溪镇的话，也许能找到一些有关这个家伙的新消息，别忘了告诉我一声，好让我更新档案。",objectives={"到月溪镇的学校去寻找关于斯塔文的新信息，回来告诉书记员达尔塔。"}]])
R(68,"斯塔文的传说",[[description="你在旧提箱里找到了一封覆满灰尘的信。",objectives={"把覆满灰尘的信交给书记员达尔塔。"}]])
R(69,"斯塔文的传说",[[description="哎呀！我上次肯定漏掉这个了。斯塔文的档案中的第一个地址下面还有另一个地址，这个地址被擦掉了一点。看起来好象他还去过闪金镇的狮王之傲旅店。你愿意的话就去那里查查看吧，$N。",objectives={"到狮王之傲旅店去问问那里的人，看看他们是否听说过斯塔文这个人。"}]])
R(70,"斯塔文的传说",[[description="斯塔文的名字让我想起点什么…哦，想起来了！$b$b很多年前的一个雷雨交加的夜晚，有个信差到这儿来过夜避雨。快到午夜12点的时候，他一边尖叫着一边从楼上跑下来，苍白的脸上满是惶恐的神色，最后他穿着睡衣逃进了瓢泼的大雨中。$b$b由于走得太匆忙，他忘了拿走楼上箱子里的信，不过后来也没有再回来取过。喏，这一封是写给斯塔文的一个住在暴风城运河区的朋友的，你自己拿去看吧。",objectives={"从箱子中拿出斯塔文的未寄出的信，把它送到暴风城的运河区。"}]])
R(71,"回复托马斯",[[description="把你找到的两块铭牌交给桥边的卫兵托马斯，让他知道两个卫兵的死讯。",objectives={"把罗尔夫和马拉凯的铭牌交给艾尔文森林东部桥边的卫兵托马斯。"}]])
R(72,"斯塔文的传说",[[description="我父亲从前是这幢宅子的管家，在那场大屠杀之后，他费了好大的工夫才把地上的血迹拖干净，不过这跟我们要谈的事情没什么关系。$b$b弗林特雷家的基金早已经用光，现在家里最后的财产都已经准备要拍卖掉了，那些像秃鹫一样贪婪的征税官！你要是真想找些什么资料，不妨在这堆垃圾里找找看，天知道你能找到什么。",objectives={"在打包的东西里寻找线索。"}]])
R(73,"<TXT> No Reward")
R(74,"斯塔文的传说",[[description="你在箱子里找到了几样东西：一些有霉味的、看上去像是传家宝的东西，一副家庭肖像画，一些打猎所得的战利品和几本旧书。在箱子底部的一个花瓶下面，你找到了一张被撕破的日记书页。",objectives={"你找到的这张被撕破的日记书页给你提供了又一个线索。"}]])
R(75,"斯塔文的传说",[[description="我刚刚搬进来住的时候发现楼上的箱子里有一捆羊皮纸，我想看看那些羊皮纸上写了什么，但是迷雾却让我根本看不清楚。$b$b给我这个快瞎了的老人帮个忙吧，去检查一下楼上箱子里的东西，看看有没有什么有关斯塔文的信息。我记得有一张褪色的日记书页，你肯定会对它感兴趣的。把它拿过来，我会尽力帮助你的。",objectives={"治安官哈迦德要你从楼上的箱子里找出一张褪色的日记书页。"}]])
R(76,"玉石矿洞",[[description="多亏了你，我们才知道法戈第矿洞里出现了很多狗头人。现在我们还需要一个人去更远处的玉石矿洞侦察。$B$B去查看一下玉石矿洞，确定那里是否有狗头人。向东沿着大路走，一直走到阿祖拉之塔，然后往北走就会看到山脚下的矿洞。",objectives={"查看玉石矿洞，然后回到闪金镇去向治安官杜汉报告。"}]])
R(77,"收集蜜糖",[[description="我这里有德兰·杜佛斯需要的包装材料。我会帮助你为玛尔顿那烦人的老爸包装他要的蜜糖……不过你得给我多带几瓶蜜糖回来。它们就在靠近隐匿石一带，在那座荒废掉的部落村庄的箱子里，可恶的泥浆怪和软泥怪霸占了那块地方，有传言说它们是由一些大型软泥怪领导着的。但不管怎么样，你必须找到蜜糖并把它们带回来让我进行包装。",objectives={"从隐匿石一带被部落废弃的基地中的箱子里找到10瓶辛特兰蜜糖。"}]])
R(78,"斯塔文的传说",[[description="我知道有人可以帮你。我以前领导暴风城卫队的时候，经常去夜色镇的血鸦旅店喝酒。那儿的老板斯密茨对当地的情况了如指掌。把这张东西给他，看看他对此有什么说法。",objectives={"把褪色的日记书页带给旅店老板斯密茨。"}]])
R(79,"斯塔文的传说",[[description="多年来我一直在追寻这个斯塔文的消息。几年前那些来访的贵族被杀之后，我曾和哈迦德一起去调查。我发现了这些沾满泥污的纸，但是一直没有都想到把这上面的笔迹和树林里的那个疯子联系在一起。你提供的线索证明了他的罪行。赶快把这个交给指挥官阿尔泰娅·埃伯洛克，告诉她你所发现的一切。",objectives={"把沾满泥污的日记书页交给指挥官阿尔泰娅·埃伯洛克。"}]])
R(80,"斯塔文的传说",[[description="有一段时间我一直注意着斯塔文这个讨厌的家伙。如果这些东西都是他写的，那就足以给他定罪了。$b$b书记员达尔塔多年以来一直负责着镇里的档案，他很擅长辨认笔迹。把这张纸给他，看看是否和档案里面斯塔文的签名笔迹相吻合。",objectives={"把染血的日记书页交给书记员达尔塔。"}]])
R(81,"送回蜜酒",[[description="我在德兰要的东西上花了好大的工夫，因为除了额定装进桶里的蜜酒之外，他还要求额外再加几瓶！虽然我对德兰这个家伙的评价并不是很高，但是这世上没有比往酒桶里死命塞瓶子更糟的事情了……你来得正是时候。$B$B现在把这个桶送到德兰·杜佛斯那里去，他在奥格瑞玛那里自己开了一家店。顺便代我向玛尔顿问好，我很希望能有机会再和他畅饮几杯。",objectives={"把桶交给奥格瑞玛的德兰·杜佛斯。"}]])
R(82,"腐化之巢",[[description="好吧，你的报告中提到了虫子……我们现在知道的是……它们正使得原本是腐化之巢所在区域的水池变得干涸，其它方面我们一无所知。$B$B首先我们要搞清楚敌人到底是谁！你得去腐化之巢那里，把那些虫子的肢体带回来给炼金师匹斯特苏格研究，这样我们就可以确定到底是谁在那里搞鬼了！",objectives={"从腐化之巢找5个森提帕尔昆虫肢体，把它们交给加基森的炼金师匹斯特苏格。"}]])
R(83,"红色亚麻布",[[description="北郡的迪菲亚潜行者戴粗麻布面罩，而艾尔文森林的迪菲亚潜行者戴的是亚麻布的，我可以用这些好的亚麻布做些东西。$B$B给我找些亚麻布面罩，我可以用来给你做点什么。$B$B有人在西南部的布莱克威尔南瓜田外看见过迪菲亚潜行者出没。",objectives={"给东谷伐木场的萨拉·迪博雷恩带去6块红色亚麻布面罩。"}]])
R(84,"比利的馅饼",[[description="这是你要的馅饼。把这东西交给那个比利的时候，别忘了告诉他我希望他吃了噎死！",objectives={"把猪肉馅饼带给马科伦农场的比利·马科伦。"}]])
R(85,"丢失的项链",[[description="我的项链丢了，一定是那个讨厌鬼比利·马科伦偷走的！他总是像只老鼠一样在东边的马科伦农场里窜来窜去。$B$B请把我的项链拿回来给我，让我这可怜的寡妇得到一些安慰吧。",objectives={"和比利·马科伦谈一谈。"}]])
R(86,"比利的馅饼",[[description="给我吃点馅饼，也许我就能想起来是谁拿着项链了。我知道另一个农场里的波尼斯老太太做的猪肉馅饼很棒……$B$B我们的农场周围有野猪，如果你能给她找几块野猪肉，她就应该会给你烤一块馅饼。",objectives={"给斯通菲尔德农场的波尼斯·斯通菲尔德带去4块野猪肉。"}]])
R(87,"金牙",[[description="我在法戈第矿洞旁边玩的时候，不小心掉了那根，呃……我是说我看见了那个老太太的项链。别问我它怎么会在那儿……和我没有关系！$B$B不管怎样，我看到一个很壮实的镶着金牙的狗头人……他把项链捡起来跑到矿洞里了。你去找那个狗头人吧，我发誓，你肯定能在他身上找到项链的！",objectives={"把波尼斯的项链带给斯通菲尔德农场的波尼斯·斯通菲尔德。"}]])
R(88,"公主必须死！",[[description="布拉克威尔一家有一头得过奖的猪，它名叫“公主”。这头母猪巨大无比，还经常偷偷溜到我的农场里偷吃我的蔬菜！$B$B在它再次糟蹋了我的农场之前……必须把它给宰了！把它的项圈带回来证明你杀了它，我会给你一些奖赏的！$B$B公主一般在布莱克威尔南瓜田出没，那个南瓜田就在东边，比马科伦农场还要往东。在它肚子饿了之前杀死她，然后再回来告诉我！",objectives={"杀掉公主，把它的项圈带给斯通菲尔德农场的斯通菲尔德妈妈。"}]])
R(89,"止水湖上的桥",[[description="上次兽人入侵的时候，我们被迫把所有能找到的铁都熔了来制造子弹、刀剑和盔甲。万不得已，我们向暴风城请求援助，让他们运一船金属材料过来。谁料一群赤脊山豺狼人劫持了运送金属的船只，并逃进了湖畔镇后的山中。$b$b这样一来，我们这座桥的重修工程马上就要面临缺少材料的困境了。如果你能给我带回5根铁矛和5个铁铆钉，我一定会奖励你的。$b$b快点去吧！",objectives={"给湖畔镇的工头奥斯洛带回5根铁矛和5个铁铆钉。"}]])
R(90,"干烤狼肉串",[[description="干烤狼肉串是有口皆碑的美食！你想吃吗？我当然可以为你做一些，不过得先给我找点材料。给我找些暴风城特产调料外加10块狼肋排来就可以了。这儿的森林里遍地都是狼，想找点肋排肯定不是问题。至于调料，你得到暴风城运河区的花店里去找菲利希亚·加姆。",objectives={"收集10块狼肋排和1份暴风城特产调料，再回夜色镇去找厨师格鲁奥。"}]])
R(91,"所罗门的律法",[[description="暴风城的一群死敌在赤脊山的东侧的山脚下建立起一片营地，这些邪恶的暴徒一直在我们的小镇中传播着恐惧。莫甘斯是这群恶徒的头领。$b$b他已经控制了暗皮豺狼人氏族，让那些邪恶的野兽为他卖力。根据湖畔镇的法律规定，协犯最高可以被判处死刑。$b$b这些肮脏的豺狼人一定要被处死！$b$b给我带回10个暗皮坠饰来，你就可以得到我们的奖励。",objectives={"给湖畔镇大厅的拜里弗·科纳彻尔带回10个暗皮坠饰。"}]])
R(92,"赤脊山炖肉",[[description="没什么能比烹制赤脊山炖肉更让我高兴的事了，但是现在有个小问题。自从兽人们出现之后，我就得没日没夜地忙着给暴风城军队的整整一个旅供应食物，我的食品柜早已是空空如也了。如果你能给我找来一些材料的话，我很乐意给你做点好吃的。$b$b只要给我带来5块硬秃鹫肉，5个巨型血牙野猪头和5份香脆蜘蛛肉就行了。",objectives={"湖畔镇的厨师布雷纳想要5块硬秃鹫肉，5个巨型血牙野猪头和5份香脆蜘蛛肉。"}]])
R(93,"黑蟹蛋糕",[[description="我可以告诉你个秘密——黑“蟹”蛋糕实际上是用蜘蛛腿做的！听起来是有点恶心，不过这种蛋糕的味道绝对一流！给我找点粘糊的蜘蛛腿来，我很快就能给你做好。$B$B听说结网毒蜘蛛身上很容易拿到这种东西——它们的巢穴就在东北部的丘陵和小河之间，暮色森林里的其它蜘蛛身上也有这东西。",objectives={"收集6条粘糊的蜘蛛腿，把它们交给夜色镇的厨师格鲁奥。"}]])
R(94,"法师的眼线",[[description="我的对手莫甘斯是个强大而邪恶的法师，他就住在赤脊山的伊尔加拉之塔里。我已经找到了一种监视他的方法，只要通过阿祖拉之眼，就可以在很远的地方看到他的一举一动。$B$B不过要研究他的思想……我还需要进一步的帮助。$B$B如果你愿意的话，就带着这个铭文饰品到伊尔加拉之塔去，把它放置在塔旁边的狮子雕像身上。$B$B完成之后，阿祖拉的铭文饰品就会告诉我们，莫甘斯又在准备什么邪恶的计划。",objectives={"把阿祖拉的铭文饰品放置到赤脊山伊尔加拉之塔旁边的狮子雕像身上。"}]])
R(95,"斯温的复仇",[[description="我原来在东南部的一座农场里工作……直到有一天，从逆风小径来的黑暗强盗洗劫了我的农场，趁我不在的时候杀了我的全家！$B$B我回来时发现有个模糊的人影在我家的谷仓附近埋了一件什么东西，可惜我没能抓住他。我也不敢在这里继续逗留，因为我害怕会有黑暗强盗追踪我。直到现在，我都都不知道那人到底藏了什么。$B$B如果你能去找出真相，我一定会感激你的。那人埋东西的地方就在我的谷仓附近的一个老树桩后面。",objectives={"到斯温的农场去找出埋在老树桩后面的是什么东西。"}]])
R(96,"水之召唤",[[description="拿着碎片，拿着碎片……赋予生命。$B$B赋予生命……理解生命，理解水就是生命本身……而堕落则会扼杀生命。$B$B你保护了生命，并将水的力量赋予了生命……",objectives={"把水灵碎片交给贫瘠之地的水之先知伊斯伦。"}]])
R(97,"斯塔文的传说",[[description="$N，你赶快去告诉指挥官阿尔泰娅·埃伯洛克，这两个笔迹完全符合！她的怀疑是正确的！",objectives={"把这个消息告诉指挥官阿尔泰娅·埃伯洛克。"}]])
R(98,"斯塔文的传说",[[description="斯塔文·密斯特曼托是个恶贯满盈的罪犯，很多无辜的人都死在他手中。毫无疑问，他犯下了无数宗罪案，给夜色镇带来了又一个威胁。天知道这个恶棍又在策划什么邪恶的行动。斯塔文的家就在小镇北边，$C，你去把他就地处死吧。$b$b完事以后把他的家族戒指带给伊瓦夫人作为证明，毕竟是她的预感导致我们揭露了这个可怕的凶手，她为夜色镇立了一功。",objectives={"干掉斯塔文·密斯特曼托，把他的家族戒指带给伊瓦夫人看看。"}]])
R(99,"阿鲁高的愚行",[[description="在我对阿鲁高的魔法的越来越了解的同时，我对这个蠢货的鄙视与轻蔑也日益加深。我基本上完成了我对他所谓“拯救”的研究。$b$b在我了解到是什么样的巫术导致了焚木村的奇怪现象之后，我也就算是了解透彻了。白天，那些农夫们都是好端端的人。但太阳一落山，他们就变成了月怒狼人。$b$b我需要从阿鲁高给他们戴上的镣铐提取出一些能量来。带给我6副焚木镣铐，$N。",objectives={"给瑟伯切尔的达拉尔·道恩维沃尔带回6副焚木镣铐。"}]])
R(100,"水之召唤",[[description="你吟诵完了咒语，瞬时间火盆便放出了万丈光芒。水滴和火焰接触时的噼啪声越来越弱，你可以感觉到笼罩在周围的堕落气息已经被消灭了。",objectives={"和银松森林的水之魂谈一谈。"}]])
R(101,"惩罚图腾",[[description="有一股神秘而邪恶的势力在森林里蔓延，我们必须更加小心地保护自己，$N。林中的夜风悄声告诉我，你很快就会遭遇巨大的危机。$b$b尊贵的$c，如果你想保护自己，就请给我找来10颗食尸鬼的牙齿、10根骷髅的手指和5瓶蜘蛛毒液。我会为你制作一个惩罚图腾，让那些企图伤害你的敌人自食其果。",objectives={"收集10颗食尸鬼的牙齿、10根骷髅的手指和5瓶蜘蛛毒液，把它们交给夜色镇的伊瓦夫人。"}]])
R(102,"西部荒野的豺狼人",[[description="暴风城已经把我们给遗弃了。一股腐朽与堕落的狂风正肆虐在西部荒野的平原之上。这里是我的故乡，我绝对不会背叛那些和我一样坚持留在这里的民众们。我们这些农夫必须站出来，为自己赢得生存的空间。$b$b若你愿意接受我们派给你的任务，就去巡视西部荒野的草原吧。找到那些可恶的豺狼人，把它们干掉，似乎这些家伙与死亡矿井里的小贼们有些联系。给我带回八只豺狼人的爪子来，我会奖励你的英勇行为的。",objectives={"给哨兵岭的丹努文队长带回8只豺狼人的爪子。"}]])
R(103,"长明的灯塔",[[description="灯塔管理员一家被杀的那一个晚上实在是太可怕啦！我就那样无助地看着老瞎眼带着那群鱼人毁了他们全家。但过去的事就让它过去吧，我现在关心的是无尽之海中那些正把船只驶近暗礁的水手们的生命。如今，维持着灯塔上火炬不至熄灭的任务就落在我一个人身上了。$b$b从那些收割机器人身上找来5瓶灯油吧，这样我才能保住火炬上的火种。",objectives={"给西部荒野灯塔中的葛瑞森船长带回5瓶灯油。"}]])
R(104,"海岸上的威胁",[[description="当我的生命终结在了那片岩石上之后，我根本不知道死后的世界会是怎样的。那天晚上的灯塔一片漆黑，因为老瞎眼吓跑了管理员全家。他们本已经逃跑了，但那天晚上他们又回来想要点亮灯塔，结果老瞎眼带着一群野蛮的鱼人突袭了灯塔。这一次，管理员的全家都在我面前无助地死去了……$b$b如果你在海岸边看到老瞎眼的话，就杀死它，把它的鳞片给我带回来，我会奖励你的。",objectives={"将老瞎眼的鳞片交给西部荒野灯塔旁的葛瑞森船长。"}]])
R(105,"啊，安多哈尔！",[[description="啊，进攻安多哈尔并彻底击败那个巫妖的时刻终于来临了！$B$B召唤者阿拉基就盘踞在安多哈尔的废墟中，他的贴身卫队无时无刻不在他的身边保护着他。你需要召集强大的盟友才能击败他。$B$B消灭巫妖，$N，从它的护符匣里拿出一块碎片来，作为你获胜的证据！",objectives={"把阿拉基的护符匣碎片交给西瘟疫之地亡灵壁垒的高级执行官德灵顿。"}]])
R(106,"年轻的恋人",[[description="天哪，我太痛苦了！我爱上了托米·乔·斯通菲尔德，但我们两家却有着不共戴天的仇恨。所以我不能去见他，可我无时无刻不在怀念那张英俊的面庞啊！$B$B请你把这封信带给托米·乔，他一般会在斯通菲尔德农场西边的河流附近，他们的农场就在这里的正西方。",objectives={"把梅贝尔的情书带给托米·乔·斯通菲尔德。"}]])
R(107,"给威廉·匹斯特的信",[[description="威廉·匹斯特肯定有能让这两个年轻人见面的办法！$B$B把这个便笺拿去交给威廉，他现在正住在闪金镇的狮王之傲旅店。",objectives={"把斯通菲尔德老奶奶的便笺交给威廉·匹斯特。"}]])
R(108,"<TXT> Mystery Reward")
R(109,"向格里安·斯托曼报到",[[description="看上去你参加过不少战斗，$c。如果你还没有去格里安·斯托曼那里报到的话，就赶快去吧。他是人民军的领袖，这是个专门负责保卫西部荒野的民兵组织，我敢说你是能帮他一些忙的。一般来说，你可以在哨兵岭的石塔周围找到他，那地方就在西部荒野中部的路边上。",objectives={"去和格里安·斯托曼谈一谈，他一般就在哨兵岭的石塔旁，这座石塔位于西部荒野中部地区的路边。"}]])
R(110,"昆虫研究",[[description="我要去看看谢申克的勘探装置……然后把他的东西整理一下。我预感到我们将会遇到更大的麻烦。$B$B我想让你去见见炼金师匹斯特苏格，了解一下他的研究是否有进展。如果他有什么新的发现，你就尽快向我回报。",objectives={"到加基森的炼金师匹斯特苏格那里去了解关于昆虫的研究有没有新的进展。"}]])
R(111,"托米的祖母",[[description="求求你，$N，去和我的奶奶谈一谈吧。如果有人能想办法让我和梅贝尔在一起的话，那个人一定是奶奶。$B$B她就在我们家的屋子里。",objectives={"和斯通菲尔德农场的米斯通菲尔德老奶奶谈一谈。"}]])
R(112,"收集海藻",[[description="我可以为梅贝尔配制一种隐形水，这样她就可以悄悄溜出马科伦农场去见托米·乔。不过我需要一些水晶海藻来配制这种药水。$B$B水晶海藻一般生长在海里……不过有时候鱼人会收集它们。去看看水晶湖附近的鱼人身上有没有海藻，水晶湖就在闪金镇的东边。",objectives={"收集4片水晶藻叶，把它们带给闪金镇的威廉·匹斯特。"}]])
R(113,"昆虫研究",[[description="高级勘探员菲兹杜瑟必须尽快看到这份报告。实际上……每个人应该知道这件事的重要性：我们正面临着一个巨大的威胁，这个威胁不仅仅涉及到塔纳利斯和加基森，如果不及时控制的话，整个卡利姆多大陆的南部地区都会有麻烦！而且这个威胁显然已经迫在眉睫了。$B$B让菲兹杜瑟把这份报告给你复制几份，然后你去把它广为传播。一定要让所有人都知道这个威胁的存在！",objectives={"把这份报告带给加基森的高级勘探员菲兹杜瑟，让他按照炼金师匹斯特苏格的要求为你复制一份报告。"}]])
R(114,"梅贝尔的隐形水",[[description="把隐形水带给梅贝尔·马科伦。它的隐形效果应该可以持续到她见到托米·乔的时候。",objectives={"把隐形水带给梅贝尔·马科伦。"}]])
R(115,"暗影魔法",[[description="黑石氏族的兽人在赤脊山脉的侵略行动得到了暗影法师的支援，他们带来了一种具有强大黑暗力量的器具——午夜宝珠。这些宝珠给赤脊山脉的保卫者们造成了巨大的伤亡，并迫使我们放弃所有在战斗中被这种宝珠污染了的器物,因为它们已经沾染了恶魔的力量。$B$B猎杀这些黑石暗影法师，并给我带回他们的午夜宝珠来。我将会把这些东西妥善地处理掉，还这世界一片清净！",objectives={"给湖畔镇的治安官马瑞斯带回3颗午夜宝珠。"}]])
R(116,"旱季",[[description="我最近真是感觉有点没劲，$N。这些酒瓶子都快空了，运酒的船也很久没来了，这都怪那些该死的兽人。$b$b也许你帮我一个小忙？$b$b我希望你能从住在西部荒野的葛瑞姆·雷酒那里搞一桶雷霆啤酒，从暴风城搞一桶葡萄酒，从夜色镇搞一瓶月光酒，还有还有，再从闪金镇搞一袋蜂蜜酒来。把这些好酒都给我弄来，我会重重谢你的。",objectives={"湖畔镇的酒吧老板丹尼尔需要一桶雷霆啤酒，一桶葡萄酒，一瓶月光酒，还有一袋蜂蜜酒。"}]])
R(117,"雷霆啤酒",[[description="快点，朋友，动作要快$b要酿更多的酒来卖$b有人要酒呀没人要菜 $b一捆蛇麻草，就够酿酒来",objectives={"给葛瑞姆·雷酒带去5捆蛇麻草以完成他的特酿。"}]])
R(118,"马掌",[[description="我把所有的铁都用来打造暴风城卫兵的装备，结果没有剩余的铁来打马掌了！$B$B把这封信带给闪金镇的铁匠阿古斯，信上说明了我现在的情况并要求他运一批马掌过来。",objectives={"把弗纳的便笺交给闪金镇的铁匠阿古斯。"}]])
R(119,"回复弗纳",[[description="好的，我会给他送去50套马掌……$B$B就是这些，你看，全部都打包好了，随时可以出发！告诉弗纳，我很高兴和他做生意，哦，对了，提醒他看清楚箱子上的标签！",objectives={"回去找赤脊山的弗纳·奥斯古，把铁匠阿古斯的一箱马掌交给他。"}]])
R(120,"送往暴风城的信",[[description="这真是段难熬的日子呀，$c。兽人的攻势没完没了，如果援军还不来的话，湖畔镇就要保不住了！我现在委托给你的这封信是非常重要的。立刻将这份报告送给暴风城的马库斯·乔纳森将军。你把信送到了那边之后，就马上带着那边回复的消息回来，无论是好消息还是坏消息，我都要尽快知道。$b$b现在就出发吧，快去快回！",objectives={"所罗门镇长要求你给暴风城的马库斯·乔纳森将军送一封信，并且在完成任务之后尽快回报。"}]])
R(121,"送往暴风城的信",[[description="在我等待着国王陛下的回应时，希望你能把这封信交给所罗门镇长。$b$b快去吧，$c！",objectives={"将暴风城的马库斯·乔纳森将军的回信带给湖畔镇的所罗门镇长。"}]])
R(122,"雏龙的鳞片",[[description="我需要一些黑龙雏龙腹部的鳞片来支付从阿古斯那里买马掌的钱。如果你能帮我搞到6块鳞片的话，在付给阿古斯一些以后……我还能用剩下的给你做点好装备。$B$B黑龙雏龙经常在湖畔镇南方游荡，猎杀它们的时候要多加小心。",objectives={"从黑龙雏龙身上收集6片雏龙的腹鳞，把它们交给赤脊山的弗纳·奥斯古。"}]])
R(123,"收货人",[[description="这是一张日程表，记录了某个人被称作“收货人”的人在某天某时会收到从艾尔文森林的矿洞运来的一车黄金。$B$B根据日程表所述，这个收货人好像就住在艾尔文森林东部的布莱克威尔南瓜田附近。$B$B这件事非常重要，你必须向闪金镇的治安官杜汉报告。",objectives={"去闪金镇找治安官杜汉，把收货人的交易日程表交给他。"}]])
R(124,"豺狼人的乱吠",[[description="似乎有这些整天攻城的兽人还不够乱！我发现最近老有一些混蛋豺狼人鬼鬼祟祟地沿着山脊在我的马场北面游荡，而且还偷我的马……$B$B如果你能把这些豺狼人都干掉的话，我，还有我的马都会感谢你的。",objectives={"杀掉10只赤脊山蛮兵和8只赤脊山秘法师，然后向弗纳·奥斯古复命。"}]])
R(125,"丢失的工具",[[description="我本来可以在这儿大干一场的, $N。可是，我的工具还没到货，由于镇子被包围了，我们很难得到外面来的补给。我本来托人从闪金镇把工具用马车运过来，可是桥被砸断了，他们只好改用船运，结果那船又被兽人的投石车给打沉了。不过，算是不幸中的万幸吧，我的工具箱没坏，它只是沉进了湖底。$b$b帮我把工具箱找回来吧，$N，我会付给你不错的酬劳的。",objectives={"湖畔镇的工头奥斯洛希望你帮他找回沉入止水湖底的工具箱。"}]])
R(126,"群山中的嚎叫",[[description="$N，那些豺狼人居然还没死绝！我还能听见他们在湖畔镇周围的山区里打猎时发出的嚎叫声。其中有一个声音喊得最响——那是犹勒，他们的头儿。$B$B干掉犹勒，把他的手下都给轰走！把这个混蛋的爪子给我带回来。$B$B不过你得小心点，这家伙能当上他们的头儿自然是有两把刷子的。犹勒可不是个低能的混血豺狼人，他是纯种的……",objectives={"将犹勒的爪子带回给湖畔镇的弗纳·奥斯古。"}]])
R(127,"卖鱼",[[description="止水湖的斑点太阳鱼是天下闻名的美味。它们总是供不应求……可我这里的存货已经不够了！$B$B给我带回10条鱼来，我会好好酬谢你的。哦，如果你不会捕鱼的话……可以从鱼人那里抢来！",objectives={"给湖畔镇的码头管理员巴伦带去10条斑点太阳鱼。"}]])
R(128,"悬赏：黑石氏族",[[description="我们一定得清剿黑石氏族。这群强盗入侵了我们的国家，占据了本应属于暴风王国的群山。根据线报说，在他们的氏族中，每支分队的领袖都被称为“勇士”，你很容易就能找到他们。他们的营地大致在北方，就在通向燃烧平原的道路西边。$b$b所罗门镇长希望有人能把这群卑鄙邪恶的家伙都消灭光。如果你有意帮助我们的话，杀死15名黑石勇士，然后向我复命。",objectives={"杀死15名黑石勇士，并向湖畔镇的卫兵豪维复命。"}]])
R(129,"免费的午餐",[[description="你能帮我一个小忙吗？我给卫兵帕克准备好了午饭，可他正在值勤……他是一个又高又壮的暴风城卫兵。他在外面是能自己保护自己的，可我们这样的寻常市民可不行，所以我没法去给他送饭……$B$B所以呢，如果你能帮我把他的午餐带给他的话，我也会给你提供一份免费的午餐！帕克就在通往暮色森林的路上巡逻。",objectives={"将卫兵帕克的午餐带给他，他就在通向夜色镇的路上巡逻。"}]])
R(130,"寻访草药师",[[description="你回到达希那边的时候，能替我捎几朵花给她吗？你可以在湖畔镇西边的草药店里买到花。$B$B不过，你去买花的时候……千万别告诉药草师玛蒂这花是谁买的，也别说是要送给谁的……",objectives={"找到草药师玛蒂·詹罗斯，和她谈一谈。"}]])
R(131,"水仙诉衷情",[[description="这是你要的花。我为你选了水仙，这是我最喜欢的花儿！",objectives={"将水仙花送给达希。"}]])
R(132,"迪菲亚兄弟会",[[description="我现在可是冒着生命危险在和你说话。迪菲亚那帮人也是听命于某个神秘人士的，我上次听说他们与许多种族都有过合作，豺狼人，狗头人，甚至还有地精。$b$b把这张便笺交给斯托曼。上面写着我所知道的关于迪菲亚兄弟会的一切。",objectives={"将威利的便笺交给西部荒野的格里安·斯托曼。"}]])
R(133,"食尸鬼假人",[[description="我住得离镇子太远了，根本得不到保护。那些食尸鬼和行尸走肉还没有把我吃掉简直是个奇迹！其实昨天还有一群噬骨者来敲击我房子四周的墙！$B$B我得做个假人，一个用来吓唬食尸鬼的“稻草人”。我需要食尸鬼的肋骨来制作这个假人。你可以从食腐者、噬骨者、食脑者、腐烂者和瘟疫食尸鬼身上拿到这东西。$B$B给我带足够的肋骨来，我就会给你一些奖赏。",objectives={"收集7个食尸鬼的肋骨，然后把它们交给亚伯克隆比。"}]])
R(134,"食人魔潜行者",[[description="几个星期前，我离开家去远处采草药，有一群食人魔袭击了我！我落荒而逃的时候丢了一箱工具和草药。$B$B这些食人魔在把我赶跑之后大摇大摆地回到了暮色森林南边的食人魔山上，我的箱子肯定就在那一带。$B$B请帮帮我吧，$N，我很需要这个箱子，请你一定要帮我拿回来。",objectives={"把亚伯克隆比的箱子拿回来交给他。"}]])
R(135,"迪菲亚兄弟会",[[description="我现在很想知道威利所提到的“石匠”是个什么意思，或许这只是一个口误？石匠公会跟迪菲亚真的有联系吗？或许暴风城军情七处的首领马迪亚斯·肖尔会知道真相。把威利的便笺拿给他，看看他对这个越来越大的谜团有什么想法吧。他就在旧城区的兵营里。",objectives={"将威利的便笺交给暴风城的马迪亚斯·肖尔。"}]])
R(136,"杉德尔船长的宝藏",[[description="如果你读到这封信的话，那就意味着我，杉德尔船长，已经长眠在深深的水底了。所以，只要你按我的提示去做，我的宝藏就是你的了。$b$b首先你要找到一只小提箱，它应该就在西部荒野西海岸的某处船只残骸旁，如今八成已经快被沙子埋起来了。海岸边有许多处船只的残骸，但只有一只沉船旁有个锈掉的锚。箱子就在锚的旁边！在箱子里面，你可以找到下一条线索。",objectives={"找到杉德尔船长的手提箱，在箱子中寻找下一条线索。"}]])
R(137,"<NYI> <TXT> Stormwind Commendation",[[description="If you earn a commendation from one of our Marshals, then bring it to me.  It will be good for one of our Lion Emblem gloves.",objectives={"General Marcus Jonathan in Stormwind will accept a commendation from Elwynn Forest.  Bringing him such a document will reward you with a choice of armor."}]])
R(138,"杉德尔船长的宝藏",[[description="你开始读小条上的字：干得好，哥们！现在你可以开始向东走，到悬崖边的路旁好好找找，看有没有一处破烟囱，你可以在那旁边的木桶中找到下一条线索。",objectives={"找到废弃烟囱旁的老木桶，在桶里寻找下一条线索。"}]])
R(139,"杉德尔船长的宝藏",[[description="仔细搜索了木桶了之后，你发现了一小片羊皮纸。上面写着：现在，从桶这里转向北，像乌鸦飞翔一般绝不回头，一直走到你看见了海边悬崖上的风车为止。找到那风车旁的一个空水罐。仔细检查那个水罐，你就可以找到你要找的东西了。",objectives={"在风车旁的一个空水罐里寻找下一条线索。"}]])
R(140,"杉德尔船长的宝藏",[[description="显然，在这只旧罐子中藏着另一条有关杉德尔的宝藏的线索。纸上有几处墨水已经化开变得模糊不清，而且泛着一股威士忌的味道，不过你还是能从中辨认出这样的字迹：看来你找到我的威士忌罐子了，你离我的财宝已经很近啦！只要向西走到海边，然后一直向西游，你就可以游到放着小宝箱的岛上啦！",objectives={"找到杉德尔船长的箱子并打开它，取得你的奖励。"}]])
R(141,"迪菲亚兄弟会",[[description="过去的石匠公会是由一个名叫艾德温·范克里夫的人运营着的。第一次兽人战争结束后，范克里夫承接下了在兽人们留下的废墟上重建暴风城的重任。很显然，范克里夫对国王陛下在重建工程完成之后给予他们的待遇非常不满意。总之，解释这一大堆具体的事情要花些时间。$b$b我这里有一份详细的说明，让你拿到西部荒野去交给你的雇主。你得马上把这个给他带去！",objectives={"将肖尔的报告交给西部荒野的格里安·斯托曼。"}]])
R(142,"迪菲亚兄弟会",[[description="我们必须得找到迪菲亚兄弟会藏身的地方。$N，我的探子报告说，迪菲亚帮的信使们经常出现在月溪镇、金海岸矿洞和詹戈洛德矿洞之间的路上。我希望你能抓住一个信使，要是他试图反抗，就干脆把他干掉，然后把他身上所有的东西带回来。",objectives={"追捕西部荒野的迪菲亚信使，并将他身上携带着的信件交给斯托曼。"}]])
R(143,"送往西部荒野的信",[[description="暴风城的军队似乎遇到了些麻烦事，他们早就该到这里增援了，但直到现在还连个人影都没有。我们没多少时间可供浪费了！我不能再这样坐视人民继续无谓地牺牲而不去要求更多的增援。我听说西部荒野组建了一支民兵部队。$b$b把这封信带给他们的领袖格里安·斯托曼。或许斯托曼的人在国王陛下的部队到达之前能来帮忙抵挡上一阵。",objectives={"所罗门镇长要求你给西部荒野的格里安·斯托曼送一封信。"}]])
R(144,"送往西部荒野的信",[[description="所罗门镇长的信让我感到心痛。但显然他并不知道西部荒野的战事也很吃紧——或者他知道，但不得不抱着一丝希望来寻求我们的帮助。如果不是暴风城对西部荒野的人民不闻不问的话，我们也不会需要建立民兵组织的。$b$b将这封回信带给你在赤脊山的主人吧，$c。请转告他，我的心情也因为那么多勇士的牺牲而变得十分沉重。",objectives={"将格里安·斯托曼的回信带给所罗门镇长。"}]])
R(145,"送往夜色镇的信",[[description="看来我又得有事麻烦你了。我写一了封信给艾尔罗·埃伯洛克公爵，请求他从他的精锐部队——暮色森林守夜人——中抽出一些人来协助湖畔镇的防务。这封信必须马上呈送给他，而且你在旅途中要多加小心。埃伯洛克公爵是夜色镇的行政官，那座小镇就在暮色森林中，小心不要迷路了。",objectives={"所罗门镇长要求你给夜色镇的艾尔罗·埃伯洛克公爵送一封信。"}]])
R(146,"送往夜色镇的信",[[description="如果我不是和所罗门镇长私交甚密的话，我一定会以为他是个疯子的。因为暴风城拒绝出兵援助，就让我们把守夜人部队派去湖畔镇？守夜人部队就是因为这里被邪恶的魔法所影响才建立起来的。如果我把他们派离这里的话，恐怕还没等到他们走出森林，这里就会被邪恶的势力彻底吞没。$b$b把这封回信带给你在湖畔镇的主人吧。",objectives={"将埃伯洛克公爵的回信带给所罗门镇长。"}]])
R(147,"猎杀收货人",[[description="如果这个“收货人”是私自从我们的矿洞里开采黄金的话，那么他就是在偷窃王国的金库！把他就地正法，然后把他的交易日程表上提到的戒指带给我。也许这枚戒指能告诉我们这个“收货人”是在为谁工作……$B$B那张交易日程表上说“收货人”就藏在布莱克威尔南瓜田里，你应该到那儿去找他。",objectives={"找到“收货人”并将他杀掉，然后带着收货人的戒指回来见治安官杜汉。"}]])
R(148,"来自夜色镇的货物",[[description="哦，一个可怜的老人家还能做点什么呢？我需要从夜色镇拿点东西过来，不过路途太遥远，我又太老了……实在是走不动啊。$B$B你能去夜色镇给我拿点幽灵的发丝回来吗？你可以向伊瓦夫人要这东西，她的家就在夜色镇的广场旁。",objectives={"去和伊瓦夫人谈一谈。"}]])
R(149,"幽灵的发丝",[[description="有个可怜的亡魂叫盲眼玛丽，她总是在夜色镇南部小山上的农宅里出没。$B$B拿着这把鬼梳，让盲眼玛丽用它梳头。然后再把梳子拿回来，我可以从上面收集到需要的幽灵的头发。$B$B小心点，那个屋子里潜伏着一些可怕的东西……",objectives={"把鬼梳带给盲眼玛丽。"}]])
R(150,"鱼人偷猎者",[[description="鱼人们如今也成了一个问题。大群的鱼人渔民在止水湖沿岸下锚撒网，都快把湖里的鱼捞光了！我们得在他们把湖里的鱼都吃光之前把他们赶走！$B$B去猎杀那些鱼人！给我带回8片鱼人的鳍来，我会奖励你的。",objectives={"给湖畔镇的码头管理员巴伦带回8片鱼人的鳍。"}]])
R(151,"老马布兰契",[[description="可怜的老马布兰契呀！我们让它干的活儿实在是太多了，看来它已经要累垮了。虽然我在离开农场以前就喂过了它，可谁会料到马车会在半路上坏掉呢？如果你能从田里替它取来几捧燕麦的话，我会对你感激不尽的。我想，你可以在田边找到足够的燕麦，不过你首先要将周围那些可怕的机器人先干掉。",objectives={"西部荒野的弗娜·法布隆要求你带给她8捧燕麦。"}]])
R(152,"清理海岸",[[description="你或许已经注意到了，海岸线上有许多船只的残骸。无尽之海确实是非常凶险，我们必须确保西部荒野海岸线上没有那些该死的鱼人到处徘徊，只有这样水手们才能安全地找到靠港的路线。$b$b去杀死7只鱼人潮行者、7只鱼人战士、7只鱼人智者，还有7只鱼人滩行者，完成任务之后到我这里来领取奖赏。",objectives={"杀死7只鱼人潮行者、7只鱼人战士、7只鱼人智者，还有7只鱼人滩行者，然后向西部荒野灯塔中的葛瑞森船长复命。"}]])
R(153,"红色皮质面罩",[[description="我们与迪菲亚兄弟会的战局总是瞬息万变。最近我一直在监视着他们的活动，根据长期观察的结果，我发现他们的成员都戴着一种特殊的红色皮质面罩。$b$b给我带15条这种面罩回来吧，我会给你奖励的。",objectives={"给哨兵岭的哨兵加里安带回15条红色皮质面罩。"}]])
R(154,"归还梳子",[[description="不！！！！！$B$B快把这个梳子拿走！$B$B我是个怪物，不会再有人说我好看了！",objectives={"把幽灵的梳子拿回去交给夜色镇的伊瓦夫人。"}]])
R(155,"迪菲亚兄弟会",[[description="这么说，斯托曼就派了你这么一个芦柴棒一样的家伙来保护我？希望你能行，当然如果你再叫上几个朋友帮忙就好了。$b$b你知道你要做些什么吧？我会把你带到迪菲亚潜行者的巢穴去，而你呢，就得保护好我。当然，你最好离我近点，越近越好。现在全迪菲亚兄弟会的人都想要我的脑袋呢。要是他们看见我和你在一起，一定会来把咱们都宰了的。$b$b等你和你的朋友准备好之后，就来跟我说一声吧。",objectives={"护送迪菲亚叛徒前往迪菲亚兄弟会的秘密藏身处。迪菲亚叛徒把你带到范克里夫和他的手下的巢穴之后，尽快回去向格里安·斯托曼汇报相关信息。"}]])
R(156,"收集腐败之花",[[description="如果你能给我找些腐败之花来，我就可以酿造很多僵尸酒。$B$B这种花很难找到，听说在恐怖骸骨和骸骨魔的头骨里可以找到这种花……不过至今我还没有亲眼见过！$B$B乌鸦岭墓地和静谧花园里都有很多这样的骷髅，你可以在寻找腐败之花的时候顺便把他们干掉，夜色镇的人民会感激你的。",objectives={"收集8个腐败之花，交给夜色镇的旅店店主斯密茨。"}]])
R(157,"幽灵的发丝",[[description="这是你要的线，$N。它有很多种用途，比如用来束缚邪恶的亡魂，或者给没有生命的东西注入生命。",objectives={"把幽灵的发丝交给亚伯克隆比，他住在乌鸦岭墓地北边的房子里。"}]])
R(158,"僵尸",[[description="我需要一瓶叫做僵尸酒的饮料。夜色镇血鸦旅店的店主斯密茨应该有些存货。$B$B最近晚上寒风刺骨，我得来点僵尸酒，好让我的血液重新沸腾起来。",objectives={"去和旅店店主斯密茨谈一谈。"}]])
R(159,"僵尸酒",[[description="这是你要的僵尸酒……$B$B不过要小心一点，这酒烈得足以把死人给呛活过来。",objectives={"把僵尸酒交给乌鸦岭墓地北方小屋里的亚伯克隆比。"}]])
R(160,"给镇长的信",[[description="请把这封信交给夜色镇的艾尔罗·埃伯洛克镇长。$B$B我和他是老朋友了……我敢说，当他读完信，并且知道了你为我做的事情……他一定会和我一样高兴的！哈哈哈哈！",objectives={"把亚伯克隆比的信交给夜色镇的艾尔罗·埃伯洛克镇长。"}]])
R(161,"水坝危机",[[description="如果我的猜测没错的话，这是某种火药粉末。应该找个爆破专家来分析一下这到底是什么东西。阿什兰·暗石就在丹莫德和萨多尔大桥一带负责那里的警戒工作，我需要你尽快去找他，这是一段重要而危险的旅程，$N。$b$b走过奥加兹大门，沿着穿过湿地的大路一直到丹莫德去找爆破专家阿什兰·暗石。留心我的建议：沿着大路走，不要停留！",objectives={"主工程师辛德维尔七世要你把怪味粉末交给丹莫德的炸药专家阿什兰·暗石。"}]])
R(162,"异种蝎的威胁",[[description="我希望你尽快把这份报告送到对处理此类事件有经验的人手里。$B$B我知道有一位名叫格拉希娜·灵风的暗夜精灵学者，她致力于研究卡利姆多大陆上那些与艾泽拉斯的普通生物截然不同的生物形态，她简直就是一本活的生物书！如果你想要知道我们面临的是怎样的威胁，以及如何解决这个威胁，那就把这份报告交给她吧，我们现在急需她的帮助。$B$B我听说她住在达纳苏斯的月亮神庙里。",objectives={"把报告带给达纳苏斯的格拉希娜·灵风。"}]])
R(163,"乌鸦岭",[[description="乌鸦岭出了点问题，$n。卡洛尔说那边的房子里有什么人——或者怪物——出没。有两个晚上，他发现有个身影在活动，第三个晚上，某闪窗户里还射出了灯光。$b$b你如果真的关心暮色森林的安危，就去查一查，看看是什么样的怪物在乌鸦岭出没。",objectives={"查出是什么东西在乌鸦岭神出鬼没。"}]])
R(164,"斯温的货物",[[description="你认识斯温吗？谢天谢地，终于有人能帮我了！斯温和他的同伴在暮色森林的西北边有个营地。$b$b不幸的是，他们的人手太少了，少到派不出人回镇里来取一些必需的补给品。你能把这些物资带给斯温吗？",objectives={"把补给物资带给斯温。"}]])
R(165,"隐士",[[description="有个老人经常到镇里来买东西，不过我已经有些日子没见过他了。如果我没记错的话，他就住在一个可以俯视乌鸦岭墓地的小屋里。你能不能去看一看出什么事了？",objectives={"去乌鸦岭墓地附近的小屋查看老人的情况。"}]])
R(166,"迪菲亚兄弟会",[[description="这里恐怕还有最后一个任务需要你来完成。我们必须派人去除掉艾德温·范克里夫。说实话，就这样对一个活生生的人宣判死刑，这实在令我非常痛心，但为了西部荒野人民的利益，我不得不让范克里夫永远安息。把范克里夫干掉之后，提他的头来见我。",objectives={"杀死艾德温·范克里夫，把他的头交给格里安·斯托曼。"}]])
R(167,"我的兄弟……",[[description="那时我们正在一个大矿洞中工作，就是那个隐藏在西部荒野月溪镇中的谷仓下面的矿洞……没人知道当时到底是怎么回事，总之矿道突然坍塌了，我逃了出来……可其他人就没那么好运了……我是说，从那以后我就再没听到过其他人的消息了。$b$b看上去你的运气可能会比我们好一点。如果你能帮我找到弟弟的话，我会非常感谢你的。他总是戴着一块探险者协会徽章，所以如果你找不到他的话，至少那块徽章能给我带来一些安慰……",objectives={"将工头希斯耐特的探险者协会徽章交给暴风城的维尔德·蓟草。"}]])
R(168,"收集记忆",[[description="在那个可怕的日子，我的许多朋友都被埋在了矿洞里。如果你在冒险中正好路过月溪镇的那处矿洞的话，请帮忙留意一下有没有什么可以辨认他们身份的标志物品。如果你能找到他们的矿业工会会员卡的话，请一定要带给我，我好知道他们的结局，并与他们的家人谈谈如何为这次恐怖的事故善后。",objectives={"给暴风城的维尔德·蓟草带回4张矿业工会会员卡。"}]])
R(169,"通缉：加塞尔佐格",[[description="悬赏！加塞尔佐格是黑石氏族袭击石堡和多次劫掠湖畔镇等行动的领导者。$b$b他是个十分危险的家伙。根据线报，他最近就躲藏在刚刚被他们攻陷的要塞中，谋划着黑石氏族的下一次劫掠行动。我们必须不惜一切代价把这些在我们的国土上横行的兽人镇压下去。如果谁能把加塞尔佐格的头带到所罗门镇长面前的话，他将会得到重赏。",objectives={"杀死加塞尔佐格并把他的头颅割下，向湖畔镇的所罗门镇长复命。"}]])
R(170,"新的威胁",[[description="我希望你能帮我们一把，$c。在上一次穴居人袭击之后，我们的人手就明显不够了。$b$b我听说他们现在已经遍布我们的国土，看来寒脊山谷也不能避免。东南部的山区和湖畔已经到处都是穴居人的身影了。$b$b糟糕的事情还不仅仅是这些，几天前，他们袭击并占领了我们西边的营地！$b$b我们这儿有些人手不足，$g孩子:姑娘;，我们需要强大的军队帮助我们赶走这些家伙。",objectives={"巴尔林·霜锤让你去杀死6个石腭穴居人和6个壮实的石腭怪。"}]])
R(171,"联盟孤儿的看护者",[[description="你的心肠真好啊，$N。我做梦都没想到我在儿童周会这么开心。谢谢你，我不想伤心因为发生在自己和他人身上的事，我的父辈告诉我忘记任何令人伤感的事。你知道吗？当我长大了，我想成为向你一样的英雄$B$B非常抱歉，是我回家的时候了，让我们回去吧，我要告诉监护人。。你是一个多么伟大的人！  ",objectives={"去暴风城的教堂广场见孤儿监护员奈丁加尔并带上这个人类孤儿哨.  "}]])
R(172,"儿童周",[[description="你愿意帮助我们的孤儿院？太感谢你了，我的朋友。感谢你愿意在儿童周的这段时间内为我们提供帮助。$B$B拿着这只哨子，你只能在儿童周的这7天内使用它。当你使用它的时候，就可以和那些由你负责照看的孩子进行对话，再次使用就可以解散那个孩子。$B$B不管怎么样，$N——使用这个口哨，见一见你的小朋友！我相信孩子们一定很想见到你。",objectives={"使用兽人孤儿哨与你即将在儿童周期间照顾的孩子进行对话。"}]])
R(173,"森林里的狼人",[[description="黑暗的势力正在笼罩暮色森林，而卡尔文主人正在努力驱除邪恶，保护夜色镇人民的安全是我们的职责。$b$b你觉得自己有能力加入我们吗？$b$b我以前也跟你想的一样，因为对哨所的安逸悠闲感到绝望，我投靠了卡尔文主人。如果你想要证明自己的实力，不是只靠嘴皮子说说就可以的。$b$b去找夜行织影狼人较量较量吧，他们经常在阳光树林——阳光，哈！——和烂果园出没。",objectives={"为夜色镇的卡洛尔杀掉6个夜行织影狼人。"}]])
R(174,"仰望星空",[[description="我的侏儒朋友考格说过要帮我制造一个可以用来观察星空的装置。我相信除了魔法之外，还有别的理由可以解释发生在这片森林中的奇怪变化。$b$b根据考格的设计图，首先要去找一个手艺高超的技师，让他帮忙造一根青铜管。",objectives={"夜色镇的维克托·安特拉斯要你给他找一根青铜管。"}]])
R(175,"仰望星空",[[description="根据考格的设计图，现在我还需要一个东西来反射光线。我记得有个叫玛丽的女人因为总是戴着一副眼镜而在这一带人人皆知，你可以去找找她，向她借一个反光镜。我记得她曾经住在暮色森林南部……",objectives={"找到玛丽，说服她借给你一个反光镜，用于维克托的计划。"}]])
R(176,"通缉：霍格",[[description="通缉：霍格$B$B巨型豺狼人霍格，现正在艾尔文森林西南部的树林里游荡。他成功地对抗了目前为止所有追捕他的行动。$B$B暴风城已经为除去这只豺狼人设下了酬金，想得到酬金的猎手必须向闪金镇的治安官杜汉提供杀死霍格的证据。",objectives={"杀死豺狼人霍格，把他那巨大的豺狼人爪带给治安官杜汉。"}]])
R(177,"仰望星空",[[description="那副眼镜是我最珍贵的宝物，不过在发生了一件事情之后……我就把它丢在谷仓后面了。有个疯狂的食尸鬼曾经在那一带徘徊，可能是它把东西给捡走了。有人说那个邪恶的家伙住在静谧花园墓场出现。",objectives={"从疯狂的食尸鬼那里拿回盲眼玛丽的眼镜，把它交给夜色镇的维克托。"}]])
R(178,"塞欧克瑞图斯的坠饰",[[description="<你听到了某种飘渺的声音>$B$B可别被吓着。我是塞欧克瑞图斯，艾尔文森林的阿祖拉之塔里的高阶法师。你手上拿着的饰物是暗皮豺狼人和他们的主子莫甘斯用来联络的工具。$B$B根据这几个月的研究，我也已经掌握了使用这些饰物进行通信的方法。如果你能听到我所说的话，就证明我的法术成功了。$B$B把这个饰物带给我，我会给你酬劳的。",objectives={"将不再发光的暗皮坠饰带给法师塞欧克瑞图斯。"}]])
R(179,"矮人的交易",[[description="嘿，你是新来的吧？看来你需要些暖手的东西，对吗？$b$b我想你应该想要一副保暖的手套。我是个热心肠，很愿意给你一副手套，不过我有个条件。$b$b你帮我弄些狼肉来，我保证你不会被冻掉手指头。你觉得怎么样？",objectives={"斯登·粗臂想要8块硬狼肉。"}]])
R(180,"通缉：范高雷中尉",[[description="悬赏：范高雷$b$b恶行累累的豺狼人头目范高雷在湖畔镇及王国的敌人莫甘斯的指使下，带着暗皮豺狼人氏族到处为非作歹。镇长所罗门下了命令，悬赏杀死这个万恶的东西。将他的手掌割下来拿给镇长，以此证明他的死亡。",objectives={"杀死范高雷并将他的手掌割下，向湖畔镇的所罗门镇长复命。"}]])
R(181,"仰望星空",[[description="根据考格的设计图，现在我们还需要一种透镜来完成整个装置。我知道什么地方有合适的透镜，不过很难拿到。$b$b有个叫扎克乌尔的食人魔住在暮色森林南部的土丘上，如果可以的话，你去把他的单片眼镜拿来吧，我可以用它做透镜。",objectives={"在暮色森林南部的食人魔土丘上找到扎克乌尔，把他的单片眼镜带回夜色镇交给维克托。"}]])
R(182,"巨魔洞穴",[[description="我和我的兄弟森内尔被派来调查丹莫罗各个地区的巨魔活动情况。参议院正在忙着对付那些不知道从哪里冒出来的穴居人，已经没工夫再关心巨魔了。$b$b据我所知，在寒脊山谷南部山洞里生活的巨魔们日子并不好过，所以我觉得派大批军队去围剿它们是杀鸡用牛刀，只要一两支训练有素的小分队就已经绰绰有余了。$b$b你也许能给我们提供些帮助吧？当然，我会对你的帮助给予一定的报酬。",objectives={"格瑞林·白须要你去杀掉14个霜鬃巨魔幼崽。"}]])
R(183,"猎杀野猪",[[description="没什么能比得上用一整天的时间去打野猪更让人愉快的了，对吧？不过，寒脊山谷里的野猪太多了，你几乎已经不可能在那里再感受到狩猎的乐趣。你根本不需要去激怒它们，因为它们早就是怒气冲天，随时准备用獠牙把你拱上天了！事实上，这些过剩的野猪已经对我的日常狩猎形成了威胁。$b$b长话短说吧，如果你能帮我杀掉些野猪，我真的会非常感激你的。",objectives={"塔林·锐眼让你去杀掉12只小型峭壁野猪。"}]])
R(184,"法布隆的地契",[[description="这是西部荒野一片农田的地契，由西奥多·法布隆和他的妻子弗娜·法布隆联名签署。地契背面还有潦草的字样：$B$B“我们到法布隆家里走了一遭，弄到了他的地契。我们觉得你可以很轻易地照着这张样本给自己也造出几份地契来。$B$B法布隆家的人不会找我们的麻烦，我最后一次看到他们的时候，他们的四轮货车坏在了路上。”$B$B你认为法布隆夫妻俩可能正在到处找这张地契……",objectives={"把法布隆的地契交给农夫法布隆。"}]])
R(185,"猎虎",[[description="当我还只是个小女孩的时候，我的父亲就开始训练我捕猎老虎。$b$b一般来说，你会发现虎崽是非常容易追踪和猎杀的。因此，要猎杀它们根本不是什么麻烦的事情，你在探险队的营地附近很容易就能找到虎崽。$b$b让我们来测试一下你的追踪技巧，看看你是否能猎杀这些野兽。",objectives={"奈辛瓦里远征队的艾耶克·罗欧克要求你杀死10只荆棘谷猛虎幼崽。"}]])
R(186,"猎虎",[[description="你学得很快，$c。让我们来测试一下你是否能杀死成年的猛虎，这次你的任务是去杀死十只荆棘谷猛虎。",objectives={"奈辛瓦里远征队的艾耶克·罗欧克要求你杀死10只荆棘谷猛虎。"}]])
R(187,"猎虎",[[description="现在我要教你些更高深的东西，然后测试一下你的技巧。去杀死十只老年荆棘谷猛虎以证明你的能力吧。如果你能做到这些的话，你就可以去面对最后的挑战了，最终，我会在奈辛瓦里大人的面前授予你猎虎大师的称号。$b$b老年荆棘谷猛虎不但非常难找，而且也是最难以对付的。",objectives={"奈辛瓦里远征队的艾耶克·罗欧克要求你杀死10只老年荆棘谷猛虎。"}]])
R(188,"猎虎",[[description="现在你要面对的将是最后的挑战。我们这几周来一直在追踪一只神秘的老虎，我们称它为辛达尔。现在让我们来看看你能不能做到一件以前从来没有任何$r可以做到的事吧：去猎杀辛达尔，把它的爪子带回来以证明你完成了任务。$b$b追踪它可不是一件简单的任务。",objectives={"奈辛瓦里远征队的艾耶克·罗欧克要求你杀死辛达尔并带回它的爪子。"}]])
R(189,"血顶巨魔的耳朵",[[description="该死的巨魔！他们杀死了我们派到丛林里去的人！我已经在和他们的冲突中损失太多优秀的护卫了。血债必须血来偿！这让我怎么向大财主里维加兹解释呀？$b$b是该做决定的时候了……想想看，科博克……你可不是被派到这里来整日无所事事的……啊，有啦！你……你就是$n，是不是？你是来帮助我的，是不是？这份工作的奖励可是很丰厚的哦！$b$b嗯嗯，给我带15只血顶巨魔的耳朵来，我就重重地酬谢你，如何？",objectives={"给藏宝海湾的科博克带回15只血顶巨魔的耳朵。"}]])
R(190,"猎豹",[[description="如果你也想加入这个由赫米特先生组建的最强狩猎队，就必须先证明自己是一个能干的猎豹高手。放心，一开始不会太难的，千万别轻言放弃。你先去猎杀10只猎豹幼崽热热身吧。$b$b当然，这只是让你热热身而已……",objectives={"奈辛瓦里远征队的埃尔加丁爵士要求你杀死10只猎豹幼崽。"}]])
R(191,"猎豹",[[description="现在你已经可以更进一步了。如果你想继续证明自己有资格和我们这些优秀的狩猎能手合作的话，就去猎杀十只黑豹。$b$b这些大家伙们都很强壮，它们可不比之前的猎豹幼崽那么好杀。",objectives={"奈辛瓦里远征队的埃尔加丁爵士要求你杀死10只黑豹。"}]])
R(192,"猎豹",[[description="接下来的部分可就比较困难了。一个真正的猎豹能手必须要有能力杀死深喉猎豹这种荆棘谷中最危险的生物。去杀死十只深喉猎豹，向我们证明你的猎豹能力吧！$b$b如果你很难找到它们的踪迹的话，就埋伏起来等它们出现……",objectives={"奈辛瓦里远征队的埃尔加丁爵士要求你杀死10只深喉猎豹。"}]])
R(193,"猎豹",[[description="你几乎已经证明自己是一位优秀的猎豹能手了。有一只名叫巴尔瑟拉的豹子目前正潜伏在这片森林里，我们一直都没能找到它。去试试猎杀巴尔瑟拉吧，记得用上你所掌握的全部技巧。$b$b将巴尔瑟拉的牙齿带回来给我，如果你成功了，你就将赢得我的尊敬！",objectives={"奈辛瓦里远征队的埃尔加丁爵士要求你杀死巴尔瑟拉，并带回它的牙。"}]])
R(194,"猎龙",[[description="你觉得你的狩猎技术是最顶尖的？我马上就检验一下，看看你是不是在骗人。到丛林里去杀几只荆棘谷迅猛龙，这样一来我们就知道你是不是所谓的王牌猎人了。$b$b当然，我是绝对不会告诉你在哪里才能找到它们的！追踪野兽本身就是挑战的一部分。",objectives={"赫米特·奈辛瓦里要求你杀死10只荆棘谷迅猛龙。"}]])
R(195,"猎龙",[[description="现在让我们来看看你能不能应付更大的挑战吧。杀进丛林里去，给我干掉十只残暴的鞭尾迅猛龙。可别说你不行啊！",objectives={"赫米特·奈辛瓦里要求你杀死10只鞭尾迅猛龙。"}]])
R(196,"猎龙",[[description="让我们来看看你能不能对付下一个挑战吧。这附近栖息着一种非常狡猾的迅猛龙，我们叫它丛林捕猎者。它们远比你之前捕猎的目标更难追踪和猎杀。猎杀十只丛林捕猎者，然后我就会告诉你这里最惹眼的目标是什么。",objectives={"赫米特·奈辛瓦里要求你杀死10只丛林捕猎者。"}]])
R(197,"猎龙",[[description="你已经证明了自己在这片丛林里的每次捕猎都不会空手而归，总能带回我们要求的猎物，因此我决定告诉你有关那只我从来也没能猎到的、最凶暴最残忍的迅猛龙的事情，艾耶克把那只迅猛龙叫作泰希斯。$b$b如果你想证明自己真的是个捕猎专家的话，就把泰希斯杀掉，把它的爪子给我带回来，这可是其他王牌猎人都从没完成过的壮举。",objectives={"赫米特·奈辛瓦里要求你杀死荆棘谷中最危险最狡猾的迅猛龙泰希斯。"}]])
R(198,"列兵索尔森的补给物资",[[description="嗯。没错，我这里确实有些适合你做的事。目前部署在荆棘谷北部的多伦上尉和他的部下需要我们的定期补给。$b$b不过由于巨魔的伏击，他们一直没能得到补给，所以我得找人来帮我处理这件事。多伦的营地就在从暮色森林进入荆棘谷的道路的西北方，你只要把补给品交给列兵索尔森就行了，相信他会处理好的。$b$b你要记住，如果你失败了的话，就得赔偿我们的损失。$b$b当然，你也可能会死在路上……",objectives={"将杂七杂八的地精补给物资带给列兵索尔森。"}]])
R(199,"水坝危机",[[description="你取了些怪味粉末的样品。",objectives={"回去见主工程师辛德维尔七世，把你找到的线索交给他。"}]])
R(200,"书呆子赫罗德",[[description="既然连库尔森都知道了这个秘密，那么他们一定也在我们这边安插了一个卧底。我们必须得搞明白这些机密内容是怎么泄露出去的！$B$B索尔森在那边的线人是书呆子赫罗德，他是库尔森的后勤官，了解库尔森的营地里的一切事务。如果你能搞到他的笔记或者档案什么的话，或许我们能分析出索尔森到底是怎么被发现的。$B$B当初，我们还跟库尔森一起共事的时候，书呆子的办公室是在营地里唯一一座两层房屋的二楼，他的档案应该还在那里。",objectives={"找到书呆子赫罗德的档案。"}]])
R(201,"调查营地",[[description="我收到一条报告说，有一群猎人在风险投资公司营地所在的纳菲瑞提湖的上游建立了一片营地。通常我根本不会在意这件事，但当我听说赫米特·奈辛瓦里也是那群猎人中的一员时，我改变了想法。那家伙可是个名声显赫的人物，如果你了解我的意思的话，就会不像现在这样无动于衷了。$b$b你为什么不去那片营地里侦察一下呢，$n？去看看他们到底想干点什么吧。",objectives={"找到猎人营地并向藏宝海湾的克拉兹克报告这个营地的位置。"}]])
R(202,"库尔森上校",[[description="你一次又一次地证明了自己的能力，而你的足智多谋略似乎甚至能与库尔森媲美。如果……如果你愿意彻底投身到与库尔森斗争的事业中去的话……也许你将成为我们反抗军的救星！$B$B他就躲在那个名叫“储藏室”的洞穴深处发号施令。你必须进入那个洞穴，干掉他身边的保镖，最终把库尔森和他的副官们都给除掉。$B$B出发吧，$N。我们的生命与希望，如今都已经全部掌握在你的手中了。",objectives={"杀掉6名库尔森精英和4名库尔森副首领，并将库尔森的头颅交给反抗军营地里的多伦上尉。"}]])
R(203,"以彼之道还施彼身",[[description="我们正在与库尔森进行一场艰难的战斗。他是个非常优秀的战术大师，而且他的手下士兵的数量是我们的十倍！如果我们想要胜利的话，就必须使用他擅长的战术来对付他。$B$B到他在东边设立的营地里去，杀掉他的士兵，越多越好，然后在增援赶来之前撤退。",objectives={"杀死15名库尔森丛林战士，然后向反抗军营地的尤瓦中士复命。"}]])
R(204,"库尔森的药物",[[description="要想和库尔森搏上一搏，我们就必须削弱他们的医疗队伍。他在那里聚集了大批医疗人员，他们能用密林药剂治疗自己的部队，并用毒草汁液对我们的人下毒。$B$B我们要用这些药物来治疗我们自己的战士，同时我们也需要一份毒液的样本来研制解药。到库尔森的营地去把这两样东西找来吧，药品应该就在那些医疗人员的身上，而毒草汁液大概是保存在营地中的一些物资箱里的。",objectives={"给反抗军营地里的尤瓦中士带回7份密林药剂和1份毒草汁液。"}]])
R(205,"巨魔巫术",[[description="在我研究这些巨魔传说的时候，我希望你能帮我收集一些巨魔们施展邪恶魔法时必备的法器。到南边的那个劈颅巨魔部族的地盘上去，从他们的巫医和秘法师那里弄一些劈颅巨魔的神像回来吧。",objectives={"给叛军营地的尼麦兹修士带回4只劈颅巨魔的神像。"}]])
R(206,"麦佐斯",[[description="库尔森的确是该死，不过……到底是谁将他带上了这条邪恶的道路呢？通过研究，我已经找到了真相：是一个名叫麦佐斯的食人魔法师干的。他住在荆棘谷东部的食人魔山中，据说他擅长心灵控制魔法，我也确信正是他使得库尔森上校堕落的。$B$B如果麦佐斯继续活在这世上，他的邪恶法术就有可能影响到更多人，或许又会出现另一个库尔森上校。$B$B杀死他，把他的心灵之眼带回来，这正是他用来诱惑他人堕落的物品。",objectives={"将心灵之眼交给反抗军营地里的尼麦兹修士。"}]])
R(207,"库尔森的秘密",[[description="库尔森上校曾是个伟大而高贵的人，我必须得找到让他堕落至此的原因！他一定是被巨魔的魔法给控制了。要想搞清楚这一点的话，我们就得先研究一下巨魔的传说故事。$B$B据说荆棘谷中的巨魔遗迹中隐藏着四块石板，我必须得看看这些石板上到底记述了些什么东西！你去给我拓一份这些石板上的文字来，把拓片都交给我。$B$B第一块石板在巴拉尔废墟里，第二块石板在暗礁海的海底，第三块和第四块应该都在祖昆达废墟里。",objectives={"找到4块石板并将上面的内容带回去交给尼麦兹修士。"}]])
R(208,"王牌猎人",[[description="$N，你现在已经成为了一位够格进入我们狩猎队的猎手了。无论是洛丹伦的战场还是危机四伏的丛林，我在哪里都没有见过有谁能像你这样拥有如此强大的战斗能力。$b$b你成功地杀死了凶残的辛达尔，狡猾的巴尔瑟拉和强悍的泰希斯。但对于这片丛林中的猎人们来说，虎王邦加拉什的头才代表着至高无上的荣耀。这只白虎正是我来这里的原因，我注意它已经很久了。如果你能杀死虎王邦加拉什，那么你无疑是这里最优秀的猎人。",objectives={"赫米特·奈辛瓦里要求你将虎王邦加拉什的头带回来给他。"}]])
R(209,"劈颅巨魔的獠牙",[[description="靠不停地猎杀老虎来保证对南海岛屿的虎牙出口实在是苦差事，不仅难度高，而且花费也也高。幸亏我们找到了一种替代品，就是这些劈颅部族的巨魔的獠牙。$b$b嘿，只要你不说，买家就不会知道，对吧？给我搞一批巨魔獠牙来吧，这样我们就能应付每月一次的供货啦！",objectives={"给藏宝海湾的科博克带回18根劈颅巨魔的獠牙。"}]])
R(210,"克拉兹克的烹调锅",[[description="在营地里，我是专门负责伙食的。过去的活真的很多，让我每天都要忙到死，直到我从藏宝海湾的地精商人那里买了台多功能机械烹调锅才有所改观。这锅实在是太棒了！它节省了我许多的时间……我是说，在它坏掉之前！$B$B你能帮我把这锅带到那个地精商人那里去，让他给我修理一下吗？他的名字叫克拉兹克。",objectives={"把克拉兹克的烹调锅带给藏宝海湾的地精克拉兹克。"}]])
R(211,"啊，安多哈尔！",[[description="啊，进攻安多哈尔并彻底击败那个巫妖的时刻终于来临了！$B$B召唤者阿拉基就盘踞在安多哈尔的废墟中，他的贴身卫队无时无刻不在他的身边保护着他。你需要召集强大的盟友才能击败他。$B$B消灭巫妖，$N，从它的护符匣里拿出一块碎片来，作为你获胜的证据！",objectives={"把阿拉基的护符匣碎片交给西瘟疫之地冰风岗的指挥官阿什拉姆·瓦罗菲斯特。"}]])
R(212,"冷餐会",[[description="我的拿手菜之一就是橙味冻蜥肉，但现在的问题是……这种肉很容易变质，而且我今天晚上必须得在一位贵族的生日晚宴上做这道菜！$B$B救场如救火，如果你能马上从刚被宰掉的冷眼蜥蜴身上割块冷蜥蜴肉给我的话，我就给你做顿堪比国宴的美味尝尝！$B$B冷眼蜥蜴一般会在荆棘谷西北海岸的沙滩上晒太阳，离这里有点远，不是么？所以你得赶紧行动啦！",objectives={"杀死一只冷眼蜥蜴，取一块冷蜥蜴肉并把它带给“蓝色隐士”旅店里的安古斯·斯特恩。$B$B<如果你在任务过程中死亡则任务失败>"}]])
R(213,"恶性竞争",[[description="太猖狂了！吉尔里兹把贸易亲王们指定的要员们都从这里赶了出去，这件事已经够糟的了，现在他居然还和那些声名狼籍的海盗们往来！$b$b里维加兹不会坐视不理的，他允许我按自己的方式来解决这些问题。$b$b我的方式是什么？偷！最近，风险投资公司的地质学家们正在研究他们从矿里挖出的一种奇怪的蓝色水晶，从那群地质学家手里搞些样本回来给我，当然，我不关心你用怎样的手段去搞。",objectives={"给藏宝海湾的科博克带回8块打磨过的水晶。"}]])
R(214,"红色丝质面罩",[[description="迪菲亚兄弟会的人都会戴着一种红色的面罩，这显然已经是个尽人皆知的秘密了。但我们又了解到，这个面罩的材料是他们的成员在帮会内部地位的象征。$b$b既然如此，那么我希望你出马杀死一些兄弟会的高阶成员。他们的最高阶成员无疑都躲在范克里夫的秘密藏身处附近。作为证据，你要给我带回10条红色丝质面罩来，这样我才能给你奖励。祝你好运，$N。",objectives={"给哨兵岭哨塔的哨兵瑞尔带回10条红色丝质面罩。"}]])
R(215,"丛林中的秘密",[[description="谢谢你救了我的命，$N。我知道这听起来有点奇怪，但……请听我解释。$B$B多伦上尉让我和库尔森的手下一起重新回到军队里，让我扮演卧底的角色，为我们反抗军搞一些有用的情报。我原本以为这里很适合我渗透入库尔森的营地，但我错了。再次感谢你救了我一命。$B$B这是个机密任务，所以你千万不能把它告诉任何人。但如果你去和多伦上尉谈谈的话，他会给你一个解释的。",objectives={"与反抗军营地里的多伦上尉谈一谈。"}]])
R(216,"蓟皮熊怪的麻烦",[[description="蓟皮熊怪在威胁我们的扩张！我们东面的蓟皮村挡住了从这里通往碎木哨岗的道路，这是一条可以包围阿斯特兰纳的道路，没有它，我们就会让联盟得到一条额外的扩张路线。$B$B$N我们决不允许有这样的缺口存在！$B$B进入蓟皮村，尽量减少那些熊怪的数量。你会为这项任务得到补偿的，但更重要的是，你会为部落尽到你的职责！",objectives={"杀死8个蓟皮复仇者和8个蓟皮萨满祭司。他们大部分都位于佐拉姆海岸东部的蓟皮村里。任务完成后回到灰谷佐拉姆加前哨站的卡拉恩·阿玛卡那里复命。"}]])
R(217,"保卫国王的领土",[[description="$N，我的侦察兵已经找到了最近一段时间来频频组织穴居人对我们发动袭击的首领。这帮洛克莫丹的怪物好象是由一个叫格劳姆格的酋长领导的，不过格劳姆格身边守卫森严，有两个精英护卫纳什尔和布劳勒尔从不离他左右。$b$b如果你想证明自己的价值的话，$N，我希望你能接下杀掉格劳姆格和他那两个手下的任务。一旦穴居人失去了领导，我们就有机会把这些怪物重新赶回地下。",objectives={"杀掉穴居人首领格劳姆格及他的两个护卫，纳什尔和布劳勒尔。然后回到南部警戒塔向拉格弗斯上尉报告。"}]])
R(218,"被窃取的日记",[[description="我的日记！那帮巨魔把它拿到洞穴里去了。拿着日记的那个家伙……他是一个皮肤和面颊上都涂着奇特印记的青面獠牙的家伙，我打从娘胎里出来后还没见过像他那样丑的。$b$b你应该能对付那些巨魔，帮我把我的日记拿回来怎么样？",objectives={"格瑞林·白须要你去杀掉冷酷的格瑞克尼尔，并取回他的日记。"}]])
R(219,"失踪人员",[[description="终于…有人来了……来自联盟的朋友！$b$b救救我…求你了…$b$b我只记得…一群邪恶的兽人让我们团全军覆没……大多数人都被杀了，我的头被狠狠地打了一下，眼前一黑就倒下去了。现在我被关在这个洞里，奄奄一息……$b$b我必须得回到镇上去…拜托了…你是我最后的希望了……",objectives={"保护基沙恩下士回到赤脊。"}]])
R(220,"水之召唤",[[description="在给你图腾之前，伊斯伦还会有一个任务让你去完成。我给你的那瓶水在任何情况下都会很有用。$B$B去吧，去找伊斯伦。我们会再见的。",objectives={"把最纯净的水交给贫瘠之地的伊斯伦。"}]])
R(221,"森林里的狼人",[[description="你可能已经注意到了，在树林周围有些个头较大的狼人和那些夜行织影狼人一起游荡。据我们所知，大多数狼人都是这类夜行黑暗狼人。$b$b我还发现在小镇西南的烂果园里已经到处都是他们的身影了，这些狼人比你之前遇到的那些更难对付。$b$b小心点。",objectives={"为夜色镇的卡洛尔杀掉12个夜行黑暗狼人。"}]])
R(222,"森林里的狼人",[[description="你之前的功绩使我确信，你已经可以去对付森林里最凶猛的狼人了。$b$b在这一带所有的狼人中，夜行邪齿狼人和夜行堕落狼人是最危险的。他们就住在南边的洞穴和矿井里。$b$b你甚至能从很远的地方看见他们的篝火。",objectives={"为夜色镇的卡洛尔杀掉8个夜行邪齿狼人和8个夜行堕落狼人。"}]])
R(223,"森林里的狼人",[[description="拿着这个，$n。把这个带给卡尔文主人。$b$b<他取出一张褪色的羊皮纸交给你>$b$b如果再多些像你这样的力量加入，我们就能让守夜人相形见拙！也许到那个时候，我们就能够彻底解决这些现在令我们疲惫不堪的危机。",objectives={"把卡洛尔的便笺交给乔纳森·卡尔文。"}]])
R(224,"保卫国王的领土",[[description="我们要保卫洛克莫丹，$N！国王的士兵都在遥远的战场上英勇作战，但我们的家园却危机丛生。每个裂缝里都有穴居人在不断冒出来！四处横行的穴居人已经成了铁炉堡最大的威胁，我们一定要消灭这些恶心的怪物！$b$b我们需要像你这样勇敢的冒险家来帮忙消除穴居人的威胁。杀掉10个碎石穴居人和10个碎石怪斥候，然后回来向我汇报。",objectives={"南部警戒塔的巡山人库伯弗林特要你杀掉10个碎石穴居人和10个碎石怪斥候。"}]])
R(225,"饱经风霜的墓碑",[[description="这座饱经风霜的墓碑上仅仅写着几个字：$b$b摩根·拉迪莫尔$b$b<经过仔细的观察，你发现墓穴的泥土最近被人动过，很多泥土好像都翻开了……>",objectives={"去和夜色镇的希拉·沃宁迪谈一谈。"}]])
R(226,"恶狼成群",[[description="我和斯温的处境越发危险了，这儿就我们俩，要吃饭就得打猎捕鱼。但是每次我们带着肉和鱼回营地的时候，那些从森林跑出来的恐狼都好像要扑上来咬一口似的。别提有多危险了！$B$B如果你能替我们除掉这些狼，也许我们就能过得轻松些。它们经常在北边和东边的小河周围出没。",objectives={"杀掉12只饥饿的恐狼和8只疯狂的恐狼，然后到斯温的营地中向拉尔斯交差。"}]])
R(227,"摩根·拉迪莫尔",[[description="<他从架子上翻出一本皮质封面的书。>$b$b如果你想知道更多，就去问阿尔泰娅，她最近正在为摩根·拉迪莫尔的事情头疼……",objectives={"去和夜色镇的指挥官阿尔泰娅·埃伯洛克谈一谈。"}]])
R(228,"摩拉迪姆",[[description="我的探子说摩拉迪姆沿着一条穿过墓地的弯曲怪异的小路，在暮色森林中四处游荡。我们曾把他的尸体埋在山上那座小屋的后面，你知道在哪儿吧？$b$b除了祝你好运之外，我没什么能帮你的了。",objectives={"杀掉摩拉迪姆，把他的头骨交给夜色镇的指挥官阿尔泰娅·埃伯洛克。"}]])
R(229,"幸存的女儿",[[description="我应该早点告诉你的……$b$b该怎么说呢……$b$b摩根可能以为他的家人都死了，不过实际上他的女儿莎拉·拉迪莫尔还活着，她现在也是个守夜人。她一直在因为她父亲死了以后所发生的……那些事情而苦恼。我想，你可以把关于她父亲的最新消息带给她。",objectives={"去和夜色镇的守夜人莎拉·拉迪莫尔谈一谈。"}]])
R(230,"斯温的营地",[[description="挖开土堆之后，你发现了一本不大的书，上面沾满了泥土。$B$B书上没有写标题，不过……书里写着一些斯温想要知道的东西。",objectives={"把你从斯温的农场找到的书交给他。"}]])
R(231,"女儿的爱",[[description="拿着这个，请把这个放到他的坟墓上。也许…也许这样他就可以知道我现在过得很好，而且我们也不会因为他所做的事责怪他。$b$b<她含着眼泪，把戴在右手上的一只戒指摘下放在你手里>$b$b还有……谢谢你，$n。",objectives={"把莎拉·拉迪莫尔的戒指拿到摩根·拉迪莫尔的坟墓上去。"}]])
R(232,"金格的货物",[[description="皇家药剂师学会需要你的帮助。仔细听好了，这个行动对你我都有好处。$B$B隔壁的药剂师基佛看上去有些……疯疯癫癫的，但如果他的研究项目能早点找到一个有眼光的买家的话，早就已经得到丰厚的成果了。幸运的是，现在我已经把这个研究项目买了过来。我要你把这份订货单交给蓝月杂货店的店主奥雷萨多·卢卡那里，他会给你一只实验工具包。当你拿到工具包之后就尽快回来向我报告，我会告诉你下一步任务的详细情况。",objectives={"把订货单交给幽暗城的奥雷萨多·卢卡。"}]])
R(233,"寒脊山谷的送信任务",[[description="嗯，$g小子:姑娘;，我想也许你不会帮我这个忙的。今天从隧道那边来了一大堆信，我想我没时间把它们都给发出去了。$b$b这些信都是寄给塔林·锐眼的。沿着这条路向西走就能找到他，就在结冰的湖泊附近。$b$b你能帮我这个忙么？",objectives={"把这一摞信件送给塔林·锐眼。"}]])
R(234,"寒脊山谷的送信任务",[[description="如果我没记错的话，格瑞林的营地就在这条路的尽头，沿着路往东南方走就是了，他一定正在等着这封信呢。",objectives={"把这封信送给格瑞林·白须。"}]])
R(235,"灰谷狩猎",[[description="年轻的冒险者们，注意了！灰谷的野兽正在等着你们！$B$B部落在贫瘠之地以北的区域建立了强大的基地。我们的两个前哨站——碎木哨岗和佐拉姆海岸哨岗——正在努力地为部落的荣耀而战！想要证明自己能力的勇士就到那儿去吧。碎木岗哨位于贫瘠之地的正北方，塞娜尼·雷心正在那里招募愿意参与灰谷狩猎中的冒险者！",objectives={"与灰谷碎木哨岗的塞娜尼·雷心谈一谈。"}]])
R(236,"Awaiting Word",[[description="A few weeks ago, I dispatched Watcher Callahan and a few others to the northern border of Duskwood to deal with the wolf infestation. I haven't heard word from him for quite some time. If he followed my instructions, he'll be camped out on the road north from Darkshire. $B$BIf it's on your way, please check up on him and inform him that I am awaiting a progress report from him.",objectives={"Speak with Watcher Callahan."}]])
R(237,"保卫国王的领土",[[description="巡山人库伯弗林特总是在我面前称赞你，$c。因此现在我要交给你一个极其重要的任务，你必须不断给那些入侵的穴居人施加压力，直到我们的兄弟们从联盟前线回来。$b$b到南部的丘陵去，杀掉10个碎石怪击颅者和10个碎石怪先知。你的行动可以为我们赢得一点时间，完成任务后就回来向我报告。",objectives={"南部警戒塔的巡山人格拉维戈要你杀掉10个碎石怪击颅者和10个碎石怪先知，然后回去向他汇报。"}]])
R(238,"金格的货物",[[description="东西都准备好了，$n。毫无疑问，药剂师金格正在等着这批货。马上把这些东西送到她那里去，告诉她我已经把价钱记在学会的帐上了。另外，请代我向她致以最高的敬意。$B$B好了，不要再站在这里了，快点出发吧！",objectives={"把采样工具包交给幽暗城的药剂师金格。"}]])
R(239,"西泉要塞",[[description="我们位于西部边界的要塞报告说，那里的豺狼人和迪菲亚潜行者最近越来越猖獗了。他们要求我从暴风城派更多士兵过去……但是我们已经没有多余的人可派了！$B$B如果你愿意帮忙的话，就去和西泉要塞的瑞尼尔副队长谈一谈，看看他需要你做些什么。$B$B沿着这条路往西走，过了桥之后向右转就是要塞。",objectives={"到西泉要塞去和瑞尼尔副队长谈一谈。"}]])
R(240,"基特斯的美餐",[[description="完成了——格鲁奥烹制的黑“蟹”蛋糕！",objectives={"把黑蟹蛋糕拿回去交给基特斯。"}]])
R(241,"<TEST> HEY MISTER WILSON!",[[description="Description",objectives={"Log"}]])
R(242,"<UNUSED>",[[description="Throm-ka, $c. There is no time to waste. Orcs of the Dragonmaw clan have fortified themselves in the valley to the south of here. $b$bThey have denied the Warchief's mandate, leaving us only one course of action. We will eliminate them so that they will no longer dirty the name of the Horde.",objectives={"Kill 8 Dragonmaw Raiders, 3 Dragonmaw Bonewarders, and a Dragonmaw Battlemaster."}]])
R(243,"进入沙漠",[[description="你现在得去一趟塔纳利斯沙漠，在那里对当地的蜥蜴、蝎子和土狼进行一些组织测试，并搜集一些组织样品放进实验工具包里。当然，你有可能得花不少工夫才能找到合适的样品，这一点是可以预料的。每种生物的样本都要十份。$B$B另外，加基森的地精拥有这类工具包所需的能量源，去和那里的首席工程师沙克斯·比格维兹谈谈，或许能得到一些必要的帮助。$B$B此行只许成功不许失败，否则就不要回来见我。",objectives={"和加基森的首席工程师沙克斯·比格维兹谈一谈，请他为实验工具包提供能量源。"}]])
R(244,"豺狼人的入侵",[[description="你好，$c。我是负责这段道路巡逻任务的卫兵。虽然这条道路现在是安全的，但我曾经在这附近的东北方看见过豺狼人的宿营地。$B$B湖畔镇必须得提防着这群豺狼人才行。请你把这条消息报告给湖畔镇的菲尔顿副队长,我想他一定会非常乐意给你的侦察行动付上一笔酬劳的。$B$B菲尔顿一般在湖畔镇桥南的地区执行警戒任务。",objectives={"找到菲尔顿副队长。"}]])
R(245,"蜘蛛的威胁",[[description="你好啊，$c。你有没有看到过在西边出没的那些蜘蛛？这些八条腿的东西实在是太多了，多到我们没法应付，指挥官又没有多余的人力可以从夜色镇派来协助我们。$b$b我实在是不好意思向你开口，不过……看样子你好像能对付它们。我不能承诺给你什么贵重的宝贝，不过如果你帮助我们除掉这些肮脏的臭虫，我肯定会奖赏你的。$b$b哦，对了，给你个忠告：尽量别碰到它们的毒液。",objectives={"守夜人道茨要你杀15只小型结网毒蜘蛛。"}]])
R(246,"审时度势",[[description="我们实在是没有多余的人手了，但我们也不能对你报告中提到的那些豺狼人不闻不问。$B$B侦察南赤脊山附近豺狼人的动向,并尽可能地杀掉足够多的豺狼人,然后向我回报他们的数量，好让我们对他们的威胁大小有个正确的认识。$B$B暴风城军方需要你的帮助，$N，你会得到奖赏的。",objectives={"杀死10个混血赤脊山豺狼人和6个赤脊山偷猎者，然后向湖畔镇的菲尔顿副队长复命。"}]])
R(247,"完成狩猎")
R(248,"监视",[[description="我监视伊尔加拉之塔已经很久了，并且我发现，莫甘斯与占据了石堡要塞的兽人之间起了矛盾。我不知道他们之前产生纷争的原因是什么，但你可以帮我揭开谜底。$B$B带上阿祖拉的铭文饰品，然后到那个能监视石堡要塞的岗哨顶部去。$B$B找一个合适的地方，把铭文饰品放进去，一个盒子或者罐子之类的东西都可以，只要铭文饰品不会被注意到就行，那样我的目的就达到了。",objectives={"爬上石堡要塞一旁的哨塔。$B$B为阿祖拉的铭文饰品找一个合适的容器。"}]])
R(249,"莫甘斯",[[description="在长期的侦察监视之后，我终于发现了莫甘斯的计划。$B$B他正在寻找月神镰刀……而且，他甚至可能已经找到了。如果他有了那东西，整个赤脊山脉地区，甚至是整个暴风王国都会被他的黑暗力量所征服。$B$B我还没有想到对付莫甘斯的办法，但我怕如果现在不行动的话，也许以后就没有机会了。所以我希望你能杀进伊尔加拉之塔与莫甘斯交战。$B$B战胜他，然后把他的暗影坠饰带回来给我。如果你成功了的话，整个王国都将以你为傲。",objectives={"击败莫甘斯。$B$B将他的阴影坠饰带给塞欧克瑞图斯，他就在艾尔文森林内的阿祖拉之塔中。"}]])
R(250,"水坝危机",[[description="老天保佑，现在终于有人关心水坝的安全了。先是有人摧毁了萨多尔大桥，然后又有人抢劫丹莫德！我敢说这座大坝肯定会是黑铁组织下一次袭击的目标。这里的驻军——包括我的长官在内——大部分都开到了联盟前线。$b$b这就是我需要你的原因，$N。我看见有几个黑铁工兵在水坝东边的斜坡下转悠。去那里查看一下，带回点线索给我。",objectives={"查看水坝东边斜坡附近的区域，调查一下黑铁矮人准备做什么，然后把线索带给主工程师辛德维尔七世．"}]])
R(251,"翻译亚伯克隆比的信",[[description="请把你给我的这封信拿给希拉·沃宁迪看看。他对语言和古代艺术很有研究——我看也只有他能翻译这封信了。",objectives={"把写给艾尔罗的信拿给希拉·沃宁迪。"}]])
R(252,"翻译好的信件",[[description="天哪！如果信上所写的内容都是真的，那亚伯克隆比所做的事情……太可怕了！$B$B你最好还是把翻好的信拿回去给艾尔罗看看。$B$B快一点，我感觉到这座小镇的末日就要到了……",objectives={"把翻好的信带给艾尔罗·埃伯洛克公爵。"}]])
R(253,"藏尸者的妻子",[[description="藏尸者是个我们经常用来吓唬孩子的故事里的人物。他曾是个善良的炼金师，但因为妻子伊莉莎的死而变得疯狂。为了让妻子复活，藏尸者用黑暗的魔法将自己的心脏放入了亡妻的胸膛里。$B$B伊莉莎复活了……不过她也受到了诅咒，开始疯狂地吞食人类的血肉，藏尸者不得不将他的妻子埋了起来。$B$B他的心脏就是他全部的力量，找到他妻子的坟墓，把他那颗仍在跳动着的心脏拿回来，就可以打破他的力量。",objectives={"找到伊莉莎的坟墓，从她的身上取回藏尸者的心脏，把它交给艾尔罗·埃伯洛克。"}]])
R(254,"掘墓")
R(255,"雇佣兵",[[description="我等了两个月才得到了从铁炉堡传来的消息，说是会有少量士兵来帮助我们防守塞尔萨玛，不过他们还得再等两个月才能到这儿来！我们的镇子没人守卫已经够糟了，但是我们的挖掘场和水坝——这些地方都随时面临着被袭击的危险！$b$b看来我已经没有选择了，必须临时征召一点士兵才行。$b$b你怎么样？你看上去挺合适的，$c。有一群食人魔在洛克湖的东北方安营扎寨，你能不能帮忙再召集点人，去把那些家伙赶走？",objectives={"塞尔萨玛的镇长埃罗恩·钝鼻雇你去杀掉4个莫格罗什食人魔、4个莫格罗什蛮兵和4个莫格罗什执行者。"}]])
R(256,"通缉令：卓克苏尔",[[description="以塞尔萨玛镇长之令：$b$b卓克苏尔，袭击塞尔萨玛镇、巨石水坝及挖掘场的食人魔的领导者和组织者。现要求不惜采用一切手段杀死卓克苏尔。$b$b若有人呈上杀死卓克苏尔的证明，镇长将给予巨额奖金。$b$b卓克苏尔最后一次出现是在洛克莫丹东北部的食人魔营地里。",objectives={"杀了卓克苏尔，把他的头颅带给塞尔萨玛的镇长埃罗恩·钝鼻。"}]])
R(257,"自豪的猎人",[[description="你觉得自己可以和勇敢的达瑞尔相提并论？我可不这么认为，当然咯，如果你不服气的话，完全可以试试看。我会让你去做一件非常困难的事情，困难到以你的能力恐怕根本没法摆平，所以就算你完成不了也用不着气馁。$b$b有一群秃鹰在这一带筑巢，你去试试能不能把它们解决掉？告诉你吧，如果你能在十五分钟里完成这个任务，我就把我的弓剑或是火枪送给你。<他轻蔑地上下打量着你>$b$b看上去你也没什么可以输掉的东西。",objectives={"杀死6只山鹫，然后回到旅行者营地见年轻的达瑞尔，时限为15分钟。"}]])
R(258,"猎人的挑战",[[description="你叫$n，对吧？看得出来，完成第一个考验之后，你已经被骄傲冲昏了头脑，不是吗？我跟你说过的，那没什么了不起。$b$b你应该再试试去捕杀野猪。相信我，这和捕杀寒脊山谷里那些野猪可不一样，所以你最好当心点。这次我只给你十二分钟。$b$b失败了也别难过。不过如果你成功了，我就把我的衬衣脱下来给你！$b$b我有没有跟你说过我这个著名的伤疤是怎么来的？没有？好吧，两年前的一天……",objectives={"杀掉5只老山猪，然后回到旅行者营地去见年轻的达瑞尔，时限为12分钟。"}]])
R(259,"<UNUSED>",[[description="Hello there, $n. I've heard much about your exploits, and must say I'm honored to meet you. I don't suppose you've heard the story of Ol' Kelt? Ah, well, Ol' Kelt--Kelt Thomasin, that is--was once considered one of the finest hunters in all the realm. There wasn't much he hadn't done, but then, one day, he became obsessed with an ancient story... a myth, really. Well, as the stories go, a huge threshadon lives in the waters of the lake. Hogwash, if you ask me. If you're interested, you might talk to Kelt.",objectives={"Talk to Kelt Thomasin."}]])
R(260,"<UNUSED>",[[description="Now, this will no doubt convince you that I am, as they say--and don't deny it, I know what they say--of an addled mind, obsessed with an impossible legend. An old dwarven legend, it is, of an enormous monster that lives in the depths of the Loch. I spent a good bit of my life trying to track it down, and I believe I got close, but alas, I fear old age has caught up to me. If you would like to try hunting down the monster of the Loch, bring me some treshadon teeth and claws.$B$B<He smiles mysteriously.>",objectives={"Collect 5 Threshadon Teeth and 5 Threshadon Claws, then bring them to Kelt Thomasin."}]])
R(261,"血色之路",[[description="坦率地说，我们现在正在与天灾军团交战。他们是一群致力于腐化我们的人民、污染我们的土地的恶魔。我们一定要在他们将我们最后的堡垒彻底血洗、将我们的世界彻底拖入黑暗之前阻止他们。我们血色十字军发誓要奉献出全部身心，与天灾军团斗争到底。$B$B如果你也如此宣誓了的话，鼓起你的勇气并证明你的忠诚——去与凄凉之地的亡灵劫掠者们作战吧，它们都聚集在那个地区南部的白骨之谷里。$B$B只有这样，十字军才会接纳你。",objectives={"杀掉30个亡灵劫掠者，然后向尼耶尔前哨站的安东修士复命。"}]])
R(262,"模糊的人影",[[description="我一定要搞清楚那个躲在暗处目睹我全家被杀的人到底是谁！$B$B求求你了，$N，你已经表现出了你的足智多谋，请你帮我找出那个模糊的人影到底是谁，我一定要知道他到底是谁！$B$B我没法再给你提供更多线索了，不过……拿着这本你在农场里找到的书，也许镇上有人能够帮助我们找到它的主人。",objectives={"带着你从斯温的农场找到的书，把它拿给夜色镇上的人看看。"}]])
R(263,"保卫国王的领土",[[description="巡山人告诉我你很勇敢也很能干，$N。我们这儿就需要像你这样的$r。穴居人的问题一点也没有好转，预备军都被派到前线去了，我们在这儿孤立无援。不过现在我们有你这样一个经验丰富的$c，事情就好办一些了。$b$b去杀掉10个碎石怪萨满祭司和10个碎石怪断骨者，让我们瞧瞧你是不是名副其实的穴居人杀手。",objectives={"南部警戒塔的巡山人沃尔班要你杀掉10个碎石怪萨满祭司和10个碎石怪断骨者。"}]])
R(264,"至死方休",[[description="太过分了！他因为那该死的十字军离开了我，说什么“圣光是我们用来与亡灵抗争的最重要的东西。”$B$B那么，他的孩子呢？我呢？我日复一日地等他……一直在默默地支持着他那该死的职责！$B$B看看“公正”带给你的一切，$N！他已经死了，而我却成了他曾经想要消灭的东西！$B$B把这个垃圾放到他那修在瑟伯切尔的坟墓上吧。我不想再跟他有任何联系了！",objectives={"把克拉莉斯的坠饰放在银松森林尤瑞夫的坟墓上。"}]])
R(265,"继续搜寻",[[description="拿回你的书吧，$N，祝你好运。你可以去问问镇上的其他人，他们也许还能给你提供更多的线索。$B$B对了，我还有个线索可以提供给你——这本书的作者不是夜色镇的人，不过书却是在镇里买来的。",objectives={"看看其他的镇民有没有关于模糊的人影的线索。"}]])
R(266,"调查旅店",[[description="这是你的书，祝你好运。$B$B你不妨去旅店里查查看，如果你要找的那个人在镇上待过的话，那么很可能有人在旅店里见过他。",objectives={"到旅店去查一查关于模糊人影的线索。"}]])
R(267,"穴居人的威胁",[[description="$C，你可能不知道矮人的领地正在面临着穴居人的威胁。铁炉堡的预备部队已经被派到联盟前线去了，只有很少一部分被留下来负责保卫这里的安全。我的部队负责看守这里的大门，提防随时可能到来的攻击，我们绝不能因为害怕而离开这里。$b$b不过我们得给山里的那些穴居人施加点压力。如果你能胜任这个工作，就去干掉这些穴居人，然后带8颗穴居人的石牙回来作为胜利的证明。",objectives={"给南部警戒塔的拉格弗斯上尉带去8颗穴居人的石牙。"}]])
R(268,"回复斯温",[[description="你找到的那本书……我还没有写完。我从斯文的农场里逃走的时候，不得不把书留在那儿……$B$B拿着这个，把这本完整的日记带给斯温。这一本对在他的农场上所发生的事情描述得更完整。$B$B这几个星期以来，我一直把这本日记放在身边，不过如果把它交出来之后我就不用面对斯温和他的愤怒的话，我宁愿把这东西交给他。",objectives={"把基特斯的日记交给斯温。"}]])
R(269,"寻求指引",[[description="到暴风城去找光明大教堂的主教法席恩，把基特斯的日记给他看一看，告诉他你决心要和摩本特·费尔进行面对面的较量。$B$B虽然暴风城抛弃了夜色镇，但是法席恩主教是个善良而又睿智的人，也许他能给你一些帮助。$B$B你的使命非常危险，不过请动作快点，$N。笼罩夜色镇的黑暗力量无时无刻不在变得更加强大。",objectives={"把基特斯的日记交给暴风城的主教法席恩。"}]])
R(270,"被诅咒的舰队",[[description="几年前，库尔提拉斯的第三舰队在湿地的海岸线附近全军覆没，对，就是丹莫罗北方的那块湿地。其中一条船上满载着光铸铁。$B$B这种金属对我们来说相当珍贵，它们可以用来制造出附有神圣力量的武器。如果你要去与摩本特·费尔作战的话，应该会需要这样一把武器。$B$B去米奈希尔港找我的矮人同事戈罗林·钢眉谈谈吧，如果你可以找到那些丢失了的金属，他应该会知道该到哪里去找。",objectives={"到湿地的米奈希尔港去，找戈罗林·钢眉谈一谈。"}]])
R(271,"维林的报复",[[description="你没被达瑞尔气得昏头昏脑吧？虽然我不愿意承认，但达瑞尔还是有点能耐的。$b$b一年前，整个旅行者营地里的猎人都在捕猎一只巨熊，不过没有一个人能解决掉它。后来，达瑞尔也去试了试，结果他的脸上就留下一道了丑陋的伤疤。$b$b如果你能杀了那只熊，就算是达瑞尔也会哑口无言的。$b$b那只名叫奥尔苏迪的熊就住在塞尔萨玛附近的山上。",objectives={"杀掉奥尔苏迪，把它的头颅带给旅行者营地里的达瑞尔。"}]])
R(272,"海狮试炼",[[description="第二个试炼是要寻找组成海狮坠饰的两个部分。其中的一半蕴含着海狮的敏捷天性，另一半蕴含着海狮那令人难以置信的耐力。德鲁伊汲取这两种特性，将它们运用到自己的水栖形态中。$B$B与月光林地中的居民谈一谈，找到这两个部分，并将它们合并起来。最后把合并好的坠饰交给德迪利特·星焰。",objectives={"寻找水兽耐力坠饰和水兽敏捷坠饰。与月光林地的居民谈一谈，找出这些东西可能被放在哪里。$B$B在雷姆洛斯神殿附近将海狮坠饰的两部分合而为一。$B$B将合并好的坠饰交给月光林地永夜港中的德迪利特·星焰。"}]])
R(273,"挖掘场的补给品",[[description="现在还不算太晚，你还可以去找胡达尔。他不大可能走得太远，尽管米兰和赛恩都很壮实，但是他们带着几只大桶是没法走太快的。$b$b他们走的是补给车队常走的路线，从镇子出发，沿着洛克湖的边缘往南走。$b$b只要他们还没走到挖掘场，你就应该可以在路上找到他们。",objectives={"和胡达尔谈一谈。"}]])
R(274,"水坝危机",[[description="这不是一般的炸药粉末。看看这些银色的小晶体。还有这股特别的味道！不用说这就是爆盐粉末了！爆盐本身没什么危害，不过一旦它沾上水，那威力，啧啧！足够把整个铁炉堡给炸上天！$b$b要想阻止这种东西爆炸就需要四种东西：潜伏者的毒液，莫格罗什水晶，一滴鳄鱼的眼泪和一些拆弹胶质。现在你得赶紧把我的话告诉辛德维尔，否则就来不及了！",objectives={"阿什兰·暗石要你回去见主工程师辛德维尔七世，把有关这种炸药的新发现告诉他。"}]])
R(275,"大地上的脓疱",[[description="我不知道是怎么回事，但是堕落正在湿地上蔓延。沼泽爬行者出现了，他们就像是腐烂而危险的脓疱。要制止这些脓疱，就必须把他们驱散开，把它们赶回沼泽。$B$B这些沼泽爬行者一般都在湿地的水道里活动。",objectives={"杀死12只沼泽爬行者，然后向湿地的绿色守卫者雷希耶尔复命。"}]])
R(276,"践踏之爪",[[description="藓皮豺狼人在湿地平静地生活了许多年，但如今他们的数量却膨胀了不少。他们的脚正践踏着沼泽地中的灌木与花朵，他们污浊的斧子也砍伐了太多的树木。$B$B他们已经令这里的自然失去了平衡。为了湿地的安宁，必须削减这些豺狼人的数量。$B$B去杀死15名藓皮豺狼人和10名混血藓皮豺狼人，他们就在南边的奥加兹大门附近活动。完成任务之后再回来向我复命。",objectives={"杀死15名藓皮豺狼人和10名混血藓皮豺狼人，然后向湿地的绿色守卫者雷希耶尔复命。"}]])
R(277,"火焰管制",[[description="藓皮豺狼人们正在大量地砍伐湿地的树木，用树干和树枝当柴火来烧。我不能再容忍这样的行为了！$B$B把藓皮豺狼人生火用的打火石都给我抢过来。除了年幼的藓皮豺狼人和混血藓皮豺狼人以外，其它所有的藓皮豺狼人身上都会带着打火石。",objectives={"给绿色守卫者雷希耶尔带回9块粗制打火石。"}]])
R(278,"水坝危机",[[description="你必须立刻去收集拆弹用的原料，$N。潜伏者的毒液在洛克莫丹的蜘蛛身上可以找到，鳄鱼的眼泪在洛克湖一带的鳄鱼身上也有。不过莫格罗什水晶很难找到。东北边矿井里的食人魔开采这种水晶，不过即使在那里，莫格罗什水晶也不常见。$b$b我们必须要作好准备才能粉碎黑铁矮人的计划！你找齐了这些材料之后就立刻回来找我，我会把它们做成拆弹剂。",objectives={"主工程师辛德维尔七世要你收集一份潜伏者的毒液，一块莫格罗什水晶和一滴鳄鱼的眼泪。"}]])
R(279,"海中的鱼人",[[description="可恶的鱼人正在从深海里源源不断地爬出来，它们沿着海岸线建立自己的村庄和定居点。这些家伙给我们的渔民和商人带来了极大的困扰，我们必须要阻止这种行为。$B$B它们当中有一个叫高布勒尔的头目最近一直带着一群蓝腮鱼人埋伏在道路旁，抢劫过往的商旅，得手之后又马上撤回它们的村子。现在我们的通商道路非常危险，所以我们想要通过悬赏来解决这个问题。$B$B高布勒尔和它的跟班们就躲在北边的河口附近。找到它，把它干掉，然后把它的头给我带回来。",objectives={"杀掉12个蓝腮鱼人。$B$B杀掉高布勒尔并砍下它的头。$B$B将高布勒尔的头颅交给米奈希尔港的卡尔·波兰。"}]])
R(280,"水坝危机",[[description="今天早些时候我发现有一些黑铁矮人背着一只大木桶向水坝游去，糟糕的是那一带没有巡山人可以拦住他们！我怀疑他们已经把爆盐炸药放到了水坝下面，随时都有可能爆炸！我马上就把这些成分混合在一起制成拆弹剂。$b$b完成了！现在我要你把这个混合剂拿去，和木桶里的炸药搅拌在一起！快一点！我们没时间了！",objectives={"主工程师辛德维尔七世要你游到水坝底部，找到装着炸药的木桶，然后把拆弹剂放进去，阻止将要发生的爆炸。"}]])
R(281,"夺回雕像",[[description="不久之前，有一艘名叫“盲眼公主”的商船遭到了一群鱼人的袭击。尽管这艘船完完整整地逃了出来，但船甲板上放着的货物都被那些该死的鱼人给拖下水抢走了，其中甚至包括一座十分宝贵的泰瑞纳斯·米奈希尔的雕像。我们希望有人能把这座雕塑给抢回来。$B$B到海岸边的鱼人村落里去，仔细找找看有没有木箱、木桶，或者其他丢失货物的踪迹。在那里找到米奈希尔雕像，然后回来向我复命。",objectives={"搜索海边鱼人村落中的木箱和木桶。"}]])
R(282,"森内尔的观察站",[[description="我原打算让我的学徒帮我把报告带给我的兄弟森内尔。但是，你看他那德性……我想如果有一个更可靠的人替我去送的话就更好了。如果你不介意的话，可以去一趟吗？$b$b嗯……你要穿越隧道，一路走到卡拉诺斯。$b$b在穿越隧道前，别忘了去和巡山人萨鲁斯聊聊，那里的穴居人简直成灾了。$b$b顺着这条路回到安威玛尔，然后向东就能到隧道了，萨鲁斯就在附近。",objectives={"和巡山人萨鲁斯谈一谈。"}]])
R(283,"水坝危机",[[description="木桶发出了轻微的嘶嘶声。",objectives={"拆弹剂看来已经产生了效果。你可以回去向主工程师辛德维尔七世汇报这个好消息了。"}]])
R(284,"继续搜寻",[[description="你继续在鱼人的村庄中仔细搜索着，但没有找到任何关于米奈希尔雕像的蛛丝马迹。$B$B也许北边和东北边的另两处鱼人村落那会有些什么线索。",objectives={"搜索米奈希尔雕塑。"}]])
R(285,"搜寻雕像",[[description="你仔细地搜索了这几处鱼人村落，但却没什么有价值的发现。$B$B……但你有一种直觉，就是你在下次搜索中一定能找出一些很有价值的线索。$B$B北边的最后几处村落里一定会有米奈希尔雕像！",objectives={"继续在鱼人村落中搜寻米奈希尔雕像的踪迹。"}]])
R(286,"归还雕像",[[description="你把这个木桶从垃圾里拖了出来，刚一打开它，一尊精心包裹在稻草中的银制小雕像就掉了出来。这是一个头发很长的年轻圣骑士高举战锤的样子。$B$B这一定就是米奈希尔雕像了！你必须马上把它交还给米奈希尔港的卡尔·波兰。",objectives={"将米奈希尔雕像还给卡尔·波兰。"}]])
R(287,"霜鬃巨魔要塞",[[description="我快要来不及提交报告了，你能帮我一下吗，$n？我只想知道这些巨魔躲在什么地方，不过我看见这么多的巨魔就怕得不敢进去了。$b$b你要做的是……进到山洞里，在里面到处走走，干掉一些巨魔，然后再回来。$b$b顺着向北的路离开卡拉诺斯，当你走到一座桥前的时候，再沿着冰冻的河流向西一直走到涌冰湖。你会发现烈酒村就在湖的西岸，而巨魔要塞就在村庄的西南边。",objectives={"侦查霜鬃巨魔要塞，替卡拉诺斯的森内尔·白须杀掉5个霜鬃猎头者。"}]])
R(288,"第三舰队",[[description="我曾经是浪花女神号上的大副——浪花女神是库尔提拉斯第三舰队的主力战舰。这是一支多灾多难的舰队，说它多灾多难是因为……它在最后一次出航中遇到了红龙的袭击。这些龙是被兽人控制的！$B$B红龙喷出的火焰对我们的战舰来说简直是毁灭性的……我们的舰队在这片海域被烧得一干二净，全军覆没。我是那次灾难的唯一幸存者……$B$B……哦，我的头疼得像鼓槌在敲！我需要一些让我头脑清醒的东西，好让我继续讲述我的故事。",objectives={"为大副菲兹莫斯买一份壶装蜜酒。"}]])
R(289,"被诅咒的船员",[[description="<缓过气来的菲兹莫斯继续讲述他的故事……>$B$B我是这支倒霉的库尔提拉斯第三舰队中唯一的幸存者，整支舰队都在北方的海岸附近覆灭了。不过，虽然我是舰队中唯一活着的人，却不是唯一一个依然在这里出现的人！因为，在一条已经沉没的船里，藏有巨大的、可怕的宝藏，它所拥有的可怕魔力将我的弟兄们的灵魂束缚在被海水侵蚀的船体里。$B$B如果你能超度我的那些被诅咒的弟兄们，也许你就能破除那个诅咒。",objectives={"杀死13个被诅咒的水手、5个被诅咒的水兵和大副斯涅利格。把斯涅利格的鼻烟盒交给米奈希尔的大副菲兹莫斯。"}]])
R(290,"解除诅咒",[[description="为了破除诅咒，解救我所有的兄弟，就必须要把装在我船上的那个鬼东西拿回来进行净化！我不知道它是什么，但我知道它被存放在船上的保险箱里，而保险箱的钥匙一向是由哈林多尔船长保管的。$B$B我的老船长仍时常出现我的梦里，在我的那艘已毁灭了的无畏号的甲板上走来走去……去找到钥匙，用它打开无畏号上的保险箱。$B$B然后，在你获得那件被诅咒的东西以后，把它交给镇上的牧师，戈罗林·钢眉。",objectives={"从哈林多尔船长那里拿到无畏号的保险箱钥匙。$B$B用钥匙打开无畏号上的保险箱。"}]])
R(291,"森内尔的报告",[[description="好极了！把我的报告交给参议员巴林·红石。他是个酸溜溜的家伙，你可别在意。他在铁炉堡，麦格尼陛下的宫殿里。$b$b你不知道去铁炉堡的路？顺着这条路向北走出卡拉诺斯，穿过一座桥，然后沿着路向东走——在路边山上应该有个很大的路标。$b$b顺便说一句，你最好不要提及你是如何帮助我的，不要让他们以为我在这里没有好好工作，好吗？",objectives={"把森内尔的报告交给铁炉堡的参议员巴林·红石。"}]])
R(292,"帕雷斯之眼",[[description="打开箱子之后，你看到了一颗发黑的宝珠，它还在闪烁着可怕的光芒。这就是菲兹莫斯所说的宝藏：一颗被诅咒的帕雷斯之眼。$B$B把被诅咒的帕雷斯之眼交给住在米奈希尔港的矮人牧师戈罗林·钢眉，请他驱除附着在它上面的诅咒。",objectives={"把被诅咒的帕雷斯之眼交给戈罗林·钢眉。"}]])
R(293,"净化帕雷斯之眼",[[description="我无法驱散帕雷斯之眼上的诅咒。它是由人类牧师手工制造的，所以你最好去暴风城寻找帮助。去和大主教本尼迪塔斯谈谈吧，他是暴风城光明大教堂的领导者，他能帮你解决问题。$B$B我希望如此。",objectives={"把被诅咒的帕雷斯之眼交给大主教本尼迪塔斯，他就在暴风城的光明大教堂里。"}]])
R(294,"奥莫尔的复仇",[[description="目前我们所面临的形势十分严峻，这已经是众所周知的事了。我们刚挖出这些骨头，它们就招来了一大群迅猛龙。这些凶残的野兽杀光了我的弟兄们，并把我、麦琳和可怜的勘察员困在了这上面。$b$b帮我把湿地里的这些迅猛龙都给杀光，$N。杂斑迅猛龙和杂斑尖啸龙就在山崖的西边，要是你有能力对付它们的话，每种都给我杀上十只。$b$b这只不过是我对它们的复仇计划的开始而已！",objectives={"维尔加挖掘场的奥莫尔·铁衣要求你杀死10只杂斑迅猛龙和10只杂斑尖啸龙。"}]])
R(295,"奥莫尔的复仇",[[description="现在是时候让这些该死的迅猛龙为它们的嗜血而后悔了。在悬崖下面还有一些杂斑刺喉龙和杂斑锯齿龙，每种都给我杀10只，它们要为自己的所作所为付出代价！",objectives={"奥莫尔·铁衣要求你杀死10只杂斑刺喉龙和10只杂斑锯齿龙，然后回到维尔加挖掘场向他复命。"}]])
R(296,"奥莫尔的复仇",[[description="在你下到悬崖底部的时候，我碰巧发现了有一只很特别的迅猛龙在那边站着休息。它比一般的迅猛龙的体形要大得多，看上去也特别凶猛。我敢打赌它就是那群迅猛龙的首领，就是它带着手下来这里毁了整个挖掘场。$b$b我现在交给你最后一个任务，$N。以正义的名义，审判萨尔图斯！当然，考虑到它所犯下的重罪，它唯一能得到的判决就是死刑！把它的一只爪子给我带回来作为它已死的证据。",objectives={"维尔加挖掘场的奥莫尔·铁衣要求你杀死萨尔图斯，并在任务完成之后带着它的一只爪子向他复命。"}]])
R(297,"收集石像",[[description="不久前，就在那些穴居人像雨后的蜗牛一样冒出来之前，我们发现了一大批奇特的小石像。但是还等我们开始着手研究它们，穴居人就把我们从废墟里赶了出来！这些石像有种奇特的效力，它可以让那些穴居人变得更加疯狂！$B$B给我拿几个石像回来——我想研究研究，所以你得把它们从穴居人手上给我抢过来！你可以在挖掘场里到处都是的穴居人身上拿到这些石像。",objectives={"收集8个小石像，把它们交给麦格玛尔·落斧。"}]])
R(298,"挖掘进度报告",[[description="我这里有一份报告要赶快送到塞尔萨玛去——这是一份挖掘进度报告，还有一份再次重申我们需要更多的火药粉的报告！你把它带给吉恩·角盔，他是我们在塞尔萨玛的联系人。$B$B这个任务没什么麻烦的，但你一定要完成它。",objectives={"把铁环挖掘场的进度报告带给塞尔萨玛的吉恩·角盔。"}]])
R(299,"发现历史",[[description="在迅猛龙大举入侵之前，我找到了一块名叫戈奥兹之石的巨大石碑。我翻译好的文字被分成了四部分，散落在挖掘场中的四个不同的地方。这些文字描述的是一个“神圣的计划”和一个“注定的命运”。$b$b我们应该马上把它们都收集起来，而不是继续在这里浪费时间。但是我已经很老了，恐怕没办法再杀出去跟那些凶猛的野兽作战了。但是你不同，你年轻而强壮。$b$b到挖掘场里去搜索这四片失落的石板：阿度斯石板、莫德尔石板、高尔姆石板和奈尔鲁石板。它们应该被藏在某些古董器物里，另外你也得留意土壤松动的地方。把它们拿回来给我，这样我才能揭开这个秘密！",objectives={"勘察员维尔加要求你在挖掘场中搜索4块石板的碎片，它们是阿度斯碎片、莫德尔碎片、高尔姆碎片和奈尔鲁碎片。"}]])
R(301,"向铁炉堡报告",[[description="我们必须得到上级的批准才能给铁环挖掘场送去更多的火药粉。把他的报告带到铁炉堡的探险者协会总部去，交给勘察员塔伯斯·雷矛。他可是个急性子的家伙，如果听说铁环挖掘场的进展如此缓慢，他一定会暴跳如雷的。$B$B你可以在探险者大厅里找到他。",objectives={"把铁环挖掘场的进度报告交给勘察员塔伯斯·雷矛。"}]])
R(302,"铁环的火药",[[description="如果铁环还需要火药粉的话，以麦格尼的名义，就再给他送一批过去！我已经派了一个信差把我的许可交给塞尔萨玛的吉恩·角盔，让他负责准备火药和其它物资。$B$B还有一件事情：我要你保证亲自把这批火药送达目的地。上一批没有送到，中间也许出了什么岔子，所以这次你得仔细提防着点。",objectives={"和塞尔萨玛的吉恩·角盔谈一谈。"}]])
R(303,"黑铁战争",[[description="战火席卷了整个世界。当许多精锐的矮人士兵们为了联盟而牺牲在前线时，我们自己的土地却沦为了这群邪恶的黑铁矮人觊觎的目标。他们已经攻陷了萨多尔大桥，丹莫德也岌岌可危。$b$b我们要你去聚集起一股力量，并将战线推回去。如果你能杀死十五名黑铁矮人、五名黑铁隧道工、五名黑铁破坏者和五名黑铁爆破手的话，就能为我们组织反击争取到宝贵的时间。$b$b兵贵神速，快出发吧！",objectives={"丹莫德的莫特雷·加玛森要求你杀死15名黑铁矮人、5名黑铁隧道工、5名黑铁破坏者和5名黑铁爆破手。"}]])
R(304,"艰巨的任务",[[description="我手下的大部分士兵都在丹莫德的战役中死去了，我的亲兄弟也在萨多尔峡谷上的西桥被毁的时候不幸牺牲。唉，黑铁矮人真是个像恶魔一般邪恶的族群。根据罗戈收集到的情报，这群在湿地四处肆虐的暴徒的领袖是一个名叫巴尔加拉斯的术士。他是个十分胆小谨慎的家伙，在把手下的士兵送上战场执行命令的时候，他自己往往却躲藏在某个不为人知的地方，躲避着任何可能面临的危险。$b$b如果你能找到这个懦夫，杀了他，把他的耳朵拿来给我，我会给你支付可观的酬劳的，$c。",objectives={"杀死邪恶的巴尔加拉斯，把他的耳朵带给丹莫德外的布莱德·长须。"}]])
R(305,"寻找挖掘队",[[description="啊，天呀，你一定就是长须派来的帮手！你真是不知道我有多担心。$b$b我的老婆麦琳上个月的时候每礼拜都会给我写一封信的。她是维尔加挖掘队的成员，她最后一次写信过来是两周前的事了。一定是出了什么事！$b$b长须说，要是我们一直都没有收到挖掘队那边送来的信，那么他就会派出一名探子去看看情况。我猜那个探子应该就是你吧，$N。快去东边的挖掘场里找到麦琳！",objectives={"塔雷尔·石纹要求你到挖掘场里去找到麦琳·石纹。"}]])
R(306,"寻找挖掘队",[[description="这太恐怖啦！我们刚刚发现了一些十分稀有的古物，而且正在把这些巨大的骸骨挖掘出来，这个时候，可怕的事就发生了，在我们反应过来之前，多到数不清的杂斑迅猛龙冲进了挖掘场，咬死了许多人！$b$b勇敢非凡的奥莫尔救下了我和勘察员，并一直把我们护送到了一处藏身之所。现在我们被彻底困在这里了，逃也逃不出去，我们努力工作的成果也全毁了。$b$b给，把这封信带回去交给我亲爱的塔雷尔，我已经在信里把事情跟他解释清楚了。",objectives={"把麦琳的信件交给塔雷尔·石纹复命。"}]])
R(307,"肮脏的爪子",[[description="东边的银泉矿洞很久以前就枯竭了。矿工联盟把它改造成了储藏库，不过现在狗头人占据了那里，把他们肮脏的爪子放在了我们矮人制造的工具上！$B$B我们很快就能把这些害人虫赶走，但是矿工联盟要求我们在冲进去大开杀戒之前，先把洞里的矿工装备拿出来。这是个艰难的任务——你也许需要几个帮手。$B$B他们的装备就在矿工联盟的储物箱里，祝你好运。",objectives={"到银泉矿洞去收集4套矿工装备，然后向巡山人卡尔·雷矛复命。"}]])
R(308,"加文的爱好")
R(309,"护送货物",[[description="准备出发了吗，$n？$b$b首先，我们得把炸药粉送到铁环挖掘场。要我一个人运这么多炸药太困难了，这些东西又很危险——而且谁知道那帮黑铁矮人打算对我做什么？$b$b有你跟我一起走，我感觉就好多了。",objectives={"确保把米兰和货物送到挖掘场，然后通知勘察员基恩萨·铁环。"}]])
R(310,"针锋相对",[[description="我不得不承认，雷酒家族的那帮家伙酿酒水平还真不赖。但是他们应该知道他们的酒并不是世界上最好的！也许你能帮我让他们了解这一点……$B$B给，带上这桶热麦酒，想办法潜入卡拉诺斯的雷酒酿造厂的酒窖，把他们的雷霆啤酒和我们的换一下。然后，我们就等着看好戏吧，顾客们肯定会更喜欢我的酒！$B$B如果有人看着酒桶的话，你就得想办法转移他的视线……",objectives={"到卡拉诺斯的雷酒酿造厂酒窖里去，把一桶雷霆啤酒换成热麦酒。"}]])
R(311,"向马莱斯回报",[[description="把一桶马莱斯的热酒放进了卡拉诺斯酿酒间的地窖里之后，你取回一桶雷霆麦酒作为行动成功的证明。",objectives={"把雷霆麦酒交给烈酒村的马莱斯·麦酒。"}]])
R(312,"马克格拉恩的干肉",[[description="我原本储备了一个月的干腌肉准备过冬，为了防止野熊把肉衔走，我把它们锁在了储藏柜里。但是在我外出打猎的时候，一个叫做冰须的野兽偷走了我的储藏柜！可笑的是那个蠢货撬不开这只用瑟银铸成的柜子。$B$B但是如果拿不回这些肉，我就会饿死的。你的身手看来不错，也许你能帮我取回储藏柜？你瞧我拖着这条废腿也没办法把那只柜子抢回来……",objectives={"从冰须的洞穴里拿回装有马克格拉恩的干肉的储藏柜。"}]])
R(313,"灰色洞穴",[[description="不是每个人都能驾驶攻城坦克的，你必须要有强壮的身体和钢铁般的神经……幸运的是，这两个条件我都有！你呢？你有足够的勇气吗？想不想证明给我看？$B$B啊……我想把我的“巨魔碾压者”号坦克改造得更舒适些，你去帮我在卡拉诺斯西边的灰色洞穴里弄一堆雪怪的鬃毛来吧，我要用那些鬃毛做一张大毯子来装饰我那“巨魔碾压者”的驾驶舱。",objectives={"收集8束雪怪的鬃毛，把它们交给驾驶员迪恩·石轮。"}]])
R(314,"保护牲畜",[[description="午夜的时候，我们听到了吵闹的声音。今天早上我才发现羊圈里少了两只羊，那头名叫瓦加什的野兽袭击了我们的牲畜。由于国王麦格尼的军队大都在遥远的战场上与联盟其他的种族并肩作战，所以没有人能对付得了瓦加什。$b$b也许你有勇气找到这只猛兽并杀了它。把它的一颗牙齿交给我作为证明，我会奖赏你的。瓦加什就躲在这里的农场附近，小心点，它非常凶残。",objectives={"山羊农场的鲁德拉·冻石要你杀了瓦加什，并且把它的牙齿给她带回去。"}]])
R(315,"完美烈酒",[[description="我正在寻求可以酿制出完美的酒的方法。我知道我能酿造出来，我缺的只是一份正确的酿酒配方……$B$B霜鬃巨魔在东边的山坡上种植了一种叫做微光草的植物，他们通常在奇怪的部族仪式上用到它。我们矮人还没有发现这种草有什么用途，不过它的口味非常特别……我要把这种植物用在我的酒里！$B$B从霜鬃先知那里给我弄一些微光草来，或者你也可以从巨魔用来装微光草的篮子里偷一些。",objectives={"收集6束微光草，把它们交给烈酒村的雷杰德·麦酒。"}]])
R(316,"<UNUSED>")
R(317,"贝尔丁的补给",[[description="我正在准备为攻城坦克旅执行一项任务。这次任务会持续很长时间，所以我得预先收集能够维持一个月的物资。贝尔丁正忙着修理我的坦克，你能帮我去弄一些东西来吗？$B$B我需要一些毛皮来做床垫，还要一些野猪肉作为食品储备。猪肉当然是从野猪身上割下来的，最好的毛皮是熊皮……在灰色洞穴南部的雪地上到处都是这两种动物的踪迹。",objectives={"收集4大块野猪肉和2张厚熊皮，把它们交给钢架补给站的驾驶员贝隆·风箱。"}]])
R(318,"艾沃沙酒",[[description="雷杰德·麦酒一直以来都亲口试验他自己酿制的酒。有的好喝，有的难喝，还有的连酒量最好的矮人都能轻松放倒。$B$B他住在烈酒村，那地方就在卡拉诺斯的西边。我需要一些他酿造的那种叫作艾沃沙的酒，在寒冷的旅程中，喝这种酒能帮我暖暖身子。$B$B还有……这种酒实在是太烈了，在紧要关头还可以当燃料使，只要把它注入我那坦克车的油箱里，整辆坦克都会爆发出无穷的力量！这个小诀窍让我不止一次地化险为夷。",objectives={"从烈酒村的雷杰德·麦酒那里弄到一桶艾沃沙酒。"}]])
R(319,"艾沃沙酒",[[description="我有一桶酿制好的艾沃沙酒，不过……你能帮我个忙吗？烈酒村急需人手去对付在村子附近溜达的野兽。有时它们离我们非常近，那真是太危险了。$B$B我们并不害怕这些熊啊，豹啊，野猪啊——任何一个有自尊的矮人都不会害怕——不过，如果你能替我把它们搞定的话，我就能腾出更多的时间来酿酒了。",objectives={"杀掉6头冰爪熊、8只老峭壁野猪和8只雪豹，然后回到烈酒村的雷杰德·麦酒那里。"}]])
R(320,"艾沃沙酒",[[description="这是你要的艾沃沙酒，$N。再次感谢你给予我们的帮助。",objectives={"把这桶艾沃沙酒交给钢架补给站的驾驶员贝隆·风箱。"}]])
R(321,"光铸铁",[[description="这附近的海滩上的船只残骸大多是属于库尔提拉斯第三舰队的，在上一次大战中，那支舰队曾与红龙们在此激战，不幸全军覆没了。$B$B那支舰队里的船大多是洛丹伦的战舰，但有一艘船却不是，那是一艘名叫“飞翔鱼鹰”的精灵驱逐舰。它运着满满一船的光铸铁加入了第三舰队的船队中，本以为这样就足够安全了，结果却讽刺性地落得个被红龙击沉的厄运……$B$B故事就讲到这儿吧，飞翔鱼鹰的残骸就在米奈希尔港的南边。如果你能在那里找到光铸铁的话，就把它给我带回来吧。",objectives={"搜索飞翔鱼鹰号的残骸。"}]])
R(322,"格瑞曼德·艾尔默",[[description="暴风城矮人区有一个名叫格瑞曼德·艾尔默的矮人武器匠会用这种光铸铁来打造武器。$B$B我已经把你找到的这些铁锭用木箱装好了。把这个箱子交给格瑞曼德，再把你的事情告诉他。我敢打赌他一定会义愤填膺地马上着手为你打造武器的，嘿嘿，那肯定是把就连摩本特·费尔看到了也会心惊胆颤的武器！",objectives={"将这箱光铸铁锭交给格瑞曼德·艾尔默。"}]])
R(323,"证明你的实力",[[description="摩本特·费尔是个亡灵巫师，也是黑暗强盗的帮凶。我希望你能去除掉摩本特·费尔，不过在了解你真正的实力之前，我还不能贸然拿你的生命开玩笑。$B$B你已经证明了你的勇气，不过如果你想要面对面地和这个巫师作战，首先得证明你能应付得了他的爪牙。",objectives={"杀掉15个骷髅袭击者、3个骷髅医师和3个骷髅看守，然后回来见斯温。"}]])
R(324,"丢失的铁锭",[[description="你好不容易把那块光铸铁锭从泡在水里的箱子中拿了出来，显然，是鱼人偷走了其余的铁锭。猎杀飞翔鱼鹰号残骸周围的鱼人，拿到它们身上带着的光铸铁锭。",objectives={"收集5块光铸铁锭，把它们交给湿地的戈罗林·钢眉。"}]])
R(325,"整装待发",[[description="你已经准备好了吗，$N？祝你好运！我期待着你凯旋归来！",objectives={"现在你已经得到了强大的武器，去向暮色森林的斯温复命吧。"}]])
R(328,"隐藏的钥匙",[[description="尽管在这些档案文件里都没有提到列兵索尔森，但你发现在赫罗德的一本帐薄后面绑着一只小小的黄铜钥匙。$B$B你还在研究他的其它笔记时发现了其中有一小部分提到，在一个“安全的保险箱”中装有大量的文件。这个保险箱应该在库尔森营地后山的某处洞穴之中，他们管那里叫“储藏室”。$B$B如果你能找到这个保险箱并用这把黄铜钥匙打开它的话，或许里面的文件有助于找到导致索尔森身份暴露的内鬼。",objectives={"使用黄铜钥匙打开书呆子赫罗德的保险箱。"}]])
R(329,"找出内鬼！",[[description="在箱子里的这些贵重物品之中，还有一张满是灰尘且写得十分潦草的便笺。尽管几乎已经没法辨认了，但你能看出来这便笺上面似乎描述了列兵索尔森所走的路线。这应该是他的巡逻路线，以及反抗军方面与他接头的人员与时间。签名只有一个字母：M。$B$B毫无疑问，这应该是索尔森身边的人写下的便笺，而且这个人就是反抗军营地中的卧底。",objectives={"将沾泥的便笺交给叛军营地里的多伦上尉。"}]])
R(330,"巡逻时间表",[[description="你给我的便笺上的签名只有一个字母“M”……我也不知道这代表谁。$B$B但是……这便笺同时也告诉我们，这个人应该是上周与索尔森一同巡逻的同伴。所以，只要知道上周谁和索尔森一起巡逻过，那他就应该是内鬼没错了！$B$B去找塞斯曼下士问一问，他是负责制订巡逻时间表的人，可以告诉你那个时候索尔森和谁在一起。",objectives={"与塞斯曼下士谈一谈。"}]])
R(331,"向多伦报告",[[description="多伦上尉不是说要你向他回报关于巡逻时间安排的情况吗？",objectives={"与多伦上尉谈一谈。"}]])
R(332,"酒店的广告",[[description="无论你跟任何人谈起酒，大家都会告诉你加林纳家卖的酒是全暴风城最好的。而且那里离我们这儿并不远，就在贸易区中，运河的边上。$B$B给，拿着这张酒票。把这个拿到店里去，交给我的姐姐苏泽塔，她会送你一瓶我们酿造的最有名的黑葡萄酒。你绝对不会后悔的！",objectives={"到加林纳酒店去, 将酒票交给苏泽塔·加林纳以换一瓶免费的酒。"}]])
R(333,"哈兰需要供货",[[description="我们过几天肯定会有大单的生意。现在似乎每个人都在购买盔甲和结实的衣服，好象他们都以为明天就会变得天寒地冻一样……$B$B但那是以后的事了。我现在最担心的是我已经卖完了全部库存的针织布，需要一次大批量的供货。$B$B如果你能把我的这个要求带给运河裁缝店的雷玛·施涅德的话，我会非常感谢你的。",objectives={"找到运河裁缝店，并将哈兰·巴格雷的布料订单带给雷玛·施涅德。"}]])
R(334,"萨尔曼的针线包",[[description="我的儿子萨尔曼在法师区的拉尔森服装店里当学徒。他今天早上走得太着急了，忘了他的剪子和针线。我知道你这样伟大的$C一般都会有些重要的事要做，可要是没了工具的话，萨尔曼可没办法做他的工作呀！$B$B拜托了，$N。你能帮我把他的针线包拿去给他吗？拉尔森服装店是法师区里的两家裁缝店之一，在比较靠里面的地方，也就是靠近法师塔的地方。",objectives={"到暴风城法师区的拉尔森服装店去，将针线包带给萨尔曼·斯涅德。"}]])
R(335,"名酿",[[description="维沙克公爵最近正在贵族议会中兴风作浪，他似乎知道一些我们的事情，而且还游说其他议员们，要他们通过他提出的对这里进行一次全面调查的提案。我有一个计划，能让维沙克迷上些别的什么东西……但我需要你的帮助。$b$b在夜色镇郊区的斯塔文的花园里生长着一种名叫蒂罗亚之泪的白色小花，去给我弄一朵来。另外我还需要一些麝鼠根，那种东西只生长在湿地，就在巨石水坝下的瀑布底部。",objectives={"黑爪加尔德斯要求你从夜色镇给他摘1朵蒂罗亚之泪，再从湿地给他采一块麝鼠根。"}]])
R(336,"名酿",[[description="维沙克公爵与所有人一样有自己的弱点，他对酒的爱好胜过一切。更可恶的是，这个蠢货整天想着把我们这个小小的酒馆给弄关门了，而他自己却呆在楼上整夜整夜地喝个不停，至于那些像滚雪球一样越攒越多的账单，他是肯定不会付的。好吧，让我们看看维沙克会有多喜欢我们给他准备的这种特制佳酿：黑爪烈酒。这一定会很有意思的，$n。$b$b把这个带给他，看看他的反应如何，我觉得这傻瓜可能会在祈愿厅里当场开喝。",objectives={"将黑爪烈酒带给祈愿厅里的维沙克公爵。"}]])
R(337,"一本破旧的历史书",[[description="这本书的封面已经有被刮坏的痕迹，还沾上了泥污，但是书脊上“暴风城的历史”的字样仍然清晰可见。打开书的第一页，可以看到上面盖着暴风城图书馆的印章。$B$B看起来似乎有人从图书馆借出了这本书却从来没有归还……",objectives={"把《暴风城的历史》这本书还给暴风城图书馆。"}]])
R(338,"荆棘谷的青山",[[description="如果奈辛瓦里知道了这一切，他一定会很生气的！$b$b出于对我的信任，他让我来校对他的小说《荆棘谷的青山》的手稿。一开始事情进行得非常顺利，但昨天一阵大风吹过了营地，结果把手稿吹得满天都是！$b$b我已经很努力地找回了大部分的书页，但还是有几页被吹进了丛林中。请你帮我把这四章里的掉落的那几页书都给收集起来吧。$b$b等这四章手稿都搜集齐了以后，把它们还给我。",objectives={"收集《荆棘谷的青山》的手稿中丢失的页面。在集齐四章书之后，将它们还给巴尼尔·石罐。"}]])
R(339,"荆棘谷的青山 - 第一章",[[description="第一章实在是太精彩了，令人欲罢不能！奈辛瓦里设定了小说的背景，而且在小说里提到了他的同伴们，甚至包括我！$b$b不过，糟糕的是……有几页好象弄丢了。似乎第1页，第4页，第6页和第8页落在丛林中的什么地方了！",objectives={"将奈辛瓦里的小说《荆棘谷的青山》的第1页，第4页，第6页和第8页带给巴尼尔·石罐以凑齐第一章。"}]])
R(340,"荆棘谷的青山 - 第二章",[[description="第二章是整个激动人心的狩猎故事的楔子。可里面也有几页找不到了，我真想踢自己几脚！$b$b看来我必须得找到第10页，第11页，第14页和第16页才能凑出完整的第二章。",objectives={"将奈辛瓦里的小说《荆棘谷的青山》的第10页，第11页，第14页和第16页带给巴尼尔·石罐以凑齐第二章。"}]])
R(341,"荆棘谷的青山 - 第三章",[[description="第三章是我最喜爱的部分。里面详细讲述了埃尔加丁爵士和罗欧克女士使用矮人步枪完成的第一次狩猎。而且第三章的结尾也写得极好，为什么？因为实在是太扣人心弦了！$b$b不过，让我看看，似乎我们仍然要需要找回第18页，第20页，第21页和第24页来凑齐这一章。这些书页不知被风吹到哪里去了……",objectives={"将奈辛瓦里的小说《荆棘谷的青山》的第18页，第20页，第21页和第24页带给巴尼尔·石罐以凑齐第三章。"}]])
R(342,"荆棘谷的青山 - 第四章",[[description="啊，第四章，大结局！多么精彩的结局啊！$b$b第四章里我们只丢了3页，也就是第25页，第26页和第27页。",objectives={"将奈辛瓦里的小说《荆棘谷的青山》的第25页，第26页和第27页带给巴尼尔·石罐以凑齐第四章。"}]])
R(343,"关于坚韧的演讲",[[description="我正要作一次关于“坚韧的灵魂”的演讲，我想引用一本关于金属学的著作《金属的延展性》里的一些段落。暴风城堡里的皇家图书馆里应该有这本书的副本。你能把它拿来给我吗？如果可以的话，圣光定会保佑你的！$B$B皇家图书馆很大，但首席管理员米尔顿·西弗对每一个书架上有些什么书都了如指掌。告诉他我需要什么，他就会把书找给你的。",objectives={"到暴风城堡的皇家图书馆去与米尔顿·西弗交谈，他将会为你找到克里斯托弗修士所需要的关于冶金学的书。"}]])
R(344,"帕克斯顿修士",[[description="《金属的延展性》？是的，我知道这本书。那是本非常好的书，是十几年前一位矮人矿工马戈尔夫·布拉贡写的。他的一生似乎都奉献给了卡兹莫丹的群山，整日在那里挖矿。他是个很聪明的家伙！$B$B但这书在哪来着？哦，对了，《金属的延展性》！这本书被我送到北郡修道院去了。那里的管理员帕克斯顿修士想为他那里的图书馆抄写一份留作副本。$B$B但这是几个月前的事了，我不知道他为什么会花这么长的时间……",objectives={"与北郡修道院的帕克斯顿修士谈一谈。"}]])
R(345,"墨水短缺",[[description="我也想把《金属的延展性》这本书尽快抄完，但是……$B$B你看看，我只用自己的墨水抄写书籍。这墨水是用我自己的配方制作的，它不容易化开，也不容易弄脏纸，唯一的缺点就是它干得太快了！我的最后一瓶墨水在我抄完之前就用光了，而且我也没法去做新的墨水！$B$B要想再配点墨水的话，我就得先弄到一些赤脊山的瑞斯班矿石，一直以来，这种矿石都是由湖畔镇的工头奥斯洛为我提供的。",objectives={"与湖畔镇的工头奥斯洛交谈，并向他要一些瑞斯班矿石。"}]])
R(346,"克里斯托弗的书",[[description="现在我已经把这本书抄完了，这里是《金属的延展性》的原本。感谢你的耐心，还有，如果你见到米尔顿的话，请替我向他道歉，我拖了那么长时间真有些不好意思。",objectives={"回到教堂广场，将《金属的延展性》交给克里斯托弗修士。"}]])
R(347,"瑞斯班矿石",[[description="瑞斯班矿石是根据第一个发现他的人——巴尔特·瑞斯班——的名字来命名的。这种矿石在冶炼之后虽然没有铁那么坚硬，但它有一种纯正的黑色，许多抄写员都用它来制作墨水或染料。在北边的瑞斯班矿洞里就可以找到这种矿石。$B$B我们通常会有一些存货，但最近大家都忙于抵抗兽人的进攻，没空去采集这种矿石。此外……这段时间以来，赤脊豺狼人占据了瑞斯班矿洞，而且他们的苦工也正在采集这些矿石。$B$B所以如果你需要的话，就得自己去那里找了。",objectives={"收集5袋瑞斯班矿石，把它们带给北郡图书馆的帕克斯顿修士。"}]])
R(348,"荆棘谷热疫",[[description="我病了…病得……非常厉害……$b$b我…染上了…荆棘谷热疫…致死的疾…疾病……$b$b……只…只有吃下…野人莫…莫…莫克…的心脏…才…才有救…那…是…一只残忍而…狡猾的…野兽。$b$b……巫医安巴格瓦巫师…是…唯一会…召唤…它…的人……$b$b找到…住在南边…海岬…洞穴…里的安巴格瓦……$b$b……快点…我就要死了…就要死了……",objectives={"找到巫医安巴格瓦并要求他召唤出野人莫克，然后将野人莫克的心脏交给芬·菲兹拉克。"}]])
R(349,"荆棘谷热疫",[[description="嗨，$N！$B$B和我的朋友巫医安巴格瓦说话。",objectives={"与巫医安巴格瓦交谈。"}]])
R(350,"老朋友",[[description="马尔松曾和迪菲亚兄弟会的一个成员进行联系，而且莱斯科瓦公爵似乎也脱不了干系……$B$B在范克里夫和特雷德被杀之后，莱斯科瓦依然逍遥法外，我们手上还是没有他罪行的证据。除了证据问题之外，莱斯科瓦本身就是个神通广大的贵族，这些优势让他得以凌驾于法律之上。$B$B你需要帮助。虽然我并不很情愿走这一步棋，但是的确有一个可以帮助我们的人。你应该到暴风城的贸易区去找提亚斯。",objectives={"与暴风城的埃林·提亚斯谈一谈。"}]])
R(351,"寻找OOX-17/TN！",[[description="你发现了一个奇怪的蛋形金属物体。随便拨弄了几下之后，它居然打开了，变成了一个看起来像是由侏儒创造的那种机器装置！一个噼里啪啦的声音从这个蛋形机器装置中传了出来。$B$B“我的名字叫奥格索普，我的母体机器人不见了！如果你能帮我找到它的话，我会奖励你的！请把这个定向器带到我的母体机器人那里。我现在已经为你勘探出了它的所在地！它现在就在塔纳利斯的大裂口那里！”",objectives={"把定位器带到奥格索普的母体机器人那里。"}]])
R(352,"<UNUSED>",[[description="Great Mammoda. Enormous, she was, with claws and teeth like swords. Now, I was caught off my guard, but I don't think being ready would have helped my cause much. One swipe and poof! Darkness. They say I'm lucky to walk now...$b$bWell, not much enjoyment to be had in hearing that old story now, is there? Anyways, $n, if you'd like to try yourself against her, the Lady of the Loch,"]])
R(353,"雷矛的包裹",[[description="雷矛部族是一个倍受尊敬的矮人部族，他们向来以独具慧眼著称——所以远在铁炉堡的巡山人才会托人不远千里地让人传信，委托我给他们打制一把武器，哈哈！$B$B这把武器已经完成了，但是巡山人卡尔·雷矛住在洛克莫丹，离这里实在是太远了。如果你正好要到那边去的话，就替我把这个包裹带给他吧。$B$B巡山人卡尔·雷矛最后一次和我联络的时候，他说他在洛克莫丹北部的哨塔里。",objectives={"把给卡尔·雷矛的包裹交给洛克莫丹北部哨塔里的巡山人卡尔·雷矛。"}]])
R(354,"阿加曼德家族",[[description="阿加曼德家族曾是提瑞斯法林地中最富有的家族。我过去曾在他们的磨坊里工作……当然，我是说在瘟疫降临之前。$B$B天灾军团入侵的时候，阿加曼德家族的人们加固了他们的庄园，并说服了在他们家做工的人留下来帮助他们抵抗天灾军团。我们实在是太蠢了，但我们至少是愚蠢而忠诚。$B$B而阿加曼德家族用荣耀之类的幌子让我们去送死，结果现在他们倒成了天灾军团的走狗！$B$B为了被遗忘者，你必须去剿灭堕落于瘟疫之中的阿加曼德家族！把他们的尸体带回来给我。",objectives={"把格里高的遗骸、妮萨的残骸和萨尔曼的遗骸交给布瑞尔的库勒曼·法席恩。"}]])
R(355,"与塞弗伦交谈",[[description="你把阿加曼德家族所有人的遗骸都带来给我了，这完全可以满足我的复仇欲望。但阿加曼德磨坊对我，哦，不仅仅是对我，对我们全体被遗忘者来说仍是个威胁。$B$B我已经把你与阿加曼德家族战斗的事迹告诉了执政官塞弗伦大人，他也希望能和你谈谈。",objectives={"与布瑞尔的执政官塞弗伦谈一谈。"}]])
R(356,"巡查后方",[[description="亡灵壁垒上的卫兵们时刻都在提防着从瘟疫之地潜入提瑞斯法的敌人，但仍有些天灾军团的士兵能躲过这样的警戒线。$B$B如果想要成功地维持我们对这一带的控制，就必须进行一次清查行动——我们绝对不能腹背受敌。如果补给线被切断了的话，那后果就将是灾难性的。$B$B去协助亡灵壁垒的卫兵进行防御吧。往东边一路巡逻过去，如果你发现任何天灾军团的爪牙，就直截了当地把他们干掉。特别注意一下东边的巴尼尔农场，那里已经到处都是天灾军团的散兵了。",objectives={"杀死8个可怕的血僵尸和8个游荡的幽灵，然后向亡灵卫兵林奈汇报。"}]])
R(357,"巫妖的身份",[[description="北边澈水湖中的一个小岛上住着一个巫妖。虽然他是个独立的亡灵，不过他认为其他所有的亡灵都是天灾军团的奴隶，他的爪牙会袭击任何靠近他的人。$B$B他是个无主之人，所以黑暗女王想要招降他。如果他确实精通于巫术的话，那么他的知识会对我们很有帮助。$B$B不过我得先看过他的法术书才能了解他的身份和学问。潜入他的营地，把书拿回来见我。",objectives={"把巫妖的法术书带给幽暗城的比索·埃斯沙德。"}]])
R(358,"盗墓贼",[[description="北边的加伦鬼屋你去过吗？那个地区的西南角是一大片乱坟岗，里面葬着提瑞斯法一带的大量因瘟疫而死的人。$B$B那边坟墓里的尸体大多没能变亡灵，但最近天灾军团派出了一群腐皮豺狼人到那里去收集尸体，以此来壮大他们的军队。我们不能允许这样的事情发生！$B$B你的任务有两个：杀光躲在乱坟岗和加伦鬼屋里的腐皮豺狼人，并把他们身上的防腐剂抢回来，正是这种防腐剂使他们活过来的。",objectives={"杀死腐皮盗墓贼和混血腐皮豺狼人。$B$B给布瑞尔的执政官塞弗伦带回8瓶防腐剂。"}]])
R(359,"亡灵卫兵的职责",[[description="我要这里东边的亡灵卫兵驿站立刻给我提交一份最新的报告。$B$B我必须知道天灾军团是否已经迂回绕过了防波堤并进入了提瑞斯法林地。我们要时刻保持警惕，封锁住这里与瘟疫之地的边境，绝对不能让天灾军团占据这里的任何一寸土地！$B$B沿着路向南走，在第一个岔路口转向东，就可以到达驿站了。到那里去找亡灵卫兵林奈，她手里掌握着我最需要的情报。",objectives={"与亡灵卫兵林奈谈一谈。"}]])
R(360,"向塞弗伦回报",[[description="现在带着这些情报回到执政官塞弗伦那里去吧。他急需这几份报告，你动作最好快点。$B$B如果你回程的路上看见了任何天灾军团的成员，就顺便干掉他们，我们可不能让这些垃圾在我们的地盘上胡作非为。",objectives={"向布瑞尔的执政官塞弗伦报告。"}]])
R(361,"未寄出的信件",[[description="这封信的作者是格里高·阿加曼德的长子萨尔曼。收件人则是一位名为伊维特·法席恩的女士，尽管现在看来这封信显然是没寄到她手上……",objectives={"找到伊维特·法席恩，将萨尔曼·阿加曼德的信交给她。"}]])
R(362,"闹鬼的磨坊",[[description="代弗林·阿加曼德是阿加曼德家的两个男孩中最小的一个，但这两个男孩子却完全不像是兄弟。萨尔曼身材高大而且待人彬彬有礼，而他的弟弟代弗林却身体虚弱，而且嘴巴很刻薄恶毒。$B$B当阿加曼德磨坊遭遇瘟疫的时候，他是第一个被感染的。现在，只要你靠近通向阿加曼德磨坊的道路，就仍能听见他那喋喋不休的呓语。$B$B我正在收集阿加曼德家族所有人的遗骸，首先，我想弄到可怜的代弗林的尸骨。找到并摧毁他，然后把他的遗骨带回来给我。",objectives={"杀死代弗林·阿加曼德，然后将代弗林的遗骸交给布瑞尔的库勒曼·法席恩。"}]])
R(363,"突然醒来",[[description="你醒得可真是时候。我们本来还准备把你和其他的死人一起火葬了，没想到你居然醒来了。$b$b我是摩尔多，丧钟镇墓穴的看护人。现在你已不再是巫妖王的奴隶了。$b$b暗影牧师萨维斯就在山脚下的教堂里，去和他谈谈吧，他会告诉你更多你必须了解的事情。",objectives={"和暗影牧师萨维斯谈一谈。"}]])
R(364,"无脑的僵尸",[[description="我们被遗忘者正在与巫妖王的天灾军团作战，那支军队包括用亡灵法术唤起的亡灵军队，大陆北方的那些愚蠢的野兽，还有那些永远遭受折磨的鬼魂。$b$b在这个村庄的北部有大量的无脑僵尸到处横行，我们必须消灭他们。消灭他们，即使他们以前可能是我们的兄弟姐妹也不要手软，那些行尸走肉如今只不过是巫妖王的奴隶罢了。",objectives={"暗影牧师萨维斯让你杀掉8个无脑的僵尸和8个丑陋的僵尸。"}]])
R(365,"悲伤之地",[[description="看看谁来了？你看上去是个菜鸟$c吧。如果你想向黑暗女王陛下证明自己的实力，就得先学会我们被遗忘者行事的几条基本原则。$b$b这里的西边有个农场，那块地上的人呀，就跟腐烂尸体上的苍蝇一样多。更糟糕的是，血色十字军从他们的哨塔里跑出来巡逻的时候，也可能会经过那里。给这些渣滓们好好地上一课吧，把他们的宝贝南瓜给我偷10颗来。$b$b偷到10颗南瓜以后，就把它们交给布瑞尔的药剂师乔汉。",objectives={"从位于布瑞尔西边、丧钟镇北边的农场中偷10颗南瓜来，把它们交给布瑞尔的药剂师乔汉。"}]])
R(366,"归还书籍",[[description="很久以前，冈瑟尔和我，还有现在隶属于天灾军团的图勒·鸦爪，我们三人是很好的朋友，我们曾一起在肯瑞托学习魔法。$B$B冈瑟尔和我都是大瘟疫的牺牲品，冈瑟尔后来成为了巫妖王的手下。现在我得知他脱离了巫妖王的魔爪，这真是个好消息。$B$B我们一定要找到他。我给他的书上施放了一个魔咒，当他看到这本书的时候就会知道我也已经摆脱了巫妖王的控制，希望他在知道这一点以后会加入我们。",objectives={"到冈瑟尔居住的小岛去归还他的法术书。"}]])
R(367,"新的瘟疫",[[description="希尔瓦娜斯大人最近交给了我们皇家药剂师学会一项很有挑战性的命令。黑暗女王相信我们的知识与新发明的魔法将会是她击败阿尔萨斯的有力武器，她要求我们研制出一种新的瘟疫，这种瘟疫要比以前出现在艾泽拉斯大陆上的任何一种疾病都要更加猛烈，它会把阿尔萨斯和他的天灾军团彻底毁灭。$b$b我的研究结果表明，野兽的血液也许是一种重要的药引。给我带回五瓶黑暗犬的血液来，我要验证一下自己的理论。",objectives={"布瑞尔镇里的药剂师乔汉要求你收集5瓶黑暗犬的血液。"}]])
R(368,"新的瘟疫",[[description="在你帮我收集样本的同时，我的实验报告也出来了。看来我还需要更多的材料来进行进一步的研究，适当加强这种新瘟疫的传染能力。毒杀个把倒霉鬼，那是小孩子才玩的把戏，只有将瘟疫传遍整个世界才算得上是有意义的事。$b$b我需要5片邪鳍鱼人身上的鳞片，在北边或者西边的海滩上应该就能找到那些鱼人。",objectives={"布瑞尔镇里的药剂师乔汉要求你收集5片提瑞斯法林地的邪鳍鱼人的鳞片。"}]])
R(369,"新的瘟疫",[[description="在你出去收集鳞片的时候，我已经在我的藏书中找到了一些古老而有趣的文章。这些文章里面提到，以前曾有一种古代的瘟疫杀死过成百上千的人，而后来又有人发现在夜行蜘蛛的毒液中就能提取到这种瘟疫的致病物质。$b$b给我带些夜行蜘蛛的毒液来，让我完成这个实验。我想知道毒液中的感染性元素是否能和我最新研制出来的瘟疫病原体共存。据说这种蜘蛛一般在提瑞斯法林地的东部出没。",objectives={"布瑞尔镇里的药剂师乔汉要你去收集4份邪恶的夜行蜘蛛的毒液样本。"}]])
R(370,"与血色十字军的战争",[[description="执行官阿伦的文件中对如何清除这群在我们的土地上肆虐的人类的问题作了详细的部署。情报表明，血色十字军派遣了派瑞恩队长以及足有一个整编旅的部队进驻了布瑞尔西南方的废塔。$b$b去杀掉派瑞恩队长、3名血色十字军狂热者和3名血色十字军传教士，然后向我回报。",objectives={"布瑞尔的执行官塞加德要求你杀掉派瑞恩队长、3名血色狂热者和3名血色传教士。"}]])
R(371,"与血色十字军的战争",[[description="我们仍然处于战争状态中，而且血色十字军正在逐渐壮大。执行官阿伦给我的报告中提到，在瓦松队长的指挥下，血色十字军正以提瑞斯法东南部巴尼尔农场附近的那座废塔为据点肆意劫掠。$b$b去杀掉瓦松和5名血色十字军苦行修士，这对十字军来说将是一次沉重的打击！",objectives={"布瑞尔的执行官塞加德要求你杀掉瓦松队长和5名血色苦行修士。"}]])
R(372,"与血色十字军的战争",[[description="血色十字军已经从提瑞斯法林地北部的废塔出发，穿过了法奥之墓。根据目前我们所掌握的情报，一个名叫麦拉其的军官指挥着这支邪恶的部队，他是个非常残忍的家伙。$b$b我相信你能完成这个非常重要而又危险的任务。以黑暗女王陛下的名义，杀死麦拉其和他的两名保镖！",objectives={"布瑞尔的执行官塞加德要求你刺杀麦拉其队长及他的两名保镖。"}]])
R(373,"未寄出的信",[[description="搜查艾德温·范克里夫的尸体时，你从一堆杂乱的物品中找到了一封还未来得及发出的信。地址一栏上写着巴隆斯·阿历克斯顿，暴风城石工协会，城市大厅，教堂广场。$B$B这显然是最近刚刚写好并封上的。",objectives={"将艾德温·范克里夫的信交给巴隆斯·阿历克斯顿。"}]])
R(374,"死亡证明",[[description="执行官塞加德告诉我说你最近和血色十字军干上了，提瑞斯法林地里现在到处都是这帮讨厌的家伙。$b$b黑暗女王麾下的瓦里玛萨斯大人计划将人类这种艾泽拉斯大陆上的渣滓与垃圾彻底清除掉。但目前的状况是，人类当中最麻烦的一群家伙——血色十字军——已经杀入了提瑞斯法林地，我们必须得面对他们的挑衅。$b$b去吧，去给这群该死的血色十字军一点颜色看看，$c。给我带回10枚血色十字军徽记之戒，以此证明你对伟大的黑暗女王陛下与瓦里玛萨斯大人的忠诚。",objectives={"给布瑞尔的亡灵卫兵伯吉斯带回10枚血色十字军徽记之戒。"}]])
R(375,"死亡之寒",[[description="好冷啊……可怕的瘟疫正如冰冷的毒蛇一般在我的血管中逡巡，也许很快我就会彻底失去意志，但这世上没有任何东西能够阻止我为我们伟大的黑暗女王效命。一接到命令，我就开始为希尔瓦娜斯大人军队中那些死去的战士缝制尸袋。$b$b但现在我的手却因为寒冷而颤栗不已。如果你能给我带回五张夜行蝙蝠的毛皮和一些粗线的话，我就可以给自己缝条毯子了。帮帮我，$N，这样我就可以继续为黑暗女王陛下的事业效力了。",objectives={"给布瑞尔的格雷森·戴德马带回5张夜行蝙蝠的毛皮和一些粗线。"}]])
R(376,"被诅咒者",[[description="我的任务包括照料受伤的士兵，缝制铠甲和衣服，还有为暗影牧师萨维斯提供任何他可能需要的支援。$b$b看起来，你也即将加入到为他效力的队伍中……我猜是要猎杀那些没脑子的家伙。好吧，如果你还想留着你的小命的话——我想你一定是的——也许我能帮助你。我这里没有足够的狼爪子和蝙蝠翅膀了，如果你能帮我弄一些来的话，我会帮你找几件铠甲。在这里的西北方可以找到大群的狼和蝙蝠。",objectives={"新兵艾尔雷斯需要6只食腐狼的爪子和6只夜行蝙蝠翼。"}]])
R(377,"罪与罚",[[description="贵族议会好象嫌他们对暮色森林的漠不关心还不够过分，现在他们居然无视夜色镇议会的存在，决定把迪克斯特·瓦德囚禁在暴风城，而不是按照埃伯洛克公爵大人的判决将这个恶棍斩首！$b$b迪克斯特·瓦德是在把墓地里的尸体卖给摩本特·费尔时被抓住的，这理应是死罪。可是暴风城却认为他们才拥有对他的处决权！$b$b去暴风城的监狱把瓦德杀掉，把他的手给我带回来作为证明，我会奖赏你的。",objectives={"夜色镇的米尔斯迪普议员要你杀死迪克斯特·瓦德，并把他的手带回来作为证明。"}]])
R(378,"卡姆·深怒",[[description="你已经向我们展示出了你对麦格尼陛下的忠诚，$c。而且我也深刻地感受到了你对那些黑铁矮人的仇恨。$b$b我必须要坚守岗位，因此，我不得不把一个本应由我亲自去完成的重要任务交给你。根据罗戈收集到的情报显示，卡姆·深怒正是袭击萨多尔大桥的元凶。由于他所布下的邪恶计划，长须才失去了他的亲人。$b$b这个刽子手由于某些政治原因被扣押在了暴风城的监狱里。我要他死，$N。为了长须！杀死卡姆·深怒，把他的脑袋给我带回来！",objectives={"丹莫德的莫特雷·加玛森要求你把卡姆·深怒的头颅交给他。"}]])
R(379,"口渴的比格维兹",[[description="你需要能量源，我可以帮你。但是你知道我要什么吗？我要喝的！给我弄五只废土水袋来，然后我就会把4711-FTZ交给你。$B$B现在……你想知道在什么地方可以找到废土水袋，对吗？去这里的东边找废土游牧民吧，他们身上会带着这种水袋。",objectives={"给加基森的首席工程师沙克斯·比格维兹带去五只废土水袋。"}]])
R(380,"夜行蜘蛛洞穴",[[description="我们的一项最重要的任务就是获取赖以生存的自然资源。即使在当年联盟最鼎盛的时候，黄金资源也是非常缺乏的。$b$b这里的西北面有一处金矿，我们需要矿洞里的资源，但是那里蜘蛛横行，我们根本无法进去采掘金矿。我手上没有人可以去完成这项任务，所以我们只有一步一步慢慢地来。去那里看看吧，也许你能做些什么……",objectives={"执行官阿伦要你去杀掉10只小夜行蜘蛛和8只夜行蜘蛛。"}]])
R(381,"血色十字军",[[description="得知我们在金矿的进展非常顺利，你一定很开心吧？得益于你的帮助，我们终于可以把注意力放到别的事情上了。$b$b我的斥候报告说，一支血色十字军的小分队在东南方建立了营地。血色十字军是一个卑鄙的组织，他们视我们为死敌，只要有一个亡灵——无论是巫妖王的爪牙还是我们被遗忘者——还活着，他们就不会停止追杀我们的行动。所以我们必须先发制人！$b$b你要多加小心，这些邪恶而狂妄的十字军是一群非常危险的家伙。",objectives={"从血色信徒和血色新兵身上收集12枚血色十字军臂章，把它们交给执行官阿伦。"}]])
R(382,"十字军信使",[[description="布瑞尔那边的上级给我发来的文件显示，有一个从血色修道院出发的血色十字军斥候已经潜入了丧钟镇。有报告说这个人携带着非常重要的情报。至于更多的细节，我不得而知。但不管怎么样，我们必须得到这份情报！$b$b你是我眼下能调动的最合适的人选，$n。找到那个信使，带回你能弄到的任何情报。",objectives={"到十字军营地去杀掉信使迈文·考加尔，将你发现的情报交给执行官阿伦。"}]])
R(383,"重要情报",[[description="我必须将这些东西交给我的上级——执行官塞加德，他就在布瑞尔。有了这份详尽的情报，我们就能给血色十字军以沉重的打击。你在丧钟镇对我们做出了很大的贡献，现在我要你去把这份情报及时交给塞加德，我想他能帮你找到更多能让你大展身手的工作。$b$b沿着这条路向北走出丧钟镇，在进入提瑞斯法林地以后，你很快就会来到一个十字路口，这时向东走，然后一直向前就可以到布瑞尔了，路上有一座炉灰庄园可以帮你确认自己的方向。",objectives={"把血色十字军文件交给布瑞尔的执行官塞加德。"}]])
R(384,"啤酒烤猪排",[[description="啤酒烤猪排是我的老主顾们最喜欢的大餐！问题是，为我提供猪排的猎手被国王征募去打仗了。$b$b也许你能帮帮我？如果你可以给我弄六块峭壁野猪肋排，外加一杯酒店里卖的狂想麦酒的话，我就把祖传的啤酒烤猪排的烹饪方法教给你，而且我还可以让你免费品尝我做出来的美食！秘密就在麦酒里！",objectives={"卡拉诺斯的拉格纳·雷酒需要6块峭壁野猪肋排和1杯狂想麦酒。"}]])
R(385,"捕猎鳄鱼",[[description="很多猎人到洛克莫丹来都是为了捕猎这里的鳄鱼。总有一些商人专门寻找这种鳄鱼皮，用它们来制作衣物或是护甲，还有些人则喜欢品尝鳄鱼肉。$b$b我们一直在进行这种贸易，但交易量并不是很大，因为鳄鱼很凶猛，而且它们一般都盘踞在洛克湖中的小岛上。嘿，别被我的话给吓倒了，和鳄鱼较量一番对你来说也是一种历练。$b$b你看能不能……",objectives={"收集5块鳄鱼肉和6张鳄鱼皮，把它们交给旅行者营地里的马雷克·铁心。"}]])
R(386,"伸张正义",[[description="可怕的塔格尔是加塞尔佐格手下的一个高级杀手。他杀人的手法十分残忍，即使以兽人的标准来看也是残暴无比。那些为了保卫国家而奋勇作战的战士们落在他手里都会被他折磨致死。这个恶棍现在被关在暴风城的监狱里，被判处了死刑。不过，这件事情好象出了点小差错，一个官僚习气十足的贵族推迟了处死他的日期。我敢打赌这里面一定有鬼。$b$b处死塔格尔吧，$N。到暴风城的监狱里去，在他玩出什么把戏之前把他干掉。",objectives={"把塔格尔的头颅带给湖畔镇的卫兵伯尔顿。"}]])
R(387,"镇压暴动",[[description="我们必须把暴动给镇压下去！我需要你的帮助。如果外面的人知道监狱里面已经失去了控制，我一定会丢了饭碗的！这是我所见过的最无聊的闹剧了。现在最重要的是逼迫这些囚犯投降，这样才能保证暴风城的安全。$b$b叛乱的代价就是死亡。去杀掉一些囚犯，这样叛乱才能得到控制！",objectives={"暴风城的典狱官塞尔沃特要求你杀死监狱中的10名迪菲亚囚徒、8名迪菲亚罪犯和8名迪菲亚叛军。"}]])
R(388,"鲜血的颜色",[[description="痛苦如同冰冷的河水一样从我的血管中流过。我的孙子麦克是个多好的孩子呀，他只有14岁。当暴风城的军队被派往前线的时候，麦克也拿起了武器去守卫城市。他是监狱的守卫，那座监狱里关押着许多迪菲亚兄弟会的成员。有一些囚徒们把他们的羊毛毯改织成他们组织的头巾，麦克把这件事情上报了，结果他遭到了报复，被人从后面刺了一刀。$b$b我要报仇。给我带回10条迪菲亚潜行者们的羊毛面罩，像鲜血一样殷红的那种。",objectives={"暴风城的尼科瓦·拉斯克要你取得10条红色毛纺面罩。"}]])
R(389,"巴吉尔·特雷德",[[description="范克里夫和我过去都曾是石匠行会的成员，我们的主要工作是在战后重新建设暴风城。$b$b当我们完成了自己的职责时，却发现我们被彻底地欺骗了。贵族们拒绝付给我们酬劳，一些石匠行会的元老被提拔成了官员，但范克里夫出于对所有石匠会员的忠诚拒绝了他们。他组织了一场暴动，并离开了城市，从此发誓要进行复仇。$b$b他的副官巴基尔·斯瑞德或许对范克里夫的计划有一些了解，他目前正被关押在监狱里。",objectives={"与监狱的典狱官塞尔沃特谈一谈。"}]])
R(390,"<UNUSED>")
R(391,"监狱暴动",[[description="让我们把话挑明了说吧，$n：我不信任你。但是，现在的情况紧急，我也管不了那么多了。$b$b你到下面去干掉那个该死的斯瑞德，把他的脑袋砍下来带给我。$b$b还有，如果你胆敢跟他合计什么把戏，或者你不上来了的话……只要被我抓到你，就准备跟那群蛆死在一块吧。",objectives={"杀死巴基尔·斯瑞德，把他的头带给监狱的典狱官塞尔沃特。"}]])
R(392,"好奇的访客",[[description="在斯瑞德刑期的第一年里，从来从没有人探视过他。我猜当时迪菲亚兄弟会认为他已经彻底没用了，所以准备任他自生自灭。$b$b然而几个月前，一切都变了。有人开始定期探视他……每周一到两次。那是个奇怪的男人，沉默寡言。我有点疑心，但他的证件是真实且合法的。$b$b他的名字叫麦里克，这是他的一些资料。我觉得他可能不会再来探视斯瑞德了。",objectives={"将神秘访客的资料交给暴风城的巴隆斯·阿历克斯顿。"}]])
R(393,"往日的阴影",[[description="我确实没什么线索，$n。但或许另外有人能帮上你的忙，而且他还欠了我一个人情——好了，现在不是说那个的时候。暴风城兵营中的军情七处首领马迪亚斯·肖尔或许能轻松搞定这类事。$b$b如果说有谁知道这事的话，一定就是他，他此刻就在旧城区。",objectives={"与旧城区的马迪亚斯·肖尔谈一谈。"}]])
R(394,"禽兽的首级",[[description="到暴风城去找肖尔，告诉他莱斯科瓦的问题已经被你解决了。我敢说他一定会为暴风城出了你这样的一位英雄而感到自豪的。$B$B他甚至有可能将你引荐给暴风城里的达官显贵。你要知道，$n，这座城市里还真没有什么肖尔搞不定的事情。贵族们可以自认为他们完全控制着暴风城，但总有一些事情是他们无能为力的。",objectives={"去见暴风城旧城区的马迪亚斯·肖尔。"}]])
R(395,"兄弟会的灭亡",[[description="啊，我差点忘了。阿历克斯顿在你离开的时候来过，他有话想跟你说。显然他是想向国王陛下报告关于迪菲亚兄弟会的事情。$b$b给你个忠告，$n。如果有人问到这个，我会把除了你杀掉莱斯科瓦以外的所有细节都告诉他。相信我，我…对这种事…已经习以为常了……$B$B另外，别跟任何人说起提亚斯的事情。",objectives={"与暴风城的巴隆斯·阿历克斯顿谈一谈。"}]])
R(396,"觐见国王",[[description="我准备了一份报告呈递给国王陛下。当我听说了你最近的事迹之后，我认为你是递送这份报告的最佳人选。别担心，国王陛下一定会嘉奖你的。$b$b你的觐见已经被列入了陛下的日程表，所以你最好快点到暴风要塞里去等待召见。",objectives={"将有关迪菲亚兄弟会的报告送给暴风要塞里的国王瓦里安·乌瑞恩。"}]])
R(397,"干得好",[[description="我听说维沙克公爵很喜欢他收到的饮料。$b$b你帮了我们的大忙，$N。暴风城的术士们从此可以不再受他人干涉地自由行事了。我准备了一件特殊的小礼物给你，以表示我们的感谢。去找我的仆人兹吉，收下你的报酬吧。",objectives={"去找黑爪加尔德斯的仆人兹吉谈一谈，并向他索要你的酬劳。"}]])
R(398,"悬赏：蛆眼",[[description="悬赏：蛆眼！$b$b这只名叫蛆眼的豺狼人臭名昭著，即使是在它的同类眼中都显得非常邪恶而污秽，它因为对被遗忘者们犯下了不可饶恕的罪名而被判处了死刑，这只卑鄙的野兽为巫妖王的军队偷盗了无数的尸体。上次有人看到蛆眼作恶是在布瑞尔北边的加伦鬼屋。$b$b布瑞尔镇将为执行这项判决的勇敢者提供一份高额的奖金。完成任务之后，请将这只野兽的爪子交给执行官塞加德。$b$b只有弱者才会有怜悯之心。",objectives={"杀死蛆眼，并将他的爪子交给布瑞尔的执行官塞加德以换取酬劳。"}]])
R(399,"童年的记忆",[[description="许多年前，我还只是个在西部荒野的农场里干活的小男孩，不过现在看来，这段回忆只能封存起来了。俗话说时光一去不复返，这句话在我身上得到了印证，我家的房子已经被烧毁，现在又给一群潜行者占领了。$b$b我曾向父亲询问过我的一些物品的下落——包括我的第一个指南针，他说他没办法把那些东西拿回来。但是他又说……它们应该就藏在农场外面的什么地方。$b$b你可以在哨兵岭的西边找到阿历克斯顿农场。你能帮我把那些东西找回来吗？",objectives={"到巴隆斯·阿历克斯顿在西部荒野的房子里去找到他的指南针，并将它带回暴风城的教堂广场交给他。"}]])
R(400,"贝尔丁的工具",[[description="贝尔丁·钢架是本地最好的坦克机械师！不过他从来不爱护他的工具，他弄坏扳手的速度远远大于我们的供货速度！$B$B我们刚刚才赶出他最近订的一批货。如果你能把这些东西交给他，我想他一定会让你感到不虚此行的。$B$B他开的钢架补给站就在卡拉诺斯的东北边。老牌的攻城坦克驾驶员们经常在那里碰头，所以你到了那里之后要睁大眼睛，说不定能找到好些活儿。",objectives={"把贝尔丁的工具交给贝尔丁·钢架。"}]])
R(401,"等待希拉完工",[[description="我很快就能把信件翻译完了。请稍等一会儿再过来吧。",objectives={"稍等片刻，然后再和希拉·沃宁迪交谈。"}]])
R(403,"戒备森严")
R(404,"腐烂的爪子",[[description="有一小撮天灾军团的士兵已经渗入了提瑞斯法林地，在布瑞尔以西一带的旧桥附近活动。$B$B去那边去增援我们的部队，杀光所有你见到的腐烂的死者和破碎的尸体。把他们都给我拆成骨头架子，然后把他们那腐烂的爪子给我带回来，我会奖励你的。",objectives={"给布瑞尔的亡灵卫兵迪林格尔带回7只腐烂的爪子。"}]])
R(405,"流浪的巫妖",[[description="幽暗城里的一位法力强大的高阶法师比索·埃斯沙德给了我一个任务，让我去为他找一个与天灾军团有着丰富斗争经验的勇士。你，$N，显然就是他要找的人。$B$B现在立刻去向比索报到，他会给你指派新的任务。我也不清楚任务的细节，但大致上好象是要招安一名独居的巫妖之类的。这份工作可能会很危险。$B$B去做好准备吧，$C。你绝对不能失败。$B$B比索就在幽暗城的魔法区里。",objectives={"将塞弗伦的命令交给幽暗城的比索·埃斯沙德。"}]])
R(406,"<UNUSED>")
R(407,"悲伤之地",[[description="看上去这南瓜没有什么不正常吧？如果我们想要阻止阿尔萨斯的军队在北方继续推进外加人类势力在南方的肆虐横行，那么我们必须从现在开始就意识到自己身为亡灵的优势。$b$b只要稍微耍点小把戏，一个简单的南瓜就能让任何人成为黑暗女王的优秀探子。我最新培育的这种南瓜就可以做到这一点。$b$b现在据说又有个血色十字军狂热者被俘虏了，他被关在恐惧之末旅店的某个房间里。把这个南瓜拿去给那个蠢货，让他吃了。",objectives={"将斑纹南瓜带给被关在恐惧之末旅店地下室中的血色十字军俘虏。"}]])
R(408,"家族墓穴",[[description="如今阿加曼德磨坊已经成了天灾军团的一处重要据点，其中防守最为坚固的地方就是阿加曼德的家族墓穴了。天灾军团的一个兵团就驻守在那里，他们由一个名叫达高尔队长的骷髅领导着。他们还利用某种通灵术复活了阿加曼德家族的死者们，并打算利用它们来对付我们。$B$B我们绝对不能允许这种事情发生，你必须阻止它。到阿加曼德家族墓穴去，战胜那些还魂的阿加曼德家族的死尸们。$B$B还有，把达高尔队长的颅骨也给我带回来。",objectives={"杀死8个哀嚎的鬼魂和8个腐烂的古尸。$B$B消灭达高尔队长，并将他的颅骨交给布瑞尔的执政官塞弗伦。"}]])
R(409,"证明忠诚",[[description="你说你没有被巫妖王控制住自己的思想，这一点已经由比索在我书上灌入的魔法证实了。但是，你仍然得先证明自己是天灾军团的敌人，这样我才会彻底信任你。$B$B在这座岛屿南边的小岛上有一处古老而血腥的祭坛，那里目前被一个强大的天灾军团斥候莉莉丝·奈法拉所占据着。$B$B从我身边的这个木箱里拿出一根诱灵蜡烛，然后将其点燃并放到祭坛上，莉莉丝会很快醒来。消灭莉莉丝，这样一来，我就会相信你确实是巫妖王的敌人了。",objectives={"拿上一根诱灵蜡烛。$B$B召唤出莉莉丝·奈法拉并杀死她。$B$B然后向岛上的冈瑟尔回报。"}]])
R(410,"潜伏的阴影")
R(411,"巫妖归顺",[[description="拜托你，请将这块虚空宝石带给我的老朋友比索。这样我就能和他交流了……我有好多事想和他说呢。",objectives={"将虚空宝石交给幽暗城的比索·埃斯沙德。"}]])
R(412,"自动净化装置",[[description="通过对诺莫瑞根现状的进一步分析，我们发现不但那些该死的穴居人没有被消灭，反而有更多的侏儒变成了丧心病狂的、邪恶的怪物。$b$b我和奥齐希望用我们的最新发明——自动净化装置——来扭转这种局面。这台机器即将大功告成，不过我们急需一些多档齿轮和自适应齿轮才能搞定最后的部分，请从诺莫瑞根的麻疯侏儒那里弄些过来吧。",objectives={"收集8个多档齿轮和8个自适应齿轮，把它们交给卡拉诺斯的拉兹·滑链。"}]])
R(413,"微光酒",[[description="我希望我兄弟维拉特能够品尝一下我最新酿制的微光酒。他是一个在南面的警戒塔里执勤的巡山人，就是靠近洛克莫丹边界的那两座哨塔里的一座。$B$B他不是酿酒师，但是他非常喜欢喝酒，而且我相信他一定喜欢这种酒的。$B$B你能替我把这桶微光酒交给他吗？",objectives={"把这一大桶微光酒交给巡山人维拉特·麦酒。"}]])
R(414,"卡德雷尔的酒",[[description="我兄弟酿造的微光酒真是极品！我想让我的一个朋友也品尝一下，他叫卡德雷尔，经常在塞尔萨玛附近的路上巡逻。$B$B要去塞尔萨玛的话，就往东南方穿越隧道，然后在岔路口向东北方走，最后沿着大路一直走就能到塞尔萨玛了。$B$B把这桶微光酒交给巡山人卡德雷尔尝尝，看看他是不是也赞不绝口！",objectives={"把这桶微光酒带给巡山人卡德雷尔。"}]])
R(415,"雷杰德的新酒",[[description="烈酒村的雷杰德·麦酒正在找你。$B$B他要和你谈谈他最新正在酿造的一种酒……他告诉我你帮了他很多忙。你也许应该去一次烈酒村，看看他要说什么。$B$B也许，你可以在那里免费享受到一顿大餐……  ",objectives={"和雷杰德·麦酒谈一谈。  "}]])
R(416,"狗头人的耳朵",[[description="我们在西边遇到了点麻烦。坑道鼠狗头人在那里的丘陵地带建起了巢穴，把我们的地盘弄得乌烟瘴气！$B$B我们必须把他们给消灭掉。去捕杀那些坑道鼠狗头人，把他们的耳朵拿回来给我，我就给你赏金。$B$B坑道鼠狗头人的巢穴就在塞尔萨玛北边的山脚下。",objectives={"收集12只坑道鼠的耳朵，把它们带给塞尔萨玛的巡山人卡德雷尔。"}]])
R(417,"驾驶员的复仇",[[description="莫里·铁钻在他的日记中写道，他受到了一头名叫癞爪的巨型冰爪熊的袭击。他赶走了这只野兽，不过自己也已遍体鳞伤。$B$B从莫里尸体上的伤痕判断，癞爪一定又折回来杀死了他。$B$B然而，莫里在他的日记中写下了他最后的遗愿：$B$B杀死癞爪，为我复仇。",objectives={"杀死癞爪。$B$B把它的肮脏的爪子和莫里·铁钻的日记交给驾驶员塞克·锤足。"}]])
R(418,"塞尔萨玛血肠",[[description="塞尔萨玛这儿饥肠辘辘的人可真不少，有跑进跑出的孩子，也有在挖掘场忙了一整天的工人。我们这儿有一道出名的菜色——血肠，你大概还没尝过吧？$b$b没有？在这儿要吃饭就得干活，别以为你是个出色的$c就可以例外。$b$b我需要熊肉、做肠衣用的猪大肠，还有做调料用的蜘蛛的毒液。把这些东西找来，剩下的就交给我维德拉好了！",objectives={"收集3块熊肉、3根猪大肠和3份蜘蛛的毒液，把它们交给塞尔萨玛的维德拉·壁炉。"}]])
R(419,"失踪的驾驶员",[[description="我的朋友，同时也是同一蒸汽坦克车组的同事——莫里·铁钻，在山上失踪了。我们当时正在寻找一种可以用来制作高爆炸药的稀有矿石。在我们搜寻的过程中，莫里驾驶着他的坦克攀上一处陡峭的山坡后抛锚了！$B$B他确信矿石就在这片山地里，所以就让我守着我们的机车，而他一个人步行继续去搜索。$B$B莫里已经有好些天没回来了，夜里我时常能听见山中的野兽发出的咆哮。莫里是个硬汉，不过我还是有点为他担心。$B$B求求你，$N，帮我找到他。",objectives={"找到驾驶员莫里·铁钻。"}]])
R(420,"森内尔的观察站",[[description="隧道里的穴居人非常具有攻击性，它们会毫不犹豫地对隧道中的过客发动袭击。不过你看起来挺结实的，应该不会有什么危险。$b$b方向？如果你要找森内尔，就到卡拉诺斯去吧。$b$b一直穿过隧道，出去之后沿着大路向前走，没几步就到卡拉诺斯了。",objectives={"把格瑞林的报告交给卡拉诺斯的森内尔·白须。"}]])
R(421,"证明你的价值",[[description="希尔瓦娜斯主人已经授命瓦里玛萨斯大人全权负责征服南方的人类和矮人的领土。$b$b但阿鲁高那个蠢货——过去他是达拉然的大骗子，现在他是影牙城堡里一只中了诅咒的困兽——他那不计后果的魔法给银松森林里那座极具战略意义的要塞带来了一场大浩劫。$b$b我需要一些拥有优秀战斗技巧的人帮我把阿鲁高留下的烂摊子给收拾掉。杀死5只月怒白头狼人以证明你的实力吧，这些野兽一般都在山脚下的道路两旁游荡。",objectives={"瑟伯切尔的达拉尔·道恩维沃尔要求你杀死5只月怒白头狼人。"}]])
R(422,"阿鲁高的愚行",[[description="阿鲁高这样一个施法能力比一张纸还要浅薄的家伙居然能够得到肯瑞托的承认，这让我实在难以想象。$b$b现在最重要的是，搞清楚阿鲁高究竟使用了什么魔法，这样一来我才能对付他，并为黑暗女士平定银松森林。$b$b阿鲁高曾经住在桥北的麦田旁，一名亡灵哨兵回报说，他发现了阿鲁高拥有的几本法术书，但无法偷取它们。把其中一本名叫《阿鲁高的拯救》的法术书从其它书里找出来，并带回来给我。",objectives={"为瑟伯切尔的达拉尔·道恩维沃尔找回《阿鲁高的拯救》。"}]])
R(423,"阿鲁高的愚行",[[description="在我研究过阿鲁高的书以后，我最坏的设想不幸被证实了。肯瑞托竟在那个连给达拉然的法师们扫屋子都不配的家伙干出那种愚昧行径的时候完全不闻不问，一群蠢货！$b$b阿鲁高使用了附有魔法的物品来加强他薄弱的施法能力。我需要尽快研究一下这些物品。去杀掉一些月怒暴食者和月怒魔魂狼人，收集他们身上带着的魔法镣铐供我研究之用。这些污秽的生物在北边和东边到处都是。",objectives={"给瑟伯切尔的达拉尔·道恩维沃尔带回6副暴食者镣铐和3副魔魂镣铐。"}]])
R(424,"阿鲁高的愚行",[[description="看来想揭开隐藏在阿鲁高所用的巫术中的黑暗秘密并不简单，这比我想象中要花掉的时间多出很多。$b$b但与此同时，我需要你来帮忙处理一下我们的亡灵哨兵发现的一个小问题。似乎阿鲁高的魔法已经控制了东南方山中的埃利姆矿洞。$b$b这座矿洞对瓦里玛萨斯大人的推进有着非常重要的意义。$b$b我希望你能干掉矿洞里的工头，白毛狼人格瑞姆森。只要他一死，矿洞就是我们的了。",objectives={"杀死白毛狼人格瑞姆森，把他的头带给瑟伯切尔的达拉尔·道恩维沃尔。"}]])
R(425,"邪恶的伊瓦",[[description="我正在和哥哥奎恩执行侦察银松森林的任务，并准备向最高执行官哈德瑞克复命。但我们进行得不太顺利——我们穿过这座农庄的时候，被食尸鬼伊瓦袭击了。$B$B我们从伊瓦那里逃了出来，但他还是重创了奎恩。喝了你给他的药水以后，哥哥正逐渐痊愈，但这段时间里伊瓦仍可能会过来。$B$B杀死伊瓦，以保证奎恩有足够的时间复原吧。伊瓦一般都躲在谷仓那里，在我放松警戒的时候它就会开始行动。",objectives={"杀死邪恶的伊瓦，并将伊瓦的头颅带给伊瓦农庄的兰妮·尤瑞克。"}]])
R(426,"磨坊告急",[[description="天灾军团正试图在阿加曼德磨坊那边建立起一座前哨基地。如果他们得逞了，那么他们在提瑞斯法的军事行动将得到有利的支持。$B$B上头已经发话下来了，必须将磨坊那边的天灾军团势力全部清除干净。$B$B到磨坊那边去，从断骨士兵和碎颅士兵身上收集锯齿肋骨，再从暗眼骷髅法师身上收集焦黑的颅骨。$B$B你只需沿着道路一直向西走，过桥以后在第一个岔路口转向北就行了。当你看到风车的时候，战斗随时都会开始。",objectives={"收集5根锯齿肋骨和3个焦黑的颅骨，然后向布瑞尔的亡灵卫兵迪林格尔回报。"}]])
R(427,"与血色十字军的战争",[[description="执行官阿伦大人提供给我们的文件中指出，我们将无法避免与那些卑劣的血色十字军进行一场战争。我们已经知道了他们穿越提瑞斯法林地所走的那条小径的确切位置。$b$b但亡灵卫兵还有其它艰巨的任务，巫妖王的军队正在夜色中逐渐壮大起来。我们需要一些像你这样的志愿者来把那群血色十字军送进坟墓。$b$b顺着镇外的道路向西走，穿过索利丹农场到废塔那里去，杀死10名血色十字军战士。以此来证明你有足够的能力为黑暗女王陛下服务。",objectives={"布瑞尔的执行官塞加德要求你杀掉10名血色战士。"}]])
R(428,"失踪的亡灵哨兵",[[description="几周前，亡灵哨兵兰妮·尤瑞克和奎恩·尤瑞克被派遣到银松森林北部去执行一次侦察任务。可我们一直没有再得到他们的消息。$B$B也许他们已经成了天灾军团的牺牲品。当然，我仍然希望有人能去确认一下，你去找到这两名亡灵哨兵。$B$B他们最初的任务是去侦察银松森林北边的农场，你可以从那里开始搜索。",objectives={"找到亡灵哨兵兰妮·尤瑞克和奎恩·尤瑞克。"}]])
R(429,"荒野之心",[[description="我的哥哥奎恩被食尸鬼伊瓦打成了重伤，我不知道在没有魔法帮助的情况下，他是否还能痊愈。尽管我不是一个药剂师，但我知道我们的药剂师能用变色的狼心制作治疗药水。$B$B帮我收集一些心脏并带给南边坟场的药剂师伦弗利尔，然后把做好的药水带回来。$B$B这附近和东边的玛尔丁果园之间有不少座狼在到处游荡。",objectives={"收集6颗变色的狼心，把它们交给瑟伯切尔的药剂师伦弗利尔。"}]])
R(430,"回到奎恩身旁",[[description="这就是那种能帮助奎恩·尤瑞克复原的药水。$B$B现在，如果你没什么事的话，我就先失陪了。我还有重要的工作要继续……",objectives={"将奎恩的药水带给瑟伯切尔北方伊瓦农场的奎恩·尤瑞克。"}]])
R(431,"诱灵蜡烛")
R(432,"该死的石腭怪！",[[description="那些该死的石腭怪，它们把我的工作地点变成了一片废墟！看那里，又一个火药桶！$b$b啊啊啊啊啊，我真想钻到地底下去扭断它们那豆芽一样的脖子！我要把它们赶尽杀绝！$b$b即使这样也无法消除我的愤怒……它们留给了我什么？什么也没有！$b$b我要亲手杀了它们，不过我的胳膊已经不再那么有力了！到采石场去，干掉那帮该死的家伙！我会奖赏你的！只要你去干掉它们！",objectives={"在古博拉采掘场里替工头乔尼·石眉杀死6个石腭击颅者。"}]])
R(433,"公众之仆",[[description="作为参议院与探险者协会的成员，我已经开始过问这个地区石腭怪泛滥的事情了。$b$b它们把古博拉采掘场搞了个天翻地覆，而且它们的这种行为看起来毫无理由。当我们在矿井中挖掘矿石的时候，它们突然出现，毁坏了我们的设备，赶走了我们的矿工。我们别无选择，只有杀光他们，之后我们才能重建工地并继续工作。$b$b如果你愿意帮助我解决掉那些石腭怪的话，我会很乐意报答你的。",objectives={"在古博拉采掘场里替参议员梅尔·圣石杀死10个石腭断骨者。"}]])
R(434,"伏击！",[[description="等我做好间谍机器人的伪装，他会进去和莱斯科瓦谈话。守卫会让他进去的。$B$B在你帮我准备材料的同时，我会暗示马尔松，让他再次和莱斯科瓦会面，我甚至会给他一点假消息，好让他对此深信不疑。$B$B接下来，莱斯科瓦就会让他的卫兵解散，然后在花园里等马尔松。等你听到他们谈起迪菲亚兄弟会的时候就采取行动。你要把他们两个都干掉。听懂了吗？$B$B当你完成任务之后，尽快向提亚斯回报。",objectives={"等待葛瑞格·莱斯科瓦公爵和沉默之刃马尔松在花园里的对话结束，杀死他们两个，之后向暴风城的提亚斯回报。"}]])
R(435,"护送埃兰德",[[description="外面的狼群看来是不想离开了，而且我每次走出屋子的时候，它们都恶狠狠地盯着我。这些野狼显然是饿极了，它们把我当成了大餐！$B$B我得通知我的队友，亡灵哨兵兰妮·尤瑞克。也就是说，我要到她那里去，得先找人帮我搞定这群狼。$B$B请护送我吧！不过，这边的狼也实在是多了点，如果你还有别的朋友的话…再好不过……",objectives={"护送亡灵哨兵埃兰德避过群狼，直到他找到兰妮·尤瑞克。"}]])
R(436,"铁环挖掘场",[[description="勘察员基恩萨·铁环正在负责挖掘洛克湖东边的一座古老的废墟。虽然我们已经给他送去了不少物资，但是他那里最近进展非常缓慢。$B$B基恩萨·铁环是一个顽强、诚实而精干的矮人，没理由会如此懈怠，所以我担心他那儿出了什么问题。$B$B到铁环挖掘场去问问麦格玛尔·落斧，他负责挖掘场的琐事，一定知道那里到底是怎么了。$B$B你要可以从湖的南端绕过去，然后一直向东走，就可以到挖掘场了。",objectives={"和麦格玛尔·落斧谈一谈。"}]])
R(437,"亡者农场",[[description="我们在银松森林的探子回报说，腐皮豺狼人在北边的一处名叫亡者农场的地方建立了一个基地。我们已经派遣了小股突袭部队去对付他们，但每次他们都能得到女妖奈塔拉什的增援，每次都是她的魔法击溃了我们的部队。$B$B我们必须杀掉奈塔拉什。$B$B到亡者农场去杀掉那里的腐皮豺狼人。如果没有看到奈塔拉什的话，就继续屠杀腐皮豺狼人直到她出现为止，然后击败她。$B$B她的灵魂将会变成尘土。把这些尘土带回来，作为你杀死了她的证明。",objectives={"清剿亡者农场的腐皮豺狼人。$B$B当奈塔拉什出现时，把她也杀掉。$B$B将奈塔拉什的灵魂带给瑟伯切尔的高级执行官哈德瑞克。"}]])
R(438,"破旧渡口",[[description="$N，我们最近发现了天灾军团的一个新据点：破旧渡口。这处渡口就在瑟伯切尔的东方，有许多腐皮豺狼人和其他亡灵层层守卫着那里。$B$B天灾军团占据了那里，这其中一定有些什么阴谋。到破旧渡口去调查一下，看看为什么天灾军团会在那里。",objectives={"到破旧渡口去，找到天灾军团占据那里的理由。"}]])
R(439,"线索",[[description="在一大堆尸体中间，有一只裸露的手。这是一只女人的手，虽因瘟疫而导致皮肤上布满红痘，但仍然十分白皙。$B$B她的手上戴着一只戒指。你从尸体的手上取下这只戒指，看到戒指内环中有一道铭文：$B$B“赠予黛丽娅”",objectives={"将黛丽娅的戒指带给瑟伯切尔的高级执行官哈德瑞克。"}]])
R(440,"黛丽娅的戒指",[[description="如果你想找到黛丽娅的丈夫或情人，也就是送给她戒指的那个人的话……去找布瑞尔的执政官塞弗伦谈谈吧。他或许拥有最近的死亡记录，当然，如果你走运的话，还能发现谁是黛丽娅。$B$B但我也不抱希望。无论给她戒指的人是谁，现在恐怕也已经死了。如果他成了亡灵，也就不会再关心黛丽娅了。",objectives={"将黛丽娅的戒指带给布瑞尔的执政官塞弗伦。"}]])
R(441,"拉林夫与幽暗城",[[description="黛丽娅有个丈夫叫拉林夫，他现在居住在幽暗城。如果居住在布瑞尔的这位黛丽娅就是这只戒指的主人，想必他应该知道。$B$B拉林夫就在幽暗城的贸易区。",objectives={"把黛丽娅的戒指交给拉林夫。"}]])
R(442,"突袭芬里斯岛",[[description="现在是把天灾军团彻底赶出银松森林的时候了。$B$B你必须再去一次那个岛，杀死图勒·鸦爪，把他的头颅提来见我！$B$B这个任务非常危险，但是你也应该知道它的重要性，$N。所以你只能成功，不能失败。",objectives={"将图勒的头颅带回给瑟伯切尔的高级执行官哈德瑞克。"}]])
R(443,"腐皮豺狼人的脓液",[[description="在我们对芬里斯岛展开一次突袭行动之前，我们必须得弄清楚谁是腐皮豺狼人背后的真正主人，我们的药剂师们相信它们的体内发生了某种神秘的变化。$B$B到破旧渡口东边的芬里斯岛去，收集一些腐皮豺狼人身上流出的脓血，然后把脓液交给瑟伯切尔外的药剂师伦弗利尔。",objectives={"给瑟伯切尔的药剂师伦弗利尔带去8瓶腐皮豺狼人的脓液。"}]])
R(444,"腐皮豺狼人的产生",[[description="我还原了你带给我的脓液，并把它们分离成了一些基本成分。我的发现还不是结论性的，但我可以肯定恶魔法术和死灵法术在这脓液的产生过程中起了极其重要的作用。$B$B在我继续研究脓液的同时，我希望你能给幽暗城的比索·埃斯沙德带些样本过去。比索虽然不是一名药剂师，但他在魔法方面的学识将会帮助我们揭开这些腐皮豺狼人的秘密。$B$B快去吧，比索就住在幽暗城的法师区。",objectives={"将脓液样本交给幽暗城的比索·埃斯沙德。"}]])
R(445,"给银松森林送信",[[description="如今，对我们这些希尔瓦娜斯女士的仆从来说，时间就是一切。显然现在你也非常清楚这一点。$b$b身为皇家药剂师学会的一员，我必须将我的研究成果与同事们分享，只有依靠所有会员的共同努力，我们才能向黑暗女王陛下提供她最期望的新瘟疫。$b$b将这些报告带给住在银松森林瑟伯切尔里的药剂师伦弗利尔，从布瑞尔向南走，到了幽暗城再转往西南就可以了。",objectives={"将药剂师乔汉的研究成果带给银松森林的药剂师伦弗利尔。"}]])
R(446,"图勒·鸦爪",[[description="这种脓液是我以前的一个同僚图勒·鸦爪制成的。在大战之前，他是一个有着大好前途的年轻法师，但在巫妖王的势力崛起之后，他背叛了他的朋友与兄弟，加入了天灾军团。$B$B我没料到他还活着，更没有想到的是，原来是他在领导腐皮豺狼人与我们对抗。$B$B我对他的许多法术都有所了解，应该能帮忙调制出一种能击败他们的药剂。把这个卷轴交给药剂师伦弗利尔，卷轴上面写着调制药水所需要的咒语。",objectives={"把比索的卷轴交给银松森林中的药剂师伦弗利尔。"}]])
R(447,"致命的配方",[[description="阿尔萨斯的手下越来越多。不过，只要再来一次新的瘟疫，我们就可以一劳永逸地同时根除天灾军团和人类。$b$b我的研究已经证明，将灰熊心脏中提取出的毒素和蜘蛛血混合在一起，就可以制成一种致命的毒药。从西北方的粘丝洞中的蜘蛛身上和银松森林中游荡着的熊身上采集一些样本回来，然后把它们送给幽暗城皇家药剂师学会里的大药剂师法拉尼尔。",objectives={"收集6个灰熊的心脏和6份粘稠的血液样本，并将这些东西送给幽暗城的大药剂师法拉尼尔。"}]])
R(448,"给哈德瑞克的报告",[[description="在你展开对芬里斯岛的攻击之前，先向高级执行官哈德瑞克复命吧。他或许还有些额外的装备或者情报要给你。",objectives={"向瑟伯切尔的高级执行官哈德瑞克复命。"}]])
R(449,"亡灵哨兵的报告",[[description="尽管奎恩的伤基本已经好了，但我仍想尽可能快地把报告呈送给高级执行官哈德瑞克。这里面的情报对被遗忘者来说十分重要，它将关系到我们在整个银松森林的统治地位。",objectives={"将亡灵哨兵的报告的报告交给瑟伯切尔的高级执行官哈德瑞克。"}]])
R(450,"致命的配方",[[description="其实你还能为皇家药剂师学会再做一些事情，$N。$b$b当初阿鲁高在整个森林中施展了他那可恶的魔法时，我们当中一位最有前途的成员——药剂师博拉尔德，也被他诅咒了。现在博拉尔德已经变成了一个忠于阿鲁高的傀儡，换句话说，他对我们已经彻底没用了。但是他的研究成果可能对我们非常有用，因为他在多年以前曾经研究过一种杀死了洛丹米尔湖中所有生物的瘟疫。$b$b将伯纳德的日记从他在焚木村旅店中的研究室里偷出来，然后把日记交给药剂师伦弗利尔。",objectives={"从焚木村的旅店中找到伯纳德的日记，把它交给瑟伯切尔的药剂师伦弗利尔。"}]])
R(451,"致命的配方",[[description="根据博拉尔德的研究日记，采自湖岸爬行者和潜藏者身上的苔藓会对我们制造出这种瘟疫大有助益。这些野兽就栖息于东边的洛丹米尔湖中的群岛上。$b$b他还提到曾在一只邪鳍鱼人身上发现了一种非常稀有的硬瘤，显然这种瘤很难得到，博拉尔德也只找到了一个。$b$b收集一些苔藓和那种稀有的瘤，把它们带给幽暗城的大药剂师法拉尼尔。",objectives={"收集6份湖岸爬行者苔藓的样本、6份湖岸潜藏者苔藓的样本和1块硬瘤，把它们交给幽暗城的大药剂师法拉尼尔。"}]])
R(452,"焚木村中的伏击",[[description="你来得正好，$N！$b$b焚木村议会随时都有可能回来，而阿鲁高此时正好无暇顾及这里。他利用议会作为傀儡控制着焚木村中无知的村民们，我相信如果没有议会的引导，阿鲁高的奴隶们一定会反戈一击，背叛他们的主人。$b$b我无法独自应付他们所有人。我需要你的帮助，只要齐心协力，我们一定能为希尔瓦娜斯主人消灭焚木村议会。",objectives={"帮助亡灵哨兵费雷亚消灭焚木村议会。"}]])
R(453,"搜寻乌鸦岭",[[description="祝你好运，$N。我希望你能找到这个家伙，也希望他还活着。$B$B外面可没有夜色镇这么安全，他可能早就成了野兽的猎物。",objectives={"找到那个模糊的人影。你的线索：$B$B他不是夜色镇的本地人。$B$B他是个紧张而敏感的人。$B$B他离开夜色镇往西边去了。"}]])
R(454,"恶战之后",[[description="在这事之前，我们一直在来来回回拖着这几个装着火药的桶往挖掘场运。现在我们得分工一下，米兰负责搬这些桶，我负责搬其它的。$b$b不过让米兰一个人运送剩下的货物我多少有点不放心，你能不能在他下次送货的时候护送他一程呢？",objectives={"和米兰谈一谈。"}]])
R(455,"丹奥加兹告急",[[description="龙喉氏族的兽人在湿地有了一处巢穴，现在他们的势力已经快扩展到丹奥加斯了！我们可绝不能让他们在这里立足，不然，我们在湿地唯一的港口与要塞——米奈希尔港与洛克莫丹的联系将会被切断。$B$B穿越丹奥加兹到湿地那边去，向米奈希尔港的瓦斯塔格·铁腭报到，路上顺便杀它几个兽人玩玩！$B$B米奈希尔就在丹奥加兹的另一边，只要先顺着路向北，然后在岔路口转向西边就是。$B$B我们寄希望于你，$N。可别让我们失望。",objectives={"翻越丹奥加兹。$B$B杀死8个龙喉斥候和6个龙喉步兵。$B$B向米奈希尔港的瓦斯塔格·铁腭报到。"}]])
R(456,"自然的平衡",[[description="你好，$N。我是管理员伊尔萨莱恩。我的职责是维护幽影谷一带的自然平衡。$b$b今年的春雨似乎比往年来得都要连绵不绝，这导致了森林中某些动物的过度繁殖，而其它动物就遭了殃。$b$b其中，夜刃豹和草刺野猪的族群已经过于庞大了，幽影谷无法为它们提供更多的食物。去吧，年轻的$c，去减少野猪和夜刃豹的数量，以保证自然的和谐。",objectives={"杀死7只夜刃豹幼崽和4只草刺野猪幼崽，然后向管理员伊尔萨莱恩复命。"}]])
R(457,"自然的平衡",[[description="削减幽影谷地中生物幼兽的数量是一个很好的开始，$N，但这还远远不够。$b$b如果问题不能得到根本解决的话，森林中的资源还是很快就会被耗尽的。杀死某些生物对于生长在这片土地上的所有生物来说都是有益的。为了自然的平衡，到森林里去清除一些癞皮夜刃豹和一些草刺野猪吧。",objectives={"管理员伊尔萨莱恩要求你杀死7只癞皮夜刃豹和7只草刺野猪。"}]])
R(458,"森林守护者",[[description="谢天谢地你在这儿，$c。森林中的小精灵们告诉了我一些奇怪的消息。$b$b神秘的森林守护者塔琳德拉又回到了幽影谷。这位树妖的身影已经许多年都没有在卡利姆多大陆上的森林中出现过了。她既然回到了这里，就意味着这里一定出了什么事情。$b$b找到了塔琳德拉，并且问问她我们的森林到底怎么了。有个哨兵向我报告过，塔林德拉曾在奥达希尔的西边出现过。",objectives={"找到树妖塔琳德拉。"}]])
R(459,"森林守护者",[[description="一些邪恶的事物正在泰达希尔的森林中滋生着。看看那些原先性情温和的熊怪们居住的地方吧。他们放弃了自己的家园，聚集在了所谓的脊骨部落的名下。$b$b一定是那些腐朽毒恶的魔苔的瘴气造成了这种变异。小劣魔和劣魔也在幽影谷滋生开来，惊扰着这里的居民。$b$b去和这些小劣魔和劣魔战斗吧，$N，观察一下他们是否真的是受了魔苔的影响。",objectives={"收集8块魔苔，把它们交给塔琳德拉。"}]])
R(460,"支离破碎",[[description="你看上去跟那帮腐皮豺狼人不一样，这真好。我都快绝望了……$B$B我叫奥拉瑞克，过去曾是图勒的大管家兼保镖。他用他的魔法“保护”了我，使我免受“亡灵瘟疫”的影响，但他的魔法也让我变成了这个半死不活的样子。而且，自从图勒创造了那群该死的腐皮豺狼人之后，他竟然砍了我的头……还把我的头给那群豺狼人当球踢！$B$B拜托，把我带到我的身体那儿去。那群豺狼人大概是把它埋在了芬里斯城堡的马厩旁……",objectives={"将奥拉瑞克的头颅带到他的坟墓旁。"}]])
R(461,"密室",[[description="我知道在这城堡中有间密室，密室里藏着一件对图勒和他的同伙们来说很宝贵的东西，也许那里面也有些对你很有用的东西。把我带到那里去！$B$B这密室就在城堡西南的塔里，在一处满是灰尘的柜子后面。$B$B带上我的身子，但是不要靴子…这靴子就没合适过……",objectives={"将奥拉瑞克带到密室去。"}]])
R(462,"<UNUSED>",[[description="Other than you, we sent two scouts through Algaz.  Only one returned.  Here's what he discovered:$B$BThe Dragonmaws sent one of their Lieutenants, Maruk Wyrmscale, to organize a crew of orcs in Algaz and cut off the land route to Menethil Harbor!$B$BWe have to stop this, now.  Take out Maruk, and then report to Valstag Ironjaw in Menethil Harbor.$B$BMaruk is headquartered in a small cave, across a pond between the second and third tunnels of Algaz.  Menethil is through Algaz, then west along the road.",objectives={"Kill Maruk Wyrmscale$B$BReport to Valstag Ironjaw in Menethil Harbor."}]])
R(463,"绿色守卫者",[[description="你听说过绿色守卫者？你应该不是在找他吧，是不是？如果是的话，我真得说你是个疯子，不过我为什么要阻止一个疯子去找他送死呢？$B$B好吧，如果你真是在找那只凶兽的话，我听说它就在沼泽里，在通向丹莫罗的那个岔路口的东边。他就潜伏在那个危险的地方，在鳄鱼群之间……听说那里还有些更可怕的东西！$B$B把你的钱留在这里吧，要是你去找他，钱对你来说也就没用……你该不会想在那家伙咬你的时候用你的金币给他镶金牙吧？",objectives={"找到绿色守卫者。"}]])
R(464,"龙喉战旗",[[description="按理说，龙喉氏族的兽人应该已经在第二次兽人战争中全部被消灭干净了呀。那时，他们失去了对红龙的控制，而被奴役了许久的红龙对兽人极度仇恨，所以就到处猎杀他们。只有一小部分龙喉兽人从格瑞姆巴托逃了出来，躲进了维尔加挖掘场东边的山里。$B$B现在他们的族群似乎又恢复了兴盛，有线报说他们在米奈希尔的东北方建立了一座营地。$B$B我们要你去进攻那座营地，并带回一些战旗作为功勋评定的证据。",objectives={"给斯托菲队长带回8面龙喉战旗。"}]])
R(465,"纳克罗什的优势",[[description="当你在和那些龙喉氏族的兽人作战时，我们又获得了更多有关他们的作战计划的情报。$B$B首先是一个坏消息，纳克罗什正在大量地建造投石车，计划一举攻陷米奈希尔！还有一个好消息，经过在丹奥加兹一带的艰苦奋战，我们已经把他们的援军彻底挡了回去！$B$B现在你所要做的就是毁掉那些投石车，它们目前仍被停放在龙喉氏族的营地里。$B$B给，带上这些火绒。你得先在营地里杀出一条血路，找到那些投石车，然后再用这些火绒烧了它们。$B$B完成这一切之后，就去找纳克罗什，把他给干掉。我们必须彻底地将这些龙喉氏族的兽人消灭掉！",objectives={"摧毁所有的龙喉投石车。"}]])
R(466,"火岩矿石",[[description="我听说最近在湿地一带发现了一种特别稀有的矿石，大家管它叫火岩，那矿洞就在奥加兹大门西北方的一处洞穴里。火岩矿石非常不稳定，它很容易爆炸，但我敢说，如果加工方法正确的话，它就可以用来制作威力强大的炮弹！$B$B给我搞一些火岩矿石的样本来，我可以去找个够胆的家伙来对它进行实验。$B$B哦，要想采集到这些矿石的话，你可得懂点采矿技术才行。如果你完全不懂的话，那么……就找个懂行的朋友一起去吧！",objectives={"给丹莫罗的驾驶员迪恩·石轮带回6份火岩矿石。"}]])
R(467,"迪恩·石轮的梦想",[[description="驾驶员迪恩·石轮和其他驾驶员一样非常喜欢他的攻城坦克，他一直都想要找到加强坦克火力的方法！$B$B他听说有一种罕见的矿石，现在正在到处拉人为他寻找这种矿石呢。如果你想找点事干的话，就去丹莫罗的钢架补给站找他，看看他都需要些什么。",objectives={"和驾驶员迪恩·石轮谈一谈。"}]])
R(468,"向巡山人罗克加报告",[[description="巡山人罗克加正在招募一些能穿越丹奥加兹到湿地去执行任务的志愿者。$B$B如果你想去北边感受一下鞋子里灌满水的感觉，那就到丹奥加兹去找罗克加谈谈吧。沿着道路向北，走过哨塔就到丹奥加兹了。",objectives={"与巡山人罗克加谈一谈。"}]])
R(469,"日常供货",[[description="你好，旅行者！$b$b你是不是要去米奈希尔港？如果不是的话，我建议你就留在这里吧，你要是想买点东西啊，喝一杯啊，或者放松放松神经什么的话，这里就再合适不过啦。$b$b如果你确实是要去米奈希尔的话，那么……我想……你应该不会介意把这捆鳄鱼皮捎给皮匠詹姆斯·哈洛兰吧？$b$b我本来是想自己亲自走一趟的，但我那个在城里的老婆最近正发脾气呢，我实在不想马上就见到她，能拖多久就拖多久。",objectives={"将这捆鳄鱼皮带给米奈希尔港的皮匠詹姆斯·哈洛兰。"}]])
R(470,"搜寻软泥怪",[[description="我每周都要对西北方山脚下的铁须之墓进行例行的拜访。然而，上次过去的时候，我竟然遭到了那些可怖的软泥怪的攻击，我当时自然是吓坏了。$b$b我身上也没带武器，只好抓起背包丢它们，不过那完全没有用！软泥怪很轻松地把我的背包给吞掉了……不过，幸运的是，这也为我争取到了逃跑的时间。$b$b但是我现在很需要包里的东西！$b$b我已经忘记把包扔进哪只软泥怪里了，它们看起来都是一模一样的！所以呢，你恐怕得多杀个几只才能找到我的包。铁须之墓就在东北方，丹奥加斯附近。多谢你啦！",objectives={"铁须之墓中的某只软泥怪身上有塞达的背包，夺回背包，把它送还给米奈希望港的塞达。"}]])
R(471,"学徒的职责",[[description="我把我的学徒派到了沼泽那边去，希望他能给我搞到一些著名的巨型鳄鱼的皮回来。然而他一直都没回来，我只好亲自去找他……怎么说呢，反正我当时看到了一些比较惨的场面。$b$b医生说他很快就会恢复健康的，但现在，我仍然急需鳄鱼皮！$b$b……要是你能帮我杀几条这种凶猛残忍的大鳄鱼，从它们身上给我剥几张皮下来，我会非常高兴的。沿着海岸北上，走过了那些鱼人搭建的简陋小屋之后就能找到鳄鱼了。",objectives={"为米奈希尔港的詹姆斯·哈洛兰带回6张巨型鳄鱼的皮。"}]])
R(472,"丹莫德的陷落",[[description="丹莫德已经被黑铁矮人攻陷了！$b$b我伤得很重，$c。我们的大多数战友都已经牺牲了！我们在萨多尔桥遭遇了伏击，正在重整部队的时候，那群该死的黑铁矮人再度突袭了我们。$b$b我们的领袖布莱德·长须被迫吹响了撤退的号角。我们刚一离开镇子，我就被人从背后砍了一斧子，然后就眼前一黑昏死了过去。$b$b当我醒来的时候已经身在米奈希尔了，但是，我现在很担心我手下的士兵们。我依然保有一丝希望，也许布莱德·长须还活着！看看你能不能在丹莫德附近找到他吧，$c！",objectives={"在丹莫德镇附近寻找布莱德·长须的踪迹。"}]])
R(473,"向斯托菲队长报告",[[description="$N，龙喉氏族的兽人们一天天地壮大了起来，这样下去它们迟早会攻破奥加兹的。斯托菲队长正在诚招志士来对抗那些兽人，他就在城堡里面的指挥室中。",objectives={"与斯托菲队长谈一谈。"}]])
R(474,"击败纳克罗什",[[description="现在所有的投石车都被烧掉了，找到纳克罗什酋长，把他干掉。",objectives={"杀掉纳克罗什酋长。$B$B将纳克罗什的头颅交给斯托菲队长。"}]])
R(475,"烦恼之风",[[description="一阵令人烦恼的微风吹过了森林。$b$b盖洛拉斯·塔文斯伦一直负责为那些在班奈希尔兽穴中休眠的猛禽德鲁伊们放哨。作为沉睡者们的保护者，他的职责是确保德鲁伊们的安全，从而使他们可以履行与伊瑟拉定下的契约。$b$b但是我很久都没有收到盖洛拉斯的消息，现在我已经越来越紧张了。到东边的星风村去一趟，帮我把盖洛拉斯的报告带回来，这样会让我心里轻松一些。",objectives={"在星风村找到盖洛拉斯·塔文斯伦。"}]])
R(476,"瘤背熊怪的堕落",[[description="瘤背部族的熊怪已经堕落了！$b$b曾经爱好和平的熊怪现在转而与森林的保护者为敌。我刚刚动身准备去班奈希尔兽穴的时候就遭到了它们的伏击，而熊怪们现在还准备掠夺星风村！它们的首领——大槌乌萨尔——正在运用魔苔的邪恶力量使它们变得更加疯狂。$b$b我伤得太重了，无法返回去把这个十万火急的消息告诉阿斯瑞达斯。这个任务就交给你了，年轻的$c。我们只能希望疯狂的瘤背熊怪还没有对班奈希尔下手！",objectives={"返回多兰纳尔去见阿斯瑞达斯·熊皮。"}]])
R(477,"越境",[[description="你也许知道，安伯米尔镇里还有一群人类在负隅顽抗，事实上，这主要是因为达拉然的法师们在支援着他们。$b$b我不知道他们到底有什么计划，不过我想，既然他们对这样一个偏僻的小镇表现出如此浓厚的兴趣，那么这个地方一定有什么还不为我们所知的重要意义。$b$b法师们隔三差五地用马车把一些木箱从希尔斯布莱德运到安伯米尔去，他们补给线的终点就在焚木村北面的一处营地里。帮我把木箱里的东西拿来一些，让我好好研究一下。",objectives={"从达拉然法师的木箱中拿出里面的东西。"}]])
R(478,"地图与符记",[[description="<你迅速从箱子里中拿起了坠饰并将箱子重新盖好。>",objectives={"将这个奇怪的坠饰交给瑟伯切尔的暗影牧师奥利斯特。"}]])
R(479,"调查安伯米尔",[[description="达拉尔正在尝试着定位出达拉然法师们施法时的能量流向。现在，我们必须要尽我们一切努力来暂缓他们的进程……$b$b那些咒术师、法师和保卫者恐怕会拼死保护坠饰。你必须清除掉这些阻碍，并把饰物抢到手。$b$b沿着大路向南走，在岔路口转向东边就可以到安伯米尔了。",objectives={"为瑟伯切尔的暗影牧师奥利斯特抢到8个达拉然坠饰。"}]])
R(480,"法师的头领",[[description="一位具有强大法力的大法师正在监管着启动节点的行动。在目前的形势下，我们只有杀死那个大法师才有可能阻止他们了。这将是个艰巨的任务，无疑会有许多法师与守卫层层护卫着他。$b$b你必须出发了，尽快结果掉他。大法师死了以后，把他的法杖带回来给我。现在就去，快！",objectives={"杀死达拉然大法师，并把他的法杖交给瑟伯切尔的暗影牧师奥利斯特。"}]])
R(481,"达拉尔的推理",[[description="把这个饰物交给达拉尔·道恩维沃尔，或许他能从中发现一些蛛丝马迹。",objectives={"把刻有符文的坠饰交给瑟伯切尔的达拉尔·道恩维沃尔。"}]])
R(482,"达拉然的意图",[[description="啊！我想起来了！$B$B安伯米尔一直是为肯瑞托所关注的地方，因为那里隐藏着一个能量节点。那群法师们一定计划启动节点，并使用里面蕴涵着的能量来为他们更深一层的目的服务。$b$b我们不能允许这样的事情发生……$b$b启动节点需要花费大量的魔法能量，只要我们把这些坠饰抢走，达拉然的法师们就无法继续他们的行动了。$b$b把这件事告诉奥利斯特，他会制定出行动计划的。",objectives={"与瑟伯切尔的暗影牧师奥利斯特谈一谈。"}]])
R(483,"唤醒圣物",[[description="瘤背部族的熊怪正在西边的班奈希尔兽穴里肆虐。$b$b除非我们伸出援手，否则那些正在沉睡的德鲁伊将永久地陷于翡翠梦境中，对即将降临的噩运浑然不觉。只有拿到所有的唤醒圣物，我们才能将休眠仪式打断。$b$b到兽穴里去帮我找回鸦爪神符、黑色羽毛、天蓝宝石和筑巢符文。德鲁伊们把这些圣物藏在神圣的盒子里，把它们带给我，我要准备进行唤醒仪式。",objectives={"寻回四件唤醒圣物,把它们带给多兰纳尔的阿斯瑞达斯·熊皮。"}]])
R(484,"小鳄鱼皮",[[description="我是皮匠詹姆斯·哈洛兰。我用鳄鱼皮做东西的手艺可是艾泽拉斯第一流的，每天都有大船把我的产品一箱一箱地运到世界各地的港口去。$b$b你见过埃纳尔了吧？他也是专门为我提供新鲜鳄鱼皮的诸多猎人之一。$b$b最近我这里的小鳄鱼皮供应量在直线下降，鉴于目前我真的很缺货，如果你能帮我弄些小鳄鱼皮回来，我会给你开出一个非常不错的价码。你可以在镇外的沼泽里找到那种小鳄鱼。",objectives={"为米奈希尔港口的詹姆斯·哈洛兰带回4张小鳄鱼皮。"}]])
R(485,"找到OOX-09/HL！",[[description="你发现了一个奇怪的蛋形金属物体。随便拨弄了几下之后，它居然自动打开了，变成了一个看来是由侏儒制造的机器装置！一个奇怪的声音从这个蛋形机器装置中传了出来。$B$B“我的名字叫奥格索普，我的母体机器人不见了！如果你能帮我找到它，我就会奖励你的！请把这个定向器带到那个母体机器人那里。别担心，我现在已经检测到了它的所在地！它现在就位于藏身石那一带的河水源头附近！”",objectives={"把定位器带到奥格索普的母体机器人那里去。$B$B奥格索普的母体机器人位于辛特兰的河水源头，就在藏身石的附近。"}]])
R(486,"大槌乌萨尔",[[description="现在我们必须去解救猛禽德鲁伊了。如果我们现在失败了，他们就将永远迷失于睡梦中。$b$b我将为苏醒仪式做好准备，不过为了进行这个仪式，就必须杀死造成现在这种混乱局面的罪魁祸首。只有到那时，仪式才能正常进行和完成。$b$b大槌乌萨尔把一切都搞得一团糟，现在只有让它为此付出代价，猛禽德鲁伊才能重获自由。到西南边的脊骨堡去杀了它！",objectives={"杀掉大槌乌萨尔，然后回到多兰纳尔的阿斯瑞达斯·熊皮那里。"}]])
R(487,"达纳苏斯之路",[[description="我们必须保证通往达纳苏斯的道路的安全。有报告说，从多兰纳尔去达纳苏斯的旅行者经常会受到来自瘤背熊怪的残忍袭击。$b$b每天都有无数重要的信息在这条路上进行传递，因此我们绝对不能容忍这帮堕落的熊怪整日恐吓无辜的旅者。$b$b以神圣森林的名义拿起武器，$c。熊怪们的巢穴就在这个高地下面的某个地方。去杀死6个瘤背伏击者，然后再回来向我报告。",objectives={"杀掉6个瘤背伏击者，然后向多兰纳尔城外的哨兵阿玛拉·夜行者报告。"}]])
R(488,"赛恩的要求",[[description="我知道你渴望工作，对你来说今天是个幸运的日子，因为我今天只能靠你这个乳臭未干的$c来帮忙了。$b$b你知道，$N，我可以使你非常幸福，我可以让你拥有你从未想过的好东西。但是首先，你必须给我带些东西来。$b$b我在森林里的工作需要一些材料……给我拿来三颗夜刃豹的牙齿、三根巨翼枭的羽毛和三份树林蜘蛛丝。",objectives={"给多兰纳尔外面的赛恩·腐蹄带去3颗夜刃豹的牙齿、3根巨翼枭的羽毛和3份树林蜘蛛丝。"}]])
R(489,"寻求救赎！",[[description="森林议会听说你帮助了赛恩·腐蹄，这个险恶的萨特是森林的敌人。作为一个$r，你应该更清楚我们不能杀害自然的生物，玷污圣洁的森林。$b$b如果你希望继续做泰达希尔的朋友的话，你就必须在众人的关注下挽回这个过错。$b$b给赛恩·腐蹄一个教训，你就可以得到原谅。魔锥果是从树上掉落的腐坏的种子，一般都冒着绿色的烟气。$b$b给赛恩带去3个魔锥果，他会以为那些只是无害的点心。",objectives={"收集3个魔锥果，把它们给在多兰纳尔外面的赛恩·腐蹄。"}]])
R(490,"Bounty: Gnarlpine Furbolg",[[description="By strict orders from the Council of Darnassus, I am commissioning a bounty on the Gnarlpine Tribe. They are no longer friends of the forest. Their corruption has left them mindless threats to our people and the creatures of the glade.$b$bAs decreed by the Council, you shall be rewarded for removing the furbolg menaces from Kalidar. Bring to me their fangs as proof of your deeds.",objectives={"Shayla Nightbreeze outside of Darnassus wants you to bring her 20 Gnarlpine Fangs."}]])
R(491,"给比索的魔杖",[[description="图勒曾经告诉过我，很久以前，他和两名同僚利用各自手中的魔杖混合造出了一根新的魔杖。这根魔杖是友谊的象征。不过图勒虽然珍视他的友谊，但他却更珍视这件物品，并且不会允许自己与别人共同拥有这样一件宝物。所以他偷走了这支魔杖，将它藏在了芬里斯城堡。$B$B就是这个。将这个魔杖送给比索·埃斯沙德，许多年前他曾是图勒的好朋友。我相信他会需要的。",objectives={"将狼人魔杖带给幽暗城法师区的比索·埃斯沙德。"}]])
R(492,"新的瘟疫",[[description="亡灵卫兵们说，他们又抓住了一个愚蠢的矮人巡山人。在对这个俘虏做出“妥善”处理之前，卫兵们似乎打算把他先关在恐惧之末旅店的地下室里。$b$b不如你帮我跑一趟，去看看这位可怜的俘虏喜欢不喜欢我为他特制的饮料吧。那饮料里只掺了一丁点黑暗女王想在整个艾泽拉斯大陆上使用的那种东西……",objectives={"将乔汉的特制饮料交给被俘虏的巡山人。"}]])
R(493,"前往希尔斯布莱德丘陵",[[description="为了给黑暗女士研究出一种新的瘟疫，皇家药剂师学会最近正承受着巨大的压力。当然，我们一直在努力工作并取得了突破性的进展。我们坚信，如果我们学会的成员彼此分享研究成果的话，进展将会更快。$b$b因此我要求你将这些我的最新发现送到塔伦米尔的药剂师林度恩那里去。塔伦米尔是一座位于希尔斯布莱德丘陵地带的小镇，这趟路程可能会很远。$b$b顺路一直向南走，记得看路标！",objectives={"将伦弗利尔的研究成果交给希尔斯布莱德山脚下塔伦米尔的药剂师林度恩。"}]])
R(494,"进攻的时机",[[description="嘘！安静点，仔细听我说，$c。$b$b我被派到这个地方来监视希尔斯布莱德镇里的人类的动向，你必须把我的口信带给塔伦米尔的高级执行官达萨利亚，跟她说一句：$b$b“西边传来乌鸦的第三声叫声。”$b$b沿着大路往东走，注意看路标。快点！赶快去塔伦米尔，这件事情很紧急！",objectives={"到塔伦米尔去，把亡灵哨兵莱什的口信带给高级执行官达萨利亚。"}]])
R(495,"意志之冠",[[description="希尔瓦娜斯殿下曾派出玛格索尔和他的食人魔手下们前往奥特兰克去夺取意志之冠。然而，不幸的是，他们并没把它还回来，那个白痴竟然把它戴在了自己的头上……我猜这群食人魔恐怕对这种亮闪闪的东西没什么抵抗力吧。$b$b无论如何，他这种自作主张的行为已经酿成了大错。想必是意志之冠操控了他，令他背叛了希尔瓦娜斯殿下。$b$b黑暗女王陛下希望我们处理掉愚蠢的玛格索尔，以此来警示其它不识时务的蠢货。到希尔斯布莱德丘陵的塔伦米尔镇去，向我的部下梅里萨拉报到。",objectives={"到希尔斯布莱德丘陵去，向塔伦米尔的梅里萨拉报到。"}]])
R(496,"受难药剂",[[description="唉，又在塔伦米尔度过了倒霉的一天。这里的新鲜空气让我浑身都不舒服，$N。$b$b我们最好早点给这些人类下毒。我一直在仔细研究我的药物里可能用到的致命药剂。$b$b如果你想帮忙的话，就给我收集这些东西：10个灰熊的舌头，还有非常稀少罕见的食苔蛛的毒液。塔伦米尔周围到处都是熊和食苔蛛。",objectives={"塔伦米尔的药剂师林度恩要你去收集10个灰熊的舌头和一些食苔蛛的毒液。"}]])
R(497,"<UNUSED>",[[description="As a child, raised as a gladiator at Durnholde Keep, I was befriended by Taretha, the daughter of my wet nurse and mistress of the damned bastard Blackmoore.$b$bThe past is the past, $n, but reports of human movements in Hillsbrad reminded me of that time. I dispatched a small party to the area to investigate and to retrieve an... item... given to me by Taretha, if they could.$b$bA fruitless task, no doubt, but perhaps...$b$bThey should have returned by now, I want you to go to Tarren Mill to investigate.",objectives={"Go to Tarren Mill and find out the status of the party sent by Thrall."}]])
R(498,"拯救行动",[[description="酋长派我和其他一些战士从敦霍尔德拿回一件东西，并调查这个所谓的辛迪加。$b$b我们到敦霍尔德去转了一圈，很惊讶地在那里看到了很多人类。我们勇敢地和他们战斗，不过他们在人数上占有绝对的优势。我们当中有些同伴被俘虏了，不过我逃了出来。$b$b敦霍尔德就在这里的东南部，过了河就是。德鲁尔和托格萨还被囚禁在那里，你得去把他们救回来。",objectives={"塔伦米尔的克鲁斯克要你把德鲁尔和托格萨从敦霍尔德城堡救出来。"}]])
R(499,"受难药剂",[[description="我得花一会儿时间把这些成分混合在一起，做成受难药剂。$b$b成功了！啊，还有什么能比给这个世界带来点灾难更让人愉快的呢？$b$b让我们看看这种药剂能不能达到预期的效果。$b$b让我的助手乌比瞧瞧黑暗女王为人类和天灾军团准备了什么样的礼物。",objectives={"把受难药剂交给乌比。"}]])
R(500,"破碎岭食人魔",[[description="破碎岭食人魔在奥特兰克城废墟附近的山上挖了一座小丘。我的侦察兵告诉我，他们现在还占领了那片遗迹。$B$B我们可不能让他们在那儿享福，一旦他们觉得在那儿生活很安全，下一步就会转移到丘陵地带，然后就是我们南海镇了！$B$B到北方的奥特兰克山去猎杀几个食人魔。把他们那肮脏的指节骨带回来，我会给你奖赏的。",objectives={"从奥特兰克山的破碎岭食人魔身上收集9个肮脏的指节骨，把它们带给南海镇的治安官雷德帕斯。"}]])
R(501,"痛苦药剂",[[description="哦，$N……希尔斯布莱德的花都开了，空气这么清新，让我不得不沉湎在这种痛苦之中。我从肮脏的窗子里望出去，渴望着那一天早点到来，让整个世界都感染上新的瘟疫，让他们得到应有的报应。$b$b我喜欢整天坐在这里思考，而现在黑暗女王赋予我的使命正在召唤我，请你帮帮我吧。我的研究表明，山地狮的血液可以制作出最棒的毒酒来。给我找一点来，让我们做点有趣的事吧。",objectives={"收集10瓶山地狮的血液，把它们交给塔伦米尔的药剂师林度恩。"}]])
R(502,"痛苦药剂",[[description="啊，我最喜欢的就是在这丘陵地区弥漫的鲜血的气味！$b$b现在我们加点这个再加点那个，然后最有趣的事情就要发生了！我想把这瓶用血制成的药剂叫做痛苦药剂。如果我的计算正确的话，这个药剂肯定能给希尔瓦娜斯殿下带来不少好处。不过我们还需要做个实验才能确认这一点。$b$b把这瓶药剂拿到西南方的希尔斯布莱德农场，然后到那个地区北部的农庄里去，让我们看看农夫雷恩的小狗斯坦雷喜不喜欢这份“礼物”。",objectives={"把痛苦药剂喂给小狗斯坦雷。"}]])
R(503,"高迪尔",[[description="从你拿到的文件来看，高迪尔被关在北边的一个辛迪加基地里，很有可能就在奥特兰克山。他已经被关押太久了，你必须尽快把他救出来。",objectives={"救出高迪尔，然后回到塔伦米尔去见克鲁斯克。"}]])
R(504,"破碎岭好战者",[[description="你已经和破碎岭食人魔打过交道了，现在我要你去好好教训教训他们……$B$B到奥特兰克遗迹去猎杀那些破碎岭好战者。我希望你多干掉一些——只有这样才能让这帮畜生离联盟的领土远一点。",objectives={"杀死15个破碎岭好战者，然后回南海镇向治安官雷德帕斯报告。"}]])
R(505,"辛迪加刺客",[[description="我是南海镇的新镇长，前一任镇长被刺杀之后，我刚刚上任。那些刺客一直都没有找到，不过据我们调查，几乎可以肯定他们是由辛迪加雇佣的——辛迪加是一个由邪恶的贵族掌管着的潜行者组织，而那些贵族则是已经陷落的奥特兰克王国的遗老遗少。$B$B根据我们最新的消息，辛迪加在由部落占据的小镇塔伦米尔的北方设有一个营地，到那儿去杀掉那里的辛迪加成员。",objectives={"杀死12个辛迪加劫匪和8个辛迪加潜行者，然后回到南海镇向赫尼·马雷布镇长报到。"}]])
R(506,"布莱克摩尔的余孽",[[description="一两天前，辛迪加的首领来找过我。他叫奥里登·匹瑞诺德，他声称自己是这片土地的领主。他向我吐露了他的计划，说要把反对他的那些兽人都变成奴隶，就象他的父亲和导师埃德拉斯·布莱克摩尔所计划的那样。$b$b更重要的是他还带着他的小情人，一个名叫艾丽萨的娇弱女孩。酋长想得到她脖子上带着的项链。$b$b现在你可以回去报信了，等手头上的事情忙完之后，我会自己回去的。",objectives={"把高迪尔收集的消息带给塔伦米尔的克鲁斯克。"}]])
R(507,"奥里登·匹瑞诺德",[[description="匹瑞诺德一定要被除掉，这个卑鄙的家伙绝不能继续在这世上逍遥了。他的领地就在北边的洛丹米尔湖岸上。去完成这个任务，$n，别忘了把酋长想要的项链也拿到手，然后再回到这里来。",objectives={"杀了奥里登·匹瑞诺德领主，并从他的情人艾丽萨身上拿回塔蕾莎的项链。"}]])
R(508,"塔蕾莎的礼物",[[description="项链吗？当然可以给你……拿走它吧！我不想再跟他有什么瓜葛了……求求你，别杀我……",objectives={"把塔蕾莎的项链交还给塔伦米尔的克鲁斯克。"}]])
R(509,"苦楚药剂",[[description="又是新的一天，又有一种新的药剂要配制。要我说，我宁愿让那些可怜的人类和天灾军团去互相拼命，他们就喜欢互相残杀。$b$b既然黑暗女王要加速这个过程，不如在这段恐怖的日子里再给这片土地加点死亡和疾病怎么样？$b$b我有个计划，$N，你现在到奈杉德哨岗去，那地方在塔伦米尔的南边，南海镇的东边。给我找6朵泥头花来让我配制药剂。",objectives={"收集6朵泥头花，把它们交给塔伦米尔的药剂师林度恩。"}]])
R(510,"预备行动计划",[[description="这些文件当中有一份物资清单，清单里包括各种日常物品（食物、武器、衣服）和其它工具（面具、油、毒药）。$B$B不过其中提到最重要的就是：尽快取得清单中的物资，为文件里所说的“针对南海镇的重要使命”进行准备。",objectives={"把预备行动计划带给南海镇的赫尼·马雷布镇长。"}]])
R(511,"密文信件",[[description="桌上有一封用密文写成的信，你根本没法读懂。",objectives={"把密码信交给南海镇的博学者迪布斯。"}]])
R(512,"贵族之死",[[description="我担心辛迪加的幕后首脑想要毁灭南海镇，因此我们必须在他们的计划得以实现之前干掉这些头目。$B$B你去北边奥特兰克山里的斯坦恩布莱德废墟调查一下，我们觉得那里是辛迪加的指挥部。$B$B我们知道这帮刺客是以前的奥特兰克贵族指使的，贵族们可能会打扮成普通辛迪加密探的样子，不过通过他们手上戴着的徽记之戒就能很容易地判断他们是不是贵族了。$B$B把他们的徽记之戒给我拿来。",objectives={"为南海镇的赫尼·马雷布镇长收集7个奥特兰克徽记之戒。"}]])
R(513,"苦楚药剂",[[description="就在我觉得这一天又要无趣地打发掉的时候，你给我带来了这些泥头花。$b$b等我把它们混合在一起。我们还需要幽暗城的大药剂师法拉尼尔给药剂里加上他的腐蚀胶体，然后就等着看好戏吧！$b$b把这个泥头花药拿去交给大药剂师法拉尼尔，$N，现在就去。",objectives={"把泥头花药交给幽暗城的大药剂师法拉尼尔。"}]])
R(514,"铁炉堡的译码者",[[description="我在铁炉堡有个同僚也许可以帮忙破译这封信。到铁炉堡的探险者联盟去找勘察员塔伯斯·雷矛谈一谈，告诉他是我让你去的，把这封信给他看。黑石塔以北如果还有人能读懂这封信的话，那一定就是他了。",objectives={"把密码信带给铁炉堡的勘察员塔伯斯·雷矛。"}]])
R(515,"苦楚药剂",[[description="泥头花药？太棒了！我怎么就没想到过这个呢？$b$b让我给这种可怕的药剂里面加入我研制的腐蚀胶体。$b$b如果要激活泥头花水里的污染成分，林度恩就得先弄到强力巨魔之血药水，还有南海岸的刺脊纳迦的鳞片和碎鳍鱼人的眼球。你去找到这些试剂，林度恩会知道怎么处理它们的。天哪，我真想早点知道他的实验进行得怎么样了！",objectives={"把泥头花水、1瓶强力巨魔之血药水、5块刺脊纳迦的鳞片和5颗碎鳍鱼人的眼球交给塔伦米尔的药剂师林度恩。"}]])
R(516,"博伦的巢穴",[[description="我收到报告说，一群天灾军团的亡灵正在附近集结，准备对我们进行一次袭击。既然得到了这样的情报，我们就本应该先下手攻击他们，把他们的计划粉碎在襁褓中才对。$b$b但不幸的是，我的情报十分有限，只知道他们在一个名为博伦的巢穴的山洞里集结。确切的位置我也不清楚，但应该在安伯米尔附近的山区中。$b$b我相信以你的能力和才智，一定可以找到他们，干掉他们。",objectives={"找到博伦的巢穴，杀死6名鸦爪苦工和6名鸦爪守护者，然后向瑟伯切尔的暗影牧师奥利斯特汇报。"}]])
R(517,"苦楚药剂",[[description="新药剂终于进入了实验阶段,不过为什么我们要把一种完美无缺、具有高度传染性的瘟疫浪费在一只青蛙或一条狗身上呢？让我们以希尔瓦娜斯大人的名义好好找点乐子吧。$b$b到丹加洛克去，你知道，就是到那些肮脏的小矮人出没的军营里去，给我偷一桶矿工烈酒出来，有了它，你我就可以开始狂欢了，$N。",objectives={"将一桶矿工烈酒交给塔伦米尔的药剂师林度恩。"}]])
R(518,"意志之冠",[[description="玛格索尔和他的破碎岭食人魔在奥特兰克废墟已经泛滥成灾了。不减少食人魔的数量的话，我们就很难去对付玛格索尔。$b$b等他们的实力被削弱以后，我们就能继续前进了。$b$b懂了吗？好的。去吧。",objectives={"塔伦米尔的梅里萨拉要你去杀掉14个破碎岭虐待者。"}]])
R(519,"意志之冠",[[description="塔尔格、玛克拉克和戈洛姆斯都是玛格索尔的下属。我们不知道食人魔的忠心来源于什么，不过他们对玛格索尔可是死心塌地。$b$b把他们的头给我带回来，$n，接下来就是砍掉玛格索尔的脑袋，彻底瓦解那些食人魔。",objectives={"干掉塔尔格、玛克拉克和戈洛姆斯，把他们的头带给塔伦米尔的梅里萨拉。"}]])
R(520,"意志之冠",[[description="玛格索尔的下属都死了，剩下的就是杀掉玛格索尔，取回意志之冠。他当然不想失去那顶王冠，所以我想你最好……首先将他周围的障碍都干掉。$b$b找到玛格索尔，把他的脑袋和王冠一起带回来。破碎岭的抵抗就到此为止了。",objectives={"杀了玛格索尔，带着他的脑袋和意志之冠去塔伦米尔见梅里萨拉。"}]])
R(521,"意志之冠",[[description="剩下的任务就是把意志之冠交给幽暗城的沙琳德拉。她会派人送去给希尔瓦娜斯大人。我得警告你，别想把它留着自己用，玛格索尔的死就是最好的例子。",objectives={"把意志之冠交给幽暗城的沙琳德拉。"}]])
R(522,"刺客的契约",[[description="这是一份刺杀赫尼·马雷布镇长的契约。合约已经封好，并用一个特殊的徽记之戒在红蜡上做了标记。",objectives={"把刺客的契约带给南海镇的赫尼·马雷布镇长。"}]])
R(523,"男爵之死",[[description="你找到的契约是瓦杜斯男爵签署的，他是以前的奥特兰克王国的贵族，并且一向以冷酷和残暴而著称。这件事的背后由瓦杜斯这样的人主使，我对此一点也不感到奇怪。$B$B去找到他，让他受到正义的制裁。他一定在辛迪加经常出没的地方活动，也许在斯坦恩布莱德的废墟，也许在废墟北面的山谷里。",objectives={"把瓦杜斯男爵的头带给南海镇的赫尼·马雷布镇长。"}]])
R(524,"苦楚药剂",[[description="隔壁的亡灵卫兵看守着几个被俘的人类农夫。高级执行官达萨利亚本来怀疑有一个暴风城来的军事顾问就藏在他们当中，不过我们昨晚发现那个可怜家伙的尸体就躺在瘟疫之地。因此，达萨利亚决定让我来处理这些没什么价值的战俘。$b$b我看是时候给这些农夫开个宴会了。这主意听上去真棒，就这么干！$b$b把这只被污染的酒桶放在他们房间的地毯上，给他们来一点带着瘟疫的酒！",objectives={"把被污染的酒桶放在被俘农夫房间的地毯上。"}]])
R(525,"更大的谜团",[[description="我已经译出了这封信，不过还是不知道它是什么意思。你是在奥特兰克丘陵的潜行者身上找到这封信的吗？真奇怪……$B$B你应该把它拿去给南海镇的镇长看看。虽然这封信的含义不甚明了，但是南海镇离奥特兰克最近，如果有什么威胁正在临近的话，我想应该先告诉他。",objectives={"把被破译的信件交给南海镇的赫尼·马雷布镇长。"}]])
R(526,"光铸铁锭",[[description="你可能已经在那箱子里找到了一块光铸铁锭，但如果要打造些什么东西的话，这么一点铁是绝对不够的！$B$B你得再回去看看，没准在船只残骸附近的鱼人身上会有更多的光铸铁锭。",objectives={"收集5块光铸铁锭，把它们交给湿地的戈罗林·钢眉。"}]])
R(527,"希尔斯布莱德之战",[[description="和我说话的时候要立正，$c。$b$b我受瓦里玛萨斯的直接领导。在我们的药剂师研制出新型瘟疫之前，我们必须要压制住人类的攻势。$b$b有消息表明，希尔斯布莱德镇是个防守很薄弱的小镇。你的第一个任务是扰乱敌人的食品供给和基础设施建设。$b$b从这里往西边方向进发，你的目标是希尔斯布莱德平原最北边的农场，在那里大开杀戒的同时，别忘了把当地的农场主——农夫雷恩和农夫盖兹也给干掉。",objectives={"杀掉6个希尔斯布莱德雇农和6个希尔斯布莱德农夫，还有农夫雷恩和农夫盖兹，然后返回塔伦米尔向达萨利亚报告。"}]])
R(528,"希尔斯布莱德之战",[[description="北方农场被袭击的消息让人类的村民们惊慌失措，你干得很出色。$b$b我们的哨兵报告说有农民向希尔斯布莱德南部逃散——这些傻瓜以为他们可以藏在果园里逃过一死。$b$b去结果他们吧，$N。回到希尔斯布莱德农场去，把这些东躲西藏的农民找出来，以黑暗女王的名义杀了他们。$b$b解散！",objectives={"杀死15个希尔斯布莱德农民，然后回到塔伦米尔向达萨利亚汇报。"}]])
R(529,"希尔斯布莱德之战",[[description="希尔斯布莱德的人类进行了顽强的抵抗，这实在有点出乎我的意料。问题的关键在于，有几个铁匠在为那些镇民提供武器，我们得切断他们的所有供给线。$b$b你的任务是干掉铁匠维林坦，还有他的那些学徒也得杀了。还有，把他们库存的铁也给抢回来。等我们征服了希尔斯布莱德并开始准备进攻南海镇的时候，这些物资就显得非常重要了。",objectives={"杀掉铁匠维林坦和4个希尔斯布莱德见习铁匠，并从那里抢回一箱铁材，然后向塔伦米尔的达萨利亚汇报。"}]])
R(530,"丈夫的复仇",[[description="瓦德雷曾经是我的好朋友，但他也是杀害我妻子的凶手。虽然我已经不知道悲伤为何物了，但我复仇的念头却一直没有改变。去帮我杀了瓦德雷，把他那双邪恶的手带给我，我会奖赏你的。$B$B我最后一次听到他的消息时，他正准备从银松森林南部的格雷迈恩之墙逃往吉尔尼斯王国。",objectives={"杀掉瓦德雷·莫莱。$B$B把他的双手带给幽暗城的拉林夫·安迪恩。"}]])
R(531,"维林的报复",[[description="天哪！别把这种东西带到营地里来……它太肮脏，太可怕…太…太肮脏了！$b$b你把它拿出去行不行？没有人想看到你这件血淋淋的战利品！真的！",objectives={"把奥尔苏迪的头交给旅行者营地的维林·疾风。"}]])
R(532,"希尔斯布莱德之战",[[description="希尔斯布莱德镇现在一片混乱，我们相信它很快就要被攻陷了。但是，我们必须继续坚持对敌人不断地发动攻击，直到把所有的人类渣滓都完全从这里赶出去为止。$b$b虽然人类损失惨重，但他们仍然团结在领袖的周围继续抵抗。我们得除掉他们的首领波恩塞德镇长，当然还有镇议会的成员。最后别忘了毁掉他们的政治文件《希尔斯布莱德宣言》，顺便把镇里的文档也都偷过来。",objectives={"杀掉波恩塞德镇长和4个希尔斯布莱德议员，摧毁《希尔斯布莱德宣言》，偷取希尔斯布莱德城镇文档，然后回到塔伦米尔向达萨利亚汇报。"}]])
R(533,"秘密潜入",[[description="我们终于得到了关于高迪尔的线索。人类不停地到处转移他，但是我们已经缩小了搜索范围，现在我们的注意力主要集中在北边的那个辛迪加营地里。$b$b到那儿去打探一下，然后回来向我报告。",objectives={"把关于高迪尔下落的消息带回来给塔伦米尔的克鲁斯克。"}]])
R(534,"<UNUSED>")
R(535,"仆从瓦里克",[[description="呃……重病、濒死，而且还要与敌人作战。$b$b毫无疑问，你会杀了我，但如果你可以带给我些南海镇烈酒的话，我会告诉你所有你想知道的——我想你们$r平时也喜欢喝点什么吧，不是吗?",objectives={"给辛迪加营地里的瓦里克带去一杯南海镇烈酒。"}]])
R(536,"清理海岸",[[description="我从暴风城守卫被调到这个鸟不生蛋的南海镇来做守卫，这镇子简直是一无是处……整日整夜都是一股鱼腥味。$b$b更别提治安官雷德帕斯了……他还想要我去对付那帮鱼人，哈！$b$b我很难打起精神去跟西部海岸上的那群奇形怪状的鱼人作战。如果你愿意替我去干掉它们，我会很感激你的。",objectives={"南海镇的法尔林·奥里涅尔中尉要你去杀掉10个碎鳍潮行鱼人和10个碎鳍智者。"}]])
R(537,"黑暗议会",[[description="你拿来的信是一个自称为纳伽兹的人写的，他是“阿古斯复苏”的一员。我不知道这个“阿古斯复苏”是个什么样的组织，不过如果他们和辛迪加是一伙的话，就是我们的威胁。$B$B我要你去查查这封信上提到的纳伽兹和暗影大法师。找到他们，把他们干掉。$B$B去高地看看，那里是辛迪加的势力范围，就在斯坦恩布莱德的北面。$B$B如果运气够好的话，你就能在那儿找到这些“阿古斯复苏”的特使。",objectives={"杀死4个暗影大法师。$B$B把纳伽兹的头带给南海镇的马雷布镇长。"}]])
R(538,"南海镇",[[description="$N，如果你不介意多跑点路的话，我有件任务给你，好为我们的暴风城图书馆增加一些书籍。$B$B古代王国奥特兰克在大战之后就已经衰落了，但那里有着大量的藏书。奥特兰克的都城被毁实在是个悲剧，但如果他们的知识也失传了的话，那就将是个更大的悲剧！我们必须竭尽全力地挽救我们能挽救的东西。$B$B南海镇是最接近奥特兰克废墟的地方，到那里去找博学者迪布斯吧，他会告诉你在哪里可以找到书。",objectives={"与南海镇的博学者迪布斯交谈。"}]])
R(539,"希尔斯布莱德之战",[[description="希尔斯布莱德城镇文档里的记录表明，碧玉矿洞已经处于联盟的控制之下——这个矿洞是联盟兵工厂运转所需的铁矿石的主要来源。$b$b虽然我们已经对希尔斯布莱德镇进行了致命的打击，但是联盟还是积极地支持和保护着碧玉矿洞。$b$b这个矿洞就在希尔斯布莱德的正南方。到那里去杀了他们的工头，一个名叫邦德斯的人类，顺便把那里的矿工也干掉。这样的行动可以给联盟传达一个足够清楚的讯息。",objectives={"杀死工头邦德斯和10个希尔斯布莱德矿工，然后回到塔伦米尔向达萨利亚汇报。"}]])
R(540,"保全书籍",[[description="那些野蛮的食人魔现在就驻扎在奥特兰克废墟，一想起他们会把那里的书籍怎么样，我就感到毛骨悚然。你一定要尽力去完成我给你的任务！$B$B进入奥特兰克废墟，找到食人魔夺走的书籍。把你找到的所有东西都带给我，特别是这本书：《格里雷克之臂》。这本书里写着巨魔的古老学说，我一定要学。奥特兰克是完整保存这本书的唯一地方。",objectives={"把5本失而复得的书籍和包含《格里雷克之臂》的破旧的皮书带给南海镇的博学者迪布斯。"}]])
R(541,"希尔斯布莱德之战",[[description="矮人正在协助人类？这帮肮脏的小东西。$b$b我们得看看这所谓的联盟的实力到底如何。等这些矮子知道我们的厉害之后，看他们还愿不愿意继续给人类卖命！$b$b我们知道这些矮人的据点在哪里，他们在希尔斯布莱德东南部沿着索拉丁之墙的地方建立了一个被称作丹加洛克的军营。你的最终目标是攻占丹加洛克，$c。他们的首领达伦·铁山上尉必须得死。",objectives={"到丹加洛克去杀掉8个巡山人、4个火枪手、2个牧师，还有达伦·铁山上尉，然后回到塔伦米尔向达萨利亚汇报。"}]])
R(542,"向米尔顿回复",[[description="我得花点时间来研究你带回来的《格里雷克之臂》，不过我敢说米尔顿已经等不急要把你找回来的另一些书放到暴风城的图书馆里去了。$B$B这些就是你从奥特兰克废墟带回来的书，我已经按照目录分类整理过了。把它们带给暴风城的米尔顿·西弗，他一定会很感激你的。",objectives={"把奥特兰克的书籍带给暴风城的米尔顿·西弗。"}]])
R(543,"匹瑞诺德王冠",[[description="匹瑞诺德王冠据说是奥特兰克王国被毁灭之前的“名门望族”匹瑞诺德家族的传家之宝，有人说它是由铁炉堡的珠宝大师们用最美丽的翡翠制成的。$B$B当奥特兰克家族被毁灭的时候，王冠也随之遗失了。但有传闻说有一个食人魔法师——叫什么守财奴格雷尔伯格的家伙——得到了它，那家伙现在还在奥特兰克遗迹附近游荡，想要找到更多的财宝。$B$B我们希望你能为我们取回王冠。",objectives={"将匹瑞诺德王冠带给暴风城的雷明顿·瑞治维尔。"}]])
R(544,"入室偷窃",[[description="我本来是到塔伦米尔来做研究的，不过现在我手头上有个麻烦一定要尽快解决掉。你知道，几个月前曾有四个被遗忘者从幽暗城逃了出来。他们抛弃了自己的同伴，这没什么，但问题是……他们偷了黑暗女王的东西。$B$B这些小偷闯入了一间秘密的地窖，偷走了四件供药剂师研究用的神器。黑暗女王命令我们把这四件神器找回来。$B$B小偷从幽暗城逃到了达拉然，而那些巫师则把他们收留在洛丹米尔收容所里。",objectives={"找到被遗忘者的叛徒，取回他们偷走的神器，然后回到塔伦米尔去见大法师沃迪恩·伍德格莱尔。"}]])
R(545,"达拉然巡逻队",[[description="达拉然的巫师在他们的城市中心建起一个巨大的魔法护罩。有人认为那是为了防止城市遭到攻击，还有人认为他们只是想有个安静的地方供他们进行魔法研究。$B$B不管那到底是什么原因，我关心的是在那个护罩之外的郊区废墟里是否藏着有用的魔法物品。$B$B不过那里有许多巫师和他们的元素奴仆在到处巡逻。$B$B去杀了他们，杀到你手软之后再回来吧。",objectives={"杀掉6个达拉然召唤师和12个元素奴仆，然后回到塔伦米尔去见大法师沃迪恩·伍德格莱尔。"}]])
R(546,"死亡的纪念品",[[description="听说达萨利亚让你和希尔斯布莱德的人类作战，我很嫉妒你……$b$b你在外面享受屠杀人类、掠夺城镇、恐吓无辜者的快乐，而我却像木头一样待在塔伦米尔做守卫。$b$b你能可怜可怜像我这样的老亡灵卫兵吗？你知道我在收集人类的颅骨，正好你还要和人类战斗一段时间。那么，能不能在你作战的这段时间里顺便给我收集30个颅骨来？我会让你的努力物有所值的。",objectives={"塔伦米尔的亡灵卫兵沙穆萨想要30个希尔斯布莱德人类颅骨。"}]])
R(547,"亨伯特的长剑",[[description="高级执行官达萨利亚派我从远处监视丹加洛克。我在一个隐蔽的角落里扎了营，但是那天早上我在烧水的时候离开了一会儿去找柴火……$b$b等我回来时，发现放在营地里的装备已经不见了。$b$b一定是那些丹加洛克的矮人侦察兵从这儿经过的时候把东西拿走了。我必须得拿回我的剑！如果你能帮我拿回来的话，我会很感激你的。但是那儿的矮人真是太多了……也许你很难在他们当中找出那个小偷。",objectives={"从丹加洛克拿回亡灵卫兵亨伯特的长剑，然后回到塔伦米尔把剑还给他。"}]])
R(548,"<NYI> <TXT> Bloodstone Pendant",[[description="This will start the Bloodstone Pendant quest line...<NYI>"]])
R(549,"通缉：辛迪加成员",[[description="经由黑暗女王希尔瓦娜斯授权，辛迪加组织的全部成员都将被处死！那些已经被羁押和俘虏的辛迪加成员必须立刻处决。残余的辛迪加成员目前在塔伦米尔东南部的敦霍尔德城堡废墟聚集。$b$b任何向高级执行官达萨利亚证明自己完成了这个任务的人都会受到重赏。",objectives={"杀死10个辛迪加盗贼和10个辛迪加哨兵，然后回到塔伦米尔向高级执行官达萨利亚报告。"}]])
R(550,"希尔斯布莱德之战",[[description="由于你在希尔斯布莱德战役中的英勇表现，我已经向上级写了这封褒奖状以表扬你。$b$b把这密封的奖状带给幽暗城的瓦里玛萨斯大人，你可以满怀骄傲地去见他，$c。",objectives={"把达萨利亚的奖状交给幽暗城的瓦里玛萨斯。"}]])
R(551,"附有魔法的羊皮纸",[[description="这张羊皮纸上被施加了某种咒语，使其无法被破译。但是，卷首的一个词却很容易辨认：$B$B$B      纳伽兹$B$B",objectives={"将这张附有魔法的羊皮纸带给南海镇的博学者迪布斯。"}]])
R(552,"赫尔库拉的复仇",[[description="正在赫尔库拉大人即将完成他的巫妖仪式的紧要关头，一群人类暴徒发现了他在山上进行仪式的位置，把他残忍地杀害了。更糟的是，他们把他的遗骨埋在了南海镇的墓地里。$b$b这种不尊重伟大的巫师的行径绝对是无法让人接受的。作为他的学徒，我一定要让复仇降临在南海镇。$b$b首先我们得找到赫尔库拉的魔棒，前不久，一群雪怪侵袭了赫尔库拉的巢穴。毫无疑问是他们当中的一个拿走了赫尔库拉的魔棒。",objectives={"从雪怪手上拿回赫尔库拉的魔棒，把它交给塔伦米尔的学徒塞万德。"}]])
R(553,"赫尔库拉的复仇",[[description="拿着赫尔库拉的魔棒，你会用得着它的。$b$b赫尔库拉用3个火葬柴堆来构筑他最强大的法术：埃希尔之焰和沃拉兹之焰在丘陵地带的洞穴里，尤基尔之焰在丘陵洞穴上面的另一个洞穴，在山的更北边。$b$b赫尔库拉的魔棒必须经过这三堆火焰的洗礼才能发挥作用。在仪式完成之后，把魔棒带到赫尔库拉的墓地去，那座墓地就在由人类重兵把守的南海镇。让赫尔库拉的复仇降临在愚蠢的人类头上吧！",objectives={"将埃希尔之焰、沃拉兹之焰和尤基尔之焰的力量注入赫尔库拉的魔棒。$b$b把经过仪式洗礼之后的魔棒带到南海镇的赫尔库拉墓地。"}]])
R(554,"解码高手",[[description="勘察员塔伯斯·雷矛是解码和译码的高手。把你找到的羊皮纸交给他，运气好的话，他说不定能弄清楚这里面写着什么。塔伯斯·雷矛现在正在铁炉堡的勘矿指挥部进修。$B$B见到他的话，就说你已经跟我谈过了，好像我最近给他添了不少的麻烦……",objectives={"把附有魔法的羊皮纸带给铁炉堡的勘察员塔伯斯·雷矛。"}]])
R(555,"海龟汤",[[description="关于南海镇，你最需要了解的是我们这儿有暴风城以北地区最好的美食！$b$b比如说我的秘密食谱：海龟汤。我听说曾有人远从夜色镇赶来这里，只为品尝一碗海龟汤！不过我最近一直都没做过这种美食。我曾经从达拉然一直走到洛丹米尔湖去捕猎钳嘴龟，不过眼下实在不是外出冒险的时候。如果你从北边那条河里弄点钳嘴龟身上的海龟肉来给我，外加一份舒心草的话，我就能很快做出点海龟汤来让你大饱口福。",objectives={"给南海镇的厨师杰森带去10块海龟肉和一些舒心草。"}]])
R(556,"石雕",[[description="达拉然巫师的一项举世闻名的能力就是他们可以操纵如元素生物这样的从其它空间来的强大生物，他们使用魔法石雕作为控制这些元素生物的工具，现在大法师伍德格莱尔想找些石雕来研究。$B$B进入达拉然巫师的领地，去给我找些用旧的石雕回来。$B$B你可以在任何一个达拉然市民的身上找到这种石雕，不过我建议你还是去收容所一带找找，那里可比达拉然安全多了。",objectives={"收集10个用旧的石雕，把它们带给塔伦米尔的看守者贝尔杜加。"}]])
R(557,"地缚护腕",[[description="大法师会对你带回来的石雕进行研究，不过我知道他会需要一些和石雕配合的东西，也就是地缚护腕。法师们将这些护腕带在元素生物的手腕上，以此来束缚他们。$B$B去干掉几个在达拉然废墟里游荡的元素生物，把它们的地缚护腕拿回来，大法师一定会很满意的。",objectives={"为塔伦米尔的看守者贝瓦里尔收集4个地缚护腕。"}]])
R(558,"吉安娜的签名",[[description="他们说塞拉摩的珍娜?普劳德摩尔是联盟最伟大的英雄之一。当我长大之后，我也要成为联盟的英雄!$B$B你认识珍娜吗，$N?你可不可以帮我个忙，帮我弄到她的签名?我不知道怎么向她开口，也许她很忙而无暇顾及我……但是你可以!你是和她一样伟大的冒险者!我打赌她会给你签名的!$B$B求求你了!",objectives={"到塞拉摩去，为你看护的孩子拿到一份珍娜?普劳德摩尔的亲笔签名。"}]])
R(559,"法尔林的证据",[[description="你相信吗，$n？雷德帕斯对咱们杀了那么多鱼人还是不满意——哦，别谦虚了，你在这方面还挺有本事。现在他又要我证明我真的杀过鱼人，他要我把那些冰凉的、粘糊糊的鱼人的头给砍下来让他过目，这样我才能得到他的肯定。",objectives={"南海镇的法尔林·奥里涅尔中尉要你从西部海岸的鱼人身上收集10颗鱼人的头颅。"}]])
R(560,"法尔林的证据",[[description="你知道，$n，我真的不想碰这些鱼人的脑袋……既然是你解决了它们，那你能不能再帮我把它们送去给雷德帕斯？",objectives={"把一袋鱼人的头颅交给南海镇的治安官雷德帕斯。"}]])
R(561,"法尔林的证据",[[description="请告诉法尔林·奥里涅尔中尉，我觉得他应该把注意力重新集中在滋生于东部海滩的纳迦身上。告诉他，一旦有什么进展，就亲自来向我汇报。",objectives={"和南海镇的法尔林·奥里涅尔中尉谈一谈。"}]])
R(562,"升官之道",[[description="我以前在暴风城的导师发来消息告诉我联盟的高级将领已经开始关注纳迦带来的威胁了。根据他打听来的消息，任何人在这方面有所表现的话，都很有可能得到提拔，或者至少是调动工作岗位。$b$b不过有一个小问题……我对付不了纳迦，$n。哦，当然，我能阻止酒吧里的醉汉互相争吵，也能拖走好斗的乞丐，不过纳迦对我来说就太难对付了。你一定得帮我这个忙，$n。",objectives={"南海镇的法尔林·奥里涅尔中尉要你去杀掉10个刺脊滩行者和10个刺脊海妖。"}]])
R(563,"人事调动",[[description="我的这份报告看来应该是没什么问题了。新的守卫长官萨缪尔森少校曾是我的导师。有了这份报告，他就完全有理由把我调回暴风城了。我需要你帮忙把报告交给他，不过……你可别让雷德帕斯拿到它。",objectives={"把法尔林的报告交给暴风要塞里的萨缪尔森少校。"}]])
R(564,"损失惨重",[[description="没有什么事比失去这些骏马更让我烦心了。相信我，就是那些讨厌的亡灵、可恶的辛迪加恶匪和其他害人的东西在这一带到处游逛，杀了我们不少的马匹。$b$b不过我可以对着我爷爷的墓碑发誓，对这些马匹威胁最大的还是奥特兰克上的山地狮。它们总是从山上跑下来给我捣乱！$b$b你觉得自己是个英雄？那就去做点什么来证明吧！",objectives={"南海镇的达伦·玛尔维要你杀掉8只山地狮和10只巨型山地狮。"}]])
R(565,"巴图罗的雪人毛皮披风",[[description="我，伟大的巴图罗，将为你做一件闻名世界、全联盟皆知的雪人毛皮披风！$b$b不信你就到处跑跑看，能不能再找件更棒的。每个人都会说：“巴图罗，没有比这更好的披风了！”当然，当然没有。$b$b巴图罗需要一个毛布卷，一件由技艺高超的制皮匠缝制的山地披风，一股细线，当然还要有雪人的毛皮！把这些东西带给我，我就让你看看我的本事！",objectives={"给南海镇的巴图罗·吉塞提找一个毛布卷、一件山地披风、一股细线和10块雪人的毛皮。"}]])
R(566,"通缉：瓦杜斯男爵",[[description="高级执行官达萨利亚发出命令，通缉名叫瓦杜斯男爵的人类，此人对被遗忘者犯下了重罪。瓦杜斯是辛迪加组织的高级人物。$b$b最后一次有人见到他是在塔伦米尔北部的奥特兰克山高地上。$b$b杀死他，然后带着他的头去见高级执行官达萨利亚换取报酬。",objectives={"杀了瓦杜斯男爵，把他的头带给塔伦米尔的高级执行官达萨利亚。"}]])
R(567,"危险！",[[description="危险！$b$b以下这个希尔斯布莱德人是危险人物，已被高级执行官达萨利亚悬赏捉拿：$b$b通缉犯书记员赫拉斯·怀特斯蒂德杀害了亡灵卫兵托马。$b$b通缉犯平民维尔克斯杀害了药剂师埃利。$b$b通缉犯矿工哈克特杀害了亡灵卫兵弗雷。$b$b通缉犯农夫卡拉巴伏击运往幽暗城的物资。$b$b这些敌人都躲藏起来了，很难找到，杀掉他们有重赏。",objectives={"塔伦米尔的高级执行官达萨利亚悬赏通缉书记员赫拉斯·怀特斯蒂德、平民维尔克斯、矿工哈克特和农夫卡拉巴。"}]])
R(568,"格罗姆高保卫战",[[description="向你致敬，$c！$b$b你来得真是时候。身为酋长委派到这个丛林基地中的指挥官，我肩负着保卫所有部落成员安全的光荣使命，我们在此的任务是保证对斯通纳德的供应线不被此地的怪物所侵扰。$b$b因此，我将委任你来负责减轻格罗姆高附近的迅猛龙给我们带来的威胁。当你取得了显著的进展后，就向我复命吧。",objectives={"格罗姆高营地的指挥官阿格罗戈什要求你杀死15只鞭尾迅猛龙。"}]])
R(569,"格罗姆高保卫战",[[description="在第一次进入这片丛林中的时候，我们根本就没想和当地的土著部落发生任何冲突。我们任务中最重要的部分就是保持对斯通纳德的供应线的畅通。但目前的情况很复杂，附近的一群食人魔占领了格罗姆高东南方的米扎废墟。他们从来就没把我们的警告放在眼里，频繁地伏击我们的补给车队。$b$b我授命你去解决掉这群冥顽不化的食人魔。$b$b到米扎遗迹去吧，就算不能把他们驱逐出这片地区，至少也得让他们好好尝尝苦头。",objectives={"格罗姆高营地的指挥官阿格罗戈什要求你杀死10个食人魔蛮兵和5个食人魔巫医。"}]])
R(570,"摩克萨尔丁的魔法",[[description="部落必须意识到丛林中蕴含着的无尽的魔法力量，并尽快学会利用它来为自己服务。到目前为止，我的仪式都是很成功的，现在我已经能够施放很强大的魔法了。勇敢的$c，我决定为你制作一件特殊的魔法物品。$b$b给我找一些深喉猎豹的爪子和一颗雌虎的牙齿来，不过你要注意，并不是任何牙都可以用的。你必须找到品质最纯正的牙齿才行。$b$b这种野兽一般都潜藏在丛林中，但你在附近也能找到，只要从米扎废墟那边渡过河流，然后向东南方走就行了。",objectives={"格罗姆高营地的先知摩克萨尔丁要求你给他带回8只深喉猎豹的爪子和一颗雌虎的牙齿。"}]])
R(571,"摩克萨尔丁的魔法",[[description="现在我要你去寻找一件非常难以得到的物品。$b$b为了将这些羽毛、爪子和牙齿中的魔法力量连接在一起，我必须要建立一个魔法阵，而这魔法阵只有用成年猩猩的肌腱才能做成。$b$b具体说来，老迈的薄雾谷猩猩身上的肌腱就很合适。他们一般栖息在藏宝海湾的东面。$b$b你必须找到足够新鲜健康的肌腱才行，这就是说，你有可能要杀死很多大猩猩才能找出一条合我心意的肌腱来。",objectives={"给格罗姆高营地的先知摩克萨尔丁带回1根成年大猩猩的肌腱。"}]])
R(572,"摩克萨尔丁的魔法",[[description="你刚才从那些野兽身上收集到的这些材料只是制造那件强力魔法物品的第一步。在我使用萨满仪式将这些物品合成之后，你就会得到一件极为有用的工具，它可以帮你更好地为酋长和部落效力。$b$b但你先得帮我收集一些丛林捕猎者的羽毛来，据说迅猛龙将这些羽毛当作它们的臂章。在格罗姆高的南边，离大竞技场不远的地方就有一个迅猛龙部族，你可以到那里去看看。",objectives={"给格罗姆高营地的先知摩克萨尔丁带回10根丛林捕猎者的羽毛。"}]])
R(573,"摩克萨尔丁的魔法",[[description="现在我们只差最后一种材料就可以完成这个魔法了。$b$b向南走到一处面对西侧海岸的高崖之上，你会发现一处圣泉。这处圣泉是许多学者争论的焦点，艾泽拉斯上的所有种族都认为这泉中的水乃是神为他们的子民所创造的。$b$b给我带一瓶圣泉的水回来，这是我给你的最后一个任务啦。不过，你得小心点。有一群纳迦卫兵正守在圣泉的附近，你得先对付他们才能取到泉水。",objectives={"格罗姆高营地的先知摩克萨尔丁要你去取回一瓶圣泉之水，同时还要求你杀死10名纳迦探险者。"}]])
R(574,"特种部队",[[description="如今我们已经在很大程度上削弱了他的正规部队，但这就意味着你得直接去面对他手下的精锐部队。如果那些家伙没有被派出去袭击我们落单的士兵的话，他们就应该驻扎在库尔森营地后山上一处名为“储藏室”的洞穴里。$B$B我私下里认识许多库尔森的手下，他们都是身经百战的老兵，对库尔森忠心耿耿，而且最要命的是，他们对敌人毫不手软。这对你来说恐怕不是个简单的任务，$N。多加小心。$B$B你战胜了他们以后，就去向我的长官多伦上尉复命吧。",objectives={"杀掉10名库尔森特种兵和6名库尔森精神医师。$B$B然后向反抗军营地的多伦上尉复命。"}]])
R(575,"供与求",[[description="“前无古人，后无来者，南海一带最好的也是世界最好的皮匠。”他们就是这么叫我的。我！崔斯里克！最好的皮……呃，好吧。$b$b我的皮货以质量优质而远近闻名，都是鉴赏家们的首选之物！$b$b我最近收到了来自工匠行会的雷德沃克斯主管的订单，他需要十二双刨花皮靴。啊，就是那种由我制作的、非常抢手的靴子。$b$b不过要想做那种靴子的话，我需要一些鳄鱼皮才行。在荆棘谷北边的河边有很多鳄鱼，你看能不能……",objectives={"收集2张淡水鳄的皮，把它们交给藏宝海湾的崔斯里克。"}]])
R(576,"海盗的眼睛",[[description="站住！谁在那边？$b$b啊，如果没有那只特制的魔法眼，我就是个废人了。当初在一次战斗中，我失去了我的眼睛！但幸运的是，我们的船停靠在米奈希尔港时，一位旅行法师送给了我一只特制的玻璃眼，这样我才又能看见东西了。$b$b不过昨天晚上我参加了袭击血帆海盗的行动，在跳出船的时候玻璃眼睛不小心给弄丢了。一定是那帮血帆海盗拿走了我的眼睛！看来他们这群混蛋已经找到了到藏宝海湾来的路。$b$b你能不能帮帮我这个老海盗，把我的眼睛给找回来？",objectives={"藏宝海湾的独眼迪兹要求你从血帆海盗那里找回他的眼睛。"}]])
R(577,"收集鳄鱼皮",[[description="嗯，这些靴子已经基本定型，接下来就要开始打磨表面了。但你带来的皮似乎少了点，做不出足够的鞋垫来。$b$b“那现在我们得干什么呢，崔斯里克？”你肯定会马上问这种问题，哈哈，你跟崔斯里克说话可真不幸啊，因为我马上就要给你派活干啦！$b$b没人会去观察鞋垫的，所以我们只要找点又厚又便宜的鳄鱼皮就行了。纳菲瑞提湖旁边的那种钳嘴鳄鱼就不错。",objectives={"给藏宝海湾的崔斯里克带回5张钳嘴鳄鱼的皮。"}]])
R(578,"海潮之石",[[description="如果个岛上确实有水元素和地精法师的鬼魂的话，也就是意味着在那里可以采到海潮之石！$b$b我希望你能找到这座闹鬼的岛屿，去看看上面到底是怎么回事。哦，如果你想知道更多的有关海潮之石的信息的话，可以带着这张凭证去暴风城图书馆，他们会帮你找到我最初读过的那本传说的手抄本。$b$b真的是加兹班首先发现那种石头的吗……?",objectives={"为藏宝海湾的大财主里维加兹找到闹鬼的岛屿。"}]])
R(579,"暴风城图书馆")
R(580,"威士忌斯利姆的酒",[[description="我们那天喝醉了，结果从很远的辛特兰那边掉下了船，活活地漂到了望海崖这里来，险些喂了鱼。$b$b而且我斯利姆从小就没怕过水！我们船长从一艘去暴风城的私掠船上抢来了一箱紫葡萄酒。$b$b我们在辛特兰被风暴袭击的时候，我东倒西歪地撞碎了那个箱子，结果那里面的酒在大风大浪里全都掉进海里了。我要是不把它们给找回来的话，船长见了我非拿我喂猫不可！帮帮我吧！",objectives={"藏宝海湾的威士忌斯利姆想要你帮他找回弄丢的紫葡萄酒。"}]])
R(581,"耶尼库的下落",[[description="厄运！厄运降临在我们酋长的小儿子耶尼库身上……按照部族里的习俗，他被过继给了祖尔格拉布的巨魔，但我们暗矛部族随后便决定跟随兽人酋长萨尔离开家乡，可怜的耶尼库就此与我们失去了联系。我是从奥格瑞玛回到荆棘谷来的，我回来寻找我们酋长的孩子。$B$B我相信是血顶部族抓住了他。$B$B如果你愿意帮助我的话，就去干掉血顶部族的那帮家伙吧，他们就在北边。把他们的獠牙给我带来。",objectives={"给格罗姆高营地的尼姆布亚带回9根血顶巨魔的獠牙。"}]])
R(582,"猎头行动",[[description="我们必须弄清楚耶尼库是否还活着。$B$B杀掉一些血顶部落的猎头者，并把他们身上挂着的皱缩的头颅给我取回来。你必须要收集尽可能多的首级回来，这样我才能检查一下耶尼库的头在不在其中。$B$B如果耶尼库真的被血顶氏族给杀了，他们的酋长，那个名叫甘祖拉恩的家伙，就一定会遭受长达600年的恶毒诅咒！$B$B去吧，$N。沿海岸北上，在祖丹亚废墟和祖昆达废墟那里就有很多血顶猎头者在活动。",objectives={"给格罗姆高营地的尼姆布亚带去20个皱缩的头颅。"}]])
R(583,"欢迎来到丛林",[[description="欢迎来到荆棘谷！$b$b也许你并不关心这个问题，但那边的那位矮人就是联盟的一位伟大的战争英雄，最最勇敢的猎人赫米特·奈辛瓦里。他并不欢迎陌生人来这个营地，不过你看上去已经见过大世面了，$c。$b$b作为一位久经沙场的老将，奈辛瓦里大人总是很关心你们这样的小辈。$b$b去和他谈一谈吧，或许他能教你些狩猎的技巧。",objectives={"与赫米特·奈辛瓦里谈一谈。"}]])
R(584,"血顶之颅",[[description="感谢蛇神，耶尼库的头并不在这些首级当中。但我们仍不清楚他的状况……$B$B我们必须知道真相，不过，恐怕只有血顶氏族的酋长和巫医才知道这些事，而他们又是我们暗矛部族的敌人，所以他们是绝对不会老老实实地告诉我们真相的，恐怕他们只有在死了以后才会愿意和我们谈谈！$B$B把甘祖拉恩和奈兹里奥克的头给我带回来，然后放进这个锅里去。$B$B他们就躲在祖昆达废墟里的深处。只要有他们的头颅……我们就能和他们好好谈谈了。",objectives={"将甘祖拉恩的头颅和奈兹里奥克的头颅带回格罗姆高营地，放入冒泡的大锅中。"}]])
R(585,"奈兹里奥克",[[description="<奈兹里奥克的头说话了>$B$B没错，我知道那个暗矛部落的孩子被带到什么地方去了。虽然你杀害了我，而且把我的灵魂也束缚了起来，但要是你们不给我点好处的话，我还是什么都不会说的！$B$B血顶部族正在与劈颅部族交战，要想让我帮忙，就从劈颅部族那里偷来3颗颅骨来，放在这里陪着我，这样我在扭曲虚空之中也就有三个奴隶啦。这三个头骨必须分别从他们在巴里亚曼废墟、赞塔加废墟和祖玛维废墟的颅骨堆中拿来。",objectives={"带回巴里亚曼战利品、赞塔加战利品和祖玛维战利品各一个，把它们放入格罗姆高营地里中的冒泡的大锅里。"}]])
R(586,"甘祖拉恩",[[description="<甘祖拉恩的头颅开始说话了>$B$B我要诅咒你！诅咒你的八辈子祖宗！$B$B只有鲜血和复仇才能平息我的愤怒，如果这是你的意愿的话，那么……这么办吧：$B$B到东边的劈颅部族的老窝去，尽情地屠杀吧，要是你够强的话……就干掉他们的酋长，残忍的安纳希克。嘿嘿，把他的盔甲碎片拿来给我看，不过我很怀疑你的能力！$B$B他肯定会把你的四肢都撕下来，然后让你烂在地里喂乌鸦，哈哈哈！",objectives={"杀死8名劈颅猎人、6名劈颅猎头者和4名劈颅狂战士。$B$B将安纳希克的盔甲碎片放入格罗姆高营地中的冒泡的大锅里。"}]])
R(587,"鼻烟",[[description="啊，海上的生活。我不想说这种生活有多美好，但这就是我的生活。$b$b当我每次入港的时候，我都会找个地方好好喝上一杯，再找点高品质的鼻烟抽抽。坏习惯吧，但海盗们怎么能没有坏习惯呢，对吧？$b$b所以你可以想象一下，当我发现镇上的药草师卖完了他的全部鼻烟并且已经离开了这座小镇的时候，我会有多沮丧有多伤心了！据说给他运货的那条船让那些该死的血帆海盗给抢劫了。$b$b我相信像你这样勇敢的$c，一定能说服他们交还船上的货物，对吧？",objectives={"藏宝海湾的迪格要求你带给他15份鼻烟。"}]])
R(588,"耶尼库的命运",[[description="<奈兹里奥克开口说话了>$B$B现在，我会告诉你关于你所寻找的那个耶尼库的事情……$B$B年轻的耶尼库和他的氏族失散了。$B$B他被巫医赞吉尔给带走了。现在赞吉尔控制了他的身心，只有一种极端强大的法术才能使他恢复自由之身。$B$B而你肯定没有这种法术，$c。$B$B或许你暗矛部落的朋友们有办法拯救耶尼库，不过我对此也相当怀疑。",objectives={"与肯维雷谈一谈。"}]])
R(589,"歌唱水晶",[[description="传说荆棘谷的中心地带深藏着一块宝石，这块宝石的名字叫心灵之眼，其中蕴涵着巨大的力量。如果你得到了这块宝石，也许我们就能用它将失落于黑暗之中的耶尼库拯救出来。$B$B我会与丛林之灵们商谈，向他们询问心灵之眼的位置。与此同时，你要去一趟东南方的水晶矿洞，从那里的铁腭蜥蜴身上收集一些蓝色波光碎片。这些水晶非常稀有，但我们需要利用其中的魔法能量来控制心灵之眼。",objectives={"给格罗姆高营地的肯维雷带回3块蓝色波光碎片。"}]])
R(590,"潜行者的交易",[[description="什么？$B$B什么？！$B$B你要钱？我可不欠你什么钱。$B$B信？什么信？哦，你是不是想打架？好吧，朋友……放马过来啊！",objectives={"打败丧钟镇的卡尔文·蒙泰古。"}]])
R(591,"心灵之眼",[[description="心灵之眼目前落在了一个食人魔法师的手里，他就住在东边的莫什奥格食人魔山的深处，他的名字是麦佐斯。我自暗矛部落还在荆棘谷定居的时候就知道他了，他是一个邪恶的家伙，而且法力非常强大。$B$B如果确实是他拿着心灵之眼的话，他的魔法就会具有极大的威力。$B$B你必须从这个麦佐斯的手中抢到心灵之眼。这确实是件危险的工作，但这也是我们拯救耶尼库的唯一希望了。",objectives={"将心灵之眼交给格罗姆高营地里的肯维雷。"}]])
R(592,"拯救耶尼库",[[description="我已经将心灵之眼重塑为一颗灵魂宝石。你必须先用它震慑住耶尼库，成功之后，就立刻把宝石放在他的额头上，这样才能抽取出他的灵魂。$B$B接下来把宝石交给尼姆布亚就可以了。$B$B耶尼库和流亡者赞吉尔一起住在阿博拉兹废墟，只要沿着水晶海岸走到荆棘谷的海角那边就能找到了。",objectives={"将装满的灵魂宝石交给尼姆布亚。"}]])
R(593,"灵魂宝石")
R(594,"瓶中信",[[description="这张便笺上有极漂亮的字迹：$B$B致任何能帮助我的人$B$B拜托，我迫切地需要帮助。一只巨大的蓝鬃猩猩将我囚禁在了南海的一座岛屿上。$B$B这里夜晚的星象我以前从未见过，岛上全是茂密的丛林，但在天气晴朗的时候，我能看见西北方的蛮荒的海岸，还有几条大船在向西南航行。$B$B求求你，请帮帮我吧。",objectives={"找到瓶中信的作者。"}]])
R(595,"血帆海盗",[[description="你看起来特别像要找份活干似的，伙计。虽然我不清楚为什么一个喜欢在平地上过日子的$r$c会愿意帮助我们这些黑水强盗，但我不会阻拦你的。$b$b我们的船就停泊在藏宝海湾，而我们的死对头——那些该死的肮脏的血帆海盗——正在整个荆棘谷南部胡作非为。$b$b现在我们这里的人不是抱着酒瓶子就是抱着姑娘！我需要一个探子来帮我做事。$b$b去侦察一下野人海岸上有些什么，没错，就是藏宝海湾北边的那片沙滩。",objectives={"大副克拉兹要求你去侦察一下藏宝海湾北边的海滩。"}]])
R(596,"染血的白骨项链",[[description="我是被派来格罗姆高帮助尼姆布亚完成他的任务的，但……我发现这里还有些更有意义的事要做。$B$B血顶部族是我们的敌人。将敌人的战利品抢过来将极大地鼓舞我们的士气，同时也能给对方以沉重的打击。也许你可以帮我们部族猎杀血顶部族的成员……$B$B他们就居住在北边，干掉那些血顶巨魔，把染上它们鲜血的白骨项链给我拿回来。你拿回来越多项链，我们就会越尊敬你。",objectives={"给格罗姆高营地的肯维雷带回25串染血的白骨项链。"}]])
R(597,"血帆海盗",[[description="这是一张藏宝海湾的地图，上面用红笔标叉的地方就是你现在站的位置。$b$b图上潦草的写着几行字：$b$b“你们的任务就是悄悄地在此地扎营，等待南方指挥部发出信号后再开始攻击。如果任何人试图阻碍你们，格杀勿论。”",objectives={"将你的发现报告给藏宝海湾的大副克拉兹。"}]])
R(598,"裂骨项链",[[description="你已经收集了足够多的血顶氏族的战利品，现在我要交给你一项新的任务。劈颅部族居住在东南方，以前我们一直和他们互无往来。虽然暗矛部落已经不住在荆棘谷了，但现在我们却卷入了与他们的冲突之中。$B$B所以，我要你去猎杀他们，把他们的裂骨项链带回来给我。如果你在我们这场战争中帮助了我们暗矛部族，就一定会赢得我们的友谊。",objectives={"给格罗姆高营地的肯维雷带回25串裂骨项链。"}]])
R(599,"血帆海盗",[[description="太令我吃惊了！那么血帆海盗正计划着进攻藏宝海湾吗？这群发了神经病的恶棍当真是不要命了么，藏宝海湾永远都是我们黑水海盗的地盘！$b$b这事比我想得还要严重。马上将你所知道的一切报告给舰队指挥官卡拉·海角！这群该死的海狗可能已经开始在镇子外面集结了……",objectives={"把血帆海盗的计划报告给舰队指挥官卡拉·海角。"}]])
R(600,"风险投资公司",[[description="最近，风险投资公司在荆棘谷一带展开了一系列的行动，这让我们这些诚实努力的地精们，你看，比如我，根本没办法在这里讨生活了！拜托，你一定要帮帮我！$B$B风险投资公司打算在北边的水晶矿洞那里采矿，可是由于那边的石化蜥蜴到处肆虐，他们根本没办法进入矿洞，只能在周围的山上开采歌唱水晶。$B$B去把他们的水晶都抢来，让他们知道他们不该在这片丛林里如此嚣张。$B$B还有……嗯嗯……把那些水晶给我带回来当证据！",objectives={"给藏宝海湾的克兰克·菲兹巴布带回10块蓝色歌唱水晶。"}]])
R(601,"水元素",[[description="这些水元素无疑是传说中发现了海潮之石的地精法师加兹班召唤的。也许你知道，海潮之石会诅咒任何挪动它的人，就是说，会让那个倒霉的家伙从这个世界上彻底消失。$b$b应该有什么办法可以破除这个该死的诅咒，我们可以请一位达拉然的法师来帮我们分析一下水元素胳膊上戴着的护腕里的魔法。你能不能回到那岛上帮我收集一些进行魔力分析所需的样本？",objectives={"为藏宝海湾的大财主里维加兹收集6个水元素护腕。"}]])
R(602,"魔法分析",[[description="虽然我听说达拉然的法师们正忙着重建他们那被毁的城市，但我敢说，你肯定能找到一个愿意帮我们检查护腕的法师。根据我对那些法师的了解，他们是绝对不会拒绝任何与魔法有关的谜题的。$b$b将这包水元素的护腕拿给他们，让他们看看能不能找到解除石头上的诅咒的方法。",objectives={"将水元素护腕交给达拉然的大法师安斯雷姆·鲁因维沃尔。"}]])
R(603,"安斯雷姆的钥匙",[[description="嗯，拥有那块石头的法师一定通过在某处集中力量来加强他的魔法效力……比如在某个祭坛上。按理说你应该可以用更强大的力量去瓦解它。$b$b就目前的情况而言，我知道有件物品可以派上用场：巨魔一族失落的另一件神器，一把远古匕首。但是，还有一个……只有一个……小问题。$b$b你知道，我过去在荆棘谷进行研究的时候得到了那把匕首，但我把匕首给了我那任性的女儿，她叫凯特琳。她现在已经去了藏宝海湾，也许是真的想当个海盗吧。",objectives={"与藏宝海湾的凯特琳谈一谈。"}]])
R(604,"血帆海盗",[[description="克拉兹高度赞扬了你为黑水海盗做出的重要贡献。我信任你，因此我要赋予你一个对于舰队来说至关重要的任务。$b$b我们要求你渗透进血帆海盗建立在蛮荒海岸的南方指挥部。偷袭他们的营地，将他们的海图与计划书都给我带回来，我们必须要搞清楚这群渣滓到底想干点什么。",objectives={"藏宝海岸的舰队指挥官卡拉·海角要求你杀死10名血帆流氓并将血帆海图和血帆计划书带回去。"}]])
R(605,"歌唱水晶碎片",[[description="歌唱水晶是荆棘谷的一种特产，它对某些人来说有着非常重要的价值。我本想运一些歌唱水晶到别的地方去卖，可那该死的风险投资公司想要独占它，所以，像我这样诚实的商人看来就无法亲自去收集水晶了！$B$B我决定雇佣你。$B$B荆棘谷中的蜥蜴都有吞食这种水晶的习性，这可以使它们的皮肤变得更硬。因此，我们可以从它们身上收获到一些高品质的水晶。$B$B随便哪只蜥蜴身上都会有水晶，但最容易对付的是在北边的海岸附近活动的那些蜥蜴。",objectives={"为克兰克·菲兹巴布收集10块歌唱水晶碎片。"}]])
R(606,"吓唬病鬼",[[description="你知道这里最让我受不了的是什么吗？这儿的人都有死也不还赌债的毛病！现在已经有一大群家伙欠着我的钱了。你能帮我催一下债吗？$B$B第一个要催的就是住在港口那边的“病鬼”菲利普。他上个礼拜欠得实在是太多了，我一定要把这笔钱给要回来！但是要想拿到它，我们就得好好吓唬吓唬他。$B$B到镇子外边去猎杀一些老迈的迷雾谷猩猩，然后从它们身上搞点内脏杂碎什么的，把这些玩意丢给那病鬼。最好别让他想到那是动物内脏，让他想点更糟的。",objectives={"给藏宝海湾的“病鬼”菲利普带回5块迷雾谷猩猩的内脏。"}]])
R(607,"向马克基雷回报",[[description="给，把这个布袋给海狼。告诉他，我是想还他钱的！我发誓！！$B$B我只是喝多了点，迷路了而已，还有……总之是一团糟了。他会理解我的——你可别乱说啊！",objectives={"将菲利浦的还款交给“海狼”马克基雷。"}]])
R(608,"血帆海盗",[[description="打击一下菲尔拉伦的脆弱神经吧！他连划着小船穿越水晶湖都做不到，更别说独自率领整支舰队来和我们对抗了。$b$b血帆海盗一定会为他们的粗心大意而付出代价的。现在我们已经掌握了他们的攻击计划，完全可以在他们什么还都不知道的时候抢先下手。$b$b我们并不需要派出全部的舰队，只要一支勇敢的冒险者队伍就能轻易完成这任务。$n，带上你最优秀的同伴守在菲尔拉伦的登陆点，杀掉血帆的指挥官。这样他们的舰队不用多久就可以去喂鱼了……",objectives={"藏宝海湾的舰队指挥官卡拉·海角要求你杀死血帆海盗的斯蒂沃特船长，尼哈鲁船长和舰队指挥官菲尔拉伦。"}]])
R(609,"讨债行动",[[description="我这儿的白条已经少了许多啦，但还是有许多没信誉的家伙欠着我的钱。$B$B接下来，我们得对付“畸形足”玛雷·维尔金斯、火柴棍乔乔，还有拇指苏克。$B$B这帮家伙的债欠了好久，我看他们是不想还了！后来，我听说他们被什么人给骗到丛林里去了。我当然不关心他们到底会怎么样——我要的是我的钱！$B$B他们应该就在东北方的阿博拉兹废墟和朱布瓦尔废墟里。找到他们，把我的钱拿回来。",objectives={"给藏宝海湾的“海狼”马克基雷带回玛雷的畸形足、乔乔的金色望远镜和苏克的巨型戒指。"}]])
R(610,"帅小伙子邓肯",[[description="我老爸派你来的？我还以为那怪老头已经早就放弃掉我了呢。$b$b我之所以离家出走确实不是他的错，他只是不应该为我安排好一条乏味的人生道路，并希望我欣然接受它。我怎么能忍受整天读着那些发霉的书本，整天和那帮灰头发加驼背的乏味老头法师们在一起！$b$b如果你需要我的匕首，你可能得从一个叫“帅小伙子”邓肯的血帆海盗那里夺回来。我想你只要教训教训他，他就会屈服的。",objectives={"从“帅小伙子”邓肯那里夺回凯特琳的匕首。"}]])
R(611,"海潮的诅咒",[[description="这么说你正在寻找某个祭坛喽？好吧，虽然我不像我老爸那样是个研究巨魔遗迹的专家，但我对你正在寻找的岛屿也略知一二，在岛的附近有一座沉没在水底的巨魔城市，我想你应该到那里去碰碰运气。$b$b既然是你帮我找回了我的匕首，借去用用当然没有任何问题……但我希望你用完以后能还给我！",objectives={"用凯特琳的匕首摧毁海潮祭坛，然后杀死加兹班，将海潮之石带给大财主里维加兹。"}]])
R(613,"玛雷的腿",[[description="该死！那见鬼的玛雷居然在他的假腿上安了一个锁，我还死活都打不开！他的宝贝，还有他欠我的钱，都藏在那条假腿里！$B$B我们得想办法找到钥匙才行。玛雷这家伙过去因为喜欢和住在东北边食人魔山上的莫什奥格食人魔赌博而出名，而且他告诉过我——我是说当他还活着的时候——他每次赢了一票大的之后都会去一趟那里，所以，或许那边的食人魔会有他的钥匙。$B$B要真是如此的话，你八成得大开杀戒才能搞到钥匙……",objectives={"把玛雷的钥匙带给藏宝海湾的“海狼”马克基雷。"}]])
R(614,"船长的箱子",[[description="我过去在一条专跑从这里到卡利姆多的棘齿城的航线上干过。我是个很优秀也很有名望的船长。$B$B直到……$B$B那些该死的海巨人毁了我的生活！他们打沉了我的船，杀光了我的水手，把我丢在一条救生艇上，让我漂回了藏宝海湾。还有，其中一个名叫高拉什的巨人还把我的箱子给偷走了，他说要拿这东西当鼻烟盒，简直是神经病！$B$B我听说有人看见高拉什最近在东边的海岸一带闲逛。找到他，把我的箱子给抢回来！快去，你会得到一位船长的敬意的。",objectives={"将斯莫特的箱子交给藏宝海湾的海克拜瑞·斯莫特。"}]])
R(615,"船长的弯刀",[[description="我的第一条船被那些海巨人们搞沉了之后，我只好买了第二艘，而且给它起名为“斯莫特的复仇”。我为它配备了新的装备和船员，并出发去寻找那些该死的巨人。我找到了他们，但……他们又一次击败了我们。他们把“斯莫特的复仇”号给打成了碎片，船员也几乎被他们杀光了，但那帮混蛋却把我丢在了一条救生艇上，让我一个人漂了回来。$B$B这次，那些海巨人中的另外一个偷了我的弯刀。$B$B到奈古拉什那里去把我的佩刀给抢回来！$B$B去和斯普罗格谈谈吧。他本来是“斯莫特的复仇”号上的厨子，沉船的时候他也幸存了下来，我想他能帮你们找到那些巨人。",objectives={"与斯普罗格谈一谈。"}]])
R(616,"幽灵岛",[[description="大财主里维加兹让我留意最近在藏宝海湾和荆棘谷附近流传的古怪传闻。虽然我平时是绝不会关心什么鬼故事的，但这两天在酒馆里听一些水手们说在海岸附近有一座闹鬼的小岛。据他们说，那上面全是水元素和一只整日说着疯话的地精的鬼魂。$b$b如果你正好要去见里维加兹阁下的话，能替我将这件事转告给他吗？",objectives={"与藏宝海湾的大财主里维加兹谈一谈。"}]])
R(617,"一捆海蛇草",[[description="听说你正在找活做，$N？要是你够胆的话，我这儿倒是有件不错的活正要找人呢。$B$B你听说过最近有许多人都在找一处泉水么？是的，有一群纳迦也在找。我有个叫格罗伊的朋友吧，他最近出了一大笔钱，想买一些纳迦称之为海蛇草的东西。我也不清楚那到底是什么，只知道是一种很值钱的海草。他也没说要那玩意干什么，不过他确实出了一个好价钱，大概需要一捆吧。$B$B你帮我搞来10根这种什么草，那我们就可以跟他做笔交易啦。不久前有人看见这里北边的海滩上出现了不少纳迦。",objectives={"给藏宝海湾的海盗布劳兹带回10根海蛇草。"}]])
R(618,"挑战奈古拉什",[[description="奈古拉什总是一副随时准备把一切都吞下去充饥的样子。$B$B那些巨人袭击我们的船的时候，奈古拉什直接冲向了我的厨房，不过他可不像其他巨人那样喜欢吃人。奈古拉什要的是酒……还有我秘制的烧烤秃鹰翅膀。嘿，这可都是我的拿手菜，我当年可是跑到荒芜之地才弄到这食谱的！$B$B如果你想把奈古拉什给引出来，只要用点酒再加上一碟烤翅就行啦。把这些东西放进我们当初丢在东南边海岸上的救生艇里，然后你就等着奈古拉什闻到食物的味儿乖乖上钩吧！",objectives={"将10块烧烤秃鹰翅膀和5瓶密林葡萄酒带到斯莫特船长的救生艇上去。$B$B然后杀死奈古拉什，将斯莫特的弯刀交给荆棘谷的斯莫特船长。"}]])
R(619,"引诱奈古拉什")
R(620,"The Monogrammed Sash",[[description="This fine sash has the letters \"HS\" embroidered along its hem.",objectives={"Return the Monogrammed Sash to its owner."}]])
R(621,"赞吉尔的秘密",[[description="流亡者赞吉尔和他的追随者们住在藏宝海湾东北方的朱布瓦尔废墟和阿博拉兹废墟里，这个家伙已经被他的部族放逐了。为什么？这个……$B$B据说是因为赞吉尔掌握了某种可以将自己的心灵与他人连接在一起的方法，而他所属部族的领袖就因此非常害怕他。他让他的追随者们喝下了一种从植物中萃取出来的液体，用它来压抑他们的自我意识并加强他们的力量。$B$B他的这种药剂对那些试图控制别人的家伙来说有非常大的价值。$B$B给我弄些这种药剂的样本来，我要研究一下……",objectives={"收集12份赞吉尔的药剂，把它们交给藏宝海湾的克兰克·菲兹巴布。"}]])
R(622,"向卡雷布下士回报",[[description="在你离开的这段时间里我已经把这锅替你修好啦。我甚至还免费加装了一个特制的蒸汽哨，看，华丽吧！这下面还装了一个新的自动菜刀，专门用来切蹄膀的！$B$B没错，克拉兹克的烹调锅将为你带来百分之百的烹调乐趣，我敢打赌它的主人会非常满意的！",objectives={"将修理过的烹调锅交给叛军营地的卡雷布下士。"}]])
R(623,"一捆海蛇草",[[description="$N，你不在的时候，格罗伊托人给我捎了一个信儿过来。他说他很满意我们上次送去的货，现在又有一位新的顾客也想要一些那种海草。$B$B我可不想花上整整一个礼拜去一趟塞拉摩，如果你愿意替我去一趟的话，那就再好不过了。$B$B很有挑战性吧？你知道那边的尘泥沼泽吧？你可得小心点，塞拉摩可不是个普通人能去的地方。",objectives={"给塞拉摩的水手格罗伊带去一束海蛇草。"}]])
R(624,"科泰罗的谜题",[[description="有一座装饰华丽，人来人往的桥$b逆风径东，赤脊山南面之地$b在那之下，它正等待着你$b这可以叫提示，也可以叫线索$b在那里，无尽的明天正等待着你$b在悲伤沼泽之中静静地等待着你",objectives={"解开这道迷题！"}]])
R(625,"科泰罗的谜题",[[description="卡利姆多上的某个遥远之地$b危险湮灭了命运与希冀$b贫瘠之地以东的环境糟糕至极$b绝望与威胁伴着沼泽中的尘泥$b但那里埋藏着线索供你寻觅$b在西南的一处洞穴中可解此谜题",objectives={"解开这道迷题！"}]])
R(626,"科泰罗的谜题",[[description="到洛丹伦去！那片混乱中的土地$b在那里，勇敢的战士们与亡灵为敌$b在剧烈的动荡中寻找属于你的路途$b最终你会解开这谜题$b沿着艾瑞匹克山峦，位于瀑布之底$b波光之下的宝藏正等待着你",objectives={"解开这道迷题！"}]])
R(627,"克拉兹克的要求",[[description="在阿拉希高地北部的枯须峡谷中有一处山洞，那里有一种十分稀有的矿石：血石。那个山洞里的血石虽然不是品质最佳的，但即使是低等级的血石也是很有价值的……当然这只是对那些懂得如何使用它们的人来说。$B$B我需要一些这种血石。$B$B我会在这里修补你的锅子，不过，当我修锅的时候……你去给我弄些血石来吧。对，多带点回来，我当然会给你报酬的。$B$B嗯嗯，要是你连这点事都搞不定，就去找个能搞定的人帮你！",objectives={"给藏宝海岸的克拉兹克带去4块次级血石矿。"}]])
R(628,"刨花皮靴",[[description="既然里面的东西都已经做完了，那么就只剩下外面的表层部分了。表层一定要用质量最好的老鳄鱼的皮。这种皮甚至比帆布还要结实，用它就可以完成我的完美设计。$b$b虽然要找到完美的皮很难，但这种老海鳄的皮是唯一能配得上我的设计的材料了。老海鳄只会在其它鳄鱼被攻击的时候才会出来保护族群，所以恐怕你得先杀些普通鳄鱼引它们出来。",objectives={"给藏宝海湾的崔斯里克带回1张老鳄鱼的皮。"}]])
R(629,"暗礁海",[[description="很久以前，有一座古老的巨魔城市因为大地震沉入了西北方的野人海岸水下。现在那里被一群鱼人所占据着，任何接近的人都会遭到他们的攻击，我们把那处地方叫作暗礁海。$B$B在那片废墟之中有一块古老的石板，上面记录着一位名叫格里雷克的巨魔英雄的传说。那块石板对于我们暗矛部落来说具有神圣的意义，尽管它太大，没办法全部运走，但我仍希望有人能从上面敲下一块碎片，让我们带到奥格瑞玛的新家去供奉起来。",objectives={"给格罗姆高营地里的肯维雷带回一块石板碎片。"}]])
R(630,"瓶中信",[[description="$N，我的一切都全靠你了！是蓝鬃猩猩之王穆克拉把我抓进来的，它统治着这岛上所有的野兽，它们不顾我的反抗，用这些铁链把我给锁在这儿。如果你能杀了它，从它身上找到能够打开这套镣铐的钥匙的话，我会好好报答你的。$B$B它通常在这座岛的北边活动，但你一定得小心，它绝对是一个很难对付的家伙。",objectives={"杀死穆克拉并带着钥匙回去救出普巴尔公主。"}]])
R(631,"萨多尔大桥",[[description="当时，山里突然传出了一阵巨大的爆炸声，而且在山谷中回荡了很久。那简直太可怕啦！$b$b士兵们为了守卫萨多尔大桥死伤惨重。长须说我们总有一天要向黑铁矮人们复仇的。$b$b我们目前的情况非常窘迫，而且暂时也得不到任何援军。长须派了老伊本瑟去侦查东边的那座桥，看看我们是否有机会攻陷那里。$b$b可这已经是好几天以前的事了。丹莫德目前全城被围，我们根本无法抽出人力去联络他。$b$b或许你能帮忙去找他……",objectives={"拉格·加玛森要求你找到老伊本瑟。"}]])
R(632,"萨多尔大桥",[[description="很显然，可怜的老伊本瑟遭遇到了黑铁矮人的伏击，已经战死了。但你突然注意到了他紧握着的拳头中似乎有一张皱皱的羊皮纸。$b$b将这条令人沮丧的消息告诉拉格·加玛森，并把你的发现报告给他。",objectives={"向拉格·加玛森回报，并将你在伊本瑟尸体上找到的羊皮纸交给他看看。"}]])
R(633,"萨多尔大桥",[[description="天呀！不！可怜的伊本瑟，这实在是一个悲剧。$b$b我们绝对不能让他就这样白白牺牲了。你发现的这张羊皮纸上写道，是卡姆·深怒在背后组织了这次进攻，并且，他还在萨多尔峡谷的阿拉希高地那一侧囤积了不少炸药。$b$b如果他们用这些炸药摧毁了桥梁的话，那么我们的通向北边的主要补给线就会被彻底切断！必须摧毁这些炸药，$n！完成了这个任务后立刻回来向我复命。$b$b你是我们最后的希望了。",objectives={"摧毁堆积的炸药。"}]])
R(634,"请求援助",[[description="我想拜托你再帮我一个小忙，$c。我们正等待着来自铁炉堡的援军。但是，罗戈说阿拉希高地上的避难谷地那里还有一处联盟的营地。$b$b到那里去找尼艾丝队长吧。问问这位善良的队长，看联盟是否能派一些暂时没有任务在身的士兵来帮我们夺回丹莫德和萨多尔峡谷。",objectives={"去避难谷地找到尼艾丝队长。"}]])
R(635,"山中的水晶",[[description="你拿着这块碎片，明显地感觉到它在跳动着……$B$B你感到它在祈求，好像有什么人想要与你交流，急切地需要你的帮助。$B$B你的脑中出现一幕奇特的影像——在阿拉希的北部山脉上，有一块明亮的水晶从地面上突出来。$B$B你感觉到自己仿佛被带到了那个地方……",objectives={"找到你在幻觉中看到的那块水晶。"}]])
R(636,"大地公主的传说",[[description="这本书叙述了元素公主密斯莱尔和她被囚禁在阿拉希高地下面的故事。$B$B它还叙述了高地里的一处秘密的水晶岩层。这些被称为“密斯莱尔水晶碎片”的东西是囚禁大地公主的监狱的窗户。$B$B如果某个勇敢的人能找到密斯莱尔水晶碎片，那么$g他:她;就有可能和她交谈……",objectives={"找到密斯莱尔水晶碎块。"}]])
R(637,"苏利·巴鲁的信",[[description="你手中的这封信湿淋淋的，已经面目全非了，只有几页像是得到了精心保护的信纸上的字迹还能辨认。$b$b这封信是写给铁炉堡的萨拉·巴鲁女士的，开头写着，“亲爱的萨拉……”",objectives={"把苏利·巴鲁的信交给铁炉堡的萨拉·巴鲁。"}]])
R(638,"巨魔之敌",[[description="随着索拉斯·托尔贝恩的死与激流堡的毁灭，沃金大人指示我们要不惜一切代价将那把传说中的宝剑托卡拉尔从人类的手里抢过来，供我们在与祖尔格拉布的巨魔的战斗中使用。$b$b我们已经派出了一个名叫森谷的资深猎人前往阿拉希高地东北部的落锤镇去寻找它。",objectives={"前往阿拉希高地的落锤镇，与森谷谈一谈。"}]])
R(639,"激流堡符印",[[description="在古代，巨魔曾与阿拉索帝国以及我们最强大的对手——被称为“激流堡的伊格纳乌斯”的托尔贝恩作战。托尔贝恩总是挥舞着托卡拉尔剑进行作战。在古代语中，托卡拉尔是“巨魔杀手”的意思。$b$b然而，现在托尔贝恩子孙的势力已大不如前了，他们的要塞也已经变成了废墟。$b$b托卡拉尔剑是由几块符印保护的，这些符印现在都在激流堡的幸存者手中，我们必须获得它们。$b$b辛迪加组织拥有第一块——这一块应该就在他们驻扎于激流堡的那群人中的某个人手里。",objectives={"帮落锤村的森古拿回激流堡符印。"}]])
R(640,"破碎的符印",[[description="索拉斯·托尔贝恩的墓室由三块符印护卫，这其中的第一块你已经从辛迪加手中得到了。另外两块更难得到，因为它们被牢牢地控制在激流堡的民兵手里。$b$b索拉丁符印被索拉斯的儿子加林分成了十一块，分别由一个激流堡守卫者掌握。取回这些符印，把它们交给巨魔祭司托尔甘，他能够将它们合成一块完整的符印。",objectives={"从激流堡的守卫者那里取回5块符印碎片，把它们交给落锤村的托尔甘。"}]])
R(641,"索拉丁符印",[[description="复原得完美无缺。现在，这块完整的符印可以被用于打开托尔贝恩墓穴上的封印了。把它交给森古吧，他一定还有别的任务要你完成。",objectives={"把修复的索拉丁符印交给落锤村的森古。"}]])
R(642,"被困的公主",[[description="我叫密斯莱尔，我是大地的公主。巨人们俘获了我，把我拘禁在阿拉希高地的地下深处。这些水晶碎块是我和外界交流的唯一途径。$B$B帮帮我。这些巨人的盟友——枯须狗头人——就在东边的枯须峡谷里活动，那里有一块类似水晶碎块。要激活那块水晶，你必须从狗头人那里收集到密斯莱尔之尘，然后把它们放在水晶上。$B$B求求你了，$N，帮帮我吧！",objectives={"收集密斯莱尔之尘。$B$B把它们放在枯须峡谷中的虹光水晶碎块上。"}]])
R(643,"阿拉索符印",[[description="尽管他们还没有控制激流堡，更不要说整个阿拉希高地，但那人类王子却率领着剩余的骑士在乡间疾驰。我不能理解他为什么这么做，谁又能理解人类的思维方式呢？$b$b且不管他到底是怎么想的，最重要的是他把一块符印交给了瓦罗卡尔中尉，也就是那群骑士的首领。找到这个人，把他的符印带回来交给我。",objectives={"取回阿拉索符印，把它交给落锤村的森古。"}]])
R(644,"托尔贝恩符印",[[description="打开索拉斯·托尔贝恩墓室所需的最后一块符印掌握在他儿子手中。他深居在激流堡的一座由民兵控制的教堂里。加林王子的保卫措施非常严密，他本人也是一名强大的勇士，所以这次你的任务会是非常艰巨的。",objectives={"杀掉加林·托尔贝恩王子，把托尔贝恩符印带给落锤村的森古。"}]])
R(645,"托卡拉尔",[[description="将四块符印放在一起，它们就能互相结合形成一块完整的符印。毫无疑问，这块符印能够击破托尔贝恩地墓室里的防护魔法。$b$b托尔贝恩的遗体就埋葬在激流堡教堂后的密室中。去取回托卡拉尔。",objectives={"从激流堡的托尔贝恩墓室中取回托卡拉尔剑。"}]])
R(646,"托卡拉尔",[[description="光芒慢慢地褪去，石鞘中的托卡拉尔剑已经松动了。",objectives={"把托卡拉尔剑交给落锤村的森古。"}]])
R(647,"马克里尔的月光酒",[[description="昨晚我喝了很多月光酒！要是布莱德知道我在当差的时候溜出去准会要了我的命。$b$b我喝得有些太多了，就感觉到头顶上有一整支蒸汽坦克部队呼啸而过，满耳都是隆隆的响声。$b$b哦，瞧这时间！我答应南海镇的布鲁米·比格尔要送他一些月光酒来抵债的。$b$b但是离我交货的最后期限只有15分钟了！请你把这些带给他，好么？要快！",objectives={"把马克里尔的月光酒交给南海镇的布鲁米·比格尔。"}]])
R(648,"拯救OOX-17/TN！",[[description="那个侏儒的声音再次从那个机器人中传了出来：$B$B“我需要你帮忙把OOX-17/TN移动到一个安全的开阔地，这样它才可以启动起飞程序。它自带隐形系统，但是我需要一点时间来远程启动这个系统。请你把这个机器人从现在的位置护送到热砂港去！那里是个非常理想的起飞点，有足够的空间作为机器人起飞的跑道！”$B$B“将它护送到那里，然后再到藏宝海湾来找我！奥格索普·奥布诺提斯——完毕！”",objectives={"将OOX-17/TN护送到热砂港，然后向藏宝海湾的奥格索普·奥布诺提斯报告。"}]])
R(649,"寻找蜜酒",[[description="我这有些事情要你来做，如果你和我一样是蜜酒的爱好者，那我敢说你一定会接受这项任务！$B$B蜜酒当然是一种酒，你这个蠢货！$B$B在一座被部落废弃的村庄那里有很多的辛特兰蜜酒，这些蜜酒是以前那里还有人做生意的时候留下的，那绝对是极品的蜜酒！玛尔顿的手下知道这个村庄的具体位置，我要你去那里一趟，给我带一些蜜酒回来！和玛尔顿谈谈吧，他会给你进一步指示的。",objectives={"和奥格瑞玛的玛尔顿·杜佛斯谈一谈。"}]])
R(650,"寻找蜜酒",[[description="你得去跟那个名叫基沃拉丁·猎日者的精灵谈谈。他只需闻一下就可以辨别任何一种葡萄酒！他可以帮我们弄到蜜酒。嗯……我们需要至少六瓶包装好的蜜酒，其中两瓶是给爸爸的，至于他实际上需要多少瓶倒无关紧要……当你打包好了蜜酒，并且搞到了给爸爸的两瓶蜜酒之后，就回到我这里来！$B$B基沃拉丁的营地在辛特兰的高等精灵大屋附近，不过那些高等精灵不太友善……相信我。",objectives={"和基沃拉丁·猎日者谈一谈，他的营地就在辛特兰区域。"}]])
R(651,"禁锢之石",[[description="在阿拉希高地上散布着4块禁锢之石，这些石头将我牢牢地钉在地下。$B$B要想解除它们，你就必须解除最坚固的那块：内禁锢之石。首先，你必须搜集到其它三块石头的钥匙。$B$B这些石头都有守护者在看守，但是如果你足够聪明或者足够幸运的话，就能找到消灭这些守卫的办法。",objectives={"从西禁锢之石、东禁锢之石和外禁锢之石中搜集烈焰钥匙、海浪钥匙和雷霆钥匙。$B$B把它们带到内禁锢之石处。"}]])
R(652,"打开钥匙之石",[[description="禁锢之石的开启基本解开了这些束缚着我的东西，可还有一把牢不可破的锁让我无法动弹。你看到这圈石头中的那块钥匙之石了吗？开锁的钥匙在弗兹鲁克手中，他是囚禁我的巨人之一，也是这石锁的看护人。$B$B你必须从弗兹鲁克那里获得一把名叫“秩序魔棒”的钥匙来打开钥匙之石。$B$B你已经为我做了这么多，$n，只是再帮个微不足道的小忙……我会对你更加感激不尽的！",objectives={"找到并杀死弗兹鲁克，然后把秩序魔棒带到阿拉希高地的钥匙之石旁。"}]])
R(653,"密斯莱尔的盟友",[[description="<密斯莱尔开始说话>$B$B自由！我自由了！我终于自由了，我要恢复力量，不过现在我还得躲避那些追捕我的敌人。因为如果他们现在找到我的话，肯定会轻松将我降服并重新监禁我。$B$B总有一天我会回到那些巨人的面前，让他们为禁锢我的行为而后悔！$B$B你是一个高尚的盟友，$N。我会再次需要你的帮助。等我准备好之后，我需要你来将我召唤到地表上。$B$B去和铁炉堡的葛利·硬骨谈谈吧，他知道如何召唤我。",objectives={"和铁炉堡的葛利·硬骨谈一谈。"}]])
R(654,"塔纳利斯的样本",[[description="启动能量源之后，野外实验工具包开始闪光和震动，看来它开始按照预定的程序工作了。$B$B根据首席工程师沙克斯·比格维兹所说的，你现在有两个小时的时间在塔纳利斯沙漠收集你所需的数据。如果你在两个小时内无法收集到全部数据，那么收集到的数据也将消失，而你则不得不重新从安全主管吉罗姆·比格维兹那里购买另外一个能量源。$B$B当你完成任务之后就尽快回到他那里。",objectives={"收集8份蜥蜴样本、8份土狼样本和8份蝎子样本，然后在能量源耗尽之前把野外实验工具包还给加基森的安全主管吉罗姆·比格维兹。"}]])
R(655,"落锤镇",[[description="一切是那么的清晰，似乎就发生在昨夜……那么多年了，从来都看不到任何希望，却有重重的木枷和钢索将我们的族人束缚在这个可怕的地方。终于，终于！奥格瑞姆酋长回来解救我们了！他像座铁塔一样站在那里，穿着那套如午夜一般漆黑的战甲，将他的战锤高高举起。$b$b那……太恐怖了……那懦夫的一击居然击倒了我们最伟大的英雄。那个懦夫骑着战马，手持长矛向他刺去……我跪倒在地。哪里才有希望？哪里才有希望……",objectives={"和落锤村的托尔甘交谈。"}]])
R(656,"召唤大地公主",[[description="你必须在密斯莱尔恢复力量之前打败她。否则，一旦等到她聚集到足够的能量，密斯莱尔就会向追捕她的人发起挑战！有一些人自信能控制住她，但是如果她真能被控制住，巨人们有必要先发制人把她囚禁起来吗？$B$B这是个疯狂的逻辑，难道不是吗？$B$B你必须在第一次和她接触的密斯莱尔水晶碎块那里将她召唤出来，然后打败她。在打败她之后搜出她身上的怪异镣铐，然后与密斯莱尔水晶碎块缚在一起。$B$B只有这样做才能再次将密斯莱尔囚禁起来。",objectives={"到密斯莱尔水晶碎块去召唤她，然后打败她。$B$B搜出她身上的怪异镣铐，将其和密斯莱尔水晶碎块缚在一起。"}]])
R(657,"新的瘟疫？",[[description="<奎艾开始仔细地阅读这份文件>$B$B这很有趣。看起来药剂师乔瑞尔正在格沙克农场里进行着一些危险的试验，很难说这和希尔斯布莱德有什么牵连，不过我看最好还是别让他得逞。$B$B你走了以后，我们看见有一些兽人跑了进来，不过我没有足够的实力去帮基恩洛的忙——她要到农场里去偷取乔瑞尔的那些还没有送往塔伦米尔的研究资料，你能协助她吗？",objectives={"和基恩洛谈一谈。"}]])
R(658,"新的瘟疫？",[[description="是费恩让你来找我们的吧？我一点都不吃惊，那家伙总是担心这个担心那个的。$B$B我们监视这个农场已经有些时候了，基恩洛说她不久前看见有一个信使从那间小房子里走出来，往南边去了。$B$B她平时话有些多，不过在这种危险的地方，我总是相信她的直觉。$B$B嗯……你的追踪能力怎么样？我们认为那个信使可能是带着信去塔伦米尔了。如果你能弄到那些文件，就有可能帮助我们搞清楚在希尔斯布莱德所发生的那些怪事。",objectives={"找到被遗忘者信使，把她的密封的信件交给格沙克农场里的奎艾。"}]])
R(659,"新的瘟疫？",[[description="欢迎你，$N。我带着一群探险者到这里来调查最近发生的一些怪事。$B$B我在希尔斯布莱德有个堂兄，他最近杀掉了家养的那只名叫斯坦雷的狗，因为这只狗突然长得很巨大，而且还野蛮地攻击所有靠近它的人。$B$B我想这一定和亡灵有些关系，我们正在寻找能证明这个猜想的更多证据。$B$B我的两个同伴奎艾和基恩洛到阿拉希高地上的格沙克农场去了，最近这些天一直没有她们的消息。你能帮我找到她们吗？我越来越担心了……",objectives={"到阿拉希高地上的格沙克农场附近找到奎艾和基恩洛。"}]])
R(660,"新的瘟疫？",[[description="好了，$N。我已经准备好了。$B$B可以出发了吗？",objectives={"保护基恩洛，直到她回到奎艾身边。"}]])
R(661,"新的瘟疫？",[[description="就算让基恩洛在旅店里睡上一晚，她也不会比现在看起来更健康。显然，你很好地保护了她。$B$B她从农场拿回来的这些东西至少能让费恩了解到在阿拉希高地附近究竟发生了些什么事情。为了确保你们的行动不会导致任何报复行动，我们会在这里继续留守一段时间。你愿意返回南海镇去和费恩谈谈吗？",objectives={"到南海镇去找到费恩·奥德利克。"}]])
R(662,"深海打捞",[[description="奥布里领船进入海湾，我们确信能在这里发现宝藏。先驱号安全靠岸，但是当处女号和银松之魂号靠近港口的时候，退潮开始了。此时发生了怪事！$b$b那两艘船撞上了什么东西……似乎是暗礁中的什么庙宇……它们很快就沉没了，这真是一场灾难。$b$b我们必须要在离开以前去取回他们的日志和航海图，这些有价值的信息绝对不能留给任何其他人！",objectives={"大副尼兹利克斯让你从处女号和银松之魂号中取回航海图和航海日志。"}]])
R(663,"法迪尔海湾",[[description="鲁鲁看见了一个小$r！鲁鲁总是待在哨所上！$b$b欢迎来到法迪尔海湾。奥布里船长说过，我们在这里待不了多久。我们只要搜集宝藏然后返回藏宝海湾就行了。$b$b但是鲁鲁认为我们要在这儿待很长很长的时间，我们失去了两艘船。可怜的银松之魂号和处女号！她们长眠在海底！$b$b鲁鲁说，如果你想在这逗留的话，就去和奥布里船长谈谈吧。",objectives={"和法迪尔海湾的奥布里船长交谈。"}]])
R(664,"船长的复仇",[[description="啊，多么可怕的生活！我本以为我再也不能像现在这样坐在火堆旁呼吸着新鲜的空气了！$b$b船员们为了拯救我那美丽漂亮的处女号尽了全力。愿神保佑他们，保佑他们的心灵。$b$b奥布里船长的船安全地进了港，可我们就没那么幸运了，大浪弄沉了我们的船。$b$b前一秒钟我们还漂浮在海上，转眼间就又被海浪吞没。而那些该死的纳迦还杀死了所有的幸存者！我逃到这里来，算是勉强保住了性命。$b$b我要让那些野兽去死！",objectives={"法迪尔海湾的斯迪加特船长要你去杀掉10个刺脊袭击者和3个刺脊巫师。"}]])
R(665,"水下宝藏",[[description="既然我们已经整装待发，那么帮助奥布里先生寻找丢失的精灵宝藏就是当务之急了！$b$b在黑暗的海底，如果没有任何辅助手段的话，要想找到那些宝藏几乎是不可能的。博士做的潜水镜可以派上大用场，不过他要从山上的洞穴里弄些魔石来，好给他的潜水镜附上魔法。$b$b但是那座洞穴已经被诅咒了！只要我们靠近洞穴就会遭到伏击。你得掩护我，让我控制魔石的能量，将它注入到潜水镜里。",objectives={"护送菲兹索普教授到洞穴里去并平安返回。"}]])
R(666,"水下宝藏",[[description="宝藏在海床上放了那么长时间，早已经被岩石包裹起来了。但是借助潜水镜中的魔法力量，你可以轻而易举地锁定这些宝藏。$b$b侏儒的创造能力实在是让人惊叹！$b$b那么你去把寻宝潜水镜借来用用，$n，看你能不能帮奥布里船长找回些丢失的宝藏。$b$b我可以潜游到那儿，可是……嗯……在这片安全而干燥的土地上，我有些重要的科学研究要做……嗯，是这样的。",objectives={"法迪尔海湾的德拉克里格博士要你去收集10块精灵宝石并在完成任务后归还寻宝潜水镜。"}]])
R(667,"水下伏兵",[[description="太糟了，看来那些刺脊纳迦正在囤积重兵准备发动攻击。纳迦在作战时是出了名的冷酷无情，只要你还有一口气，他们就决不会停止攻击。$b$b我并不是说我自己的性命比弟兄们更宝贵，但你必须得保护我，因为如果没有我对大海的了解，弟兄们是不可能回到藏宝海湾去的。$b$b纳迦会从大海里向我们发起进攻，我要你留在这儿与我一起对抗他们，齐心协力把他们打退。$b$b你准备好了吗，$n？",objectives={"在纳迦的攻击中保护沙克斯·奥布里。"}]])
R(668,"水下宝藏",[[description="我们不要让奥布里船长等了。他急着想看到这些宝藏呢。这不正是我们在这儿的原因吗？$b$b和这些海盗们打了几个星期的交道以后，我和教授都意识到，手里拿着海盗的宝藏永远是不安全的。$b$b拿着这些，$n，把它们交给奥布里。",objectives={"把精灵宝石交给奥布里船长。"}]])
R(669,"水下宝藏",[[description="舰队指挥官卡拉·海角一定想马上知道我们找到了什么。$b$b你也看到了，我们还不能离开这儿。不单单是因为潮水太低的缘故，还因为那些被我们惊动的可恶家伙正密切地注视着我们的一举一动。$b$b假如你能把口信带给藏宝海湾的舰队指挥官卡拉·海角，并告诉他我们已经发现宝藏的话，你可就帮了我们黑水海盗的大忙了。把这件东西交给舰队指挥官卡拉·海角，这样他就会确信你说的是真的了。",objectives={"把精灵宝石样本交给藏宝海湾的舰队指挥官卡拉·海角。"}]])
R(670,"水下宝藏",[[description="嘿，$n，看来你是个喜欢冒险的$r。在我们重新进货之前，我的船队会一直停泊在藏宝海湾。$b$b这里即将发生一些大事，我得找人把相关的绝密信息通报给在阿拉希海岸上的沙克斯·奥布里。$b$b你可以确保将口信安全而保密地送达吗？",objectives={"把海角船长的密信送给阿拉希高地的沙克斯·奥布里。"}]])
R(671,"邪恶的魔法",[[description="我感觉空气中弥散着一种奇怪的东西……这种感觉在我的血液中不断升腾。对此我感到很奇怪，于是便着手去寻找给我造成这种不安的原因，然后我就在西边的诺斯弗德农场找到了一些邪恶的召唤法术留下的痕迹。当我慢慢地靠近时，我的热血开始沸腾，胸中的怒气不断上升。$b$b我在地上发现了一枚血石护符，那是用在恶魔召唤仪式中的东西。可是，我找到的这枚血石护符的能量已经被耗尽了。现在我需要再弄一些来研究，可我不敢回农场去了。你能帮我找一些来吗？",objectives={"帮落锤村的托尔甘找10枚血石护符。"}]])
R(672,"振奋精神",[[description="我们把他安顿下来，不断地鼓舞他，向他讲述我们在卡利姆多建立伟大的奥格瑞玛城的故事，但所有的这些都无法打动他。$b$b关于我们年轻的酋长的故事，拥有奥格瑞姆的战甲和战锤的萨尔酋长……也许吧……也许吧！我们新发现的萨满魔法或许会带给他新的希望。这值得一试！$b$b我们可以给他一件小东西，对……给我带些迅猛龙的眼睛，我要看看我们能做些什么。",objectives={"从高地阔步龙和高地长尾龙身上取得10个高地迅猛龙的眼球，把它们交给落锤村的托尔甘。"}]])
R(673,"邪恶的魔法",[[description="我确信有一个强大的术士居住在激流堡城内。这个术士经常通过一种魔法物品来召唤大量的恶魔。我们必须毁掉他的能量源泉。$b$b找到这个术士，杀掉他。把所有你在他身上发现的物品都拿来给我，我会设法销毁它的。我们绝对不能让这片大地再被玷污了！",objectives={"取回玛雷兹·考尔的血石宝珠，把它交给落锤村的托尔甘。"}]])
R(674,"振奋精神",[[description="把这枚护符交给戈穆尔，看看迅猛龙的力量能否唤醒这位勇士的血管中曾经燃烧过的火焰。",objectives={"把迅猛龙利爪护符交给戈穆尔。"}]])
R(675,"振奋精神",[[description="<戈穆尔把护身符扔到了地上>$b$b托尔甘让你来的，是吗？呸！我不理解他为什么要怜悯我。在我不能和我的酋长一起战死的时候，我就不再接受任何怜悯了。我注定要被这残酷的命运煎熬……",objectives={"和托尔甘谈一谈。"}]])
R(676,"落锤之战",[[description="软弱的家伙……他们全都是懦夫……你，$c，你在看什么？你觉得自己有什么特殊的么？怎么不去证明一下？$B$B阿拉希的落锤村哨所正受到攻击。再不增派援兵的话，他们就会全军覆灭的。$B$B不过在你去那里之前，是不是应该先试试看自己够不够格？阿拉希的激流堡东北部有个食人魔的营地，石拳部族的食人魔就住在那里。等你搞定了那里的食人魔和执行者之后，再去向落锤村的杜拉姆法尔报告吧。",objectives={"杀掉8个石拳食人魔和10个石拳执行者，然后去阿拉希高地的落锤村哨所找杜拉姆法尔。"}]])
R(677,"短兵相接",[[description="枯木巨魔和阿拉希的石拳食人魔联合起来，要把我们赶出这片土地，但我们决不会把命运交给他们掌控！我们要除掉他们，让他们知道谁是这儿真正的主宰。$B$B巨魔背弃了我们，食人魔想要把我们当作美味的食物——我们决不能允许这种事情发生。$B$B现在，让我们从南边的枯木巨魔开始吧。去杀掉他们，让他们血流成河！",objectives={"杀死10名枯木掷斧者、10名枯木猎头者和8个枯木巫医，然后回到落锤村哨所的杜拉姆法尔那里。"}]])
R(678,"短兵相接",[[description="$N，你的强大已经是有目共睹的了。现在让我们看看你如何去面对一个真正的敌人。$B$B从这里往西南走，在通往矮人修建的那座大桥的途中，有一个石拳食人魔的老巢。如果我没搞错的话，那儿的虐待者和法师对你来说应该是个难度不小的挑战——至少到现在为止对于我们来说是这样的。$B$B尽可能多地杀死他们，无论最终是胜利还是失败，无论回来见我的是你自己还是你的灵魂，我都会赞赏你在战斗表现出的坚韧精神。",objectives={"杀死10个石拳蛮兵和4个石拳法师，然后向落锤村哨所的杜拉姆法尔复命。"}]])
R(679,"短兵相接",[[description="$N，现在是时候和这些家伙算总账了……很明显你完全有能力帮我们完成这最后的一击。这些与我们为敌的蠢货的领导者已经在激流堡废墟里建立了巢穴。激流堡的废墟……那是人类软弱无能的最好证明！$B$B找到那些石拳领主和他们的萨满祭司，把他们全都杀掉，这些妄图将我们赶离家园的蠢货们活不了多久了！",objectives={"杀死7个石拳萨满祭司和3个石拳领主，然后向落锤村哨所的杜拉姆法尔复命。"}]])
R(680,"真正的威胁",[[description="你帮我丈夫干得不错，$c，可他并不知道为什么落锤村会遭受攻击。$B$B奥卡拉尔是玛格索尔派到激流堡去的走狗，他非常害怕我的丈夫。很多年前，我的丈夫打败了他，他巴不得我的丈夫早点死去。$B$B我占卜到奥卡拉尔给我的丈夫设下了陷阱，并且感觉到了那些食人魔正在伺机害他……$B$B如果他知道那些食人魔在哪里的话，一定会不顾三七二十一地杀过去。所以……请你帮我杀死奥卡拉尔吧。",objectives={"杀死奥卡拉尔，将他的头颅带给落锤村哨所的科林法尔。"}]])
R(681,"诺斯弗德农场",[[description="我们正在为激流堡而战，然而我们却逐渐落入下风。我们、食人魔以及辛迪加分别控制着这座城市的一部分，现在我们这三方势力陷入了整日互相征战却毫无突破的僵局。$B$B然而，当敌人们力量开始逐渐增强的时候，我们却在慢慢地变弱。$B$B我们需要南海镇的援助，但是辛迪加控制了我们和南海镇之间的领地，因此那边的补给很难运到这里来。$B$B到辛迪加在诺斯弗德农场的基地去干掉他们，也许这样做能让我们补给线上的压力大大减轻，然后才能有更多的物资平安运抵这里。",objectives={"杀掉6个辛迪加雇佣兵和10个辛迪加路霸，然后回到避难谷地去向尼艾丝队长复命。"}]])
R(682,"激流堡徽章",[[description="我们的民兵分队正在和控制着激流堡的辛迪加成员激战。为了刺激他们那群乌合之众与我们作战，辛迪加的头目们使出了重金悬赏的手段，只要有人能杀死我们的民兵，并从他们身上缴获激流堡徽章，辛迪加都会给予奖励。$B$B我们必须夺回那些徽章——决不能让刽子手们用我们的战士的性命来换取金钱！$B$B到激流堡城内的辛迪加控制区去杀掉那些歹徒，取回我们的徽章。",objectives={"把激流堡徽章交给位于避难谷地的尼艾丝队长。"}]])
R(683,"萨拉·巴鲁的请求",[[description="$n，我对你有个小小的请求。$b$b这张便笺是我写给铁炉堡的国王麦格尼·铜须的。对于你这种曾为联盟的事业英勇作战的$r来说，这个任务再容易不过了。$b$b以我在现在这种状态去觐见国王陛下是很不合适的，我相信你应该可以理解。",objectives={"把萨拉·巴鲁的便笺交给铁炉堡的国王麦格尼·铜须。"}]])
R(684,"通缉：玛雷兹·考尔",[[description="重金悬赏玛雷兹·考尔的项上人头。这个兽人是辛迪加组织的高级顾问和技工，人们最后一次看见她是在激流堡内的辛迪加控制区。$B$B赏金请到尼艾丝队长处领取。$B$B请注意：玛雷兹是一个强大而狡猾的术士，她和恶魔有着非常密切的联系。追杀她时务必非常小心。",objectives={"把玛雷兹的头颅交给避难谷地的尼艾丝队长。"}]])
R(685,"通缉：奥图和法库雷斯特",[[description="激流堡民兵团重金悬赏法库雷斯特公爵和他的保镖奥图的头颅。法库雷斯特是辛迪加在阿拉希地区的主要领导者，他的死将使该组织在这一地区的活动陷入瘫痪。$B$B他的保镖奥图不是我们的战略目标，但他生性凶残，已经杀死了许多激流堡的士兵。$B$B赏金请到尼艾丝队长处领取。",objectives={"把法库雷斯特和奥图的头颅交给避难谷地的尼艾丝队长。"}]])
R(686,"国王的礼物",[[description="象巴鲁夫人这样好心的矮人可能无法理解要忍受这场可笑的战争其实是为了我们族人更高的利益。无论是她的丈夫还是其他在战斗中献出生命的矮人，每次听到他们的名字都让我感到非常心痛。$b$b虽然我不能让她的丈夫死而复生，不过我可以向他致以崇高的敬意。$b$b我会委派大石匠玛布勒斯坦为苏利·巴鲁建造一座纪念碑。$b$b把口信带给他，$c。你来负责传达我的这条命令。",objectives={"国王麦格尼·铜须让你去和大石匠玛布勒斯坦谈一谈。"}]])
R(687,"迷失者塞尔杜林",[[description="迷失者塞尔杜林曾经是我们暮光之锤的一员。但是有一天他突然精神失常，摒弃了我们的信条，背叛了我们的信仰。在背离我们之前，他还偷走了密斯莱尔卷轴！我们没能抓到他，但有传言说他就躲藏在荒芜之地中，整日胡言乱语，已经完全疯掉了。$B$B如果你要将公主带回来的话，就必须找到卷轴，而要找到卷轴，你就必须找到塞尔杜林。",objectives={"找到迷失者塞尔杜林。"}]])
R(688,"密斯莱尔的盟友",[[description="<密斯莱尔开始说话>$B$B自由！我自由了！我终于自由了，我要恢复力量，不过现在我还得躲避那些追捕我的敌人。因为如果他们现在找到我的话，肯定会轻松将我降服并重新监禁我。$B$B总有一天我会回到那些巨人的面前，让他们为禁锢我的行为而后悔！$B$B你是一个高尚的盟友，$N。我会再次需要你的帮助。等我准备好之后，我需要你来将我召唤到地表上。$B$B去和落锤村的萨鲁克谈谈吧，他知道如何召唤我。",objectives={"和落锤村的萨鲁克谈一谈。"}]])
R(689,"国王的礼物",[[description="我们的国王要建一座纪念碑向一个叫苏利·巴鲁的士兵致敬？你是说那个可怜的士兵是在萨多尔大桥的悲剧中死的？$b$b唉，艾泽拉斯还会有和平吗？$b$b不管怎样，国王下达的任务就是第一要务。我要用最好的石头来建这座纪念碑，你到希尔斯布莱德的丘陵洞穴为我找一些奥特兰克花岗岩来吧。",objectives={"铁炉堡的大石匠玛布勒斯坦要5块奥特兰克花岗岩。"}]])
R(690,"马林的要求",[[description="你好，$N。我看出你是个渴望冒险的$c，现在我有项任务需要你的帮助。$B$B我原来的主人，大法师特雷莱恩，不久从位于阿拉希高地的激流堡里逃了出来。他让我到那里去帮他取回一些临走时落下的物品。$B$B激流堡现在已经陷入了重围之中，他在努力保卫阿拉索之塔，但是现在看来情况越来越危险了。我的人已经到了阿拉希高地，但他们需要更多的支援。你有兴趣去帮忙吗？",objectives={"找到位于阿拉希高地上的避难谷地中的斯奎尔图。"}]])
R(691,"证明实力",[[description="$N，别怕斯奎尔图。他是因为事情太多才变得这么暴躁。在我们等他完成侦察任务的时候，为什么不做些更有意义的事情呢？马林派我到这里来为他收集一些试剂，对于如何收集这些物品，我感到很困惑。不过现在你来了，我想我的问题也解决了。$B$B我需要这些东西：枯木巨魔的獠牙，枯木巨魔的医药包和一把暗影猎手的小刀。$B$B你能帮我找到这些吗？枯木巨魔一般都在阿拉希高地的东南一带出没。",objectives={"帮避难谷地中的学徒克里汀收集10个枯木巨魔的獠牙，4只枯木巨魔的医药包和1把暗影猎手的小刀。"}]])
R(692,"遗失的卷轴碎片",[[description="密……密斯莱尔卷轴？！你要那东西干什么？它强大的魔法力量可以把密斯莱尔召唤到地面上来，那时候我们就有大麻烦了！$B$B也许……也许已经太迟了，也许她已经自由了。密斯莱尔可能正在为报复我们而聚集力量。如果是这样，那你就必须掌握着这至关重要的卷轴！$B$B……太糟了，它被毁掉了。愤怒的元素生物偷走了卷轴，并将它撕成了碎片。现在它们又在为这些碎片争斗不休。$B$B如果你能搜集那些碎片的话，也许我们还有希望将它修复成原来的样子……",objectives={"把破损的卷轴碎片、弄皱的卷轴碎片和烧焦的卷轴碎片带给迷失者塞尔杜林。"}]])
R(693,"特雷莱恩的符咒魔杖",[[description="你好啊，$N，很抱歉我以前对你那么凶……我可以断定特雷莱恩的第一件宝物的所在：它在石拳大厅的考格雷什手里。顺便说一句，他已经可以使用冰爆术来教训不听话的手下，看来离他完全掌握魔杖力量的日子也已经不远了。$B$B石拳大厅就在这里的南边，萨多尔大桥的东边。从那个食人魔手里把那根魔杖拿回来吧。$B$B在你回来之前，我要想想我们要怎样解决激流堡的问题。",objectives={"帮避难谷地的斯奎尔图找到特雷莱恩的符咒魔杖，并把它带回来。"}]])
R(694,"特雷莱恩的防御",[[description="休息好了吗？$B$B我们的下一步计划和激流堡的阿拉索之塔周围的食人魔有关。我们必须首先开启这座塔的防御系统，当然，前提是你能活着到达存放那些物品的地方。为此，首先我们需要一些石拳萨满祭司经常携带着的宝石。他们把宝石从塔里带了出来，但他们没有什么机会占有这些宝石了。$B$B从他们那里弄一块宝石，把它送去给克里汀——他能够给宝石附魔，这样一来，宝石就可以当钥匙用了。",objectives={"找到一块碧蓝玛瑙石，把它交给避难谷地处的学徒克里汀。"}]])
R(695,"学徒的魔法",[[description="拿着宝石吧，$n。只要将宝石放置在塔基的任何一个支撑脚上，就能激活阿拉索之塔的防御。当你准备进入塔中寻找特雷莱恩的其余物品时，就使用这颗宝石。$B$B祝你好运，我将在营地里等你回来。哦，对了，在你离开之前别忘了去和斯奎尔图谈谈，他会告诉你一些你必须了解的细节。",objectives={"和斯奎尔图谈一谈。"}]])
R(696,"进攻高塔",[[description="以下是你要找的东西：特雷莱恩的护符匣、特雷莱恩的宝珠和特雷莱恩的黑玛瑙。$B$B所有这三样东西应该都在塔中的箱子里，你打开这些箱子应该不会有什么问题，只是要当心那些食人魔就成。$B$B阿拉索之塔的防御不会作用于那些食人魔，因此你必须时刻准备战斗。如果那些食人魔发现你在偷他们的东西，你就少不了一场恶战。$B$B多加小心，祝你好运。",objectives={"找到特雷莱恩的护符匣、特雷莱恩的宝珠和特雷莱恩的黑玛瑙，把它们交给避难谷地的斯奎尔图。"}]])
R(697,"马林的要求",[[description="把这封信送到暴风城去，让马林知道我和克里汀很快就可以回家了。对于你给我们的帮助，马林一定会好好回报你的，$N，对于这一点我深信不疑。$B$B祝你旅途顺利。",objectives={"将给大法师马林的信交给暴风城法师区里的大法师马林。"}]])
R(698,"缺乏补给",[[description="我正努力为我们在东边海滩那里的哨所收集一些补给品，托克卡尔已经尽了他的全力。但他又要值勤，又要为他的士兵们做饭，一天这么下来就没什么时间了。$B$B他们很喜欢吃盐齿鳄鱼的肉，但我没时间为他们再送去一批补给了。你能帮我这个忙吗？$B$B盐齿鳄鱼幼崽的肉不如成年鳄鱼的口感好，所以你别猎杀小鳄鱼，等它们长大了再吃它们也不迟。",objectives={"给悲伤沼泽的托克卡尔带去8块新鲜的盐齿鳄鱼肉。"}]])
R(699,"缺乏补给",[[description="我们之所以被部署在这里，是为了警戒在这片海岸附近出没的鱼人，以防它们——或者任何其它什么东西——威胁到斯通纳德，当然，要是他们太嚣张了点的话，我们也会去给它们一些颜色看看。这工作可不轻松，我们几乎很少有自由的时间，所以只好拜托你来帮忙了，当然，我是说如果你愿意的话。$B$B加工得当的盐齿钳嘴鳄的爪子可以用来制作精良的武器，给我带些它们的爪子回来，我就会送你一件精致的武器作为酬谢。",objectives={"给悲伤沼泽的托克卡尔带去6只盐齿钳嘴鳄的爪子。"}]])
R(700,"国王的礼物",[[description="啊，洛丹伦的石头真不赖，可惜那儿已经变成一片废墟了。$b$b纪念碑完成了！我想国王陛下一定会满意的。$b$b如果你愿意的话，请替我去告诉国王陛下，纪念碑已经完成了。",objectives={"向铁炉堡的国王麦格尼·铜须汇报。"}]])
R(701,"迅猛龙的狡诈",[[description="只要借助一些特别的物品，我就能创造出一件注入了迅猛龙的狡诈力量的东西！这样就应该能让戈穆尔了解到我们新的能量，并重新找回潜藏着的勇士的力量！$b$b我需要迅猛龙的心脏来完成这件物品和法书。",objectives={"从高地猎兽龙身上获取12颗迅猛龙的心脏，把它们交给托尔甘。"}]])
R(702,"迅猛龙的狡诈",[[description="拿着这颗宝珠，用它的能量来给戈穆尔灌入迅猛龙力量的精髓。这一定会让他的精神备受鼓舞，并给予他新的生活目标。当他恢复正常之后，我们就可以向他说明部落现在的状况，在我们永无止境的战斗中，这位伟大的战士也将帮上大忙。",objectives={"把托尔甘的宝珠交给戈穆尔。"}]])
R(703,"烧烤秃鹰翅膀",[[description="哦，当然，烧烤秃鹰翅膀是我的最爱！酱汁浓郁，肉香扑鼻，香味能把数公里外饥饿的野兽都给吸引过来！$B$B我有能做一顿美味佳肴的一切原料，呃……还差点秃鹫翅膀！$B$B如果你想尝尝我的手艺，就去帮我弄些秃鹫翅膀来。尽量多弄点，没准我一高兴就把烹饪方法一并教给你！",objectives={"给里格弗兹带去4只秃鹫的翅膀。"}]])
R(704,"阿戈莫德的命运",[[description="阿戈莫德送来的最后一份报告让我感到十分困惑，现在他死了，我就更难受了！他提到挖掘队在奥达曼附近的挖掘场找到了一些“远古的石罐”。我担心是他找到的罐子影响了石腭怪，就像这里发现的小石像一样。$B$B我要你去找到那些罐子，把它们拿回来以供研究。到奥达曼挖掘场去收集那些罐子吧，完成之后再回到我这里来。",objectives={"收集4个雕纹石罐，把它们交给洛克莫丹的勘察员基恩萨·铁环。"}]])
R(705,"潜水采珍珠",[[description="荒芜之地是一个无比荒凉的地方，是凶残的捕食者和食腐动物的乐园。这里的一切都令人感到恐慌，尤其是对于我这样的小个子地精来说。为了生存，我不得不机灵些！$B$B我知道闪光弹的制作方法，也常用它来吓走野兽。不过，作为原料之一的蓝珍珠粉快要用完了。你能不能帮我找些蓝珍珠回来？当然我会给你足够的报酬。$B$B呵呵，这个东西并不是那么好找的，恐怕你得走不少的路了。我所需要的蓝珍珠可以在暗礁海的牡蛎身上找到。$B$B对，就是位于荆棘谷的那个暗礁海。",objectives={"收集9枚蓝珍珠，把它们交给荒芜之地的里格弗兹。"}]])
R(706,"黑龙之火",[[description="作为费拉诺·钢趾的学徒，我从他那里学会了赋予武器强力魔法的特殊技能。我最后一次听到他的消息时，他正和从洛丹伦过来的狩猎小队合伙工作。$b$b我不能告诉你关于这种技术的太多细节，但可以告诉你必须要用黑龙血来完成这个附魔过程， 而且一定要是从黑色幼龙那仍在跳动的心脏中涌出的血液。我现在除了等待铁炉堡的消息以外无事可做，所以如果你能从莱瑟罗峡谷帮我带一颗黑色幼龙之心回来，我就向你展示一下我的技术！",objectives={"为西格鲁·铁斧拿到一颗黑色幼龙之心。"}]])
R(707,"铁环挖掘场需要你！",[[description="$N。洛克莫丹的勘察员基恩萨·铁环从他的挖掘场给我送来报告，说是需要为我们的另一项挖掘计划外出搜集一些情报。$B$B我就知道这么多了，如果你愿意活动一下筋骨，就去和基恩萨·铁环谈谈吧。",objectives={"和洛克莫丹铁环挖掘场的勘察员基恩萨·铁环谈一谈。"}]])
R(708,"黑盒子",[[description="这个黑色金属箱的表面已经被严重破坏，似乎在酸液中浸泡过——它一定在那只巨型秃鹫的肚子里呆了很长的时间。$B$B翻转过箱子之后，你发现箱底印着一个标记，标记下是一行字：$B$B“19号坦克 - 铁炉堡攻城坦克旅”",objectives={"把这个黑盒子带到铁炉堡的军事大厅去。"}]])
R(709,"化解灾难",[[description="天哪……天哪！厄运就要降临了。它已经朝我而来了！厄运就要降临了！$B$B不，我不能说……不能说出他们的名字，否则会被他们听到的！但是，如果我们……如果我们对他们有更多了解的话……也许我们就可以知道如何击败他们！$B$B也许……$B$B到奥达曼去。不！我说过！你必须找到……找到雷乌纳石板……对，找到它！别让我再提到那个名字！$B$B它深藏在那里，就在一个古代的箱子里……这个箱子甚至比矮人族群的年代还要久远……",objectives={"把雷乌纳石板带给迷失者塞尔杜林。"}]])
R(710,"研究石元素",[[description="在荒芜之地，我停下了所有手头的事情来专注于我的最新项目：元素禁锢镣铐。$B$B这些镣铐一旦完成，就可以让法师们在更广的范围内召集更加强大的元素生物。首先，我需要些小石头碎块，来检验我最新的攻击性咒语和小发明。$B$B你可以从西面那里的次级石元素身上收集到这些碎片，能给我弄一些来吗？",objectives={"收集10块小石头碎块，把它们交给荒芜之地的鲁特维尔·沃拉图斯。"}]])
R(711,"研究石元素",[[description="$N，你的能力超过了我所有学徒的总和。$B$B我所需的下一个部分需要花些功夫。只要你稍加留心，就能在石元素身上找到一些大石片。他们的身体更加庞大，因而会有足够大的碎片来供我试验。你可以在西边远一点的地方或者东南方的山地边缘找到它们。$B$B不用太着急，测试你带来的小石头碎块还需要花些时间。",objectives={"收集3块大石片，把它们交给荒芜之地的鲁特维尔·沃拉图斯。"}]])
R(712,"研究石元素",[[description="$N，我还需要从荒芜之地的元素生物身上弄一些东西：巨型石元素身上的护腕。据我估测，那些护腕完全可以检验出我的镣铐所具有的力量。$B$B我的占卜显示，在西南边有一批巨型石元素。我想起来了，那附近好像还有一些食人魔。$B$B给我带5个护腕来，我想5个就足够了。阿布总是放错我的试剂和实验品，这方面它的名声可不太好。",objectives={"收集5个石缚护腕，把它们交给荒芜之地的鲁特维尔·沃拉图斯。"}]])
R(713,"至关重要的冷却剂",[[description="让我来告诉你些有关冰霜之油的事情吧：没有别的什么东西能够像它一样防止发动机或者齿轮过热。$B$B它的冷却性能和润滑效果无与伦比。不仅如此，它还有助于保存附着在魔法物品上的魔力。$B$B我需要一小瓶冰霜之油以加强镣铐的魔力，好让它们足够强大，不然我可没法阻止那些被召唤来的“朋友们”对我们大开杀戒。$B$B我在奥特兰克有一个名叫布洛金的地精朋友，他能教你制取冰霜之油的方法。",objectives={"找到冰霜之油，把它交给荒芜之地的鲁特维尔·沃拉图斯。"}]])
R(714,"发条式什么什么仪",[[description="$N，你所做的一切都是超一流的。$B$B<鲁特维尔的注意力显然从工作中移开了>$B$B如果我们曾在卡拉诺斯见过，你随时都可以来申请工作。$B$B哎呦！快抓住……对，那个。谢谢。$B$B我现在还需要一件东西。虽然是件小东西，但是也非常关键的东西，它就是精密的发条式同步协调陀螺仪。$B$B如果你能帮我找一个的话，我就能完成工作啦。",objectives={"给荒芜之地的鲁特维尔·沃拉图斯带去一个发条式同步协调陀螺仪。"}]])
R(715,"卢希恩的药水",[[description="我想你为鲁特维尔找的那些东西会不会给我们带来什么麻烦，$N。另一方面，你已经在帮助鲁特维尔神圣的科学研究的过程中体现了超凡的才能，那么帮帮我如何？$B$B我需要一瓶隐形药水和一瓶治疗药水。如果他的进展一切顺利，这两件东西都必须及时到位。$B$B作为报酬，我会给你这个配方，它是我向鲁特维尔求学时，在鲁特维尔长期以来在荒芜之地的研究成果的基础上开发出来的。",objectives={"为荒芜之地的卢希恩·枪穗找到一瓶次级隐形药水和一瓶治疗药水。"}]])
R(716,"有备无患",[[description="我知道鲁特维尔疯狂起来会有多么危险，你最好让我给你制作一些装备以防万一。也许它能保护你免受鲁特维尔新发明的折磨。$B$B我一直都在研究那些你给他找来的石头，所以我想我能造出一些不错的护腕来供你使用。嗯，它们当然都是附有魔法的。$B$B我只需要一些铁匠打造的青铜花纹护腕就可以帮你造出附魔的护腕了。",objectives={"给荒芜之地的卢希恩·枪穗带去一些青铜花纹护腕。"}]])
R(717,"大地的震颤",[[description="显然，我们不能保证黑龙布莱克拉什和赫玛图斯仍能被囚禁在莱瑟罗峡谷里。大批黑龙盘踞在那里的现状以及食人魔试图偷走大地印章的事实说明后面将会有更可怕的事情发生。$b$b黑龙的监狱由三块符石维持着，只有使用大地印章才能得到它们，而那些符石就是打破封印的关键。$b$b$n……我们要确保那些黑龙的梦想永远无法成真。",objectives={"用大地印章激活钻石柱、玛瑙石柱和紫水晶石柱并拿到三颗符石。$b$b把符石放在大地封印上，释放黑龙布莱克拉什和赫玛图斯。$b$b杀了这两条黑龙，把布莱克拉什的锁链、赫玛图斯的锁链和大地印章交给加瑞克。"}]])
R(718,"饥肠辘辘",[[description="在匆忙撤出奥达曼挖掘场的途中，我们不得不丢弃了很多补给物资，那些柯什营地里的食人魔像兀鹫看见了腐烂的尸体一样疯狂地掠夺我们扔掉的物资，呃，那些家伙闻起来也和晒了好几天的尸体没什么区别……$b$b不管怎么说，他们抢走了我们装着武器的马车，而且现在……现在的状况实在是只能用窘迫两个字来形容了——我们现在几乎什么吃的都找不到了。$b$b就连腌菜也要吃光了，你看……能不能帮我们弄点什么吃的来？",objectives={"帮西格鲁·铁斧找回补给箱。"}]])
R(719,"矮人的工具",[[description="你好，$c。千万要小心四周。这里到处都是黑铁矮人，似乎都是属于暗炉部族的。$B$B他们刚刚袭击了我们的挖掘场……杀死了那里几乎所有的人，包括我的老板铁趾格雷兹，只有我侥幸逃了出来。$B$B挖掘场在这里的北面，我想找回我们的一些物资，尤其是我的好运锄。$B$B你能帮帮我吗？如果找不到其它的，至少帮我找回我的锄头吧。",objectives={"找到雷杜尔的好运锄，把它交给铁趾挖掘场南边的勘察员雷杜尔。"}]])
R(720,"一线希望",[[description="<在地图上有一行用粉笔潦草写下的文字>$B$B“雷杜尔，$B他们把我带到了奥达曼，请速来援助。$B——铁趾”",objectives={"找到勘察员雷杜尔，告诉他铁趾格雷兹还活着。"}]])
R(721,"一线希望",[[description="$N，你能找到他吗？你能在奥达曼找到铁趾吗？$B$B如果那些卑鄙的暗炉矮人将他抓为人质是为了获得他掌握的有关泰坦的信息的话，铁炉堡就有大麻烦了。$B$B很久以来，黑铁矮人一直在寻找可以制造出威力更大的作战傀儡的魔法。铁趾也在寻找这样的魔法，但他的目的仅仅是为了阻止他们。$B$B估计在套出重要情报之前，他们是不会杀了铁趾的。你要抓紧时间，尽快救出铁趾！",objectives={"在奥达曼找到铁趾格雷兹。"}]])
R(722,"铁趾的护符",[[description="你很勇敢……<咳嗽>……为了我来到奥达曼，$c。$B$B如果你真要帮助我……那么……<咳嗽>……你就必须找到……帮我找到我的护符。$B$B它在……马格雷甘·深影的手里。他就在这附近……肯定在这片废墟上。如果你不能阻止他的话，那枚护符将会引导他……<咳嗽>……找到卷轴。$N，就看你的了。$B$B请……拿到那枚护符。$B$B卷轴一旦落入黑铁矮人的手里……一切就都太晚了……",objectives={"找到铁趾的护符，把它交给奥达曼的铁趾。"}]])
R(723,"铁趾的遗愿",[[description="<铁趾捂着伤口，老半天才缓过劲来，他接着说道>$B$B找到雷杜恩，$N……把护符交给他。<猛烈的咳嗽>他……<咳嗽>知道该怎么办。雷杜恩知道我一直在寻找我们种族的起源，他也……<咳嗽>知道阻止暗炉部族是我的使命。不能让他们找到卷轴……<咳嗽>",objectives={"把铁趾的护符交给荒芜之地的勘察员雷杜恩。"}]])
R(724,"铁趾的遗愿",[[description="好吧……谁知道下一步该做些什么？$B$B史学家卡尼克！没错！$B$B他就在铁炉堡里。我想我们可以从他那里寻求一些帮助。铁趾和他曾经共同在奥达曼挖掘古代神器，估计暗炉矮人已经对他们的底细了如指掌了。$B$B去把铁趾的不幸遭遇告诉卡尼克，然后把护符交给他——他会告诉你该怎么办。",objectives={"把铁趾的护符交给铁炉堡的史学家卡尼克。"}]])
R(725,"亡者的警告",[[description="$N，你赶快去找顾问贝尔格拉姆，把你看到的一切都告诉他，问问他我们下一步该怎么做。这封信会让他了解的消息。$B$B与此同时，我会和铁趾的亡灵交谈，也许他所知道的事情能够帮助我们解决那帮暗炉部族的家伙带来的麻烦。让我们祈祷吧。",objectives={"找到顾问贝尔格拉姆，把便笺交给他。"}]])
R(726,"亡者的警告",[[description="<顾问贝尔格拉姆读到信的结尾，他的眼睛瞪大了好一会儿。>$B$B哎哟，这真是太可怕了。$B$B$N，你回去告诉史学家卡尼克，赶快以国王的名义对这一事件采取行动。他必须制止暗炉矮人在荒芜之地的所作所为！",objectives={"和史学家卡尼克谈一谈。"}]])
R(727,"远赴铁炉堡",[[description="石板说明了不少问题，但这还不够，远远不够！$B$B有这么一本书，它是雅格因在若干年前写的笔记，上面记载着一些……我想方设法要避开的人……他们在世界各地都珍藏着这本书的复制本。而他们中最有学问的人也一直在研究它，因为它包含着极其丰富的知识……可以让我们免遭灾难的知识！$B$B到铁炉堡去找葛利·硬骨，把徽章拿给他看看，他就会相信你是他们中的一员。向他要到雅格因的笔记……然后马上把它交给我！",objectives={"把战锤印章交给铁炉堡的葛利·硬骨。"}]])
R(728,"远赴幽暗城",[[description="石板说明了不少问题，但这还不够，远远不够！$B$B有这么一本书，它是雅格因在若干年前写的笔记，上面记载着一些……我想方设法要避开的人……他们在世界各地都珍藏着这本书的复制本。而他们中最有学问的人也一直在研究它，因为它包含着极其丰富的知识……可以让我们免遭灾难的知识！$B$B到幽暗城去找看守者贝尔杜加，把徽章拿给他看看，他就会相信你是他们中的一员。向他要到雅格因的笔记……然后马上把它交给我！",objectives={"把战锤印章交给幽暗城的看守者贝尔杜加。"}]])
R(729,"健忘的勘察员",[[description="首席考古学家杜瑟·灰须派我在伟大的勘察员雷姆塔维尔的指导下进行工作，这对我来说是无上的荣誉。在铁炉堡学院时，每个人都知道雷姆塔维尔有许多伟大的发现。$b$b不过这位伟大的勘察员实在是……嗯……有些健忘……他常常对周围的一切都浑然不觉。$b$b我们刚刚发现了一座大型的古代城镇，但是突然间，可怕的傀儡从地下蜂拥而出，占据了那里。不过雷姆塔维尔似乎还没有发现这一点，我跑回奥伯丁就是为了找人去救他。$b$b请到南边去一趟，看看伟大勘察员是否还一切安好！",objectives={"到南边去一趟，看看勘察员雷姆塔维尔现在处境如何。"}]])
R(730,"黑海岸的麻烦事",[[description="很高兴见到一个对我们伟大的考古事业有如此浓厚的兴趣的$C。$B$B我们的工作经常被联盟中的其他朋友当成是矮人的休闲活动而不被理解，但是很多人都没有意识到，最近在卡兹莫丹一带的发现证实，一股强大的势力正威胁着从洛丹伦到卡利姆多的整个世界。$B$B我很担心那些到黑海岸去考古的兄弟们，他们有好几个星期都音信全无了。$B$B到奥伯丁去找找看有没有关于他们的线索吧。",objectives={"到奥伯丁去寻找矮人挖掘队的线索。"}]])
R(731,"健忘的勘察员",[[description="好吧，那么，霍莉……哦，不对，你不是霍莉。霍莉去哪儿啦？$b$b不说这个了，那不是我们要讨论的话题。我们必须找到那把石刷……我是说神秘的化石！我们必须找到化石。达纳苏斯的探险者协会希望能看到我的工作进展情况。$b$b如果你准备好了，就和我说一声，我们去寻找那把刷子……我是说化石！我们要找到一些能让协会满意的东西。$b$b你准备好了吗？",objectives={"在勘察员雷姆塔维尔搜寻神秘化石的时候保护他，然后回到奥伯丁的考古学家霍莉那里。"}]])
R(732,"大地的震颤",[[description="我听西格鲁说，你在过去几天帮了他的大忙。现在我也需要你的帮助。我的主人，肯瑞托的大法师克拉苏斯派我来结束莱瑟罗峡谷的混乱局面。$b$b我不能透露这次任务的确切性质以及我要完成的使命，但是这个任务真的非常重要。$b$b有一伙四处游荡的食人魔偷走了一件名叫大地印章的东西，我必须要把它拿回来。如果你能帮我找到它，我就让你知道更多的消息。",objectives={"帮加瑞克取回大地印章。"}]])
R(733,"搜集行动",[[description="如果不能弄到一些物资来建构防御工事和其它的必要设施，我们在这里的处境就会非常糟糕。我发现这个地区的食人魔居然有许多金属碎片，也许传说在荒芜之地出没攻城坦克不久之后也会出现……$b$b无论如何，勘察员对我们营地的状况非常担忧，所以我要尽早开工。$b$b食人魔的主营地就在火山洞穴，从这里往西一直走就能找到。",objectives={"帮西格鲁收集7块金属碎片。"}]])
R(734,"不祥的感觉",[[description="太好啦，太好啦。$B$B<鲁特维尔看了你一会儿，又去摆弄他的镣铐了>$B$B去找卢希恩吧，$N。跟他说我需要一个5号齿轮。你能把它拿来给我吗？",objectives={"和荒芜之地的卢希恩·枪穗谈一谈。"}]])
R(735,"星，手，心",[[description="雅格因的笔记？你要它干什么？没关系，我不该问这个。$B$B我会帮你的，因为我这里还有一本。我们得互相帮助，对不对？这样我们才能各自获利。$B$B我需要三件宝物，把它们给我拿来，我就给你那本笔记。$B$B我不会说出它们的名字，因为可能有人正在偷听，不过我可以把这几个名字写下来。",objectives={"找齐葛利·硬骨的便笺上列出的东西，然后把它们交给铁炉堡的葛利·硬骨。"}]])
R(736,"星，手，心",[[description="你需要雅格因的笔记？一整本？当然……当然我会帮助你，我的$g兄弟:姐妹;。$B$B但你也得帮我。$B$B我需要三件威力强大的物品，把这些物品给我找来，笔记就是你的了。$B$B我不能把它们的名字说出来，不过我可以给你写下来。$B$B把这个单子上的东西找来，如果你能完成这个任务，那么你就有能力接到更重要的工作。",objectives={"把贝尔杜加的便笺上列出的东西带给幽暗城的看守者贝尔杜加。"}]])
R(737,"禁断的知识",[[description="$n，我这里有你想要的笔记，我想不需要我再提醒你要保管好它了吧？特别是绝对不要让它落入敌人之手。$B$B这本书里记录了很多真相……$B$B……可以毁灭你的真相。",objectives={"把雅格因的笔记交给塞尔杜林。"}]])
R(738,"寻找阿戈莫德",[[description="勘察员阿戈莫德曾是荒芜之地的挖掘场负责人，就是西南边的那座挖掘场。我说“曾是”，是因为……嗯，最近几周我都没有得到他的任何消息。请你帮我找到阿戈莫德并拿到他的报告。$B$B我最后一次得到的消息是：阿戈莫德在荒芜之地最南边的挖掘场——那是苦痛堡垒附近的一个不起眼的小地方。你先去那里找找看吧。",objectives={"找到阿戈莫德。"}]])
R(739,"莫达洛克",[[description="阿戈莫德留下的足迹表明他是从西边走过来的。从沙石上的斑斑血迹不难看出，矮人阿戈莫德爬行了好一段距离。$B$B爬到这里的时候，他终于被死神带走了。$B$B经过仔细察看，你在旁边的沙石中发现了几个潦草写下的字迹：“莫达洛克”。$B$B字迹就在阿戈莫德的手边。",objectives={"干掉杀害阿戈莫德的凶手：莫达洛克。$B$B顺便杀掉12个石窟断骨者。$B$B然后向洛克莫丹的勘察员基恩萨·铁环报告。"}]])
R(741,"健忘的勘察员",[[description="勘察员雷姆塔维尔要把神秘的化石送给达纳苏斯的探险者协会？可是我不太想把他一个人留在这里。$b$b给你，$n，把这块神秘的化石交给达纳苏斯的首席考古学家杜瑟·灰须。",objectives={"把神秘的化石交给达纳苏斯的首席考古学家杜瑟·灰须。"}]])
R(742,"灰谷狩猎",[[description="年轻的冒险者们，注意了！灰谷的野兽正在等着你们！$B$B部落在贫瘠之地以北的区域建立了强大的基地。我们的两个前哨站——碎木哨岗和佐拉姆海岸哨岗——正在努力地为部落的荣耀而战！想要证明自己能力的勇士就到那儿去吧。碎木岗哨位于贫瘠之地的正北方，塞娜尼·雷心正在那里招募愿意参与灰谷狩猎中的冒险者！",objectives={"与灰谷碎木哨岗的塞娜尼·雷心谈一谈。"}]])
R(743,"风怒鹰身人",[[description="谢谢你抽时间来和我谈话，$N。我是鲁尔，既是一个战士，也是一个导师。$B$B如果你想在莫高雷之外经历更多冒险的话，现在正是让你接受更多考验的时候了。$B$B如果你想测试自己的能力，就去东南方找风怒鹰身人作战吧。他们驻扎在山边远离大路的地方。$B$B鹰身人是我们的天敌，对你来说，和他们战斗会是个不错的考验。",objectives={"给血蹄村的卢尔·鹰爪带回8只风怒鹰身人的爪子。"}]])
R(744,"准备典礼",[[description="$N，我的兄弟很快就要去面见血蹄酋长了，我要为他做一个头饰，这对我来说是一种荣耀。$B$B在我处理这些皮革的时候，你能不能帮我一个忙？我没有时间去收集足够的羽毛，不知道你能否帮助我去收集一些呢？$B$B你应该可以在雷霆崖北面和西北面的鹰身人身上找到尺寸合适的羽毛。我需要6片碧蓝色的和6片古铜色的羽毛来完成我的头饰。",objectives={"收集6根碧蓝色的羽毛和6根古铜色的羽毛，把它们交给雷霆崖的伊恩·鹰爪。"}]])
R(745,"土地之争",[[description="这片土地上有很多纷争，$N。我希望你不会象我一样经历那么多的战争，不过我还是希望你去做一件事，让你可以了解到，一个看似不值一提的小小威胁如果不加制止的话，会对我们的领土带来多大的危害。$B$B白鬃豺狼人已经在西边的一个洞穴中和血蹄村的南边扎了营。我们曾试图和他们交流，却被他们无理地拒绝了，而且他们还大肆屠杀莫高雷的野生动物。$B$B现在语言已经不能解决问题了，我们必须有所行动。",objectives={"杀死10个白鬃制革工、8个白鬃剥皮工和5个白鬃偷猎者，然后回到血蹄村向贝恩·血蹄复命。"}]])
R(746,"矮人的挖掘场",[[description="西北部有些矮人正在准备修建一座挖掘场。他们认为地下埋藏着某些秘密，事实也的确如此，不过挖掘和污染大地并不是获得这些秘密的正确途径。$B$B收集矮人的挖掘工具，把它们全都毁掉，然后把这些被损坏的工具带给我。$B$B要毁掉这些工具的话，你必须得找到一块铁砧才行。在雷霆崖就有一处铁匠铺，不过任何铁砧——包括矮人营地里的——都可以用来毁掉工具。",objectives={"收集5个勘察员的锄头。$B$B在铁匠铺砸碎这些勘察员的锄头。$B$B把5件损坏的工具交给血蹄村的贝恩·血蹄。"}]])
R(747,"开始狩猎",[[description="欢迎来到纳拉其营地，$n。你来到这里的消息很快就传遍了部族。或许很快有一天你会被迎去雷霆崖上的大城市里，但首先，你必须先向我们证明你的能力。$b$b我们这些生活在红云台地上的牛头人无疑对自己优秀的狩猎技术最为自豪，当然，牛头人只为生存需要和竞技而狩猎。我们库存的肉已经不多了，另外我们还需要羽毛来做衣服。现在去猎杀附近的平原陆行鸟来给村庄提供补给吧，同时你也可以借此证明自己的能力。",objectives={"纳拉其营地的格鲁尔·鹰风要求你带给他7片平原陆行鸟的羽毛和7块平原陆行鸟肉。"}]])
R(748,"毒水",[[description="那些地精和他们的爪牙污染了我们神圣的水井！我们必须制止他们！$B$B要想净化所有的水井，我得先制造出相应的净化图腾，然后你把图腾拿到水井那儿去完成净化的仪式。$B$B首先，我们给冰蹄之井制作一个净化图腾，这需要大地的帮助。去猎捕一些草原狼和成年平原陆行鸟，把它们的爪子带回来给我，它们就在西南方活动。",objectives={"收集6只草原狼的爪子和4只平原陆行鸟的爪子，把它们交给血蹄村的穆尔·雷角。"}]])
R(749,"被破坏的货车",[[description="几天前，我们在石牛湖北岸发现了有一个被重兵保护着的风险投资公司的马车。我们在先前的战斗里已经失去了两个同伴，所以我们就把怒气倾泻在这辆马车身上，速战速决地把它给摧毁了。$b$b我们没去管他们的储物箱，满以为一把火就可以把这些东西和马车一起烧成灰。不过有人在那辆熊熊燃烧的货车附近看见了风险投资公司的抢救人员，那些箱子可能没被烧掉。$b$b也许你可以去那辆货车旁，看看箱子里面到底是什么。",objectives={"摩林·云行者要你去查看被破坏的货车附近的储备箱里有什么东西。"}]])
R(750,"继续狩猎",[[description="善于狩猎的牛头人从不仅仅将他的猎物看作战利品，这些生活在平原上的野兽对我们的生存有着极为重要的意义。如果你能带回一些珍贵的山狮皮的话，就会令部族里的长老们对你刮目相看。你可以在南边的山区找到它们。$b$b我们的孩子需要衣服，部族里的帐篷也需要维修了。",objectives={"纳拉其营地的格鲁尔·鹰风要求你带给他10张山狮皮。"}]])
R(751,"被破坏的货车",[[description="撬开盖子之后，你发现了堆得满满的矿石，这又一次证明了风险投资公司确实在莫高雷地区有采矿活动。在矿石的最上面有一捆文件。$b$b你可以依稀听见东部丘陵的顶部传来丁丁当当的声音，还可以看见从一大堆篝火上升起的浓烟。",objectives={"把风险投资公司文件交给血蹄村附近的摩林·云行者。"}]])
R(752,"一件琐事",[[description="我们部族的所有成员都过着完美和谐的生活，我们一起劳作，一起生活。$b$b部族中的每个成员都对其他人负有义务，并且我们总是将这些义务放在首位。现在我需要你帮我做一件麻烦的事情。$b$b我的母亲今天早上去纳拉其东南方的水井中取水，她已经去了很久了。你能不能替我去看看？部族里的事务让我实在抽不开身。",objectives={"鹰风酋长要求你去纳拉其营地东南方的水井处寻找他的母亲。"}]])
R(753,"一件琐事",[[description="我这一生也算是经历了不少磨难，走了不少路，现在我这一把老骨头也没什么力气啦。我仍然在为部族尽力，但有些时候，我还真感觉有些力不从心。$b$b不过，你这$c似乎是正想找点什么事情做做呀。正好，让我来看看你的体力如何吧。把水井旁的这个水罐交给我儿子，他就在纳拉其营地里。$b$b记住，即使是最琐碎的小事，只要你做得够好，也能获得长老们的首肯。",objectives={"在井边拿一只水罐。$b$b把它带给纳拉其营地里的鹰风酋长。"}]])
R(754,"净化冰蹄之井",[[description="我已经做好了可以净化冰蹄之井的图腾。现在你就把它拿到那儿去完成净化仪式。冰蹄之井就在东南边，有许多地精把守着那里！$B$B这不是个简单的任务，不过如果我们想要重新使用那里的水，就必须得这么做。$B$B祝你好运，$N。",objectives={"用冰蹄之井净化图腾为冰蹄之井完成净化，然后回来见穆尔·雷角。"}]])
R(755,"大地之母仪祭",[[description="你愿意为纳拉其的牛头人做这样琐碎的小事，同时又渴望学习新的知识，这足以说明你有着高贵的品质，$n。我相信总有一天你会成为一位在雷霆崖赫赫有名的$c。$b$b不过在那之前，你必须首先完成大地之母仪祭，这个伟大的传统共由三个不同的试炼组成。$b$b第一个试炼是力量之仪祭。去找灰舌先知，告诉他是鹰风酋长派你去的。$b$b翻过纳拉其营地正南方的山后，你就可以找到他的居所了。",objectives={"找到居住在纳拉其营地正南方山中的灰舌先知。"}]])
R(756,"雷角图腾",[[description="要制作雷角之井净化图腾，你必须先去收集莫高雷平原上的肉食动物的爪子。去捕猎草原捕食者和平原狮，然后把它们的爪子带回来见我。$B$B它们就在这里的东边和西边活动。",objectives={"收集6个草原捕食者的爪子和6个平原狮的爪子，把它们带给穆尔·雷角。"}]])
R(757,"力量仪祭",[[description="大地之母仪祭对于每一个想要在雷霆崖得到尊重的年轻牛头人来说都是非常重要的。$b$b但在那之前，你必须先通过力量仪祭的试炼。在这个试炼中，你必须通过杀死部族的敌人来证明你的勇猛。$b$b生活在东边的刺刃峡谷中的刺背野猪人侵占了我们部族不少的土地，他们偷袭我们的狩猎小队，还在晚上到村子里来偷东西。$b$b杀死他们，展示出你的英勇无畏吧。拿着它们的腰带去见纳拉其营地的酋长，他将证明你通过了试炼。",objectives={"杀掉刺刃峡谷的刺背野猪人并带回12条刺背腰带，把它们交给纳拉其营地的鹰风酋长。"}]])
R(758,"净化雷角之井",[[description="图腾已经准备好了，$N。这一次还是由你来完成净化仪式。$B$B到村庄北面的雷角之井去，用雷角之井净化图腾完成净化仪式，然后再回来找我。$B$B愿大地之灵指引你。",objectives={"在雷角之井使用雷角之井净化图腾，然后回来见穆尔。"}]])
R(759,"蛮鬃图腾",[[description="还剩下一口井需要净化，它是以蛮鬃部族的名字命名的。要想净化这口井，你必须从大地上寻找一种凶猛的肉食动物的牙齿，那就是草原狼前锋的牙齿。去北边寻找草原狼前锋，拿到我要的东西之后再回来。$B$B这些草原狼前锋经常在雷霆崖的山脚下游荡。",objectives={"收集8颗草原狼前锋的牙齿，把它们交给血蹄村的穆尔·雷角。"}]])
R(760,"净化蛮鬃之井",[[description="你净化冰蹄之井和雷角之井的事迹已经被广为传诵了，年轻的$N。我也已经做好了蛮鬃之井净化图腾，接下来这就是你的最后一个任务了。$B$B蛮鬃之井在雷霆崖的北面，到那里完成净化仪式吧，拯救这片被地精污染的土地，让这片土地上的生灵再次畅饮甘甜纯净的井水！",objectives={"在蛮鬃之井使用蛮鬃之井净化图腾，然后回来见穆尔·雷角。"}]])
R(761,"猎捕猛鹫",[[description="猛鹫是一种狡猾无比、很难猎捕的鸟。收集猛鹫的羽毛可以证明一个猎手的智慧和决心。$B$B如果你想接受这个任务，就去平原上猎捕猛鹫吧。$B$B把它们的羽毛带给我，为你的部族赢得荣誉。$B$B猛鹫在莫高雷的任何地方都能找到，不过要发现它们，你得有锐利的眼睛；要捕捉它们，你得有灵活的手脚。",objectives={"收集8根猛鹫的羽毛，把它们带给血蹄村的哈肯·风之图腾。"}]])
R(762,"邪恶的使者",[[description="拉格纳罗斯派因弗努斯大使到苦痛堡垒去监督暗炉矮人在奥达曼挖掘神器的工作。$B$B我们的同胞已经遭受了惨重的伤亡，然而这样的情况仍然在继续。我不愿去猜测他们会找到多少强大的神器并用它们来对付铁炉堡。$B$B我们的目的很简单，$c。回到荒芜之地去，干掉因弗努斯大使。在除掉了这个威胁之后，把你完成任务的证据交给顾问贝尔格拉姆。$B$B现在马上出发吧。",objectives={"杀死苦痛堡垒中的因弗努斯大使，把证明他已死亡的信物交给铁炉堡的顾问贝尔格拉姆。"}]])
R(763,"大地之母仪祭",[[description="要想继续大地之母仪式，你必须先通过两个小试炼。现在也正好是你去积累积累经验的时候了，$n。$b$b到血蹄村去找那里的酋长，凯恩之子贝恩·血蹄吧。你可以在那儿继续你的冒险历程并得到雷霆崖的长老们的承认。$b$b把这个图腾带给贝恩。他会读懂我刻在上面的符号，并帮助你继续修行。$b$b顺着这条从纳拉其营地通向外面的路快点出发吧，千万别迷路了。",objectives={"顺着离开纳拉其营地的路将鹰风图腾带给血蹄村的贝恩·血蹄。"}]])
R(764,"风险投资公司",[[description="这就解释了为什么风险投资公司在不断往莫高雷地区增派职员和设备。这些地精……他们的公司扩张得太快了。就像他们自己所说的那样，只要给地精一点甜头，你就能听到他们打算盘的声音。$b$b这些小东西实在是太贪婪了。不过我们牛头人决不会让他们在我们的领土上为所欲为。到他们的矿洞去，给他们点颜色看看，那个矿洞就在被破坏的货车的东北方。",objectives={"血蹄村的摩林·云行者要你去杀死14个风险投资公司工人和6个风险投资公司主官。"}]])
R(765,"菲兹普罗克主管",[[description="根据你从箱子里拿来的文件可以看出，风险投资公司已经制定了很多把我们从这儿赶走的计划，然后他们就能随心所欲地掠夺我们的土地了。$b$b他们为了利润居然可以堕落到这种程度，这简直让我感到厌恶和惊骇。我们要除掉这个阴谋的策划者，他就是菲兹普罗克主管。你可以在被破坏的货车以东的风险投资公司矿洞里找到他，把他的笔记板带给我，让我们看看有没有什么有价值的东西。",objectives={"杀掉菲兹普罗克主管，把他的笔记板带给血蹄村的摩林·云行者。"}]])
R(766,"马兹拉纳其",[[description="我祖父曾讲述过他和一只叫马兹拉纳其的陆行鸟战斗的故事，说起过它那邪恶的红眼睛，剃刀般锋利的爪子，只要被它咬一口，你就会身中剧毒。$b$b在我穿越平原的时候，正巧遭遇了它，肩膀被它咬了一口。它比我祖父所说的还可怕！我需要一些东西来帮我解毒：一颗狼心，狮子的腿骨，平原陆行鸟的鳞片和猛鹫的胃。$b$b快点，我快要不行了。",objectives={"收集草原狼的心脏、平原狮的腿骨、平原陆行鸟的鳞片和猛鹫的胃各一份，把它们交给血蹄村的茂尔·祈雨。"}]])
R(767,"幻象仪祭",[[description="作为大地之母仪祭之一的幻象仪祭可以指引你最终赢得雷霆崖长老们的尊重。$b$b我们早已认识到，土地就是我们最神圣的生命之本。如果你准备好要进行幻象仪祭的话，就得去和村里的精神领袖扎尔曼·双月谈一谈。",objectives={"和血蹄村的扎尔曼·双月谈一谈。"}]])
R(768,"收集皮革",[[description="你好，年轻的$r。我从你的眼中看到了你重回原野捕猎的渴望。希望你能为你的部族带来荣耀！$B$B我擅于利用各种兽皮来为雷霆崖的居民制作护甲和衣物。$B$B如果你能帮我搞到一些兽皮的话，那我就可以用它们来为你制作一些你需要的东西。",objectives={"收集12块轻皮，把它们交给雷霆崖的维尔伦·陆行者。"}]])
R(769,"科多兽皮包",[[description="莫高雷的科多兽强壮而凶猛，它们的这些特质备受我们尊敬。如果你善于皮革加工，而且希望获得制作科多兽皮包的知识，那就给我弄点材料来吧。$B$B弄些材料来，我就会把我的手艺传授给你。",objectives={"给雷霆崖的维尔伦·陆行者带去4块轻皮和4份粗线。"}]])
R(770,"恶魔之伤",[[description="鬼嚎那粗糙的毛皮上还留着一个可怕的伤口，是在它与燃烧军团的战斗中留下的。$B$B也许你应该把鬼嚎的死讯告诉血蹄村里的什么人……",objectives={"去打听打听谁听说过鬼嚎。"}]])
R(771,"幻象仪祭",[[description="要想通过幻象仪祭，你必须先找到制作先知之水的试剂。$b$b我需要一些水井石，你可以在莫高雷一带的水井附近找到它们。另外，你还得在这周围的大树下面找到一些琥珀颗粒。$b$b这两种东西都具有强大的元素力量，把它们结合起来，用部族之火点燃之后，你可以看到一个幻象。追随它，它就会引领你进入这个神圣使命的下一个阶段。",objectives={"收集2块水井石和2个琥珀颗粒，把它们带给血蹄村的扎尔曼·双月。"}]])
R(772,"幻象仪祭",[[description="现在，我把神圣的先知之水交给你。$b$b准备好了之后，就去部族之火旁把水喝下，然后稍等片刻，一个幻象就会出现在你的眼前。$b$b你必须立刻决定是否要追随这个幻象……",objectives={"在血蹄村的部族之火前将先知之水喝下，当幻象出现之后跟随它。"}]])
R(773,"智慧仪祭",[[description="要让雷霆崖的资深长者接受你，你就必须再完成大地之母仪祭的下一个阶段：智慧仪祭。$b$b你已经通过了幻象仪祭，赤色石的先祖之魂会祝福你的，只有那些喝过先知之水的人才能得到这种祝福。$b$b向雷霆崖的东面去，到赤色石寻找先祖之魂吧。",objectives={"到雷霆崖东边的赤色石去和先祖之魂谈一谈。"}]])
R(774,"<UNUSED>")
R(775,"雷霆崖之旅",[[description="任何能够完成大地之母仪祭的$r都可以赢得整个雷霆崖的尊重。$b$b你的最后一个任务是去见见我们的伟大首领凯恩·血蹄，他就住在雷霆崖最高的那座台地上。",objectives={"和雷霆崖的凯恩·血蹄谈一谈。"}]])
R(776,"大地之母仪祭",[[description="你已经通过了大地之母仪祭，在雷霆崖赢得了你自己的一席之地。$b$b不过要维持你现在获得的荣誉，你还必须不断证明你自己的价值。$b$b我们生来就是猎手，$n。在莫高雷城下有一只非常强大的科多兽，我们称它为阿兰其亚。把它的角带来，向我证明你追踪和捕猎的能力。",objectives={"雷霆崖的凯恩·血蹄要你将阿兰其亚的角带给他。"}]])
R(777,"不祥的感觉",[[description="好吧，拿去吧。$B$B我现在要去找个掩体……$B$B你要不要一起来？",objectives={"把5号齿轮交给鲁特维尔·沃拉图斯。"}]])
R(778,"不祥的感觉",[[description="哈哈！完成啦！镣铐完成啦！$B$B记住这个时刻，卢希恩,记住这个时刻，阿布！你准备好了吗？你将亲眼看见炼金术、工程学和魔法的完美结合。$B$B我将召集一个强大的元素生物。今天，对于我们来说，是具有里程碑意义的一天！",objectives={"击败法姆雷托守护者，并将鲁特维尔的元素禁锢镣铐交还给鲁特维尔。"}]])
R(779,"大地封印")
R(780,"斗猪",[[description="生活在东边的刺刃峡谷中的斗猪已经侵占了我们部族的狩猎场。正在与我们交战的刺背野猪人把这些野猪训练成了凶暴而富有攻击性的生物。$b$b去把这些可恶的家伙杀掉，再带些猪头和肋排回来，我们可以炖肉给孩子们吃。",objectives={"纳拉其营地的格鲁尔·鹰风要求你去干掉斗猪，并带给他4块斗猪头和4块斗猪肋排。"}]])
R(781,"纳拉其营地的危机",[[description="在仔细查看了地图之后，你意识到刺背野猪人的酋长正计划着对纳拉其营地展开进一步攻击。$b$b鹰风酋长必须马上得知这个消息。",objectives={"将刺背野猪人的进攻计划交给纳拉其营地的鹰风酋长。"}]])
R(782,"破碎的联盟",[[description="在第二次兽人战争期间，部落与死亡之翼之间曾有过盟约，我们也因此得知死亡之翼的两个副手——黑龙布莱克拉什和赫玛图斯——现在正被囚禁在莱瑟罗峡谷里。$b$b如今我们要让堕落的昔日盟友们“安静”一点，我们要恢复部落的荣耀。我们雇佣了索格伦和他的食人魔雇佣兵团帮我们夺回大地印章，也就是那把可以打开黑龙监狱的钥匙。$b$b然而，索格伦背叛了我们，他打败了我们，将大地印章占为己有。",objectives={"杀掉索格伦，把大地印章交给卡加斯的高恩。"}]])
R(783,"身边的危机",[[description="我希望你已经整装待发了，年轻的$c。北郡需要你的帮助！$B$B当然，我不是在说让你去耕田种地之类的。$B$B暴风城的卫兵们努力地维持着这里的和平，但我们人手短缺，更多的危险还在不断迫近。我们正在招募愿意出力保卫家乡和联盟的人。$B$B如果你也是应招而来的话，请和我的上级——治安官玛克布莱德谈谈。他就在我身后的这座修道院里。",objectives={"与治安官玛克布莱德谈一谈。"}]])
R(784,"背信弃义的人类",[[description="库尔提拉斯的人类曾在普罗德摩尔将军的率领下大举进攻杜隆塔尔，彻底破坏了在共同抵抗阿克蒙德和他的恶魔大军时由酋长和吉安娜·普罗德摩尔定下的互不侵犯协议。$b$b我们击退了人类的进攻，并攻下了提拉加德城堡。但最近，由本尼迪克上尉率领的后备军又重新占领了提拉加德城堡，对我们的家园构成了新的威胁，这些人类从不遵守外交协议。$b$b到南方的提拉加德城堡去消灭那些人类侵略者，证明你的勇气和荣誉。",objectives={"杀死10个库尔提拉斯水手和8个库尔提拉斯水兵，再把本尼迪克上尉干掉，然后回剃刀岭向加索克复命。"}]])
R(785,"A Strategic Alliance",[[description="Thrall is a most wise and noble leader. His tenacity on the battlefield is matched only by his diplomatic tact.$b$bThe Darkspear Trolls have proven to be invaluable allies to orckind. Out of loyalty and honor we have sworn a pact of protection with them.$b$bThe Warchief has sent orders to make sure our Darkspear friends in Sen'jin Village are not under any direct threat. One of their most trusted scouts, Lar Prowltusk is keeping a close watch on their western flank.$b$bSeek out Lar and assist as needed.",objectives={"Seek out Lar Prowltusk on the western flank of Sen'jin Village."}]])
R(786,"科卡尔半人马的进攻",[[description="小声点，$c。科卡尔半人马就在西边科卡尔峭壁的山脊上。$b$b昨天晚上，我潜入了他们的村庄，发现这些肮脏的野兽准备同时向杜隆塔尔的巨魔和兽人发动三波攻势。$b$b我们决不能让他们的入侵计划得逞！你可以召集一些兵力，潜入科卡尔峭壁并粉碎他们的进攻计划。$b$b他们已经把进攻计划分别交给了三个首领，准备由他们率领三股部队同时行动。",objectives={"在森金村外面的拉尔·猎齿要求你粉碎科卡尔峭壁内的三份进攻计划。"}]])
R(787,"新的部落",[[description="向你致意，$c。我是伊崔格，奉萨尔酋长的命令在此负责招募新兵。$b$b部落已经不再是从前的那个部落了。我曾经离开过部落，在那段时间里，我受到燃烧军团的蛊惑而迷失了自我。在被放逐后，我被一群人类抓去当了俘虏，但最终被我们伟大的酋长救了出来。在酋长那拯救部落的远大志向的指引下，在萨满祭司的教诲之下，我回来了。$b$b高内克会给你进一步的指示。",objectives={"向大兽穴里的高内克报到。"}]])
R(788,"小试身手",[[description="第一项任务将在力量方面对你进行考验。我本来可以把你派去贫瘠之地猎杀科多兽，不过呢，照实说，你活着比死了对我们来说更有用。$b$b我相信你更合适和那些杂斑野猪斗一斗，往北边走就可以找到它们。",objectives={"杀掉10只杂斑野猪，然后向大兽穴里的高内克报告。"}]])
R(789,"工蝎的尾巴",[[description="无论是强大的战士还是笨拙的新手，都有可能会倒在蝎尾上的毒针之下。在这里的西北方有大量蝎子在活动，给我带10条蝎尾回来，以此来证明你的战斗能力吧。$b$b事实上，它们尾巴上的毒针正是制作解毒剂的重要材料，解毒剂便是从毒针中提取的。我们需要长期备有大量的解毒剂，以防止像你这样的新手被蝎毒所害……$b$b但我肯定你是不会需要这种玩意的，对吧？",objectives={"给大兽穴中的高内克带回10根工蝎的尾巴。"}]])
R(790,"萨科斯",[[description="$C！我差点就神不知鬼不觉地死在这鬼地方了！我在谷里捕猎蝎子的时候，突然看到一只看上去特别凶恶的蝎子。当时我就决定以它为猎物，打算在它那硕大的钳子钳住我的腿以前，先重重地给它来上那么一下子。$b$b但我忘记了它还有根毒刺，毒刺猛扎了下来，一下子就刺进我的胸口。拜托，你一定得替我报仇！只有这样才能留存我的名誉！我是在南边的高地上碰上它的。",objectives={"杀死萨科斯并将它的爪子带回去交给哈纳祖。"}]])
R(791,"新的背包",[[description="我太老了，已经没法上战场拼杀了。所以我开始用别的途径为部落出力，实现我的价值。$b$b我在这里监视周围的情况，我们的力量越来越强大，我吹起号角的机会也越来越少。$b$b为了打发时间，我经常给那些保卫家园的年轻战士们做些有用的东西。$b$b我可以给你做一个用来放置财物的包袱，但是你得先给我找些帆布脚料来，人类和半人马经常使用这种布料。",objectives={"剃刀岭了望塔中的弗恩·凝眉想要8块帆布脚料。"}]])
R(792,"邪灵劣魔",[[description="我相信你会在试炼谷学到很多东西，年轻的$c。$B$B我本是被派到这处谷地里来指引和教育你们的，但我却在这里发现了一些不洁之物……$B$B一群自称为火刃氏族的兽人潜入了试炼谷，他们躲进了东北方的一处洞穴里，而他们的邪灵劣魔则肆虐着周边的一大片地区。$B$B作为你对抗火刃氏族的第一个任务，我命令你消灭这些劣魔。尽可能地多杀一些，如果杀完了它们之后你还活着的话，就回来向我复命。",objectives={"杀死12只邪灵劣魔，然后向大兽穴外的祖雷萨复命。"}]])
R(793,"破碎的联盟",[[description="大地印章由三块符石控制，它们分别被放置在莱瑟罗峡谷的钻石柱、玛瑙石柱和紫水晶石柱中。用大地印章就可以取下符石并打开大地封印。$b$b当心点，$n，黑龙布莱克拉什和赫玛图斯是很难对付的。杀掉它们，把它们身上的锁链交给我。",objectives={"用大地印章激活钻石柱、玛瑙石柱和紫水晶石柱并拿到三颗符石。$b$b把符石放在大地封印上，释放黑龙布莱克拉什和赫玛图斯。$b$b杀了这两条黑龙，把黑龙布莱克拉什的锁链、赫玛图斯的锁链和大地印章交给高恩。"}]])
R(794,"火刃奖章",[[description="我通过预言术发现在火刃集会所的深处藏有一件蕴涵着强大力量的物品，它被一些猛兽和黑暗的魔法守卫着。$B$B那件物品叫作火刃奖章，你的下一个任务就是找到它，把它从集会所里偷出来。$B$B不过你可得小心，因为奖章的所有者可能是一个火刃部落中的强者，他也许要比你以前对付过的那些家伙要强上许多倍。$B$B现在就出发吧，$N，那个洞穴就在这里的西北方。",objectives={"给大兽穴外的祖雷萨带回火刃奖章。"}]])
R(795,"大地封印")
R(796,"<UNUSED>")
R(797,"<UNUSED>")
R(798,"<UNUSED>")
R(799,"<UNUSED>")
R(800,"<UNUSED>")
