R(3085,"神圣石板",[[description="啊，刚刚你不在的时候，有人送来了这块石板，$N。$B$B如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这块石板是牧师训练师肯杰写的，他有事找你。",objectives={"阅读神圣石板，然后和试炼谷大兽穴外的肯杰谈一谈。"}]])
R(3086,"雕文石板",[[description="啊，刚刚你不在的时候，有人送来了这块石板，$N。$B$B如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这块石板是法师训练师迈安写的，她有事找你。",objectives={"阅读雕文石板，然后和试炼谷里大兽穴入口附近的迈安谈一谈。"}]])
