R(7886,"功勋奖章",[[description="You have proven your value to our efforts in Warsong Gulch. Continue to aid the cause and bring me more talismans of merit. Do this, and you will earn even more of our trust.",objectives={"You obtained a Silverwing Talisman of Merit for your last task, talk to me again, and you gain your reward."}]])
R(7887,"功勋奖章",[[description="你已经证明了自己在战歌峡谷中的价值!继续帮助我们作战，并给我带来更多的功勋奖章。我们会因此而更加信任你。",objectives={"您为上一个任务获得了银翼功勋奖章，再次与我交谈，您将获得奖励。"}]])
