R(8118,"巫毒幻象")
R(8119,"完美巫毒幻象")
R(8120,"阿拉希盆地之战！",[[description="无疑你已经听说了，阿拉索联军正派大量的军队进驻阿拉西盆地。联盟那帮蠢货想要食物和补给，因此妄图占据这块富饶的土地。我们必须让他们知道阿拉希永远不再会是人类的家园了！$B$B去阿拉希盆地然后进攻那里矿井，伐木场，铁匠铺和马厩。夺下敌人在那里的旗帜，把那里变成部落的领土。$B$B出发吧，$N。当任务完成之后向我复命。",objectives={"进攻阿拉希盆地的矿洞、伐木场、铁匠铺和兽栏，然后向落锤镇的屠杀者杜维尔复命。"}]])
R(8121,"夺取四座基地",[[description="$N，随着阿拉希盆地的战事进展，你的事迹已经传遍了战场。你的所做所为让我确信你一定可以完成现在我要给你的任务。$B$B现在是给阿拉索联军一个信号的时候了。我们将会向他们展示，他们在阿拉希盆地的防守是多么脆弱。我们要通过同时占领阿拉希盆地的四个战略点来让他们明白这一点。$B$B如果你可以完成这个任务，$N，你将赢得污染者的尊敬。",objectives={"同时占据阿拉希盆地中的四座基地，然后向落锤镇的屠杀者杜维尔复命。"}]])
R(8122,"夺取五座基地",[[description="我们其实已经深深陷入战争之中，只是我们还没有意识到。幸好，我们的探子回报说发现了阿拉索联军的弱点。我们必须利用这一机会对他们造成致命一击！回到阿拉希盆地，和我们的敌人交战吧。诅咒他们，干掉他们，控制所有的五个战略点！让他们的士兵尖叫，流血，从前线仓皇撤退，让他们用抽泣的嘴唇述说你的事迹。$B$B完成这一目标，为污染者带来光辉的胜利。",objectives={"同时占据阿拉希盆地中的五座基地，然后向落锤镇的屠杀者杜维尔复命。"}]])
R(8123,"切断阿拉索补给线",[[description="阿拉索联军正在不惜一切代价进攻阿拉希，并妄图夺回这个区域。联盟的各个种族正在全力进军这块遥远的土地，想要将他们的势力从避难谷地扩张到这里。我们必须阻止他们，而最好的方式就是夺取他们的资源。$B$B你可以帮助我们，$N。进入阿拉希盆地，那里遍地都是丰富的矿藏、肥沃的土地和技艺精湛的能工巧匠。占据并控制你找到的所有基地，赢得战斗，然后把你获得的资源给我拿回来。",objectives={"进入阿拉希盆地，获得一箱阿拉希资源箱，然后将它交给落锤镇的亡灵哨兵莫提斯。"}]])
R(8124,"更多的资源",[[description="阿拉索联军正在不惜一切代价进攻阿拉希，并妄图夺回这个区域。联盟的各个种族正在全力进军这块遥远的土地，想要将他们的势力从避难谷地扩张到这里。我们必须阻止他们，而最好的方式就是夺取他们的资源。$B$B你可以帮助我们，$N。进入阿拉希盆地，那里遍地都是丰富的矿藏、肥沃的土地和技艺精湛的能工巧匠。占据并控制你找到的所有基地，赢得战斗，然后把你获得的资源给我拿回来。",objectives={"进入阿拉希盆地，获得一箱阿拉希资源箱，然后将它交给落锤镇的亡灵哨兵莫提斯。"}]])
