R(8446,"梦魇的缠绕",[[description="这东西了渗出堕落的力量。$B$B它和来自翡翠梦境的龙类或许有些关系。你必须找到能解读这东西的人。或许月光林地或是塞纳里奥要塞的德鲁伊能帮助你。",objectives={"寻找能解读梦魇包裹的物品中所隐藏的信息的人。$B$B或许拥有强大力量的德鲁伊可以帮助你。"}]])
R(8447,"唤醒传说",[[description="月神湖的湖水可以融解这东西里面的梦魇。给我点时间来净化它吧，$N。",objectives={"等待月光林地的守护者雷姆洛斯净化梦魇包裹的物品。"}]])
R(8458,"<UNUSED>",[[description="I believe I can find this demon lord given the proper reagents.$B$BIf he is indeed as powerful as I suspect, I will need items gathered from deadly creatures. But you act in the Warchief's name, so I am sure you will accept my task.$B$BFirst, I will have to break any wards he has against scrying. For this, I will need the scalp from a satyr--but not any satyr. The scalp must come from a Hatefury shadowstalker.$B$BSearch for them among the ancient ruins in the northeast of Desolace.",objectives={"Bring a Shadowstalker Scalp to Maurin Bonesplitter in Desolace."}]])
R(8459,"<UNUSED>",[[description="Description",objectives={"Log"}]])
R(8460,"木喉熊怪的盟友",[[description="木喉部族是唯一没有被堕落力量污染的熊怪部族。然而，许多其他的种族盲目地屠杀熊怪，却并没有搞清他们是敌是友。因此，木喉熊怪很少相信别人。$B$B你想要证明自己的立场吗？去赶走腐化的死木部族，我们以后也许会接受你成为盟友。你可以在费伍德的南部找到死木战士、探路者和园丁。",objectives={"格拉兹要你去杀死6个死木战士、6个死木探路者以及6个死木园丁。"}]])
R(8461,"北方的死木熊怪",[[description="此地西南方向有一处死木熊怪的营地。我不清楚他们想要干什么，但是我希望能在他们开始捣乱之前就结果他们。$B$B死木部族非常邪恶，是恶魔的力量侵蚀了他们的心智。他们的天性并不坏，但是现在一切都无法挽回了。因此，我对被迫与自己的同胞作战感到非常悲哀。$B$B$N，去结果他们吧，别对我说起战斗的具体过程，我不忍心听到那些。",objectives={"格拉兹要你去杀死6个死木守卫、6个死木复仇者和6个死木萨满祭司。"}]])
R(8462,"与纳菲恩交谈",[[description="也许你可以帮助我们木喉部族应付我们正在遭受着的更大的威胁。你一定可以在这里展示自己的能力……$B$B在木喉要塞另一头站着一个我的同类，就沿着这条路去背面。他的名字叫纳菲恩；虽然他看上去是很凶猛和令人讨厌的野兽，但是你不要害怕。他只是在寻求帮助来对抗那些威胁我们家园的力量。",objectives={"沿着费伍德森林的路向北走，与一个名叫纳菲恩的熊怪谈谈。他站在木喉要塞的入口处。"}]])
R(8464,"冬泉熊怪的活动",[[description="木喉部族倾向于防守，$N。虽然我们允许那些值得信赖的朋友安全地通过，但我们还是尽可能地避开其他熊怪部族。$B$B最近我注意到冬泉部族与我们的敌对情绪有所增长。他们似乎处于极度愤怒的状态，完全陷入了对一切他们无法理解的事物的恐慌和仇视。$B$B如果你能削减他们的数量，那对我们来说将是莫大的帮助，$N。",objectives={"萨尔法要你去杀死8个冬泉萨满祭司、8个冬泉巢穴守卫和8个冬泉巨熊怪。萨尔法就站在冬泉谷的木喉要塞入口处。"}]])
R(8465,"与萨尔法交谈",[[description="除了来自南面的死木熊怪的堕落威胁之外，东面的冬泉熊怪同样也同样是我们的心头大患。如果你愿意继续帮助我们的话，就去和要塞另外一头的萨尔法谈谈吧。沿着左边的这条路一直走下去。$B$B你要小心，如果我里面的兄弟对你表示敌意，他们也许会攻击你。尽快通过那里，避免纠纷。你每杀死一个木喉熊怪——即便是出于自卫——都会极大地降低你在木喉熊怪中的声望。",objectives={"穿过木喉要塞去冬泉谷。和萨尔法谈谈，他就在木喉要塞另一头的出口处。"}]])
R(8466,"给格拉兹的羽毛")
R(8467,"给纳菲恩的羽毛")
R(8469,"给萨尔法的珠串")
R(8470,"死木仪祭图腾",[[description="你找到了一根死木仪祭图腾。图腾本身没有什么雕刻的痕迹，但是它却散发出一种让人绝望的气息。如果有什么东西导致了死木熊怪的堕落的话，那么这件东西应该就是罪魁祸首了。$B$B木喉要塞中的某个熊怪一定对它有兴趣……当然，你首先需要在他们当中赢得一定的声望。",objectives={"把死木仪祭图腾拿到木喉要塞去，看看是否有熊怪想要研究一下它。只有当你在木喉要塞的声望达到中立或者更高级别的时候，木喉要塞的熊怪才会和你说话。"}]])
R(8471,"冬泉仪祭图腾",[[description="你找到了一根冬泉仪祭图腾。图腾本身没有什么雕刻的痕迹，但是它却散发出一种让人绝望的气息。如果有什么东西导致了冬泉熊怪的堕落的话，那么这件东西应该就是罪魁祸首了。$B$B木喉要塞中的某个熊怪一定对它有兴趣……当然，你首先需要在他们当中赢得一定的声望。",objectives={"把冬泉仪祭图腾拿到木喉要塞去，看看是否有熊怪想要研究一下它。只有当你在木喉要塞的声望达到中立或者更高级别的时候，木喉要塞的熊怪才会和你说话。"}]])
R(8481,"万恶之源",[[description="$N，感谢你的帮助，我们已经找到了致使冬泉部族堕落的根源——有一个堕落的恶魔正在控制着他们！$B$B把这支火炬拿到冬泉酋长所在的山洞去，然后放在那里。这样就可以让那个恶魔现身。此时你和你的盟友就要把它击倒！只有使用恶魔身上的精华才能帮助我们进行治愈冬泉部族的工作……最终解除他们对木喉要塞的威胁。",objectives={"把恶魔召唤火炬放在寒水村的冬泉酋长的洞穴入口处。击败召唤出来的恶魔，然后把沙迪维尔斯精华交给木喉要塞的独眼高恩。"}]])
R(8484,"重铸和平",[[description="你的事迹已经远远超过英雄的范畴，$N。如果你代表了你的人民，那么我们一定会努力和你的人民保持和平。$B$B请你把这个交给住在钢铁之山中的那位矮人国王，我想你们把那里叫做铁炉堡。过去，他曾经代表联盟试图和我们建立联系。现在我们需要依赖你来实现木喉部族与联盟之间的和平。",objectives={"将木喉和平契约交给铁炉堡的国王麦格尼·铜须。"}]])
R(8485,"重铸和平",[[description="你的行为超越了平凡英雄的故事，$N。若你是你们人民的代表，那么，你们人民都将成为我们为了维持和平而努力的伙伴。$B$B请将这项提议带给兽人酋长，他就住在杜洛塔群岛，我知道你们都称这座城为奥格玛。很久以前，他曾试着代表他的部落和我们接触，现在正是通知你的时候，你将代表你部落的努力成果进行和平斡旋。",objectives={"带回木喉和平契约给奥格玛的索尔。"}]])
R(8492,"联盟需要铜锭！",[[description="你好，$c，看来你很合适为我们的备战计划做出点贡献！我们欢迎一切帮助来准备安其拉之战。$B$B为了这样一件有意义的事情，我正在收集20块一组的铜锭。你觉得怎么样？",objectives={"把20块铜锭交给铁炉堡军事区的布罗恩·石眉。"}]])
R(8493,"联盟需要更多铜锭！",[[description="又回来了$c？太好了！我们需要更多你从安其拉之战取得的铜锭。你会帮我们吗？",objectives={"带20个铜锭给丹莫洛飞机场的石眉中尉。"}]])
R(8494,"联盟需要铁锭！",[[description="你好，$g先生:小姐;，你不是传说中云游四海，无所不知的那种冒险者吗？最近的事情你都不知道？联盟正在准备对安其拉发动战争，我们需要大量的铁锭，越多越好。把它们带给我，每20块一组。我们会在功劳薄上为你记上一笔，怎么样，$c？",objectives={"把20块铁锭交给铁炉堡军事区的卡恩斯下士。"}]])
R(8495,"联盟需要更多铁锭！",[[description="这么快就回来了？不要让我再重新评估对你不好的看法$c，你让我觉得很感伤。那么，你知道我们仍然没有足够的铁锭供应武器、护甲、蒸气坦克和搜寻故障所有需要的东西。你觉得你可以在去祖尔格拉布的路上，或是你们这些孩子现在鬼混的地方带回另一批20个铁锭吗？",objectives={"带20个铁锭给丹莫洛飞机场的卡恩斯下士。"}]])
R(8496,"战场上的绷带",[[description="我们的绷带储备在最近接连不断的战事之后急剧降低。收集大量的急救物资，把它们交给塞纳里奥要塞的唤风者梅恩·长角。",objectives={"把30根厚符文布绷带、30根厚魔纹绷带和30根厚丝质绷带交给唤风者梅恩·长角。你还必须随身带着后勤任务简报 X才能完成这个任务。"}]])
R(8497,"沙漠生存包",[[description="随着新兵增援塞纳里奥城堡，如何让他们在沙漠中生存成了一个问题。缺水是基本的问题，沙漠中无数具毒的生物对没有经验的志愿兵而言是很大的威胁。收集沙漠生存工具包需要的物资并带给塞纳里奥城堡的卡兰德拉斯。",objectives={"带4个纯水之球，4个强效抗毒药剂和4个沙漠肉丸子带到希利苏斯给塞纳里奥城堡旅店的卡兰德拉斯。你还必须将后勤任务简报 I带去才能完成这个任务。"}]])
R(8498,"暮光作战命令",[[description="我们的侦察兵报告说，暮光之锤的领袖收到了新的作战命令。现在这道命令正在被发送到各处的暮光预言者那里，并且有重兵护送。拦截这道命令，把它们交给指挥官玛尔利斯。",objectives={"拿到暮光作战命令，把它交给希利苏斯塞纳里奥要塞的指挥官玛尔利斯。"}]])
R(8499,"联盟需要瑟银锭！",[[description="你能主动关心联盟需要什么东西，这真是太好了。除了现在正在收集的各种物资之外，我们还需要大量的瑟银锭，我将负责这方面的收集。所有的瑟银都将用于制作各种战争必需的物资，特别是用来制造一个军团的蒸汽坦克，准备进攻希利苏斯。你能帮帮我吗，$c？",objectives={"把20块瑟银锭交给铁炉堡军事区的达米。"}]])
R(8500,"联盟需要更多瑟银锭！",[[description="你能主动关心联盟需要什么东西，这真是太好了。除了现在正在收集的各种物资之外，我们还需要大量的瑟银锭，我将负责这方面的收集。所有的瑟银都将用于制作各种战争必需的物资，特别是用来制造一个军团的蒸汽坦克，准备进攻希利苏斯。你能帮帮我吗，$c？",objectives={"把20块瑟银锭交给铁炉堡军事区的达米。"}]])
R(8501,"目标：亚什毒蝎",[[description="这一地区猖獗的异种虫类对我们来说是个巨大的威胁。你被指派负责对亚什虫巢发动攻击，主要目标是亚什毒蝎。$B$B在你的任务完成之后，向指挥官玛尔利斯汇报。",objectives={"击杀30只亚什毒蝎，然后向塞纳里奥要塞的指挥官玛尔利斯复命。你还必须带着作战任务简报 XII才能完成这个任务。"}]])
R(8502,"目标：亚什工蝎",[[description="这一地区猖獗的异种虫类对我们来说是个巨大的威胁。你被指派负责对亚什虫巢发动攻击，主要目标是亚什工蝎。$B$B在你的任务完成之后，向指挥官玛尔利斯汇报。",objectives={"击杀30只亚什工蝎，然后向塞纳里奥要塞的指挥官玛尔利斯复命。你还必须带着作战任务简报 III才能完成这个任务。"}]])
R(8503,"联盟需要荆棘藻！",[[description="那么$c，我是否告诉过你荆棘藻的所有用处？有没有说过？哦，好吧……不管怎么样，我们需要很多荆棘藻，我说很多的意思就是非常非常多！你可以帮帮我吗？我知道这意味着你无法用它来制作许多你需要的东西，但是我们是在为了正义的事业而努力！",objectives={"把20棵荆棘藻交给铁炉堡军事区的列兵德拉里格。"}]])
R(8504,"联盟需要更多荆棘藻！",[[description="又见面了…有什么事？啊，对了，$N！来看看我是否需要更多的荆棘藻吗？嗯，今天真是你的幸运日，因为这个重要问题的答案是肯定的“是”！你可以再收集20个来吗？",objectives={"带20个荆棘藻给丹莫洛飞机场的士兵德拉里格。"}]])
R(8505,"联盟需要紫莲花！",[[description="$c，紫莲花是一种非常有用的植物。我在这里作为联盟的官员收集紫莲花，我要负责监督整个收集过程，并保证在战时有足够的紫莲花储量可供使用。$B$B我希望你可以到世界各地帮我带回一些紫莲花。你可以做到吗？",objectives={"把20朵紫莲花交给铁炉堡军事区的艾文·夜歌。"}]])
R(8506,"联盟需要更多紫莲花！",[[description="$c，紫莲花是一种非常有用的植物。我在这里作为联盟的官员收集紫莲花，我要负责监督整个收集过程，并保证在战时有足够的紫莲花储量可供使用。我希望你可以到世界各地帮我带回一些紫莲花。你可以做到吗？",objectives={"把20朵紫莲花交给铁炉堡军事区的艾文·夜歌。"}]])
R(8507,"战地任务",[[description="你好，$N。在我为你布置更重要的任务之前，你需要首先完成一些常规的战地任务。$B$B你可以在佐拉虫穴外找到布莱卡维尔上尉的部队。$B$B向他或者他的副官珍妮拉·钢锤报到，然后回到我这里来。那时我将会给你下达进一步的指令。$B$B哦，别忘了离奥格瑞玛军团远一些。由于这两股势力之间的互相仇视，我们被迫把他们分开来。",objectives={"向佐拉虫巢外的铁炉堡军团报到，从布莱卡维尔上尉那里拿到签过字的战地任务文件，把它交给希利苏斯塞纳里奥要塞的唤风者卡尔东。$B$B注意：给铁炉堡军团的士兵治疗或者施放增益法术会打开你的PvP标志。"}]])
R(8508,"战地任务文件")
R(8509,"联盟需要阿尔萨斯之泪！",[[description="我会简要地告诉你重点，$c。联盟需要大量的阿尔萨斯之泪来准备安其拉战争。不要问我它们是用来做什么的，我并不关心这个。但是我需要你收集尽可能多地这种草药，并把它们交给我。你愿意这样做吗？",objectives={"把20棵阿尔萨斯之泪交给铁炉堡军事区的士官长戈麦恩。"}]])
R(8510,"联盟需要更多阿尔萨斯之泪！",[[description="我会简要地告诉你重点，$c。联盟需要大量的阿尔萨斯之泪来准备安其拉战争。不要问我它们是用来做什么的，我并不关心这个。但是我需要你收集尽可能多地这种草药，并把它们交给我。你愿意这样做吗？",objectives={"把20棵阿尔萨斯之泪交给铁炉堡军事区的士官长戈麦恩。"}]])
R(8511,"联盟需要轻皮！",[[description="我们家族历代都是著名的剥皮匠，$c。这就是联盟要求我们为了安其拉之战而收集轻皮的原因。我在这里的工作是确保皮革经过正确的处理，准备投入使用。但是我们需要你的帮助。$B$B因为我不得不留在这里，所以我需要你去帮忙收集皮革，然后把它们交给我。你觉得怎么样，$g小伙子:小姑娘;，你会帮我吗？",objectives={"把10块轻皮交给铁炉堡军事区的波尼·碎石。"}]])
R(8512,"联盟需要更多轻皮！",[[description="很高兴再见到你，$N。显然我们需要更多轻皮来制作各种战争要用的东西。如果你能再帮我带来10张轻皮就太完美了。",objectives={"带10张轻皮给丹莫洛飞机场的波尼?碎石。"}]])
R(8513,"联盟需要中皮！",[[description="长官！我正在负责收集所有战争所需的中皮。如果你有足够的精力和资金来收集中皮的话，那么请把它们交给我。我们希望有更多像你这样的人来帮助我们。",objectives={"把10块中皮交给铁炉堡军事区的下士波特。"}]])
R(8514,"联盟需要更多中皮！",[[description="是的$g 先生 : 女士;，看来目前我们已经收集了$2063w张中皮。我知道这个数量很庞大，但如果你愿意，我可以藉由你的帮忙让我的配额减少一点。",objectives={"带10张中皮给丹莫洛飞机场的士兵波特。"}]])
R(8515,"联盟需要厚皮！",[[description="这一定会很有意思！$c，安其拉之战迫在眉睫，我正在负责收集厚皮。我们需要大量的储备，但是首先我们必须先从第一批开始。总之这就是你来这里的原因。$B$B那么，你是否可以帮我带来一些质量不错的厚皮呢？可以吗，可以吗？",objectives={"把10块厚皮交给铁炉堡军事区的玛塔·钢轴。"}]])
R(8516,"联盟需要更多厚皮！",[[description="没错，存货仍然不够。$N，我们仍未达到理想的$2071w张重皮。想想我们能用重皮做的所有东西！各种护甲和武器。蒸气坦克的零件和步枪瞄准器！工程学护目镜，而且如果到最后我们还有剩下，可以把它们交给部落的齐柏林飞艇！$B$B你会为我带更多的重皮回来吗？",objectives={"带10张厚皮给丹莫洛飞机场的玛塔·钢轴。"}]])
R(8517,"联盟需要亚麻绷带！",[[description="安其拉的战争将会持续很长时间，并且会非常残酷。显然联盟寻求你们这些冒险者的帮助是很明智的选择，我们需要收集足够的资源来赢得这场战争。$B$B我在这里收集战争所需要的亚麻绷带，希望你可以帮助我们达成目标。现在一切物资都很紧缺，但是至少亚麻绷带还是比较容易制作的。你愿意帮助我们吗，$c？",objectives={"把20卷亚麻绷带交给铁炉堡军事区的哨兵塞尔瓦·银空。"}]])
R(8518,"联盟需要更多亚麻绷带！",[[description="我非常惊奇有那么多无私的人将私欲抛于一旁。$c，我还需要收集更多的亚麻绷带，直到完成我的指标。你是否可以再帮我收集一些亚麻绷带呢？",objectives={"把20卷亚麻绷带交给丹莫罗飞机场的哨兵塞尔瓦·银空。"}]])
R(8519,"往日的回忆",[[description="当你恢复镇静并重新汇集目光的时候，你发现有些东西从水晶之内往外瞪着。通过进一步的观察，你所看到的是过去……一段记忆……很久之前就遗忘的记忆。",objectives={"了解所以可以的过去的事情，然后和塔纳利斯时光之穴的阿纳克洛斯谈谈。"}]])
R(8520,"联盟需要丝质绷带！",[[description="安其拉的战争阴云正笼罩着大地，我们需要尽力让我们的士兵做好准备。现在我正在做的就是这件事情：负责收集足够多的丝质绷带。$B$B你可以帮帮我吗，$c？",objectives={"把20卷丝质绷带交给铁炉堡军事区的女护士斯通菲尔德。"}]])
R(8521,"联盟需要更多丝质绷带！",[[description="你能再次帮我真是太好了，$c。看来我们已经收集了$2082w个丝质绷带，所以我们需要更多绷带。",objectives={"带20个丝质绷带给丹莫洛飞机场的护士斯通菲尔德。"}]])
R(8522,"联盟需要符文布绷带！",[[description="关于战争的走向，你可以随意评说，$c，但是现在这场战争已经箭在弦上。看看你周围的朋友和家人，问问你自己，如果战争真的爆发，你会为此做些什么，你周围的人会一定会尽其所能地努力生存下来。$B$B现在，我在这里收集符文布绷带。你愿意捐赠一些吗？",objectives={"把20卷符文布绷带交给铁炉堡军事区的守护者莫沙·月影。"}]])
R(8523,"联盟需要更多符文布绷带！",[[description="又是讨论紧急事件的时候了，$c。我再次感谢你之前所作的努力；不是每个人都能如此无私奉献。但是我们仍然很多事要完成。$B$B$N，你可以再去收集符文布绷带并拿回来这里给我吗？",objectives={"带20个符文布绷带给丹莫洛飞机场的守护者月影。"}]])
R(8524,"联盟需要彩鳍鱼！",[[description="你好，朋友！你不认为士兵也和别人一样需要吃饭吗？你当然会赞同这一点。我110%地同意你的看法！很高兴我们达成了一致。现在我要你做的就是去钓很多很多新鲜的彩鳍鱼，然后把它们烧好，带到我这里来。嗯，我仿佛已经可以尝到它们了……",objectives={"把20条彩鳍鱼交给铁炉堡军事区的美食家斯里克。"}]])
R(8525,"联盟需要更多彩鳍鱼！",[[description="你好，朋友！你不认为士兵也和别人一样需要吃饭吗？你当然会赞同这一点。我110%地同意你的看法！很高兴我们达成了一致。现在我要你做的就是去钓很多很多新鲜的彩鳍鱼，然后把它们烧好，带到我这里来。嗯，我仿佛已经可以尝到它们了……",objectives={"把20条彩鳍鱼交给铁炉堡军事区的美食家斯里克。"}]])
R(8526,"联盟需要烤迅猛龙肉！",[[description="嘿，最近过得怎么样啊，$c？我看你好像有兴趣帮即将开始的安其拉战争收集食品物资。我爸爸觉得我来这里帮忙是一个学习的好方法。这可是个大错误，我根本不喜欢吃肉。$B$B不管怎么样，如果你愿意的话，请带给我大量的烤迅猛龙肉。显然这是所有士兵都想要的美食。",objectives={"把20块烤迅猛龙肉交给铁炉堡军事区的萨拉·塞维斯。"}]])
R(8527,"联盟需要更多烤迅猛龙肉！",[[description="嘿，最近过得怎么样啊，$c？我看你好像有兴趣帮即将开始的安其拉战争收集食品物资。我爸爸觉得我来这里帮忙是一个学习的好方法。这可是个大错误，我根本不喜欢吃肉。不管怎么样，如果你愿意的话，请带给我大量的烤迅猛龙肉。显然这是所有士兵都想要的美食。",objectives={"把20块烤迅猛龙肉交给铁炉堡军事区的萨拉·塞维斯。"}]])
R(8528,"联盟需要斑点黄尾鱼！",[[description="虽然看起来烧鱼算不上什么英雄事迹，但是绝对不要低估战前准备的价值，年轻的$c。士兵和其他人一样需要吃饭，我们在这里要准备的可是安其拉战争开始后所必需的东西。$B$B为此，我在这里收集斑点黄尾鱼，一种适合于存储并且可以用于多种菜肴的物资。另外它也没有其它咸水鱼的那种难闻的味道。你愿意帮助我吗？",objectives={"把20条斑点黄尾鱼交给铁炉堡军事区的女猎手蕾尔·急流。"}]])
R(8529,"联盟需要更多斑点黄尾鱼！",[[description="如果你愿意我想派你再去捕一批斑点黄尾鱼，$N。我想你有了第一次的经验，这次捕鱼一定会更快更容易。你愿意吗？",objectives={"带20条斑点黄尾鱼给丹莫洛飞机场的女猎手蕾尔·急流。"}]])
R(8530,"The Alliance Needs Singed Corestones!",[[description="$C, I need your help. In the Molten Core there are these stones, singed Corestones to be precise, that we need to harvest for the Ahn'Qiraj war effort. I'm told that our blacksmiths and engineers can put them to good use, so that's where you come in. I need you to go into the Molten Core and gather up as many of these corestones as you can. Of course, you'll want to talk thirty-nine of your closest friends along with you.",objectives={"Bring 50 singed corestones to Commander Stronghammer at the airfield in Dun Morogh."}]])
R(8532,"部落需要铜锭！",[[description="很高兴你来帮助我们。并不是所有人都能搞清楚我所需要的东西是什么，所以我要确保你不犯错误。我需要的是铜锭，不是铜矿石。我们没有时间自己进行熔炼，希望你可以帮助我们。你可以办到吧，$c？",objectives={"把20块铜锭交给奥格瑞玛精神谷的矿工克罗威尔。"}]])
R(8533,"部落需要更多铜锭！",[[description="这么快就回来了？你很快就会成为一个真正的矿工了，$c。那么，你已经知道怎么钻孔了；我需要你出去帮我挖掘一堆铜矿，熔解它们做成铜锭再带回来给我。我知道你能办到，问题是，你愿意吗？",objectives={"带20个铜锭给杜洛塔的矿工克罗威尔。"}]])
R(8534,"佐拉虫巢侦查报告",[[description="我们派出了最好的斥候深入异种虫类的巢穴收集情报。艾泽奈尔这几天来一直在监视佐拉虫巢，去找到她，拿回她的书面报告。我们需要这些情报来制定战术，要尽快，$n。",objectives={"在佐拉虫巢内找到塞纳里奥斥候艾泽奈尔，然后把佐拉虫巢侦查报告交给塞纳里奥要塞的唤风者梅恩·长角。你还必须随身带着战术任务简报 VI才能完成这个任务。"}]])
R(8535,"苍白圣殿骑士",[[description="暮光之锤和深渊议会之间的联系看来比我们想象的还要意义重大。$B$B根据可靠情报，那个被称深渊公爵的元素领主将要策动暮光之锤对塞纳里奥要塞实施一次大规模的攻击。设法把他引诱出来，然后击杀他。",objectives={"设法召唤并击杀深渊公爵，然后向塞纳里奥要塞的唤风者梅恩·长角复命。"}]])
R(8536,"土色圣殿骑士",[[description="暮光之锤和他们所膜拜的元素生物对我们在希利苏斯地区的行动是个不小的威胁。安其拉虫墙内的敌人还在虎视眈眈，所以我们绝对不能对暮光之锤的势力掉以轻心。$B$B想办法召唤并摧毁一名土色圣殿骑士，然后向鲍尔·蛮鬃汇报。",objectives={"召唤并杀死一名土色圣殿骑士，然后向塞纳里奥要塞的鲍尔·蛮鬃复命。你还必须随身带着战术任务简报 III才能完成这个任务。"}]])
R(8537,"赤红圣殿骑士",[[description="暮光之锤和深渊议会之间的联系看来比我们想象的还要意义重大。$B$B根据可靠情报，那个被称作微风公爵的元素领主将要策动暮光之锤对塞纳里奥要塞实施一次大规模的攻击。设法把他引诱出来，然后击杀他。",objectives={"设法召唤并击杀微风公爵，然后向塞纳里奥要塞的唤风者梅恩·长角复命。"}]])
R(8538,"四个公爵",[[description="暮光之锤和深渊议会之间的联系看来比我们想象中的还要意义重大。$B$B根据可靠情报，那些被称作深渊圣殿骑士的元素领主们可能正在策动暮光之锤对塞纳里奥要塞实施一次大规模的攻击。设法把他们引诱出来，然后击杀他们。",objectives={"设法召唤并击杀四个深渊圣殿骑士，然后向塞纳里奥要塞的唤风者梅恩·长角复命。"}]])
R(8539,"目标：佐拉雌蝎",[[description="我们需要援军进攻佐拉虫巢。你的主要目标是那些佐拉雌蝎，当你的任务完成之后就去向指挥官玛尔利斯报告。",objectives={"击杀30只佐拉雌蝎，然后向塞纳里奥要塞的指挥官玛尔利斯复命。你还必须带着作战任务简报 V才能完成这个任务。"}]])
R(8540,"卫兵的靴子",[[description="塞纳里奥城堡守卫的坐骑军师缺少精制秘银战靴。取得一批战靴并立即送给塞纳里奥城堡的维斯·库鲁兹队长。",objectives={"将3双精制秘银战靴带到希利苏斯给塞纳里奥城堡的守卫队长维斯·库鲁兹。你还必须将后勤任务简报 II带去才能完成这个任务。"}]])
R(8541,"卫兵的砂轮",[[description="塞纳里奥要塞的卫兵急需磨刀石。去收集足够的磨刀石，然后立即把它们交给塞纳里奥要塞的维斯·库鲁兹队长。",objectives={"把磨刀石交给希利苏斯塞纳里奥要塞的维斯·库鲁兹。"}]])
R(8542,"部落需要锡锭！",[[description="你好，$r。我没有很多时间来向你进行解释。我们现在正在准备和安其拉开战，但是首先，酋长决定要我们进行一些工作，这些工作被称为“备战”。这意味我需要派你出去帮我收集锡锭，我想我需要的锡锭数量连我自己都数不过来。$B$B你还留在这里干什么？",objectives={"把20块锡锭交给奥格瑞玛精神谷的步兵玛乌格。"}]])
R(8543,"部落需要更多锡锭！",[[description="很好，我看的出来你对战争很认真。不过我对战争要开始有点急躁，所以如果你不快点把东西带来我就会生气。或许我可以直接拿你开刀。$B$B哈！还是不要好了，因为这样谁会帮我带锡锭来呢？",objectives={"带20个锡锭给杜洛塔的步兵玛乌格。"}]])
R(8544,"征服者的肩铠",[[description="据说凡人所穿着的绚丽护肩是他们用来模仿龙翼的。$B$B把其拉虫人的最高领袖所佩戴的腕轮交给我，我会用它来制作一副比奈法利安的双翼还要可怕的护肩！",objectives={"把其拉命令腕轮、2个夜晚塑像、5个岩石甲虫和5个陶土甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。"}]])
R(8545,"部落需要秘银锭！",[[description="$c，战争即将到来，我们所能做的就是准备作战。在这方面我们可以互相帮助。你看，他们派我来负责收集秘银锭，以供制作我们所需的东西。现在我需要更多秘银锭！$B$B那么，我希望你可以帮我去找来一些秘银矿石，然后熔化成锭。你可以做到这些吧？",objectives={"把20块秘银锭交给奥格瑞玛精神谷的军士长克拉恩。"}]])
R(8546,"部落需要更多秘银锭！",[[description="$c，战争即将到来，我们所能做的就是准备作战。在这方面我们可以互相帮助。你看，他们派我来负责收集秘银锭，以供制作我们所需的东西。现在我需要更多秘银锭！那么，我希望你可以帮我去找来一些秘银矿石，然后熔化成锭。你可以做到这些吧？",objectives={"把20块秘银锭交给奥格瑞玛精神谷的军士长克拉恩。"}]])
R(8548,"志愿兵的装备",[[description="$N，你在与敌人作战、提供后勤补给和执行战略任务之后获得的徽章并不只是用来炫耀的。$B$B希望你还保留着它们。作为对你的鼓励，我想要奖励你一些只有塞纳里奥议会最亲近的盟友才能获得的东西。",objectives={"把5枚作战徽章、3枚后勤徽章和7枚战术徽章交给塞纳里奥要塞的瓦古斯。你必须在塞纳里奥议会中达到友善声望才能完成这个任务。"}]])
R(8549,"部落需要宁神花！",[[description="据说每一代人都需要面对一次决定性的试炼。恐怕安其拉之战将是我们这一辈人所要经历的残酷考验。我们要做好准备，了解自己的实力究竟如何。$B$B我在这里志愿帮忙收集宁神花，我们会用它们制作战争所需的药水。我希望你来这里是为了帮助我们，如果是这样的话，那么我需要你帮我带回大量的这种草药。你会帮助我吗，$c？",objectives={"把20朵宁神花交给奥格瑞玛精神谷的草药学家波德·飞羽。"}]])
R(8550,"部落需要更多宁神花！",[[description="据说每一代人都需要面对一次决定性的试炼。恐怕安其拉之战将是我们这一辈人所要经历的残酷考验。我们要做好准备，了解自己的实力究竟如何。我在这里志愿帮忙收集宁神花，我们会用它们制作战争所需的药水。我希望你来这里是为了帮助我们，如果是这样的话，那么我需要你帮我带回大量的这种草药。你会帮助我吗，牧师？",objectives={"把20朵宁神花交给奥格瑞玛精神谷的草药学家波德·飞羽。"}]])
R(8551,"船长的箱子",[[description="我过去在一条专跑从这里到卡利姆多的棘齿城的航线上干过。我是个很优秀也很有名望的船长。$B$B直到……$B$B那些该死的海巨人毁了我的生活！他们打沉了我的船，杀光了我的水手，把我丢在一条救生艇上，让我漂回了藏宝海湾。还有，其中一个名叫高拉什的巨人还把我的箱子给偷走了，他说要拿这东西当鼻烟盒，简直是神经病！$B$B我听说有人看见高拉什最近在东边的海岸一带闲逛。找到他，把我的箱子给抢回来！快去，你会得到一位船长的敬意的。",objectives={"将斯莫特的箱子交给藏宝海湾的海克拜瑞·斯莫特。"}]])
R(8552,"刺着字母的腰带",[[description="这条精致的腰带的边上刺着两个字母“HS”。",objectives={"将刺着字母的腰带还给他的主人。"}]])
R(8553,"船长的弯刀",[[description="我的第一条船被那些海巨人们搞沉了之后，我只好买了第二艘，而且给它起名为“斯莫特的复仇”。我为它配备了新的装备和船员，并出发去寻找那些该死的巨人。我找到了他们，但……他们又一次击败了我们。他们把“斯莫特的复仇”号给打成了碎片，船员也几乎被他们杀光了，但那帮混蛋却把我丢在了一条救生艇上，让我一个人漂了回来。$B$B这次，那些海巨人中的另外一个偷了我的弯刀。$B$B到奈古拉什那里去把我的佩刀给抢回来！$B$B去和斯普罗格谈谈吧。他本来是“斯莫特的复仇”号上的厨子，沉船的时候他也幸存了下来，我想他能帮你们找到那些巨人。",objectives={"与斯普罗格谈一谈。"}]])
R(8554,"挑战奈古拉什",[[description="奈古拉什总是一副随时准备把一切都吞下去充饥的样子。$B$B那些巨人袭击我们的船的时候，奈古拉什直接冲向了我的厨房，不过他可不像其他巨人那样喜欢吃人。奈古拉什要的是酒……还有我秘制的烧烤秃鹰翅膀。嘿，这可都是我的拿手菜，我当年可是跑到荒芜之地才弄到这食谱的！$B$B如果你想把奈古拉什给引出来，只要用点酒再加上一碟烤翅就行啦。把这些东西放进我们当初丢在东南边海岸上的救生艇里，然后你就等着奈古拉什闻到食物的味儿乖乖上钩吧！",objectives={"将10块烧烤秃鹰翅膀和5瓶密林葡萄酒带到斯莫特船长的救生艇上去。$B$B然后杀死奈古拉什，将斯莫特的弯刀交给荆棘谷的斯莫特船长。"}]])
R(8555,"守护之龙")
R(8556,"坚定力量之戒",[[description="据说其拉虫人的军官所佩戴的戒指可以给他们带来无穷的能量。那些戒指上镶嵌着腐化的宝石，也许我们可以用纯净的材料替换它们，以此来制作净化版本的戒指。$B$B那些装饰在其拉雕像上的宝石就非常合适，它们的质量非常好。$B$B把戒指和雕像交给我，我会为你制作一枚强大的戒指，$c。",objectives={"将1枚其拉将领戒指、2个柔光雕像、5个青铜甲虫和5个象牙甲虫交给唤风者耶萨德拉。"}]])
R(8557,"坚定力量披风",[[description="我很高兴听说你愿意帮助我们进攻安其拉，$N。我可以制作一件装备，让你在作战时获得一些保护，$c。$B$B我需要一件其拉斗篷，然后把它按照你的体型进行修改。我还需要其拉塑像和圣甲虫，这样我才能制作合适的扣子。$B$B我保证你一定不会失望的。",objectives={"将1件其拉军用披风、2个玛瑙雕像、5个银质甲虫和5个白骨甲虫交给凯伊·迅爪。你必须在塞纳里奥议会中达到崇敬声望才能完成这个任务。"}]])
R(8558,"坚定力量之镰",[[description="其拉虫人和他们的奴仆所使用的装备是由最珍稀宝贵的物品制作而成的，包括古代巨兽的骨头，大地最深处的宝石，以及最坚硬纯净的金属。$B$B这些其拉神器让我有一种冲动，想要用一些这样的材料来锻炼我的技艺。向塞纳里奥议会证明你的忠诚吧，$N，我会用最好的其拉虫人材料帮你制作一把强大的武器。",objectives={"将1件其拉尖刺刀柄、2个雪白雕像、5个水晶甲虫和5个岩石甲虫交给希利苏斯的守望者哈尔洛。你必须在塞纳里奥议会中达到崇拜声望才能完成这个任务。"}]])
R(8559,"征服者的胫甲",[[description="其拉虫人的魔法古老而又强大，它们最强大的武器甚至可以与龙抗衡。$B$B把其拉统御腕轮和其它辅助材料交给我，我将为你制作一双威力无比的靴子。$B$B你会在与敌人作战的时候发现它所蕴含的力量。",objectives={"把其拉命令腕轮、2个战争塑像、5个象牙甲虫和5个黄金甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。"}]])
R(8560,"征服者的腿铠",[[description="你想要向我们证明你的价值吗，凡人？很好，也许我们可以互相帮助。$B$B在传说中，古老的沙虫奥罗是一个非常强大的存在。据说是上古把它创造出来的原因是为了嘲笑生命的软弱。$B$B它的皮肤非常特殊……异常结实，甚至是无法击破的，而它本身的移动速度却不会因此而受到任何妨碍，它和那些小型生物一样动作灵敏。$B$B把它的皮肤样品和其它一些原材料都交给我，我会给你制作一条具有强大力量的护腿。",objectives={"把奥罗的外皮、2个死亡塑像、5个青铜甲虫和5个象牙甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。"}]])
R(8561,"征服者的皇冠",[[description="双子皇帝……他们正向我轻声密语，这折磨着我的神志。他们嘲笑我，他们知道我无法进入神殿的深处去拯救我的兄弟亚雷戈斯。$B$B我可以看见他们狰狞的脸庞，他们头上戴着具有无穷力量的皇冠。但是我必须要报仇……我会把这种代表其拉虫人力量的饰品转化成对我们有利的东西。$B$B把我需要的材料交给我，$N。我会为你制作一顶具有超凡力量的头盔。",objectives={"把维克尼拉斯的头饰、2个太阳塑像、5个岩石甲虫和5个水晶甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。"}]])
R(8562,"征服者的胸甲",[[description="最令人恐怖的上古之神正在从安其拉的休眠之中慢慢醒来。艾泽拉斯世界不久之后即将面对这股恐怖的力量，时间对于如此强大的存在来说毫无意义。$B$B当星辰的位置合适的时候，他将让恐怖的力量席卷所有的一切。你必须在此之前找到他，消灭他。$B$B完成这个任务，把他的外壳交给我。我会奖励你一件凡人从未见到过的护甲……一件只有弑神者才有资格获得的护甲！",objectives={"把上古之神的外鞘、2个战争塑像、5个银质甲虫和5个白骨甲虫交给安其拉的温瑟拉。你必须在诺兹多姆的子嗣中达到尊敬声望才能完成这个任务。"}]])
