R(8728,"好消息和坏消息",[[description="好吧，这比预期的时间稍微长了一些。现在让我看看账本上都写了些什么。$B$B<纳瑞安默默地读着账本，有的时候还喃喃自语。>$B$B好消息是，我可以99%地肯定，我能为你制作一个奥金鱼漂。当然，还有一个坏消息。$B$B坏消息就是，我需要大量的奥金，源质矿石，还有一些珍贵的宝石。$B$B把它们带来，然后我就可以开工了。",objectives={"塔纳利斯的纳瑞安要你给他带去20块奥金锭、10块源质矿石、10颗艾泽拉斯钻石，以及10颗蓝宝石。"}]])
R(8729,"耐普图洛斯的愤怒",[[description="我和你说过坏消息了吗?它的名字叫巨齿鲨:100尺长，死亡和毁灭的化身。我想我忘记和你说这个了。$B$B根据我的超级精准千里眼提供的讯息，你会在艾萨拉的海岸找到最合适使用这个浮标的地方，就在风暴海湾。$B$B你要寻找一个大漩涡，就是附近都是沉船的地方。$B$B另外，我希望你带上你的朋友。$B$B如果你成功的话，那么把权杖碎片带给安纳克罗斯。",objectives={"在艾萨拉风暴海湾一带的大漩涡使用奥金浮标。"}]])
R(8730,"奈法里奥斯的腐蚀",[[description="Champion, is it you? A thousand years it has been since I was entrusted the shard and it is at my darkest hour that one should rise to relieve me of it... But what would tragedy be without cruelty?$B$B<Vaelastrasz coughs weakly.>$B$BNe... Nefarius now holds the scepter shard.$B$BTime is of the essence. Nefarius plans to destroy the shard. You must hurry!",objectives={"干掉奈法利安并拿到Red Scepter Shard。把Red Scepter Shard带给塔纳利斯时光之穴门口的阿纳克洛斯。你必须在一个半小时之内完成这个任务。"}]])
R(8731,"战地任务",[[description="你好，$N。在我为你布置更重要的任务之前，你需要首先完成一些常规的战地任务。$B$B你可以在佐拉虫穴外找到克鲁格·碎颅的部队。$B$B向他报到，然后拿着你完成任务的证明文件回到我这里来。那时我将会给你下达进一步的指令。$B$B哦，别忘了离铁炉堡军团远一些。由于联盟和部落的志愿兵之间摩擦不断，我们被迫把他们分开来。",objectives={"向雷戈虫巢外的奥格瑞玛军团报到，从克鲁格·碎颅那里拿到签过字的战地任务文件，把它交给希利苏斯塞纳里奥要塞的唤风者卡尔东。$B$B注意：给奥格瑞玛军团的士兵治疗或者施放增益法术会打开你的PvP标志。"}]])
R(8732,"战地任务文件")
R(8733,"伊兰尼库斯，梦境之暴君",[[description="这将是一段救赎之旅，英雄。如果今天我要死去，那么我也要为了一个正义而伟大的事业而牺牲。你必须找到绿色节杖碎片，你必须净化被上古之神控制的伊兰尼库斯。$B$B到达纳苏斯去，在城墙外，你可以找到我的人。这个人将会为我们进行协调，并在不让鹿盔发现的情况下将我们的计划通知给泰兰德。$B$B<玛法里奥叹了口气。>$B$B一千年的守护终究堕落了……",objectives={"到达纳苏斯的城墙外去找到玛法里奥的亲信。"}]])
R(8734,"泰兰德和雷姆洛斯",[[description="我们会通知泰兰德的，凡人。玛法里奥·怒风已经让我做好应付这次事件的准备了。$B$B现在你必须去月光林地，和雷姆洛斯谈一谈。他会进一步指引你召唤伊兰尼库斯。$B$B祝你好运。",objectives={"到月光林地去，和守护者雷姆洛斯谈一谈。"}]])
R(8735,"腐蚀梦魇",[[description="你必须到艾泽拉斯世界的四个翡翠梦境入口去。在每个入口处，你都可以收集到腐蚀梦魇的碎片。住在这些地区的龙类生物身上会携带着这样的碎片。当你收集到全部四块碎片后就回到我这里来。",objectives={"到艾泽拉斯世界的四个翡翠梦境入口去，分别收集该处的腐蚀梦魇的碎片。当你任务完成之后，就回到月光林地的守护者雷姆洛斯那里。"}]])
R(8736,"噩梦显现",[[description="我们必须尽量控制伊兰尼库斯，我们要让他获得救赎，而不是摧毁他。$B$B泰兰妲已经在赶来帮助我们的路上了。我们必须守住巨龙的攻击，保护永夜港免遭伤害。$B$B做好准备!你和你的盟友是我们唯一的希望。",objectives={"保护永夜港免受伊兰尼库斯的伤害。不要让守护者雷姆洛斯死亡。不要杀掉伊兰尼库斯。保护好你们自己。等待泰兰妲。"}]])
R(8737,"碧蓝圣殿骑士",[[description="暮光之锤和深渊议会之间的联系看来比我们想象的还要意义重大。$B$B根据可靠情报，那个被称作灰烬公爵的元素领主将要策动暮光之锤对塞纳里奥要塞实施一次大规模的攻击。设法把他引诱出来，然后击杀他。",objectives={"设法召唤并击杀灰烬公爵，然后向塞纳里奥要塞的唤风者梅恩·长角复命。"}]])
R(8738,"雷戈虫巢侦查报告",[[description="我们派出了最好的斥候深入异种虫类的巢穴收集情报。兰迪奥这几天来一直在监视佐拉虫巢，去找到他，拿回他的书面报告。我们需要这些情报来制定战术，要尽快，$n。",objectives={"在雷戈虫巢内找到塞纳里奥斥候兰迪奥，然后把雷戈虫巢侦查报告交给塞纳里奥要塞的唤风者梅恩·长角。你还必须随身带着战术任务简报 VII才能完成这个任务。"}]])
R(8739,"亚什虫巢侦查报告",[[description="暮光之锤和深渊议会之间的联系看来比我们想象的还要意义重大。$B$B根据可靠情报，那个被称作灰烬公爵的元素领主将要策动暮光之锤对塞纳里奥要塞实施一次大规模的攻击。设法把他引诱出来，然后击杀他。",objectives={"设法召唤并击杀灰烬公爵，然后向塞纳里奥要塞的唤风者梅恩·长角复命。"}]])
R(8740,"暮光掠夺者",[[description="Bands of mounted Twilight's Hammer cultists have been spotted riding outside the reach of our forces in Cenarion Hold, picking off our smaller patrols and caravans.$B$BFind and defeat the twilight marauders along with their leader, a terrible warrior by the name of Morna.  Report to Windcaller Proudhorn after completing the task.",objectives={"干掉Twilight Marauder Morna和5个Twilight Marauders。当任务完成之后向唤风者梅恩·长角报告。"}]])
R(8741,"勇士归来",[[description="守护者在等待着你，$n。把绿色节杖碎片交给时光之穴前的阿纳克洛斯吧。您会收到：$B$B完成任务后，你将获得：$B$B您会收到：$B$B完成任务后，你将获得：$B$B完成任务后，你将获得：$B$B",objectives={"把绿色节杖碎片交给塔纳利斯时光之穴的阿纳克洛斯。"}]])
R(8742,"卡利姆多的力量")
R(8743,"敲响甲虫之锣！")
R(8744,"精心包裹的礼物")
R(8745,"时光之王的财宝")
R(8746,"驯鹿梅森",[[description="出大事啦！驯鹿梅森被绑架了！$B$B冬天爷爷有八头驯鹿，梅森是其中的一头，也是烟林牧场的财产。我们收到了宣称对此次绑架事件负责的组织寄来的勒索信，而且不是一封，是两封！两封，你明白吗？节日即将来临，我们早已经穷得叮当响啦！帮帮忙吧，帮我们找到梅森，把它救回来！$B$B你可以看看这些勒索信里面有什么线索，找到梅森之后，把驯鹿之尘洒在它身上，这样就可以让它摆脱一切束缚！$B$B事不宜迟！",objectives={"找到驯鹿梅森。在你手头上的便笺中查找有关梅森下落的线索。$B$B当你找到它之后，往它身上洒一些驯鹿之尘，这样就可以让它摆脱任何束缚。$B$B解救梅森之后，把驯鹿之尘还给奥格瑞玛的凯玛德·考伯宾奇。"}]])
