R(8778,"铁炉堡军团需要爆炸品！",[[description="战场的绷带储存量在最近战争伤亡之后急剧降低。把大量的急救物资带给塞纳里奥要塞的唤风者梅恩·长角。",objectives={"把20个重符文绷带，20个厚丝质绷带和20个厚绒线绷带带给唤风者梅恩·长角。"}]])
R(8779,"研究材料",[[description="战场的绷带储存量在最近战争伤亡之后急剧降低。把大量的急救物资带给塞纳里奥要塞的唤风者梅恩·长角。",objectives={"把20个重符文绷带，20个厚丝质绷带和20个厚绒线绷带带给唤风者梅恩·长角。"}]])
R(8780,"战场上的护甲片",[[description="我们的绷带储备在最近接连不断的战事之后急剧降低。收集大量的急救物资，把它们交给塞纳里奥要塞的唤风者梅恩·长角。",objectives={"把20根重符文绷带、20根厚丝质绷带和20根厚绒线绷带交给唤风者梅恩·长角。"}]])
R(8781,"战场上的武器",[[description="我们的绷带储备在最近接连不断的战事之后急剧降低。收集大量的急救物资，把它们交给塞纳里奥要塞的唤风者梅恩·长角。",objectives={"把20根重符文绷带、20根厚丝质绷带和20根厚绒线绷带交给唤风者梅恩·长角。"}]])
R(8782,"制服供应",[[description="最近不断涌来的志愿者导致我们制服紧缺。去搜集一些制服的材料，然后把它们交给唤风者梅恩·长角。",objectives={"把1块月布、2卷符文布卷和1份铁网蛛丝交给塞纳里奥要塞的唤风者梅恩·长角。你还必须随身带着后勤任务简报 VIII才能完成这个任务。"}]])
R(8783,"特殊的材料",[[description="瓦古斯是塞纳里奥要塞的铁匠，他需要一些附魔材料来为我们的部队制作强力的武器。去找到这些材料，把它们直接交给瓦古斯，这样塞纳里奥议会的军队就有了作战装备的保障。",objectives={"把2块魔化瑟银锭和2块魔化皮交给希利苏斯塞纳里奥要塞的瓦古斯。你还必须随身带着后勤任务简报 IX才能完成这个任务。"}]])
R(8784,"其拉的秘密",[[description="你找到了一件上古其拉神器！也许神殿入口附近的龙用得到这件东西。",objectives={"把上古其拉神器交给隐藏在神殿入口处的龙类。"}]])
R(8785,"奥格瑞玛军团需要魔精！",[[description="奥格瑞玛军团要求我们提供一些不寻常的物资。他们在希利苏斯的表现很不错，因此我们最好尽快满足他们的需求。收集必需的材料，把它们交给那个名叫沙艾的巨魔。",objectives={"把6份强力魔精、6份大瓶魔精和8份献祭之油交给希利苏斯地区的雷戈虫巢附近的暗影祭司沙艾。你还必须随身带着后勤任务简报 IV才能完成这个任务。"}]])
R(8786,"战场上的武器",[[description="我们的绷带储备在最近接连不断的战事之后急剧降低。收集大量的急救物资，把它们交给塞纳里奥要塞的唤风者梅恩·长角。",objectives={"把20根重符文绷带、20根厚丝质绷带和20根厚绒线绷带交给唤风者梅恩·长角。"}]])
