R(8800,"塞纳里奥的装备",[[description="一旦你完成了分配给你的任务，就去找铁匠瓦古斯谈谈。让他看看你在战斗中得到的徽章。他会为你提供一些合适的装备。",objectives={"与希利苏斯塞纳里奥要塞的瓦古斯谈一谈。"}]])
R(8801,"克苏恩的遗产",[[description="安其拉的高墙摇晃起来。超越这世界的邪恶力量已经被摧毁了。$B$B当你注视着巨像憎恶的遗迹时，心跳几乎被冻结。在死一般的寂静中，你还是能感觉克苏恩的邪恶力量。$B$B你完成了别人认为不可能的任务。$B$B你取下恶魔的眼柄小心放进你的包包里。$B$B把克苏恩之眼带到下一个房间里的巨龙那儿。",objectives={"将克苏恩之眼带给安其拉神庙的卡拉史塔斯。"}]])
R(8802,"卡利姆多的救世主",[[description="前往时光之穴，$G大人：女士；$N。安纳克罗斯等着你回来。把克苏恩之眼交给他，他绝对会将它放在主人的收集品里。",objectives={"把克苏恩之眼带给时光之穴的安纳克罗斯。"}]])
R(8803,"节日礼物")
R(8804,"沙漠生存包",[[description="目前塞纳里奥要塞涌入了大量的新兵，我们的首要问题就成了如何保证他们在沙漠中生存下来。缺水的环境和遍布希利苏斯的剧毒生物都威胁着这些缺乏经验的志愿者。去收集一些必需的物资，把他们交给要塞里的卡兰德拉斯吧。",objectives={"把4份纯水之球、4份特效抗毒药剂和4份烤鲑鱼交给希利苏斯塞纳里奥要塞的卡兰德拉斯。你还必须随身带着后勤任务简报 I才能完成这个任务。"}]])
R(8805,"卫兵的靴子",[[description="目前塞纳里奥要塞的骑兵团缺乏足够的毛皮护甲片，去收集大量护甲片，然后立即把它们交给塞纳里奥要塞的维斯·库鲁兹队长。",objectives={"把毛皮护甲片交给希利苏斯塞纳里奥要塞的维斯·库鲁兹。"}]])
R(8806,"卫兵的砂轮",[[description="塞纳里奥要塞的卫兵急需磨刀石。去收集足够的磨刀石，然后立即把它们交给塞纳里奥要塞的维斯·库鲁兹队长。",objectives={"把磨刀石交给希利苏斯塞纳里奥要塞的维斯·库鲁兹。"}]])
R(8807,"研究材料",[[description="战场的绷带储存量在最近战争伤亡之后急剧降低。把大量的急救物资带给塞纳里奥要塞的唤风者梅恩·长角。",objectives={"把20个重符文绷带，20个厚丝质绷带和20个厚绒线绷带带给唤风者梅恩·长角。"}]])
R(8808,"制服供应",[[description="战场的绷带储存量在最近战争伤亡之后急剧降低。把大量的急救物资带给塞纳里奥要塞的唤风者梅恩·长角。",objectives={"把20个重符文绷带，20个厚丝质绷带和20个厚绒线绷带带给唤风者梅恩·长角。"}]])
R(8809,"特殊的材料",[[description="瓦古斯是塞纳里奥要塞的铁匠，他需要一些附魔材料来为我们的部队制作强力的武器。去找到这些材料，把它们直接交给瓦古斯，这样塞纳里奥议会的军队就有了作战装备的保障。",objectives={"把2块魔化瑟银锭和2块魔化皮交给希利苏斯塞纳里奥要塞的瓦古斯。你还必须随身带着后勤任务简报 IX才能完成这个任务。"}]])
R(8810,"战场上的绷带",[[description="我们的绷带储备在最近接连不断的战事之后急剧降低。收集大量的急救物资，把它们交给塞纳里奥要塞的唤风者梅恩·长角。",objectives={"把20根重符文绷带，20根厚丝质绷带和20根厚绒线绷带带给唤风者梅恩·长角。你还必须随身带着后勤任务简报 X才能完成这个任务。"}]])
