R(8856,"沙漠生存包",[[description="With the arrival of fresh recruits to Cenarion Hold comes the problem of keeping them alive in the desert.  Dehydration as well as numerous poisonous creatures present a serious threat to inexperienced volunteers.  Gather the supplies necessary for a desert survival kit and bring them to Calandrath in Cenarion Hold.",objectives={"Bring 4 Globes of Water, 4 Powerful Anti-Venom and 4 Baked Salmon to Calandrath at the inn in Cenarion Hold in Silithus."}]])
R(8857,"亚什巨甲虫的秘密",[[description="我正在寻找那些经过战争洗礼的冒险者，看他们是否愿意从亚什巨像的尸体上取到新鲜的獠牙样本，并把它交给藏宝海湾的奥格索普。不，不，我可不希望你在那家伙的尸体附近游荡。你只需迅速取回样本，这东西腐烂了就不好办了！",objectives={"把亚什巨像的獠牙交给藏宝海湾的奥格索普·奥布诺提斯。"}]])
R(8858,"雷戈巨甲虫的秘密",[[description="我只想把这个甲虫壳套在奥菲斯特的大肥脸上…可惜，我现在要在这里收集畸形的蟑螂样本。我会一直在这里直到清晨。$B$B快点帮我把这个样本带给奥菲斯特，$c。他会重重答谢你!$B$B没错，瑟银哨塔 – 就在灼热峡谷。",objectives={"把雷戈巨像的甲壳带给灼热峡谷的工头奥菲斯特。"}]])
R(8859,"佐拉巨甲虫的秘密",[[description="我的奴仆差点在取得这个样本时丧命。你一定要动作快！玛克斯韦尔·泰罗索斯男爵急需要一个新鲜的甲壳样本。他相信巨像的秘密可以帮助我们对抗天谴军团！$B$B你怎么还在这里！？到圣光之愿礼拜堂！没错，你会得到可观的奖励…",objectives={"把佐拉巨像的甲壳带到东瘟疫之地的圣光之愿礼拜堂给玛克斯韦尔·泰罗索斯男爵。"}]])
R(8860,"庆祝新年！",[[description="暴风城正在举行新年庆典！所有人都可以全天畅饮美酒佳肴，晚上还会有焰火表演！听起来是不错……不过藏宝海湾也有这样的庆典，我敢说这个肯定更棒！$B$B总之，暴风城的旅店老板奥里森需要一些烟林牧场的补给品才能应付需求量巨大的庆典，你能帮我送一趟货吗？$B$B谢谢你，$n！旅店老板奥里森在镶金玫瑰旅店，就在暴风城的贸易区里。",objectives={"将烟林补给品交给暴风城的旅店老板奥里森。"}]])
R(8861,"庆祝新年！",[[description="雷霆崖正在举行新年庆典！所有人都可以全天畅饮美酒佳肴，晚上还会有焰火表演！听起来是不错……不过藏宝海湾也有这样的庆典，我敢说这个肯定更棒！$B$B总之，雷霆崖的旅店老板帕拉需要一些烟林牧场的补给品才能应付需求量巨大的庆典，你能帮我送一趟货吗？$B$B谢谢你，$n！帕拉的旅店就在通往猎人高地的吊桥边。",objectives={"将烟林补给品交给雷霆崖的旅店老板帕拉。"}]])
