R(8935,"小小的补偿",[[description="你做到了你所承诺的事，把穆克斯制造的装备给我带了回来，那么我也按承诺给予你一件不错的奖励。把你原先使用的腰带和手套拿来吧，我会帮你升级它们。我敢保证，新的装备会比原来的好得多。",objectives={"将一条迅影腰带和一副迅影手套交给铁炉堡的德莉亚娜。"}]])
R(8936,"小小的补偿",[[description="你做到了你所承诺的事，把穆克斯制造的装备给我带了回来，那么我也按承诺给予你一件不错的奖励。把你原先使用的腰带和手套拿来吧，我会帮你升级它们。我敢保证，新的装备会比原来的好得多。",objectives={"将一条鬼雾腰带和一副鬼雾手套交给铁炉堡的德莉亚娜。"}]])
R(8937,"小小的补偿",[[description="你信守承诺将莫克斯建构的仪器带来了。我相信如果我给你奖赏，你会感兴趣的。若你想升级的话，就把腰带和一整套手套拿来给我。我承诺我交还给你的将会是更精良的物品。",objectives={"将勇气腰带和1套勇气护手带给铁炉堡的德莉娜。"}]])
