R(8942,"小小的补偿",[[description="你证明了自己是个非常可靠的人，$N。我相信你会帮我度过这次的困境，我会依照你的表现来给予奖励。$B$B现在就交换你的腰带和护手。如果我们一起度过了这个难关，我就会把剩下的装备都做给你。",objectives={"将元素束腰和1套元素护手带给奥格玛的莫克瓦。"}]])
R(8943,"小小的补偿",[[description="你证明了自己是个非常可靠的人，$N。我相信你会帮我度过这次的困境，我会依照你的表现来给予奖励。$B$B现在我要把你的腰带和手套换掉。如果我们一起度过了这个难关，我就会把剩下的装备都做给你。",objectives={"将鬼雾腰带和1套鬼雾手套带给奥格玛的莫克瓦。"}]])
