R(9015,"挑战",[[description="听好了，$N。为了让这面旗帜运转起来，你必须要进入黑石深渊的竞技场，然后听任裁决者格里斯通宣判你，然后将这面旗子牢牢地插在地面上有处挑战标记的地方。$B$B这时你想挑战的人就会被不可抗拒的力量推入战场，浑身上下只有将你杀死的欲望。当你从他身上找到了你要的东西以后，就回去找安泰恩吧。",objectives={"到黑石深渊的竞技场去，在你被裁决者格里斯通宣判之后将挑战之旗插在场地中央。杀死塞尔德林和他的角斗士，然后将瓦塔拉克饰品第一部分交给东瘟疫之地的安泰恩·哈尔蒙。"}]])
R(9016,"告别安泰恩",[[description="瓦萨拉克的灵魂被存在这个护符里。因为我们的贪婪，愚蠢地把护符分成三块，不知道有可怕的诅咒在等着我们。$B$B阻止瓦萨拉克的魔法的唯一方法就是将护符重新组合回去。回到莫克瓦那里，告诉他布德利是找到剩下护符的唯一希望。和他谈谈为你安排的奖励。$B$B我，这一次，终于可以安息了。祝你好运；你需要这份好运的！",objectives={"带着野性之心长靴，野性之心褶裙和野性之心肩甲回到奥格玛的莫克瓦那里。"}]])
R(9017,"告别安泰恩",[[description="瓦萨拉克的灵魂被存在这个护符里。因为我们的贪婪，愚蠢地把护符分成三块，不知道有可怕的诅咒在等着我们。$B$B阻止瓦萨拉克的魔法的唯一方法就是将护符重新组合回去。回到莫克瓦那里，告诉他布德利是找到剩下护符的唯一希望。和他谈谈为你安排的奖励。$B$B我，这一次，终于可以安息了。祝你好运；你需要这份好运的！",objectives={"带着驭兽者长靴，驭兽者短裤和驭兽者衬肩回到奥格玛的莫克瓦那里。"}]])
R(9018,"告别安泰恩",[[description="瓦萨拉克的灵魂被存在这个护符里。因为我们的贪婪，愚蠢地把护符分成三块，不知道有可怕的诅咒在等着我们。$B$B阻止瓦萨拉克的魔法的唯一方法就是将护符重新组合回去。回到莫克瓦那里，告诉他布德利是找到剩下护符的唯一希望。和他谈谈为你安排的奖励。$B$B我，这一次，终于可以安息了。祝你好运；你需要这份好运的!",objectives={"带着博学者长靴，博学者护腿和博学者衬肩回到奥格玛的莫克瓦那里。"}]])
R(9019,"告别安泰恩",[[description="瓦塔拉克的灵魂就封印在这枚护符里。因为贪婪，我们愚蠢地将它分成了好几部分，丝毫不了解这会为我们带来怎样残酷的诅咒。$B$B唯一解除瓦塔拉克的法术的办法，就是将这枚勋章重新组合在一起。回到莫克瓦尔那里去，告诉他说，伯德雷已经是他找齐剩余部分的最后希望了。顺便跟他提一下你应得的报酬。$B$B我只希望能从此安息。祝你好运……你会非常需要运气的！",objectives={"带上一双虔诚软鞋、一条虔诚长裙和一副虔诚衬肩，回去向奥格瑞玛的莫克瓦尔复命。"}]])
R(9020,"告别安泰恩",[[description="瓦萨拉克的灵魂被存在这个护符里。因为我们的贪婪，愚蠢地把护符分成三块，不知道有可怕的诅咒在等着我们。$B$B阻止瓦萨拉克的魔法的唯一方法就是将护符重新组合回去。回到莫克瓦那里，告诉他布德利是找到剩下护符的唯一希望。和他谈谈为你安排的奖励。$B$B我，这一次，终于可以安息了。祝你好运；你需要这份好运的!",objectives={"带着迅影长靴，迅影短裤和迅影肩甲回到奥格玛的莫克瓦那里。"}]])
R(9021,"告别安泰恩",[[description="瓦萨拉克的灵魂被存在这个护符里。因为我们的贪婪，愚蠢地把护符分成三块，不知道有可怕的诅咒在等着我们。$B$B阻止瓦萨拉克的魔法的唯一方法就是将护符重新组合回去。回到莫克瓦那里，告诉他布德利是找到剩下护符的唯一希望。和他谈谈为你安排的奖励。$B$B我，这一次，终于可以安息了。祝你好运；你需要这份好运的！",objectives={"带着鬼雾便鞋，鬼雾护腿和鬼雾衬肩回到奥格玛的莫克瓦那里。"}]])
R(9022,"告别安泰恩",[[description="瓦萨拉克的灵魂被存在这个护符里。因为我们的贪婪，愚蠢地把护符分成三块，不知道有可怕的诅咒在等着我们。$B$B阻止瓦萨拉克的魔法的唯一方法就是将护符重新组合回去。回到莫克瓦那里，告诉他布德利是找到剩下护符的唯一希望。和他谈谈为你安排的奖励。$B$B我，这一次，终于可以安息了。祝你好运；你需要这份好运的!",objectives={"带着勇气战靴，勇气腿铠和勇气肩甲回到奥格玛的莫克瓦那里。"}]])
R(9023,"完美的毒药",[[description="我和我的兄弟在拉文霍德庄园外进行毒药研究。$B$B拉文霍德公爵命令我们研制一种极效混合毒药，祖尔格拉布和安其拉废墟出产这种毒药的原料，也就是毒囊。$B$B有两只剧毒的野兽居住在那些可怕的废墟中，它们很可能有我们需要的毒囊。$C，去取回库林纳克斯和温诺希斯的毒囊，我们会永远记得你的恩情的。",objectives={"塞纳里奥要塞的德尔克·雷木让你把温诺希斯的毒囊和库林纳克斯的毒囊交给他。"}]])
R(9024,"阿瑞斯坦的预感",[[description="我找到了！你闻到过风中的新香气没有？新的香水现在有那么流行么？我们的卫兵不该这么简单就这样抛弃他们的职责！$b$b嗯，一定是因为他们的理智完全被这些该死的炼金术产品所盖过去了。$b$b要想搞清楚问题，只有一个办法：弄一些香水的样本，把它们交给摩根·匹斯特，并把我的推断告诉他。别担心，你回来的时候我会把买香水的钱付给你的。",objectives={"将1瓶古龙水和1瓶香水交给暴风城贸易区的摩根·匹斯特。"}]])
R(9025,"摩根的发现",[[description="好吧，有问题。看来阿瑞斯坦还真是个很警觉的人。我在香水中发现了一些应用在爱情药水中的物质，以及一些可以影响情绪的危险成分。$b$b在香水中应用这些物质虽然并非是前所未有的，但我从中分析出的一些原料……闻起来很有趣。",objectives={"回到暴风城银行附近的阿瑞斯坦·莫塔那里。"}]])
R(9026,"追查货源",[[description="我们一定得找到源头才行。我看到许多人，包括卫兵，都在镶金玫瑰那里进进出出。跟奥里森谈谈，要是她在卖这些东西，就问问她是从哪里弄来的货。",objectives={"与暴风城贸易区中的镶金玫瑰旅店的老板奥里森谈一谈。"}]])
R(9027,"追查货源",[[description="我的香水有点古怪？有可能。我从来没见过人们对某种产品这样痴迷。$b$b你看，要是有什么古怪的话，我也很想知道。我是从一个叫埃文特·索里萨姆的商人那里进到这批货的。他是新来的。$b$b他提到过说有些货物得送到“最好的线团”那边去。",objectives={"与暴风城运河旁的裁缝店“最好的线团”里面的埃文特·索里萨姆谈一谈。"}]])
R(9028,"水落石出",[[description="什么？叛国罪？不，不，我向你保证，我绝对没有任何的恶意。$b$b难道说帮助那些想轻松度过痛苦的求爱期的年轻人也有错吗？拜托，这绝对不是犯罪。$b$b为了证明我确实没有恶意，我可以告诉你货源。$b$b据说这些香水都是一个叫斯塔弗隆·雷伦特的药剂师制作的，不过我从未与他见过面，也没有说过话。$b$b我们的地精中间人说，他就在希尔斯布莱德地区工作，似乎就是那个神秘的拉文霍德庄园一带。祝你好运！",objectives={"到希尔斯布莱德丘陵去，在拉文霍德庄园后面找到药剂师斯塔弗隆·雷伦特。"}]])
R(9029,"薰炉")
R(9030,"Anthion's Parting Words",[[description="Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.$B$BThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.$B$BI, for once, shall rest in peace.  I wish you the best of luck, and you shall need it!",objectives={"Speak to Deliana in Ironforge."}]])
R(9032,"伯德雷的不幸",[[description="这枚徽章里有瓦萨拉克的灵魂吗?被这强大的诅咒所守护其实也没什麽好惊讶的。$B$B布德利的所在位置显现出一些问题。上次我听到的是他准备重返黑石塔的消息，然後就再也没音讯了。$B$B到黑石山去找他，不过我很担心他可能早已身亡。所以我建议你随身携带哥布林的装置，朋友。",objectives={"到黑石山并使用超空间鬼魂显像机，去黑石塔附近寻找布德利。"}]])
R(9033,"战争的回响",[[description="上一次战争距今已有5年了……$B$B数万名士兵战死沙场，他们的牺牲换来了什么？危机远远没有消失。$B$B巫妖王再次蠢蠢欲动……他的走狗克尔苏加德正在集聚军队，准备对我们的家园发动新一轮的袭击。$B$B我们绝不会让他得逞！拿出你的奉献精神吧。勇敢地投入战斗，以此证明你的无畏！银色黎明和血色十字军组成的联军将是你坚强的后盾和战友。$B$B前往纳克萨玛斯的宫殿，打败天灾军团……",objectives={"东瘟疫之地圣光之愿礼拜堂的指挥官埃里戈尔·黎明使者要你杀死5个畸形妖、5只岩肤石像鬼、8个死亡骑士队长和3只毒性捕猎者。"}]])
R(9034,"无畏胸甲",[[description="在你与纳克萨玛斯宫殿中的天灾军团作战过程中，如果看到被玷污的护甲和板甲碎片，将它们带给我，我会为你打造一套适合英雄穿着的护甲。",objectives={"如果你将1件被玷污的胸甲、25块板甲碎片、4块奥金锭和2块连结水晶交给东瘟疫之地圣光之愿礼拜堂的科尔法克斯，他会为你制作一件无畏胸甲。"}]])
R(9036,"无畏腿铠",[[description="在你与纳克萨玛斯宫殿中的天灾军团作战过程中，如果看到被玷污的护甲和板甲碎片，将它们带给我，我会为你打造一套适合英雄穿着的护甲。",objectives={"如果你将1副被玷污的腿铠、20块板甲碎片、4块奥金锭和3个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的科尔法克斯，他会为你制作一副无畏腿铠。"}]])
R(9037,"无畏头盔",[[description="在你与纳克萨玛斯宫殿中的天灾军团作战过程中，如果看到被玷污的护甲和板甲碎片，将它们带给我，我会为你打造一套适合英雄穿着的护甲。",objectives={"如果你将1顶被玷污的头盔、15块板甲碎片、5块奥金锭和1块连结水晶交给东瘟疫之地圣光之愿礼拜堂的科尔法克斯，他会为你制作一顶无畏头盔。"}]])
R(9038,"无畏肩铠",[[description="在你与纳克萨玛斯宫殿中的天灾军团作战过程中，如果看到被玷污的护甲和板甲碎片，将它们带给我，我会为你打造一套适合英雄穿着的护甲。",objectives={"如果你将1副被玷污的肩铠、12块板甲碎片、2块奥金锭和3个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的科尔法克斯，他会为你制作一副无畏肩铠。"}]])
R(9039,"无畏马靴",[[description="在你与纳克萨玛斯宫殿中的天灾军团作战过程中，如果看到被玷污的护甲和板甲碎片，将它们带给我，我会为你打造一套适合英雄穿着的护甲。",objectives={"如果你将1双被玷污的马靴、12块板甲碎片、2块奥金锭和3个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的科尔法克斯，他会为你制作一双无畏马靴。"}]])
R(9040,"无畏护手",[[description="在你与纳克萨玛斯宫殿中的天灾军团作战过程中，如果看到被玷污的护甲和板甲碎片，将它们带给我，我会为你打造一套适合英雄穿着的护甲。",objectives={"如果你将1副被玷污的护手、8块板甲碎片、1块奥金锭和5个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的科尔法克斯，他会为你制作一副无畏护手。"}]])
R(9041,"无畏腰带",[[description="在你与纳克萨玛斯宫殿中的天灾军团作战过程中，如果看到被玷污的护甲和板甲碎片，将它们带给我，我会为你打造一套适合英雄穿着的护甲。",objectives={"如果你将1条被玷污的护腰、8块板甲碎片、1块奥金锭和5个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的科尔法克斯，他会为你制作一条无畏护腰。"}]])
R(9042,"无畏护腕",[[description="在你与纳克萨玛斯宫殿中的天灾军团作战过程中，如果看到被玷污的护甲和板甲碎片，将它们带给我，我会为你打造一套适合英雄穿着的护甲。",objectives={"如果你将1副被玷污的护腕、6块板甲碎片、1块奥金锭和1块连结水晶交给东瘟疫之地圣光之愿礼拜堂的科尔法克斯，他会为你制作一副无畏护腕。"}]])
R(9043,"救赎外套",[[description="杀死纳克萨玛斯城中的敌军首领之后，你会在他们的尸体上发现阵亡英雄的遗骸。将那些被亵渎的遗物、板甲碎片和其它材料交给我，也许我能试着移除护甲上的诅咒，重新为你打造一件精良的护甲。",objectives={"如果你将1件被玷污的外套，25块板甲碎片，4块奥金锭和3个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的指挥官埃里戈尔·黎明使者，他将为你制作一件救赎外套。"}]])
R(9044,"救赎腿甲",[[description="杀死纳克萨玛斯城中的敌军首领之后，你会在他们的尸体上发现阵亡英雄的遗骸。将那些被亵渎的遗物、板甲碎片和其它材料交给我，也许我能试着移除护甲上的诅咒，重新为你打造一件精良的护甲。",objectives={"如果你将1副被玷污的腿甲，20块板甲碎片，4块奥金锭和2块连结水晶交给东瘟疫之地圣光之愿礼拜堂的指挥官埃里戈尔·黎明使者，他将为你制作一副救赎腿甲。"}]])
R(9045,"救赎头饰",[[description="杀死纳克萨玛斯城中的敌军首领之后，你会在他们的尸体上发现阵亡英雄的遗骸。将那些被亵渎的遗物、板甲碎片和其它材料交给我，也许我能试着移除护甲上的诅咒，重新为你打造一件精良的护甲。",objectives={"如果你将1件被玷污的头饰，15块板甲碎片，5块奥金锭和2个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的指挥官埃里戈尔·黎明使者，他将为你制作一件救赎头饰。"}]])
R(9046,"救赎肩铠",[[description="杀死纳克萨玛斯城中的敌军首领之后，你会在他们的尸体上发现阵亡英雄的遗骸。将那些被亵渎的遗物、板甲碎片和其它材料交给我，也许我能试着移除护甲上的诅咒，重新为你打造一件精良的护甲。",objectives={"如果你将1副被玷污的肩铠，12块板甲碎片，2块奥金锭和2块连结水晶交给东瘟疫之地圣光之愿礼拜堂的指挥官埃里戈尔·黎明使者，他将为你制作一副救赎肩铠。"}]])
R(9047,"救赎长靴",[[description="杀死纳克萨玛斯城中的敌军首领之后，你会在他们的尸体上发现阵亡英雄的遗骸。将那些被亵渎的遗物、板甲碎片和其它材料交给我，也许我能试着移除护甲上的诅咒，重新为你打造一件精良的护甲。",objectives={"如果你将1双被玷污的长靴，12块板甲碎片，2块奥金锭和3个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的指挥官埃里戈尔·黎明使者，他将为你制作一双救赎长靴。"}]])
R(9048,"救赎护手",[[description="杀死纳克萨玛斯城中的敌军首领之后，你会在他们的尸体上发现阵亡英雄的遗骸。将那些被亵渎的遗物、板甲碎片和其它材料交给我，也许我能试着移除护甲上的诅咒，重新为你打造一件精良的护甲。",objectives={"如果你将1副被玷污的护手，8块板甲碎片，1块奥金锭和5个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的指挥官埃里戈尔·黎明使者，他将为你制作一副救赎护手。"}]])
R(9049,"救赎束带",[[description="杀死纳克萨玛斯城中的敌军首领之后，你会在他们的尸体上发现阵亡英雄的遗骸。将那些被亵渎的遗物、板甲碎片和其它材料交给我，也许我能试着移除护甲上的诅咒，重新为你打造一件精良的护甲。",objectives={"如果你将1条被玷污的束带，8块板甲碎片，1块奥金锭和3块连结水晶交给东瘟疫之地圣光之愿礼拜堂的指挥官埃里戈尔·黎明使者，他将为你制作一条救赎束带。"}]])
R(9050,"救赎护腕",[[description="杀死纳克萨玛斯城中的敌军首领之后，你会在他们的尸体上发现阵亡英雄的遗骸。将那些被亵渎的遗物、板甲碎片和其它材料交给我，也许我能试着移除护甲上的诅咒，重新为你打造一件精良的护甲。",objectives={"如果你将1副被玷污的护腕，6块板甲碎片，1块奥金锭和2个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的指挥官埃里戈尔·黎明使者，他将为你制作一副救赎护腕。"}]])
R(9051,"毒性测试",[[description="这些你帮我制造的毒素有着特殊的用途。环形山里的魔暴龙使得那里的狩猎和生存环境对我来说都变得十分恶劣。即使我足够强壮，杀死一只魔暴龙也只会让另一只游荡入那块带领地而已。$b$b带上这根毒针并将其刺入一只活着的魔暴龙体内。毒素会使它很快就安静下来，不过……我不知道很快有多快……",objectives={"将魔暴龙之刺扎入一只魔暴龙的体内。"}]])
R(9052,"血瓣毒药",[[description="我要你帮我制作一批毒素，用来制服某些生活在环形山里的巨兽。它并非是致命性的，不过只有一个足够细心和聪明的$c才能收集到所有的材料。$b$b在环形山里任意血瓣花苗身上，你都可以找到一些血帽蘑菇，而格里什钉刺则可以从环形山南部巨痕谷中的那些巨蜂身上找到。",objectives={"收集一些血帽和格里什钉刺，然后向托尔瓦·寻路者复命。"}]])
R(9053,"更好的材料",[[description="这正是我所担心的，看来毒素的力量还是太弱了，无法对这样强大的生物产生影响。$b$b我们必须造出一种更强力的毒素，你需要前往阿塔哈卡神庙的底部，揭开那个祭坛的秘密，并从那里的守卫身上取一些腐烂的藤蔓来。神庙很危险，我建议你带些朋友一起去。$b$b完成之后回到我这里来吧。",objectives={"从沉没的神庙底部的守卫身上得到一些腐烂藤蔓，把它们交给托尔瓦·寻路者。"}]])
R(9054,"地穴追猎者外套",[[description="我发现地穴恶魔的甲壳大有用处。我可以利用这种甲壳以及丢失在纳克萨玛斯宫殿中的被玷污的护甲，打造出一套轻便时尚的、具有毁灭性力量的套装。$B$B帮我寻找必需的材料，我就能制作出这套前所未有的装备！",objectives={"如果你将1件被玷污的外套、25块锁甲碎片、4块奥金锭和3个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的猎手雷奥普德，他会为你制作一件地穴追猎者外套。"}]])
R(9055,"地穴追猎者腿甲",[[description="我发现地穴恶魔的甲壳大有用处。我可以利用这种甲壳以及丢失在纳克萨玛斯宫殿中的被玷污的护甲，打造出一套轻便时尚的、具有毁灭性力量的套装。$B$B帮我寻找必需的材料，我就能制作出这套前所未有的装备！",objectives={"如果你将1条被玷污的腿甲、20块锁甲碎片、3块奥金锭和5个熟化毛皮交给东瘟疫之地圣光之愿礼拜堂的猎手雷奥普德，他会为你制作一条地穴追猎者腿甲。"}]])
R(9056,"地穴追猎者头饰",[[description="我发现地穴恶魔的甲壳大有用处。我可以利用这种甲壳以及丢失在纳克萨玛斯宫殿中的被玷污的护甲，打造出一套轻便时尚的、具有毁灭性力量的套装。$B$B帮我寻找必需的材料，我就能制作出这套前所未有的装备！",objectives={"如果你将1件被玷污的头饰、15块锁甲碎片、4块奥金锭和2块连结水晶交给东瘟疫之地圣光之愿礼拜堂的猎手雷奥普德，他会为你制作一件地穴追猎者头饰。"}]])
