R(9229,"拉玛兰迪的命运",[[description="拉玛兰迪是兄弟会的一名战士，早在银色黎明成立之前他便是莫格莱尼阁下的学生了！当莫格莱尼的死讯传来时，仇恨和愤怒充斥着他的心灵。$B$B试想一下吧，$N，一个被复仇的怒火占据了心灵的人还能算个人吗，无非是个被情绪操控的傀儡。拉玛兰迪在盛怒之下冲进了纳克萨玛斯的宫殿，想为恩师报仇……可惜是肉包子打狗。$B$B前往纳克萨玛斯的宫殿打探拉玛兰迪的下落吧。",objectives={"进入纳克萨玛斯的宫殿，找到拉玛兰迪的下落。"}]])
R(9230,"拉玛兰迪的寒冰之握",[[description="要修复这枚戒指可不是件容易的事儿，$N。瞧，它的原材料是取自天灾建筑物中形成的冰冻符文，例如纳克萨玛斯的宫殿。当然我还需要其它材料，但是你的主要任务就是找到冰冻符文。把我所需的材料拿来，我会让这枚戒指重新恢复光泽的。",objectives={"东瘟疫之地圣光之愿礼拜堂的科尔法克斯要1个冰冻符文、1块蓝宝石和1块奥金锭。"}]])
R(9232,"我只会唱这一首歌……",[[description="你自诩为银色黎明的英雄，是吗？克尔苏加德手下的小喽啰能轻松砍翻我军最优秀的士兵，这是我亲眼所见！像你这样的蠢货还想去纳克萨玛斯的宫殿？$B$B<威尔海姆叹了一口气。>$B$B呸，我还能有什么选择？你是我惟一的希望；我或许能帮上忙。$B$B“奥玛里恩悄悄地走，除了一份图样，他什么都没留……”，我只会唱这一首歌……嗯，我可以为你制作一条很棒的裤子，但是你得为我提供材料。",objectives={"将2个冰冻符文、2个水之精华、2块蓝宝石和30金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。"}]])
R(9233,"奥玛里恩的手册",[[description="威尔海姆：$B$B当你翻阅这本手册时，我已经咽气了——这对我来说是个解脱。我想告诉你，我临死前还想着你和你那糟糕的商业头脑。不幸的是，就工匠技能来说，送手册给你的家伙连你都不如。$B$B这本手册记载了我生前研制的配方，可以让手册的持有者制造出任何他们想要的东西。我想你一定会向别人收取高额费用的，因为你就是这么个混帐。$B$B我鄙视你，$B$B奥玛里恩",objectives={"将奥玛里恩的手册交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。"}]])
R(9234,"破冰护手",[[description="谢谢你与欧玛利安，愿他安息。我现在能制作冰克护手了，你只需要替我找来制作材料，以及支付一些工匠费就可以了。",objectives={"东瘟疫之地圣光之愿礼拜堂的铁匠维尔海姆需要你带给他5个冰冻符文，12个瑟银锭，2个奥金锭，2个水之精华，还有200金。"}]])
R(9235,"破冰护腕",[[description="感谢你和奥玛里恩（愿奥玛里恩就此安息），现在我可以开始制作破冰护腕了。你要做的只是为我提供材料，并支付一笔小小的加工费。",objectives={"将4个冰冻符文、12块瑟银锭、2块奥金锭、2个水之精华和200金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。"}]])
R(9236,"破冰胸甲",[[description="感谢你和奥玛里恩（愿奥玛里恩就此安息），现在我可以开始制作破冰胸甲了。你要做的只是为我提供材料，并支付一笔小小的加工费。",objectives={"将8个冰冻符文、16块瑟银锭、2块奥金锭、4个水之精华和300金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。你在银色黎明的声望必须达到崇拜。"}]])
