R(9240,"冰川外衣",[[description="谢谢你与欧玛利安，愿他安息。我现在能制作冰川外衣了，你只需要替我找来制作材料，以及支付一些工匠费就可以了。",objectives={"东瘟疫之地圣光之愿礼拜堂的铁匠维尔海姆需要你带给他8个冰冻符文，8份符文布卷，6个水之精华，4份铁网蛛丝，还有300金。同时你必须在银色黎明达到崇拜声望值，才能完成这项任务。"}]])
R(9241,"北极护腕",[[description="感谢你和奥玛里恩（愿奥玛里恩就此安息），现在我可以开始制作北极护腕了。你要做的只是为我提供材料，并支付一笔小小的加工费。",objectives={"将4个冰冻符文、12个魔化皮、3个水之精华、3个熟化毛皮和200金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。"}]])
