R(9247,"圣光的召唤",[[description="$N，$B$B在过去的日子里，你尽心尽力地为银色黎明做出了杰出的贡献。现在，在这紧要关头，我们再次发出号召。$B$B$N，如果你愿意伸出援手，就去东瘟疫之地圣光之愿礼拜堂向名单登记员报道吧。",objectives={"将名单登记员的信交给东瘟疫之地圣光之愿礼拜堂的名单登记员。"}]])
R(9248,"谦卑的馈赠",[[description="Ishnu-alah，$R。让我看看能证明你杀死深渊议会领主的证据，我就奖励你一件好东西，它能在你与其拉虫人作战时帮你一臂之力。",objectives={"将一根深渊节杖交给希利苏斯塞纳里奥要塞的奥蕾尔·金叶。你在塞纳里奥议会的声望必须达到尊敬。"}]])
R(9249,"40 Tickets - Schematic: Steam Tonk Controller")
R(9250,"埃提耶什之杖",[[description="合成杖柄之后，从形状上来看，守护者的传说之杖埃提耶什只差法杖顶部和杖柄末端两个部分了。还有个小问题就是：这根杖子蕴涵着萨格拉斯的邪恶力量。$B$B看看有谁能帮你找到残余的法杖碎片并且净化那些邪恶的力量。",objectives={"看看有谁能帮你找到法杖的最后两个部分，并且净化邪恶的力量。"}]])
R(9251,"埃提耶什，被玷污的传说之杖",[[description="你很困惑为何自己还活在世上吧。毕竟，你拥有这么一件邪恶的物品。没有确切的答案，$N。我只是做我应该做的事儿罢了。$B$B克尔苏加德就在纳克萨玛斯宫殿的王座上策划着某个阴谋……他要找的东西在你手中，而你要找的东西在他手中。$B$B一位名叫布莱恩·铜须的矮人曾携带杖柄的末端进入安其拉，却不小心将它遗失在了安其拉里面。$B$B一旦你成功拿到杖柄末端，就立即来找我吧。",objectives={"塔纳利斯时光之穴的阿纳克洛斯要你找到埃提耶什的法杖顶部和埃提耶什的杖柄末端。"}]])
R(9257,"埃提耶什，守护者的传说之杖",[[description="最后一个任务会是最困难的，魔兽资料库网友。你要去迎头攻击巫妖王的将军跟上古之神，但是，你现在要面对的是萨格拉斯之手。$B带着这个法杖到斯坦索姆。你会看到圣化之地:而罗德隆最伟大的骑士就是在这里被谋杀的。把这污损的法杖放在圣化之地上，准备巨大力量由内破坏……毁灭这个支配法杖的邪恶东西，然后回到我这。",objectives={"塔纳利斯时光之穴的安纳克罗斯要你带着阿泰丝,守护者之杖前往斯坦索姆，在圣化之地上使用它。击败从法杖内被驱除的生物再回去找他。"}]])
R(9259,"血帆海盗的叛徒")
R(9260,"调查暴风城的天灾入侵",[[description="巫妖王的部队已经在我们鼻子底下扎了营，我们可不能坐以待毙！你会拿起武器跟这些可憎的入侵者作战，保卫暴风城的吧？$B$B城外出现了奇怪的符文法阵，它散发着神秘的能量，亡灵和悬浮在半空的浮空城也被同样的能量环绕着。我想这个符文法阵对天灾士兵们必然有着重要的意义，因此想让你调查此事。去和城外的亡灵作战吧，带回你杀死他们的证据，以及你的调查结果，我会奖励你的。去吧！",objectives={"从暴风城外面的天灾士兵身上收集3块暗淡的死灵石，并调查天灾营地附近的发光符文法阵。"}]])
R(9261,"调查铁炉堡的天灾入侵",[[description="巫妖王的部队已经在我们鼻子底下扎了营，我们可不能坐以待毙！你会拿起武器跟这些可憎的入侵者作战，保卫铁炉堡的吧？$B$B城外出现了奇怪的符文法阵，它散发着神秘的能量，亡灵和悬浮在半空的浮空城也被同样的能量环绕着。我想这个符文法阵对天灾士兵们必然有着重要的意义，因此想让你调查此事。去和城外的亡灵作战吧，带回你杀死他们的证据，以及你的调查结果，我会奖励你的。去吧！",objectives={"从铁炉堡外面的天灾士兵身上收集3块暗淡的死灵石，并调查天灾营地附近的发光符文法阵。"}]])
R(9262,"调查达纳苏斯的天灾入侵",[[description="巫妖王的部队已经在我们鼻子底下扎了营，我们可不能坐以待毙！你会拿起武器跟这些可憎的入侵者作战，保卫达纳苏斯的吧？$B$B城外出现了奇怪的符文法阵，它散发着神秘的能量，亡灵和悬浮在半空的浮空城也被同样的能量环绕着。我想这个符文法阵对天灾士兵们必然有着重要的意义，因此想让你调查此事。去和城外的亡灵作战吧，带回你杀死他们的证据，以及你的调查结果，我会奖励你的。去吧！",objectives={"从达纳苏斯外面的天灾士兵身上收集3块暗淡的死灵石，并调查天灾营地附近的发光符文法阵。"}]])
R(9263,"调查奥格瑞玛的天灾入侵",[[description="天灾士兵们在主城外扎了营，我们不能坐以待毙！你会拿起武器跟这些可憎的入侵者作战，保卫奥格瑞玛的吧？$B$B城外出现了奇怪的符文法阵，它散发着神秘的能量，亡灵和悬浮在半空的浮空城也被同样的能量环绕着。我想这个符文法阵对天灾士兵们必然有着重要的意义，因此想让你调查此事。去和城外的亡灵作战吧，带回你杀死他们的证据，以及你的调查结果，我会奖励你的。去吧！",objectives={"从奥格瑞玛外面的天灾士兵身上收集3块暗淡的死灵石，并调查营地附近的发光的符文法阵。"}]])
R(9264,"调查雷霆崖的天灾入侵",[[description="天灾士兵们在主城外扎了营，我们不能坐以待毙！你会拿起武器跟这些可憎的入侵者作战，保卫雷霆崖的吧？$B$B城外出现了奇怪的符文法阵，它散发着神秘的能量，亡灵和悬浮在半空的浮空城也被同样的能量环绕着。我想这个符文法阵对天灾士兵们必然有着重要的意义，因此想让你调查此事。去和城外的亡灵作战吧，带回你杀死他们的证据，以及你的调查结果，我会奖励你的。去吧！",objectives={"从雷霆崖外面的天灾士兵身上收集3块暗淡的死灵石，并调查营地附近的发光的符文法阵。"}]])
R(9265,"调查幽暗城的天灾入侵",[[description="天灾士兵们在主城外扎了营，我们不能坐以待毙！你会拿起武器跟这些可憎的入侵者作战，保卫幽暗城的吧？$B$B城外出现了奇怪的符文法阵，它散发着神秘的能量，亡灵和悬浮在半空的浮空城也被同样的能量环绕着。我想这个符文法阵对天灾士兵们必然有着重要的意义，因此想让你调查此事。去和城外的亡灵作战吧，带回你杀死他们的证据，以及你的调查结果，我会奖励你的。去吧！",objectives={"从幽暗城外面的天灾士兵身上收集3块暗淡的死灵石，并调查营地附近的发光的符文法阵。"}]])
